# ---------------------------------------------------------------------------
# Мини-парсер YAML
# ---------------------------------------------------------------------------
# Поддерживается ровно то подмножество, которое используется в репозитории:
#   * вложенные словари на 2-3 уровня;
#   * скаляры: null/~/true/false, целые, float, строки в кавычках и без;
#   * блочные списки "- item" и "- key: value";
#   * inline-списки "[a, b, c]";
#   * комментарии "#" (вне кавычек);
#   * разделители документа "---" / "...".
# Если PyYAML установлен — используется он, иначе этот парсер.

try:  # pragma: no cover - зависит от окружения
    import yaml as _pyyaml  # type: ignore
except Exception:  # pragma: no cover
    _pyyaml = None


def _build_ssot_loader():
    """SafeLoader PyYAML, в котором sexagesimal-числа остаются строками.

    YAML 1.1 (PyYAML) разбирает `10:00:00` как число секунд (36000). В SSoT
    такие значения — время дежурств (`duty.yaml → onCallSchedule.startTime`),
    и конвертировать его в секунды нельзя: prepare сохраняет строку `HH:MM`
    (docs/09-pipeline.md). Встроенный мини-парсер и так оставляет строку —
    здесь поведение обоих путей приводится к одному.
    """
    class _SsotLoader(_pyyaml.SafeLoader):
        pass

    def _construct_int(loader, node):
        text = loader.construct_scalar(node)
        if ":" in str(text):
            return str(text)
        return _pyyaml.SafeLoader.construct_yaml_int(loader, node)

    def _construct_float(loader, node):
        text = loader.construct_scalar(node)
        if ":" in str(text):
            return str(text)
        return _pyyaml.SafeLoader.construct_yaml_float(loader, node)

    _SsotLoader.add_constructor("tag:yaml.org,2002:int", _construct_int)
    _SsotLoader.add_constructor("tag:yaml.org,2002:float", _construct_float)
    return _SsotLoader


_SSOT_LOADER = _build_ssot_loader() if _pyyaml is not None else None


class YamlError(Exception):
    """Ошибка разбора YAML с указанием файла и строки."""


_INT_RE = re.compile(r"^[+-]?\d+$")
_FLOAT_RE = re.compile(r"^[+-]?(?:\d+\.\d*|\.\d+)$")
# YAML 1.1 sexagesimal: "10:00" читается как 600. Такие строки квотируются.
_SEXAGESIMAL_RE = re.compile(r"^[+-]?\d+(?::[0-5]?\d)+(?:\.\d*)?$")
_MAP_ITEM_RE = re.compile(r"^[A-Za-z0-9_.\-]+\s*:(\s|$)")


def _strip_comment(line: str) -> str:
    """Убрать комментарий, не задевая '#' внутри кавычек и внутри скаляра.

    YAML считает '#' началом комментария только в начале строки или после
    пробельного символа. Поэтому `a#b` — это значение `a#b`, а не `a`.
    """
    out = []
    quote = None
    i = 0
    while i < len(line):
        ch = line[i]
        if quote:
            out.append(ch)
            if ch == "\\" and quote == '"' and i + 1 < len(line):
                out.append(line[i + 1])
                i += 2
                continue
            if ch == quote:
                quote = None
            i += 1
            continue
        if ch in "\"'":
            quote = ch
            out.append(ch)
            i += 1
            continue
        if ch == "#" and (i == 0 or line[i - 1] in " \t"):
            break
        out.append(ch)
        i += 1
    return "".join(out)


def _yaml_error(source: str, lineno: int, column: int, message: str) -> "YamlError":
    """Ошибка разбора в формате `<файл>:<строка>:<колонка>: <причина>`."""
    return YamlError(f"{source}:{lineno}:{max(int(column), 1)}: {message}")


def _tokenize(text: str, source: str):
    tokens = []
    for lineno, raw in enumerate(text.splitlines(), 1):
        leading = raw[: len(raw) - len(raw.lstrip(" \t"))]
        if "\t" in leading:
            column = leading.index("\t") + 1
            raise _yaml_error(
                source,
                lineno,
                column,
                "табуляция в отступе не поддерживается, используйте пробелы",
            )
        line = _strip_comment(raw).rstrip()
        if not line.strip():
            continue
        body = line.lstrip(" ")
        indent = len(line) - len(body)
        body = body.strip()
        if body in ("---", "..."):
            continue
        tokens.append([indent, body, lineno])
    return tokens


def _split_commas(text: str) -> list:
    parts = []
    buf = []
    depth = 0
    quote = None
    for ch in text:
        if quote:
            buf.append(ch)
            if ch == quote:
                quote = None
            continue
        if ch in "\"'":
            quote = ch
            buf.append(ch)
            continue
        if ch in "[{":
            depth += 1
        elif ch in "]}":
            depth -= 1
        if ch == "," and depth == 0:
            parts.append("".join(buf).strip())
            buf = []
            continue
        buf.append(ch)
    tail = "".join(buf).strip()
    if tail:
        parts.append(tail)
    return parts


_YAML_ESCAPES = {
    "n": "\n",
    "t": "\t",
    "r": "\r",
    "0": "\0",
    '"': '"',
    "\\": "\\",
}


def _unescape_double(text: str) -> str:
    """Раскодировать escape-последовательности двойных кавычек."""
    out = []
    i = 0
    while i < len(text):
        ch = text[i]
        if ch == "\\" and i + 1 < len(text):
            nxt = text[i + 1]
            if nxt in _YAML_ESCAPES:
                out.append(_YAML_ESCAPES[nxt])
                i += 2
                continue
        out.append(ch)
        i += 1
    return "".join(out)


def _scalar(token: str, source: str, lineno: int, column: int = 1):
    value = token.strip()
    if value == "":
        return None
    if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
        return _unescape_double(value[1:-1])
    if len(value) >= 2 and value[0] == "'" and value[-1] == "'":
        return value[1:-1].replace("''", "'")
    if value.startswith("["):
        if not value.endswith("]"):
            raise _yaml_error(source, lineno, column, "незакрытый inline-список '['")
        inner = value[1:-1].strip()
        if not inner:
            return []
        return [_scalar(part, source, lineno, column) for part in _split_commas(inner)]
    if value.startswith("{"):
        if value == "{}":
            return {}
        raise _yaml_error(
            source,
            lineno,
            column,
            "inline-словари '{...}' не поддерживаются — запишите блоком с отступом",
        )
    low = value.lower()
    if low in ("null", "~", "none"):
        return None
    if low in ("true", "yes"):
        return True
    if low in ("false", "no"):
        return False
    if _INT_RE.match(value):
        return int(value)
    if _FLOAT_RE.match(value):
        return float(value)
    return value


def _split_key(content: str, source: str, lineno: int, column: int = 1):
    quote = None
    for idx, ch in enumerate(content):
        if quote:
            if ch == quote:
                quote = None
            continue
        if ch in "\"'":
            quote = ch
            continue
        if ch == ":":
            key = content[:idx].strip()
            rest = content[idx + 1 :].strip()
            if not key:
                raise _yaml_error(
                    source, lineno, column + idx, "пустой ключ перед ':'"
                )
            if len(key) >= 2 and key[0] == key[-1] and key[0] in "\"'":
                key = key[1:-1]
            return key, rest
    raise _yaml_error(
        source,
        lineno,
        column,
        f"ожидался формат 'ключ: значение', получено: {content!r}",
    )


def _parse_map(tokens, i, indent, source):
    result = {}
    while i < len(tokens):
        ind, content, lineno = tokens[i]
        if ind < indent:
            break
        if ind > indent:
            raise _yaml_error(
                source,
                lineno,
                ind + 1,
                f"неожиданный отступ {ind} (ожидался {indent})",
            )
        if content == "-" or content.startswith("- "):
            raise _yaml_error(
                source,
                lineno,
                ind + 1,
                "элемент списка внутри словаря без ключа-родителя",
            )
        key, rest = _split_key(content, source, lineno, ind + 1)
        i += 1
        if rest == "":
            if i < len(tokens) and tokens[i][0] > indent:
                value, i = _parse_block(tokens, i, tokens[i][0], source)
            else:
                value = None
        else:
            value = _scalar(rest, source, lineno, ind + 1)
            if i < len(tokens) and tokens[i][0] > indent:
                raise _yaml_error(
                    source,
                    tokens[i][2],
                    tokens[i][0] + 1,
                    f"неожиданный отступ — значение уже задано в строке {lineno}",
                )
        if key in result:
            raise _yaml_error(
                source, lineno, ind + 1, f"повторяющийся ключ {key!r}"
            )
        result[key] = value
    return result, i


def _parse_list(tokens, i, indent, source):
    items = []
    while i < len(tokens):
        ind, content, lineno = tokens[i]
        if ind < indent:
            break
        if ind > indent:
            raise _yaml_error(
                source,
                lineno,
                ind + 1,
                f"неожиданный отступ {ind} (ожидался {indent})",
            )
        if not (content == "-" or content.startswith("- ")):
            break
        rest = content[1:].strip()
        if rest == "":
            i += 1
            if i < len(tokens) and tokens[i][0] > indent:
                value, i = _parse_block(tokens, i, tokens[i][0], source)
            else:
                value = None
            items.append(value)
            continue
        if _MAP_ITEM_RE.match(rest):
            tokens[i] = [indent + 2, rest, lineno]
            value, i = _parse_map(tokens, i, indent + 2, source)
            items.append(value)
        else:
            items.append(_scalar(rest, source, lineno, ind + 3))
            i += 1
    return items, i


def _parse_block(tokens, i, indent, source):
    if i >= len(tokens):
        return None, i
    if tokens[i][0] < indent:
        return None, i
    content = tokens[i][1]
    if content == "-" or content.startswith("- "):
        return _parse_list(tokens, i, indent, source)
    return _parse_map(tokens, i, indent, source)


def parse_yaml(text: str, source: str = "<string>"):
    """Разобрать YAML. Ошибки — YamlError с файлом, строкой и колонкой."""
    tokens = _tokenize(text, source)
    if not tokens:
        return {}
    data, index = _parse_block(tokens, 0, tokens[0][0], source)
    if index != len(tokens):
        raise _yaml_error(
            source,
            tokens[index][2],
            tokens[index][0] + 1,
            f"не удалось разобрать строку: {tokens[index][1]!r}",
        )
    return data


def load_yaml(path: Path):
    text = Path(path).read_text(encoding="utf-8")
    if _pyyaml is not None:
        try:
            return _pyyaml.load(text, Loader=_SSOT_LOADER)
        except _pyyaml.MarkedYAMLError as exc:  # type: ignore[attr-defined]
            mark = exc.problem_mark or exc.context_mark
            if mark is not None:
                raise YamlError(
                    f"{path}:{mark.line + 1}:{mark.column + 1}: "
                    f"{exc.problem or exc.context}"
                ) from exc
            raise YamlError(f"{path}: {exc}") from exc
        except Exception as exc:  # noqa: BLE001 - сообщение PyYAML информативно
            raise YamlError(f"{path}: {exc}") from exc
    return parse_yaml(text, str(path))

