ID_RE = re.compile(
    r"^sber\.ecom\.(?P<contour>[a-z0-9][a-z0-9-]*)"
    r"\.criticality_passport\.(?P<name>[a-z0-9][a-z0-9-]*)$"
)
DATE_RE = re.compile(r"^(\d{4})[.\-](\d{2})[.\-](\d{2})$")
CODE_RE = re.compile(r"^[a-z0-9][a-z0-9-]*\.(?:mm|smkt|[a-z0-9-]+)$")

