class Report:
    """Копилка ERROR/WARN для validate."""

    def __init__(self):
        self.errors = []
        self.warns = []

    def error(self, where: str, message: str):
        self.errors.append((where, message))

    def warn(self, where: str, message: str):
        self.warns.append((where, message))


def parse_date(value) -> dt.date:
    """Разобрать дату в формате YYYY.MM.DD или YYYY-MM-DD."""
    text = str(value).strip()
    match = DATE_RE.match(text)
    if not match:
        raise ValueError(
            f"дата {text!r} не в формате YYYY.MM.DD или YYYY-MM-DD"
        )
    year, month, day = (int(part) for part in match.groups())
    try:
        return dt.date(year, month, day)
    except ValueError as exc:
        raise ValueError(f"некорректная дата {text!r}: {exc}") from exc


def fmt_date(value) -> str:
    if value is None or value == "":
        return "—"
    try:
        return parse_date(value).isoformat()
    except ValueError:
        return str(value)


def today() -> dt.date:
    return dt.date.today()


def _atomic_write(path, text, encoding="utf-8"):
    """Записать файл атомарно: temp в той же папке → fsync → os.replace.

    Обрыв процесса (сигнал, `File too large`, нехватка места) не оставляет
    обрезанный файл: оригинал заменяется только целиком, а при ошибке
    временный файл удаляется. Права существующего файла сохраняются,
    у нового — 0644 (mkstemp создаёт 0600).
    """
    path = Path(path)
    parent = path.parent
    parent.mkdir(parents=True, exist_ok=True)
    try:
        mode = stat.S_IMODE(path.stat().st_mode)
    except FileNotFoundError:
        mode = 0o644
    fd, tmp_name = tempfile.mkstemp(
        dir=str(parent), prefix=f".{path.name}.", suffix=".tmp"
    )
    tmp = Path(tmp_name)
    try:
        with os.fdopen(fd, "w", encoding=encoding) as handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    except BaseException:
        try:
            if tmp.exists():
                tmp.unlink()
        except OSError:  # pragma: no cover - уборка не должна маскировать ошибку
            pass
        raise
    return path


def add_months(source: dt.date, months: int) -> dt.date:
    month_index = source.month - 1 + months
    year = source.year + month_index // 12
    month = month_index % 12 + 1
    day = min(source.day, [31, 29 if year % 4 == 0 and (year % 100 or year % 400 == 0) else 28,
                           31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1])
    return dt.date(year, month, day)


PROJECT_ROOT_MARKERS = ("catalog.yaml", "is.example.yaml", ".git")


def _looks_like_project_root(path: Path) -> bool:
    try:
        return any((path / marker).exists() for marker in PROJECT_ROOT_MARKERS)
    except OSError:  # pragma: no cover - недоступный каталог
        return False


def _find_project_root_upwards(start: Path):
    """Первый каталог вверх по дереву, похожий на корень проекта."""
    current = start.resolve()
    for candidate in (current, *current.parents):
        if _looks_like_project_root(candidate):
            return candidate
    return None


def resolve_project_root(explicit=None) -> Path:
    """Корень проекта с данными (is/, catalog.yaml, INDEX.md, docs/).

    Порядок: --root → env CRITICALITY_ROOT → подъём от cwd → подъём от
    SKILL_DIR. Если ничего не найдено — YamlError с подсказкой про --root.
    """
    if explicit:
        return Path(explicit).expanduser().resolve()
    env = os.environ.get("CRITICALITY_ROOT")
    if env:
        return Path(env).expanduser().resolve()
    found = _find_project_root_upwards(Path.cwd())
    if found is not None:
        return found
    found = _find_project_root_upwards(SKILL_DIR)
    if found is not None:
        return found
    raise YamlError(
        "не найден корень проекта: нет catalog.yaml/is.example.yaml; укажите --root"
    )


def repo_root(path_arg=None) -> Path:
    return resolve_project_root(path_arg)


def repo_root_from_args(args) -> Path:
    """Корень проекта из разобранных аргументов: --root приоритетнее --path."""
    return resolve_project_root(
        getattr(args, "root", None) or getattr(args, "path", None)
    )


def _clone_abs(value, default=None) -> Path:
    """Абсолютный путь клона: относительный `--ssot`/`--dochub` не ломает git.

    Путь клона уходит в git дважды — как `cwd` процесса и как `-C <путь>`.
    Относительный путь разрешается от cwd родителя, поэтому `-C ssot` внутри
    процесса с `cwd=ssot` указывает на `ssot/ssot` и git падает с
    `fatal: cannot change to 'ssot'`. Приводим к абсолютному один раз здесь.
    """
    raw = value if value not in (None, "") else default
    if raw in (None, ""):
        raise YamlError("не задан путь клона")
    return Path(str(raw)).expanduser().resolve()


def _root_is_explicit(args) -> bool:
    """Корень задан явно (--root/--path) или через CRITICALITY_ROOT."""
    return bool(
        getattr(args, "root", None)
        or getattr(args, "path", None)
        or os.environ.get("CRITICALITY_ROOT")
    )


def print_project_root(root: Path, args=None) -> None:
    """Напечатать корень данных и предупредить о «чужом» корне.

    Корень ищется подъёмом от cwd, затем от каталога скилла. Второй фолбэк
    может молча выбрать другой проект (например, при запуске из пустого
    каталога рядом с репозиторием) — поэтому корень печатается всегда, а
    несовпадение с cwd показывается WARN.
    """
    print(f"Корень: {root}")
    if args is not None and _root_is_explicit(args):
        return
    try:
        cwd = Path.cwd().resolve()
    except OSError:  # pragma: no cover - недоступный cwd
        return
    if cwd == root or root in cwd.parents:
        return
    print(
        f"WARN: корень проекта {root} не совпадает с текущим каталогом {cwd} — "
        "данные читаются из первого; чтобы выбрать другой корень, укажите --root"
    )


def _validate_catalog_path(root: Path, entry) -> None:
    """`systems[].path` — только относительный путь внутри корня репозитория.

    Без проверки абсолютный путь или `..` уводит запись (DATA-REQUIREMENTS.*,
    паспорт) за пределы проекта.
    """
    raw = entry.get("path")
    if raw in (None, ""):
        return
    text = str(raw)
    code = entry.get("code")
    pure = Path(text)
    inside = True
    if pure.is_absolute() or ".." in pure.parts:
        inside = False
    else:
        try:
            (root / pure).resolve().relative_to(root.resolve())
        except ValueError:
            inside = False
    if not inside:
        raise YamlError(
            f"некорректный path у ИС {code}: {text} "
            "(должен быть внутри репозитория)"
        )


# Поля-ссылки на страницы Confluence в catalog.yaml (page_id или null).
#   architecture_page_id — страница архитектуры ИС: подставляется в публикацию
#     вместо АДР, когда АДР не найдена (actions.adr_basis = architecture);
#   product_scope_page_id — страница Product scope продукта: источник
#     E2E-процессов и функциональных областей (top-level, переопределяется
#     в записи ИС).
CATALOG_PAGE_FIELDS = (
    ("architecture_page_id", "страницы архитектуры ИС"),
    ("product_scope_page_id", "страницы Product scope продукта"),
)


def catalog_page_id_problem(value):
    """page_id в catalog.yaml: целое > 0 (или строка цифр); None — проблема."""
    if value in (None, ""):
        return None
    if isinstance(value, bool):
        return f"{value!r} — ожидался page_id (целое число) или null"
    if isinstance(value, int):
        if value <= 0:
            return f"{value!r} — page_id должен быть > 0"
        return None
    text = str(value).strip()
    if text.isdigit() and int(text) > 0:
        return None
    return f"{value!r} — ожидался page_id (целое число) или null"


def load_catalog(root: Path):
    """Вернуть (catalog_dict, systems_list). Бросает YamlError/SystemExit-текст."""
    path = root / "catalog.yaml"
    if not path.exists():
        raise YamlError(f"{path}: файл реестра не найден")
    data = load_yaml(path)
    if not isinstance(data, dict):
        raise YamlError(f"{path}: ожидался словарь верхнего уровня")
    systems = data.get("systems")
    if systems is None:
        systems = []
    if not isinstance(systems, list):
        raise YamlError(f"{path}: ключ 'systems' должен быть списком")
    for index, entry in enumerate(systems, 1):
        if not isinstance(entry, dict):
            raise YamlError(f"{path}: systems[{index}] должен быть словарём")
        if not entry.get("code"):
            raise YamlError(f"{path}: systems[{index}] без поля 'code'")
        _validate_catalog_path(root, entry)
    return data, systems


def catalog_by_code(systems):
    return {entry["code"]: entry for entry in systems if entry.get("code")}


def split_is_code(code):
    """Единая точка разбора кода ИС: 'erm.mm' -> ('erm', 'mm').

    Контур — часть после **последней** точки (код ИС = <name_is>.<контур>).
    Без точки -> (code, '').
    """
    text = str(code).strip()
    if "." in text:
        name, contour = text.rsplit(".", 1)
        return name, contour
    return text, ""


def passport_path(root: Path, entry) -> Path:
    return root / str(entry.get("path", "")) / "criticality-passport.yaml"


def read_passport(path: Path):
    """Вернуть (object_id, body). Бросает YamlError с понятным текстом."""
    doc = load_yaml(path)
    if not isinstance(doc, dict):
        raise YamlError(f"{path}: ожидался словарь верхнего уровня")
    section = doc.get("ecom.criticality_passport")
    if not isinstance(section, dict) or not section:
        raise YamlError(f"{path}: нет секции 'ecom.criticality_passport'")
    if len(section) != 1:
        raise YamlError(
            f"{path}: в 'ecom.criticality_passport' должен быть ровно один объект, "
            f"найдено {len(section)}"
        )
    object_id = next(iter(section))
    body = section[object_id]
    if not isinstance(body, dict):
        raise YamlError(f"{path}: объект {object_id} должен быть словарём")
    return object_id, body


def passport_body(root: Path, entry):
    """Тело паспорта ИС или None, если файла нет."""
    path = passport_path(root, entry)
    if not path.exists():
        return None
    try:
        _, body = read_passport(path)
        return body
    except YamlError:
        return None


def effective(entry, body, field, default=None):
    """Значение из паспорта, иначе из реестра."""
    if body is not None and body.get(field) is not None:
        return body.get(field)
    value = entry.get(field, default)
    return value


def effective_review_date(entry, body):
    """Дата текущей оценки: реестр → паспорт → None.

    `catalog.yaml → review_date` — версионируемый источник даты переоценки;
    паспорт хранит её копию. До фикса C1 в копию попадала дата генерации, и
    копия маскировала просрочку (`make due` показывал «0 просрочено» при пяти
    просроченных ИС). Поэтому реестр в приоритете, а отсутствие значения НЕ
    подменяется датой генерации: None означает «дата оценки не зафиксирована».
    """
    entry = entry or {}
    raw = entry.get("review_date")
    if raw not in (None, ""):
        return raw
    if body is not None and body.get("review_date") not in (None, ""):
        return body.get("review_date")
    return None


def review_date_source(entry, info=None, existing=None):
    """(дата, подпись источника) текущей оценки для паспорта.

    Приоритет: `catalog.yaml → review_date` → `INFORMATION.yaml → history` →
    `criticality-passport.yaml → review_date` (перенос уже зафиксированной
    даты). Дата генерации (`--date`) источником НЕ является: если ни одного
    источника нет, возвращается (None, None) и в паспорт пишется null.
    """
    entry = entry or {}
    raw = entry.get("review_date")
    if raw not in (None, ""):
        try:
            return parse_date(raw), "catalog.yaml → review_date"
        except ValueError:
            pass
    history = (info or {}).get("history")
    if isinstance(history, list):
        for item in reversed(history):
            if not isinstance(item, dict):
                continue
            value = (
                item.get("date")
                or item.get("assessed_date")
                or item.get("review_date")
            )
            if value in (None, ""):
                continue
            try:
                return parse_date(value), "INFORMATION.yaml → history"
            except ValueError:
                continue
    if isinstance(existing, dict):
        raw = existing.get("review_date")
        if raw not in (None, ""):
            try:
                return (
                    parse_date(raw),
                    "criticality-passport.yaml → review_date (перенос)",
                )
            except ValueError:
                pass
    return None, None


def review_period(catalog, entry, criteria=None) -> int:
    """Период переоценки ИС в месяцах.

    Приоритет: `review_period_months` системы → `review_period_months_default`
    реестра → `criteria.staleness.review_period_months` (единственное правило
    периодичности в критериях) → 12.
    """
    value = entry.get("review_period_months")
    if value in (None, ""):
        value = catalog.get("review_period_months_default")
    if value in (None, ""):
        value = ((criteria or {}).get("staleness") or {}).get("review_period_months")
    if value in (None, ""):
        value = 12
    try:
        return int(value)
    except (TypeError, ValueError):
        return 12


def due_date(review, months: int) -> dt.date:
    """Дата, к которой переоценка должна быть выполнена."""
    return add_months(review, months)


def review_staleness(entry, body, catalog=None, criteria=None, reference=None):
    """(review_date, due_date, overdue) — просрочка по `due_date = review_date + период`.

    `review_date` — дата **текущей** оценки (реестр → паспорт), а не дата, к
    которой переоценка должна быть сделана. Поэтому просрочка наступает только
    когда `due_date` (review_date + период переоценки) стала раньше `reference`:
    ровно в день `due_date` переоценка ещё не просрочена, на следующий день —
    просрочена. Сравнение `review_date < reference` давало ложную просрочку на
    следующий день после любой переоценки (дефект: validate спорил с `due`).

    Возвращает `(None, None, False)`, если дата оценки не зафиксирована или не
    разбирается — «нет даты» не равно «просрочено».
    """
    raw = effective_review_date(entry, body)
    if raw in (None, ""):
        return None, None, False
    try:
        review = parse_date(raw)
    except ValueError:
        return None, None, False
    due = due_date(review, review_period(catalog or {}, entry or {}, criteria))
    return review, due, due < (reference or today())


def parse_date_arg(value, flag: str) -> dt.date:
    """Разобрать дату из аргумента CLI; ValueError с понятным текстом."""
    try:
        return parse_date(value)
    except ValueError:
        raise ValueError(
            f"неверный формат даты {value!r} для {flag}: "
            "ожидалось YYYY-MM-DD или YYYY.MM.DD"
        ) from None


def _approve_link_domains(criteria):
    """Домены ссылок подтверждения: criteria.external_refs.approve_link_domains."""
    block = (criteria or {}).get("external_refs") or {}
    if not isinstance(block, dict):
        return []
    domains = block.get("approve_link_domains")
    if not isinstance(domains, list):
        return []
    return [str(item).strip().lower() for item in domains if str(item or "").strip()]


def approve_link_problem(value, criteria=None):
    """Вернуть текст проблемы со ссылкой подтверждения или None.

    Домены — из criteria.external_refs.approve_link_domains; список не задан —
    проверяется только схема http(s), чтобы скилл работал в другом контуре.
    Относительная ссылка RocketChat (`/link?rid=...&msg=...`, `/channel/...`)
    принимается: домен у неё тот же инстанс, что и у абсолютной.
    """
    text = str(value).strip()
    if text.startswith(("/link?", "/channel/", "/group/")):
        return None
    if not text.startswith(("http://", "https://")):
        return "не похоже на ссылку http(s)"
    domains = _approve_link_domains(criteria)
    if domains:
        host = (urlsplit(text).hostname or "").lower()
        if not any(host == item or host.endswith("." + item) for item in domains):
            return (
                "домен не из criteria.external_refs.approve_link_domains "
                f"({', '.join(domains)}) — {APPROVE_URL_HINT}"
            )
    return None


def read_frontmatter(path: Path):
    """Разобрать YAML-frontmatter Markdown-файла.

    Возвращает (data, key_lines, body_start_line), где key_lines — номер строки
    файла для каждого ключа, body_start_line — номер строки после закрывающего
    `---`. Бросает YamlError с понятным текстом.
    """
    text = Path(path).read_text(encoding="utf-8")
    lines = text.splitlines()
    if not lines or lines[0].strip() != "---":
        raise YamlError(f"{path}: нет frontmatter (первая строка должна быть '---')")
    end = None
    for index in range(1, len(lines)):
        if lines[index].strip() in ("---", "..."):
            end = index
            break
    if end is None:
        raise YamlError(f"{path}: frontmatter не закрыт строкой '---'")
    fm_lines = lines[1:end]
    data = parse_yaml("\n".join(fm_lines), str(path))
    if not isinstance(data, dict):
        raise YamlError(f"{path}: frontmatter должен быть словарём")
    key_lines = {}
    for offset, raw in enumerate(fm_lines, 2):
        match = re.match(r"^([A-Za-z0-9_.\-]+)\s*:", raw)
        if match:
            key_lines.setdefault(match.group(1), offset)
    return data, key_lines, end + 1


def _check_criticality_md(
    report: Report, root: Path, md_path: Path, code, body, by_code, criteria=None
):
    """Проверить человекочитаемый паспорт CRITICALITY.md."""
    rel = md_path.relative_to(root).as_posix()
    if not md_path.exists():
        report.error(rel, "нет файла CRITICALITY.md (человекочитаемого паспорта)")
        return

    try:
        data, key_lines, _ = read_frontmatter(md_path)
    except (YamlError, OSError) as exc:
        report.error(rel, f"frontmatter не разобран: {exc}")
        return

    def at(key):
        line = key_lines.get(key)
        return f"{rel}:{line}" if line else rel

    if data.get("is_code") != code:
        report.error(
            at("is_code"),
            f"is_code={data.get('is_code')!r}, ожидалось {code!r}",
        )

    body = body or {}
    yaml_crit = body.get("object_criticality_estimation")
    if data.get("criticality") != yaml_crit:
        report.error(
            at("criticality"),
            f"criticality={data.get('criticality')!r} ≠ object_criticality_estimation "
            f"{yaml_crit!r} из criticality-passport.yaml",
        )

    entry = by_code.get(code)
    catalog_ssot = entry.get("criticality_ssot") if entry else None
    if catalog_ssot is not None and data.get("criticality_ssot") != catalog_ssot:
        report.error(
            at("criticality_ssot"),
            f"criticality_ssot={data.get('criticality_ssot')!r} ≠ "
            f"criticality_ssot={catalog_ssot!r} из catalog.yaml",
        )

    status = data.get("status")
    if status not in ("draft", "confirmed"):
        report.error(
            at("status"),
            f"status={status!r} (допустимо draft/confirmed)",
        )

    approve = data.get("approve_link")
    if status == "confirmed" and not approve:
        report.error(
            at("status"),
            "status=confirmed, но approve_link пуст — нет ссылки на тред "
            "согласования (сделайте make handoff)",
        )
    if approve:
        problem = approve_link_problem(approve, criteria)
        if problem:
            report.warn(at("approve_link"), f"approve_link={approve!r}: {problem}")

    tags = data.get("tags")
    if not isinstance(tags, list):
        report.error(at("tags"), "tags должен быть списком")
    else:
        for tag in tags:
            text = "" if tag is None else str(tag)
            if text != text.lower():
                report.error(
                    at("tags"),
                    f"тег {text!r} содержит заглавные буквы — теги только строчными",
                )
            elif not TAG_RE.match(text):
                report.error(
                    at("tags"),
                    f"тег {text!r} содержит недопустимые символы "
                    "(разрешены строчные буквы, цифры и дефис)",
                )

    text = md_path.read_text(encoding="utf-8")
    headings = [
        (lineno, line.strip())
        for lineno, line in enumerate(text.splitlines(), 1)
        if line.startswith("## ")
    ]
    positions = {}
    for lineno, heading in headings:
        positions.setdefault(heading, lineno)
    last = 0
    for expected in CRITICALITY_MD_SECTIONS:
        if expected not in positions:
            report.error(rel, f"нет обязательного раздела {expected!r}")
            continue
        lineno = positions[expected]
        if lineno < last:
            report.error(
                f"{rel}:{lineno}",
                f"раздел {expected!r} стоит не в том порядке",
            )
        last = lineno


def _check_cyrillic_codes(report: Report, root: Path):
    """Найти кириллические буквы в кодах продукта (Е001, А10, …).

    Клоны (apps/, ssot/, dochub/) — чужие репозитории, а не данные проекта:
    их коды не наши, поэтому внутрь не заходим (иначе `validate` падает на
    чужом YAML и перестаёт быть проверкой этого репозитория).
    """
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = sorted(
            name
            for name in dirnames
            if name not in CLONE_DIRS and name != ".git"
        )
        for name in sorted(filenames):
            path = Path(dirpath) / name
            if path.suffix.lower() not in TEXT_SUFFIXES:
                continue
            try:
                text = path.read_text(encoding="utf-8")
            except (UnicodeDecodeError, OSError):
                continue
            rel = path.relative_to(root).as_posix()
            for lineno, line in enumerate(text.splitlines(), 1):
                match = CYRILLIC_CODE_RE.search(line)
                if match:
                    report.error(
                        f"{rel}:{lineno}",
                        f"кириллическая буква в коде продукта: {match.group(0)!r} "
                        "(коды набираются латиницей)",
                    )


def _language_findings(root: Path, systems):
    """Свободный текст не на русском в ручных данных ИС (R16) → список WARN.

    Проверяются только человеко-прозаические поля: `catalog.yaml`
    (`systems[].notes`, `systems[].reason` при `excluded: true`),
    `INFORMATION.yaml` (`notes[]` и `conflicts[].note`) и
    `DATA-REQUIREMENTS.yaml` (`inputs.*.source.ref`, `inputs.*.source.note`,
    `inputs.*.notes`). Идентификаторы и enum-значения отсеивает
    `_prose_language_problem`: это предупреждение о языке, а не о факте,
    поэтому значение не отбрасывается и прогон не блокируется.
    """
    findings = []

    def check(where: str, field: str, value):
        if isinstance(value, list):
            for index, item in enumerate(value):
                check(where, f"{field}[{index}]", item)
            return
        problem = _prose_language_problem(value)
        if problem is not None:
            findings.append(
                (
                    where,
                    f"{field} заполнен не на русском — ожидается русский текст: "
                    f'"{problem}"',
                )
            )

    for entry in systems or []:
        code = entry.get("code")
        check("catalog.yaml", f"systems[{code}].notes", entry.get("notes"))
        if entry.get("excluded") is True:
            check("catalog.yaml", f"systems[{code}].reason", entry.get("reason"))

    for entry in systems or []:
        code = str(entry.get("code") or "")
        if not code:
            continue
        folder_rel, _legacy = is_folder(root, code, entry)
        info_path = root / folder_rel / INFORMATION_FILE
        if info_path.is_file():
            rel = info_path.relative_to(root).as_posix()
            try:
                info = load_yaml(info_path)
            except (YamlError, OSError):
                info = None
            if isinstance(info, dict):
                notes = info.get("notes")
                if isinstance(notes, list):
                    for index, item in enumerate(notes):
                        if isinstance(item, dict):
                            # Структура `notes[]` не зафиксирована шаблоном:
                            # поддерживаются оба встречающихся ключа прозы.
                            for key in ("text", "note"):
                                check(rel, f"notes[{index}].{key}", item.get(key))
                        else:
                            check(rel, f"notes[{index}]", item)
                conflicts = info.get("conflicts")
                if isinstance(conflicts, list):
                    for index, item in enumerate(conflicts):
                        if isinstance(item, dict):
                            check(rel, f"conflicts[{index}].note", item.get("note"))
        sheet_path = root / folder_rel / DATA_REQUIREMENTS_YAML
        if not sheet_path.is_file():
            continue
        rel_sheet = sheet_path.relative_to(root).as_posix()
        try:
            sheet = load_yaml(sheet_path)
        except (YamlError, OSError):
            continue
        inputs = sheet.get("inputs") if isinstance(sheet, dict) else None
        if not isinstance(inputs, dict):
            continue
        for identifier, block in inputs.items():
            if not isinstance(block, dict):
                continue
            source = block.get("source")
            if isinstance(source, dict):
                check(
                    rel_sheet,
                    f"inputs.{identifier}.source.ref",
                    source.get("ref"),
                )
                check(
                    rel_sheet,
                    f"inputs.{identifier}.source.note",
                    source.get("note"),
                )
            check(rel_sheet, f"inputs.{identifier}.notes", block.get("notes"))
    return findings


# Символы, с которых не может начинаться plain-скаляр YAML.
_PLAIN_START_FORBIDDEN = "-?:,[]{}#&*!|>'\"%@`"
# Строки, которые YAML трактует как null/bool, а не как текст.
_YAML_AMBIGUOUS = ("null", "~", "none", "true", "false", "yes", "no", "on", "off")


def _yaml_needs_quotes(text: str) -> bool:
    """Единый набор условий квотирования для записи и для каталога.

    Квотируем всё, что YAML иначе прочитает не как строку или разберёт
    неверно: ": " (разделитель ключа), " #" (комментарий), начало с
    YAML-спецсимвола, конец с ":", перевод строки/табуляцию, числа,
    bool/null-подобные слова и пустую строку.
    """
    if text == "":
        return True
    return (
        text != text.strip()
        or ": " in text
        or " #" in text
        or "\n" in text
        or "\r" in text
        or "\t" in text
        or text.endswith(":")
        or text[0] in _PLAIN_START_FORBIDDEN
        or text.lower() in _YAML_AMBIGUOUS
        or bool(_INT_RE.match(text))
        or bool(_FLOAT_RE.match(text))
        or bool(_SEXAGESIMAL_RE.match(text))
    )


def _yaml_quote(text: str) -> str:
    """Двойные кавычки + escape-последовательности; round-trip без потерь.

    Переводы строк и табуляция кодируются как `\\n` / `\\t`, поэтому
    мини-парсер и PyYAML возвращают исходное значение (а не строку с
    пробелом вместо перевода строки).
    """
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    text = text.replace("\\", "\\\\").replace('"', '\\"')
    text = text.replace("\n", "\\n").replace("\t", "\\t")
    return '"' + text + '"'


def yaml_scalar(value) -> str:
    """Отрендерить скаляр для записи в catalog.yaml."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return str(value)
    if isinstance(value, list):
        return "[" + ", ".join(yaml_scalar(item) for item in value) + "]"
    text = str(value)
    if _yaml_needs_quotes(text):
        return _yaml_quote(text)
    return text


# --- запись YAML (только блок-стиль, разбираемый мини-парсером) -------------

_SAFE_KEY_RE = re.compile(r"^[A-Za-z0-9_.\-]+$")


def dump_scalar(value) -> str:
    """Отрендерить значение так, чтобы мини-парсер вернул его обратно.

    Набор условий квотирования совпадает с `yaml_scalar`: иначе строка вида
    "backend: основной сервис" писалась бы plain-скаляром и ломала файл.
    """
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return repr(value)
    if isinstance(value, list):
        if not value:
            return "[]"
        return "[" + ", ".join(dump_scalar(item) for item in value) + "]"
    if isinstance(value, dict):
        if not value:
            return "{}"
        raise YamlError("вложенный словарь нельзя записать в строку — нужен блок")
    text = str(value).replace("\r\n", "\n").replace("\r", "\n")
    if _yaml_needs_quotes(text):
        return _yaml_quote(text)
    return text


def dump_key(key) -> str:
    text = str(key)
    if _SAFE_KEY_RE.match(text) and text.lower() not in (
        "null", "true", "false", "yes", "no", "none", "~", "on", "off"
    ):
        return text
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"') + '"'


def _dump_mapping(data, indent, lines):
    pad = " " * indent
    for key, value in data.items():
        key_text = dump_key(key)
        if isinstance(value, dict) and value:
            lines.append(f"{pad}{key_text}:")
            _dump_mapping(value, indent + 2, lines)
        elif isinstance(value, list) and value:
            lines.append(f"{pad}{key_text}:")
            _dump_sequence(value, indent + 2, lines)
        else:
            lines.append(f"{pad}{key_text}: {dump_scalar(value)}")


def _dump_sequence(items, indent, lines):
    pad = " " * indent
    for item in items:
        if isinstance(item, (dict, list)) and item:
            lines.append(f"{pad}-")
            if isinstance(item, dict):
                _dump_mapping(item, indent + 2, lines)
            else:
                _dump_sequence(item, indent + 2, lines)
        else:
            lines.append(f"{pad}- {dump_scalar(item)}")


def dump_yaml(data) -> str:
    """Сериализовать структуру в YAML блок-стилем (детерминированно)."""
    lines = []
    if isinstance(data, dict):
        _dump_mapping(data, 0, lines)
    elif isinstance(data, list):
        _dump_sequence(data, 0, lines)
    else:
        lines.append(dump_scalar(data))
    return "\n".join(lines) + "\n"

# ---------------------------------------------------------------------------
# Мини-движок шаблонов (stdlib, без внешних зависимостей)
# ---------------------------------------------------------------------------
# Синтаксис:
#   {{ path.to.value }}                  подстановка; отсутствующий путь — ERROR
#   {{ path | default: "текст" }}        значение по умолчанию
#   {{ path | or_missing }}              null/пусто -> «⛔ не заполнено»
#   {{ path | or_missing: null }}        null/пусто -> литерал (null, «—», …)
#   {{ path | yaml }}                    значение как YAML-скаляр (null, кавычки)
#   {{#if path}}...{{else}}...{{/if}}    ветвление
#   {{#each list}}...{{/each}}           цикл по списку: {{ .field }}, {{ @index }}
#   {{#each map}}...{{/each}}            цикл по словарю: {{ @key }}, {{ . }}
#   {{! комментарий }}                   не выводится
#
# Строгий режим: неизвестный путь в подстановке — ошибка шаблона, а не пустая
# строка. Для необязательных полей обязателен фильтр (`or_missing`/`default`).

MISSING_MARK = "⛔ не заполнено"

# `actions.<ключ>` внутри плейсхолдера — включая `{{#if actions.x}}` и
# `{{#each actions.x}}`. Нужен для проверки согласованности шаблонов и словаря
# контекста (`_template_action_key_problems`).
ACTIONS_REF_RE = re.compile(r"\{\{[^{}]*?actions\.([A-Za-z_][A-Za-z0-9_]*)")


class TemplateError(Exception):
    """Ошибка шаблона: файл, строка, причина."""


class _TplText:
    __slots__ = ("text",)

    def __init__(self, text):
        self.text = text


class _TplVar:
    __slots__ = ("path", "filters", "line")

    def __init__(self, path, filters, line):
        self.path = path
        self.filters = filters
        self.line = line


class _TplIf:
    __slots__ = ("path", "then", "other", "line")

    def __init__(self, path, line):
        self.path = path
        self.then = []
        self.other = []
        self.line = line


class _TplEach:
    __slots__ = ("path", "body", "line")

    def __init__(self, path, line):
        self.path = path
        self.body = []
        self.line = line


def _tpl_split_filters(expr):
    parts = []
    buf = []
    quote = None
    for ch in expr:
        if quote:
            buf.append(ch)
            if ch == quote:
                quote = None
            continue
        if ch in "\"'":
            quote = ch
            buf.append(ch)
            continue
        if ch == "|":
            parts.append("".join(buf))
            buf = []
            continue
        buf.append(ch)
    parts.append("".join(buf))
    return [part.strip() for part in parts]


def _tpl_parse_filter(text):
    if ":" in text:
        name, arg = text.split(":", 1)
        return name.strip(), arg.strip()
    return text.strip(), None


def _tpl_literal(arg):
    if arg is None:
        return None
    text = arg.strip()
    if len(text) >= 2 and text[0] == text[-1] and text[0] in "\"'":
        return text[1:-1]
    return text


def parse_template(text, name="<шаблон>"):
    """Разобрать шаблон в список узлов. Ошибки — TemplateError со строкой."""
    nodes = []
    stack = []
    target = nodes
    index = 0
    line = 1
    while True:
        start = text.find("{{", index)
        if start < 0:
            target.append(_TplText(text[index:]))
            break
        if start > index:
            chunk = text[index:start]
            target.append(_TplText(chunk))
            line += chunk.count("\n")
        end = text.find("}}", start + 2)
        if end < 0:
            raise TemplateError(
                f"шаблон {name}, строка {line}: незакрытый '{{{{'"
            )
        raw = text[start + 2:end]
        token_line = line
        line += raw.count("\n")
        index = end + 2
        token = raw.strip()
        if not token or token.startswith("!"):
            continue
        is_block = (
            token.startswith("#if ")
            or token.startswith("#each ")
            or token in ("else", "/if", "/each")
        )
        if is_block:
            # Блок-тег, стоящий отдельной строкой, съедает свою строку целиком:
            # отступ перед тегом и перевод строки после него. Проверка не должна
            # зависеть от типа предыдущего узла — иначе после {{/each}}/{{/if}}
            # перевод строки протекает в вывод и даёт лишнюю пустую строку.
            chunk = (
                target[-1].text
                if target and isinstance(target[-1], _TplText)
                else None
            )
            tail = "" if chunk is None else chunk.rsplit("\n", 1)[-1]
            if (chunk is None or tail.strip() == "") and text[index:index + 1] == "\n":
                if chunk is not None:
                    target[-1].text = chunk[: len(chunk) - len(tail)]
                index += 1
                line += 1
        if token.startswith("#if "):
            node = _TplIf(token[4:].strip(), token_line)
            target.append(node)
            stack.append(("if", node, target))
            target = node.then
            continue
        if token.startswith("#each "):
            node = _TplEach(token[6:].strip(), token_line)
            target.append(node)
            stack.append(("each", node, target))
            target = node.body
            continue
        if token == "else":
            if not stack or stack[-1][0] != "if":
                raise TemplateError(
                    f"шаблон {name}, строка {token_line}: '{{{{else}}}}' вне {{{{#if}}}}"
                )
            target = stack[-1][1].other
            continue
        if token in ("/if", "/each"):
            want = token[1:]
            if not stack or stack[-1][0] != want:
                raise TemplateError(
                    f"шаблон {name}, строка {token_line}: лишний '{{{{{token}}}}}'"
                )
            target = stack.pop()[2]
            continue
        if token.startswith("#"):
            raise TemplateError(
                f"шаблон {name}, строка {token_line}: неизвестная конструкция '{{{{{token}}}}}'"
            )
        parts = _tpl_split_filters(token)
        path = parts[0]
        filters = [_tpl_parse_filter(part) for part in parts[1:] if part]
        target.append(_TplVar(path, filters, token_line))
    if stack:
        kind, _node, _parent = stack[-1]
        raise TemplateError(
            f"шаблон {name}: не закрыт блок '#{kind}'"
        )
    return nodes


def _tpl_walk(current, parts):
    for part in parts:
        if isinstance(current, dict):
            if part not in current:
                return False, None
            current = current[part]
        elif isinstance(current, list) and part.isdigit():
            position = int(part)
            if position >= len(current):
                return False, None
            current = current[position]
        else:
            return False, None
    return True, current


def _tpl_resolve(path, root, frames):
    text = path.strip()
    if text in ("@index", "@key", "@first", "@last"):
        if not frames:
            return False, None
        frame = frames[-1]
        key = text[1:]
        return (frame.get(key) is not None), frame.get(key)
    if text == ".":
        if not frames:
            return False, None
        return True, frames[-1]["item"]
    if text.startswith("."):
        if not frames:
            return False, None
        return _tpl_walk(frames[-1]["item"], text[1:].split("."))
    return _tpl_walk(root, text.split("."))


def _tpl_truthy(value):
    if value is None or value is False:
        return False
    if isinstance(value, (str, list, dict)):
        return bool(value)
    return True


def _tpl_stringify(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, list):
        return ", ".join(_tpl_stringify(item) for item in value)
    if isinstance(value, dict):
        return ", ".join(f"{key}: {_tpl_stringify(val)}" for key, val in value.items())
    return str(value)


def _brief_source(value, limit=240):
    """Короткая подпись провенанса для человекочитаемых отчётов.

    Полная строка источника живёт в `INFORMATION.yaml`/`SOURCES-FINDINGS.yaml`;
    в отчёте нужен адрес, а не объяснение: `type: X, ref: Y` → `X: Y`,
    хвост-пояснение после `;` отрезается, сверх `limit` — усечение по границе
    слова. Ничего не выдумывает: только сокращает существующее значение.
    """
    text = _tpl_stringify(value).strip()
    match = re.match(r"^type:\s*([^,]+),\s*ref:\s*(.*)$", text, re.S)
    if match:
        text = f"{match.group(1).strip()}: {match.group(2).strip()}"
    text = text.split("; ")[0].strip()
    if len(text) > limit:
        cut = text[:limit]
        text = cut.rsplit(" ", 1)[0] + "…"
    return text


def _tpl_filter_arg(arg, root, frames):
    """Аргумент фильтра: литерал или путь `.field` относительно текущего элемента."""
    if arg is None:
        return None
    text = arg.strip()
    if text.startswith(".") and frames:
        found, value = _tpl_walk(frames[-1]["item"], text[1:].split("."))
        if found and value not in (None, "", [], {}):
            return _tpl_stringify(value)
        return None
    return _tpl_literal(arg)


def _tpl_apply_filters(value, found, filters, path, name, line, root=None, frames=None,
                       strict=False):
    if strict:
        # Строгий режим (описания MR): значение обязано быть непустым, а
        # фолбэки or_missing/default запрещены — иначе «нет данных» тихо
        # превращается в заглушку и MR уходит с пустым полем.
        if filters:
            raise TemplateError(
                f"шаблон {name}, строка {line}: фильтр {filters[0][0]!r} "
                "недопустим в строгом режиме (пустое значение — ошибка)"
            )
        empty = (
            (not found) or value is None or value == "" or value == []
            or value == {}
        )
        if empty:
            raise TemplateError(
                f"не заполнено поле '{path}' в шаблоне {name}"
            )
        return _tpl_stringify(value)
    for filter_name, arg in filters:
        empty = (not found) or value is None or value == "" or value == [] or value == {}
        if filter_name == "or_missing":
            if empty:
                literal = _tpl_filter_arg(arg, root, frames)
                return MISSING_MARK if literal is None else literal
            continue
        if filter_name == "default":
            if empty:
                literal = _tpl_filter_arg(arg, root, frames)
                return "" if literal is None else literal
            continue
        if filter_name == "yaml":
            return dump_scalar(value)
        if filter_name == "brief":
            return _brief_source(value)
        if filter_name == "upper":
            return _tpl_stringify(value).upper()
        if filter_name == "lower":
            return _tpl_stringify(value).lower()
        if filter_name == "md_cell":
            # Значение для ячейки markdown-таблицы: '|' и перевод строки внутри
            # цитаты/причины не должны ломать таблицу и создавать новую строку.
            return "" if empty else _md_cell(_tpl_stringify(value))
        raise TemplateError(
            f"шаблон {name}, строка {line}: неизвестный фильтр {filter_name!r}"
        )
    if not found:
        raise TemplateError(f"шаблон {name}, строка {line}: неизвестный путь {path}")
    if value is None:
        raise TemplateError(
            f"шаблон {name}, строка {line}: путь {path} = null "
            "(добавьте фильтр | or_missing или | yaml)"
        )
    return _tpl_stringify(value)


def _tpl_render_nodes(nodes, root, frames, name, strict=False):
    out = []
    for node in nodes:
        if isinstance(node, _TplText):
            out.append(node.text)
            continue
        if isinstance(node, _TplVar):
            found, value = _tpl_resolve(node.path, root, frames)
            out.append(
                _tpl_apply_filters(
                    value,
                    found,
                    node.filters,
                    node.path,
                    name,
                    node.line,
                    root=root,
                    frames=frames,
                    strict=strict,
                )
            )
            continue
        if isinstance(node, _TplIf):
            found, value = _tpl_resolve(node.path, root, frames)
            if strict and not found:
                raise TemplateError(
                    f"не заполнено поле '{node.path}' в шаблоне {name}"
                )
            branch = node.then if (found and _tpl_truthy(value)) else node.other
            out.append(_tpl_render_nodes(branch, root, frames, name, strict=strict))
            continue
        if isinstance(node, _TplEach):
            found, value = _tpl_resolve(node.path, root, frames)
            if not found:
                raise TemplateError(
                    f"шаблон {name}, строка {node.line}: неизвестный путь {node.path} "
                    "(#each требует существующую коллекцию)"
                )
            if strict and not value:
                raise TemplateError(
                    f"не заполнено поле '{node.path}' в шаблоне {name}"
                )
            if value is None:
                continue
            if isinstance(value, list):
                total = len(value)
                for position, item in enumerate(value):
                    frames.append(
                        {
                            "item": item,
                            "index": position,
                            "key": None,
                            "first": position == 0,
                            "last": position == total - 1,
                        }
                    )
                    out.append(
                        _tpl_render_nodes(node.body, root, frames, name, strict=strict)
                    )
                    frames.pop()
                continue
            if isinstance(value, dict):
                items = list(value.items())
                total = len(items)
                for position, (key, item) in enumerate(items):
                    frames.append(
                        {
                            "item": item,
                            "index": position,
                            "key": key,
                            "first": position == 0,
                            "last": position == total - 1,
                        }
                    )
                    out.append(
                        _tpl_render_nodes(node.body, root, frames, name, strict=strict)
                    )
                    frames.pop()
                continue
            raise TemplateError(
                f"шаблон {name}, строка {node.line}: #each по значению "
                f"типа {type(value).__name__} ({node.path})"
            )
    return "".join(out)


def render_template(text, context, name="<шаблон>"):
    """Отрендерить шаблон. Ошибки — TemplateError с файлом и строкой."""
    nodes = parse_template(text, name)
    return _tpl_render_nodes(nodes, context, [], name)


def render_template_file(path, context):
    path = Path(path)
    text = path.read_text(encoding="utf-8")
    return render_template(text, context, str(path))


def _mr_text_problems(text, template_text, name):
    """Проверки описания MR после рендера: без плейсхолдеров и пустых заглушек."""
    problems = []
    if "{{" in text or "}}" in text:
        problems.append("в результате остались незаполненные {{ }}")
    if MISSING_MARK in text:
        problems.append(f"в результате остался маркер «{MISSING_MARK}»")
    lines = [line.rstrip() for line in text.splitlines()]
    present = {line.strip() for line in lines}
    for raw in template_text.splitlines():
        stripped = raw.strip()
        if not stripped.startswith("#") or "{{" in stripped:
            continue
        if stripped not in present:
            problems.append(f"заголовок {stripped!r} потерян")
    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue
        if stripped in {"-", "—", "|", "| |", "||", "- [ ]", "- [ ] —"}:
            problems.append(f"пустая строка-заглушка: {stripped!r}")
            break
        if stripped.startswith("|") and "||" in stripped.replace(" ", ""):
            problems.append(f"пустая ячейка таблицы: {stripped!r}")
            break
    return problems


def render_template_file_strict(path, context):
    """Отрендерить описание MR: пустое поле — ошибка, MR не создаётся.

    Отличия от обычного рендера: значения обязаны быть непустыми, фолбэки
    (`or_missing`/`default`) запрещены, а результат проверяется на остатки
    `{{ }}`, маркер «⛔ не заполнено» и пустые строки-заглушки. Так описание
    MR не может уехать с «самодеятельной» вставкой вместо факта.
    """
    path = Path(path)
    if not path.exists():
        raise TemplateError(f"нет шаблона описания MR: {path}")
    text = path.read_text(encoding="utf-8")
    nodes = parse_template(text, str(path))
    rendered = _tpl_render_nodes(nodes, context, [], str(path), strict=True)
    problems = _mr_text_problems(rendered, text, str(path))
    if problems:
        raise TemplateError(
            f"шаблон {path}: " + "; ".join(problems)
        )
    return rendered


# ---------------------------------------------------------------------------
# start: генерация артефактов из шаблонов
# ---------------------------------------------------------------------------
# Артефакт = шаблон + факты из INFORMATION.yaml + детерминированный расчёт.
# Нет факта — явный маркер (⛔ не заполнено / null), а не придуманное значение.
# Нет обязательных входов — генерация блокируется, файлы не пишутся.

START_TEMPLATES = {
    "passport": "templates/criticality-passport.yaml",
    "criticality": "templates/CRITICALITY.md",
    "publication": "templates/publication.md",
    "generation": "templates/GENERATION.md",
    "jira": "templates/actions/jira-task.md",
    "confluence": "templates/actions/confluence-page.md",
    "message": "templates/actions/rocketchat-message.md",
}

START_PROTECTED = ("criticality-passport.yaml", "CRITICALITY.md")

STATUS_MARK = {
    "confirmed": "✅ подтверждено",
    "derived": "⚠️ требует подтверждения",
    "legacy": "⚠️ требует подтверждения",
    "missing": "⛔ не заполнено",
}


def registry_row_status(entry, value):
    """Статус ячейки провенанса для поля, чей источник — реестр (`catalog.yaml`).

    Статус не хардкодится: он производный от двух фактов — есть ли значение и
    подтверждена ли запись реестра (`status`).

    - значения нет → `missing` («⛔ не заполнено»);
    - значение есть и `status: confirmed` → `confirmed`: это факт реестра,
      подтверждённый SRE, а не косвенный вывод;
    - значение есть, но запись не подтверждена (`draft`/`needs_validation`) →
      `derived` («⚠️ требует подтверждения»): значение выведено, но SRE его
      ещё не подтвердил.
    """
    if value in (None, ""):
        return "missing"
    status = str((entry or {}).get("status") or "").strip().lower()
    return "confirmed" if status == "confirmed" else "derived"

START_METHOD_RULES = {
    "detailed": [
        ("axes",),
        ("time_buckets",),
        ("impact_matrix",),
        ("cia",),
        ("cia", "weights"),
        ("cia", "protection_levels"),
        ("cia", "protection_to_level"),
        ("final_matrix",),
        ("levels",),
    ],
    "express": [
        ("express_method",),
        ("express_method", "formula"),
        ("express_method", "client_coefficients"),
        ("express_method", "impact_coefficients"),
        ("express_method", "intervals"),
        ("express_method", "matrix"),
        ("express_method", "score_to_level"),
        ("levels", "dochub_to_ssot"),
        ("levels",),
    ],
}

CONVENTION_PATHS = {
    "detailed": [
        ("cia", "protection_levels", "boundary_convention"),
    ],
    "express": [
        ("express_method", "numerics"),
    ],
}


def _slug(value) -> str:
    text = "" if value is None else str(value)
    text = text.strip().lower()
    text = re.sub(r"[\s_]+", "-", text)
    text = re.sub(r"[^a-z0-9\u0430-\u044f\u0451-]", "", text)
    return text or "unassigned"


def _iso_date(value):
    if value in (None, ""):
        return None
    try:
        return parse_date(value).isoformat()
    except ValueError:
        return None


def _dot_date(value):
    if value in (None, ""):
        return None
    try:
        return parse_date(value).strftime("%Y.%m.%d")
    except ValueError:
        return None


def _plain(value):
    if isinstance(value, (dict, list)):
        return None
    return value


def _scalar_at(info, path):
    return _plain(_dig(info, path))


def _input_specs(criteria):
    """Спецификации входов гейта из criteria.inputs.required.

    Поля: `method`, `blocking`, `switches_scenario` (флаг переключения на
    сложный сценарий), `description`, `source_hint`.
    """
    specs = []
    for item in ((criteria.get("inputs") or {}).get("required") or []):
        if not isinstance(item, dict):
            continue
        identifier = str(item.get("id"))
        method = item.get("method")
        if method not in ("detailed", "express", "both"):
            method = "both"
        specs.append(
            {
                "id": identifier,
                "method": method,
                "blocking": bool(item.get("blocking")),
                "switches_scenario": item.get("switches_scenario") is True,
                "description": item.get("description"),
                "source_hint": item.get("source_hint"),
            }
        )
    return specs


def _entry_has_any(identifier, entry):
    """Есть ли у входа хотя бы одно непустое значение (даже частичное)."""
    if identifier == "axes_scores":
        return any(entry.get(axis) is not None for axis in INFORMATION_AXES)
    if identifier == "cia":
        return any(
            entry.get(lower) is not None or entry.get(upper) is not None
            for upper, lower in INFORMATION_CIA
        )
    if identifier == "time_to_impact":
        return _has_value(entry.get("bucket")) or _has_value(entry.get("value"))
    return _has_value(entry.get("value"))


def _input_record(info, identifier):
    """Один вход гейта: значение, полнота, статус, провенанс.

    has_any  — есть хотя бы одно непустое значение (для выбора метода);
    complete — значение полное (все оси/все C/I/A) и статус не missing;
    status   — missing | derived | confirmed | legacy | unset.
    """
    block = _criteria_input_block(info)
    entry = block.get(identifier)
    if isinstance(entry, dict):
        value, complete = _criteria_entry_value(identifier, entry)
        status = str(entry.get("status") or "").strip().lower() or "unset"
        waive = entry.get("waive")
        return {
            "id": identifier,
            "value": value,
            "has_any": _entry_has_any(identifier, entry),
            "complete": complete,
            "status": status,
            "ref": f"criteria_inputs.{identifier}",
            # Блок отказа (R17): причина, режим допущения и решение. Нужен
            # гейту (waived закрывает вход) и расчёту (диапазон вместо числа).
            "waive": waive if isinstance(waive, dict) else None,
        }
    for candidate in INFORMATION_FIELD_PATHS.get(identifier, [identifier]):
        candidate_value = _dig(info or {}, candidate)
        if _has_value(candidate_value):
            return {
                "id": identifier,
                "value": candidate_value,
                "has_any": True,
                "complete": True,
                "status": "legacy",
                "ref": candidate,
                "waive": None,
            }
    return {
        "id": identifier,
        "value": None,
        "has_any": False,
        "complete": False,
        "status": "missing",
        "ref": None,
        "waive": None,
    }


# ЕДИНЫЙ критерий «вход закрыт» (см. `_input_closed`). Значение должно быть
# полным и подтверждённым: `confirmed` (человек/enrich/sources) или `derived`
# (вычислено и принято). `legacy` — значение уже лежит в INFORMATION.yaml по
# документированному старому пути (INFORMATION_FIELD_PATHS): подтверждать его
# нечем и не нужно, лист требований не должен его запрашивать.
INPUT_CLOSED_STATUSES = ("confirmed", "derived", "legacy")


def _input_closed(record):
    """Вход закрыт: значение полное и статус подтверждён.

    Единственная точка истины для трёх мест, которые обязаны совпадать:
      * гейт `evaluate_gate` (blocking/advisory «filled» и вердикт);
      * лист требований `DATA-REQUIREMENTS.*` (закрытые входы в него не попадают);
      * `validate` (лист не должен содержать закрытых входов).

    `record` — элемент `gate["records"]` (`_input_record`): `complete` —
    значение полное (все оси/все C/I/A), `status` — missing | derived |
    confirmed | legacy | unset. Своих списков статусов вызывающие не заводят.
    """
    if not isinstance(record, dict) or not record.get("complete"):
        return False
    status = str(record.get("status") or "").strip().lower()
    return status in INPUT_CLOSED_STATUSES


def _coerce_int(value):
    """Целое из int/float/строки; None, если значение не целое."""
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return int(value) if value.is_integer() else None
    if isinstance(value, str):
        text = value.strip()
        if _INT_RE.match(text):
            return int(text)
    return None


def _value_problems(info, criteria, records):
    """Валидация ЗНАЧЕНИЙ входов (не только их наличия).

    Возвращает список причин. Пустой список — значения допустимы.
    Ошибка значения всегда ведёт к BLOCKED, чтобы `check` и `start` давали
    одинаковый вердикт и не падали трейсбеком на этапе расчёта.
    """
    problems = []
    block = _criteria_input_block(info)

    axes = (records.get("axes_scores") or {}).get("value")
    if isinstance(axes, dict):
        for axis in INFORMATION_AXES:
            value = axes.get(axis)
            if value is None:
                continue
            number = _coerce_int(value)
            if number is None or not 0 <= number <= 4:
                problems.append(
                    f"axes_scores.{axis} = {value!r} вне диапазона: ожидается целое 0..4"
                )

    cia = (records.get("cia") or {}).get("value")
    if isinstance(cia, dict):
        for upper, lower in INFORMATION_CIA:
            value = cia.get(upper)
            if value is None:
                continue
            text = str(value).strip().lower()
            if text not in ("low", "medium", "high"):
                problems.append(
                    f"cia.{lower} = {value!r} вне допустимого множества: "
                    "low, medium, high"
                )

    try:
        allowed_buckets = time_bucket_columns(criteria)
    except YamlError:
        allowed_buckets = []
    expected_buckets = ", ".join(allowed_buckets) or "<1h, 1-12h, 12-24h, >24h"
    bucket_entry = block.get("time_to_impact")
    if isinstance(bucket_entry, dict):
        raw_bucket = bucket_entry.get("bucket")
        raw_value = bucket_entry.get("value")
        if _has_value(raw_bucket):
            try:
                bucket = normalize_time_bucket(raw_bucket)
            except ValueError as exc:
                problems.append(f"time_to_impact.bucket: {exc}")
            else:
                if allowed_buckets and bucket not in allowed_buckets:
                    problems.append(
                        f"time_to_impact.bucket = {raw_bucket!r} вне time_buckets.order: "
                        + expected_buckets
                    )
        elif _has_value(raw_value):
            try:
                bucket = normalize_time_bucket(raw_value)
            except ValueError:
                problems.append(
                    "time_to_impact.bucket не задан, а value = "
                    f"{raw_value!r} не распознано как корзина времени; "
                    f"допустимо: {expected_buckets}"
                )
            else:
                if allowed_buckets and bucket not in allowed_buckets:
                    problems.append(
                        f"time_to_impact.value = {raw_value!r} даёт корзину "
                        f"{bucket!r} вне time_buckets.order: {expected_buckets}"
                    )

    for identifier in ("object_sla", "peak_hour_load"):
        value = (records.get(identifier) or {}).get("value")
        if value in (None, ""):
            continue
        number = _coerce_int(value)
        if identifier == "object_sla":
            # 0 — валидный норматив «простой недопустим»: калькулятор считает с
            # SLA = 0 (t = порог/E×60), поэтому гейт не должен его отклонять.
            if number is None or number < 0:
                problems.append(
                    f"{identifier} = {value!r}: ожидается целое >= 0 "
                    "(0 = простой недопустим)"
                )
        elif number is None or number <= 0:
            problems.append(f"{identifier} = {value!r}: ожидается целое > 0")

    for identifier, allowed in (
        ("consumers_type", CONSUMERS_TYPES),
        ("outage_impact", OUTAGE_IMPACTS),
    ):
        value = (records.get(identifier) or {}).get("value")
        if value in (None, ""):
            continue
        text = _canon_text(value)
        if text not in [_canon_text(item) for item in allowed]:
            problems.append(
                f"значение {identifier} вне допустимого enum: {text!r}. Допустимо: "
                + "; ".join(allowed)
            )
    return problems


# --- два сценария расчёта (criteria.scenarios) ------------------------------
#
# Сценарий — не флаг команды, а свойство данных: он выбирается по
# `scenarios.selection.rule` и определяет blocking-набор входов. Простой
# (экспресс) — 4 входа калькулятора; сложный (детальная оценка) — все входы
# `inputs.required`. Фолбэк со сложного на простой запрещён: частично
# заполненный детальный набор — это BLOCKED, а не «примерная» оценка.

SCENARIO_LABELS = {"simple": "простой", "complex": "сложный"}

SCENARIO_DEFAULT_TITLES = {
    "simple": "Простой сценарий (экспресс-оценка)",
    "complex": "Сложный сценарий (детальная оценка)",
}

# Входы, относящиеся только к сложному набору. Используются, только если
# секция `scenarios` в критериях отсутствует (переносимый скилл).
COMPLEX_ONLY_INPUTS = ("time_to_impact", "axes_scores", "cia")

# Предупреждение в листе требований: заполнение advisory detailed-входа в
# простом сценарии переключает ИС на сложный (`scenarios.selection.rule`),
# после чего обязательным становится `time_to_impact`.
SCENARIO_SWITCH_NOTE = (
    "заполнение переключает ИС на сложный сценарий: "
    "обязательным станет time_to_impact"
)

# Формулировка причины BLOCKED: переключение сценария — следствие заполнения
# detailed-входов, а не «неполный набор вообще».
SCENARIO_SWITCH_REASON = (
    "сценарий переключён заполнением {inputs}; для расчёта нужен time_to_impact"
)

# Тексты правил выбора сценария: одни и те же в `check`, `start` и `score --is`.
SCENARIO_RULES = {
    "selection": (
        "сценарий сложный, если хотя бы один вход только сложного набора "
        "(time_to_impact, axes_scores, cia) содержит непустое значение; "
        "иначе простой"
    ),
    "simple": (
        "простой сценарий: обязательны четыре входа калькулятора "
        "(peak_hour_load, consumers_type, outage_impact, object_sla); "
        "отсутствие любого — BLOCKED"
    ),
    "complex": (
        "сложный сценарий: обязательны все входы inputs.required; неполный "
        "набор — BLOCKED, фолбэк на простой сценарий запрещён"
    ),
}


def _scenarios_block(criteria):
    """Секция criteria.scenarios или пустой словарь (скилл переносимый)."""
    block = (criteria or {}).get("scenarios")
    return block if isinstance(block, dict) else {}


def _scenario_part(criteria, scenario):
    part = _scenarios_block(criteria).get(scenario)
    return part if isinstance(part, dict) else {}


def scenario_inputs(criteria, scenario):
    """Список входов сценария из criteria.scenarios.<scenario>.inputs."""
    ids = []
    for item in _scenario_part(criteria, scenario).get("inputs") or []:
        text = str(item or "").strip()
        if text and text not in ids:
            ids.append(text)
    return ids


def scenario_title(criteria, scenario):
    """Заголовок сценария: criteria.scenarios.<scenario>.title или дефолт."""
    title = _scenario_part(criteria, scenario).get("title")
    text = str(title).strip() if title not in (None, "") else ""
    return text or SCENARIO_DEFAULT_TITLES.get(scenario, scenario)


def _scenario_complex_only(criteria):
    """Структурный набор переключателей: complex.inputs минус simple.inputs.

    Считается только по `scenarios` — без флага `switches_scenario`, поэтому
    `criteria check` может сравнить с ним набор флага и поймать расхождение.
    """
    simple_ids = scenario_inputs(criteria, "simple")
    return [
        identifier
        for identifier in scenario_inputs(criteria, "complex")
        if identifier not in simple_ids
    ]


def complex_only_inputs(criteria):
    """Входы, входящие только в сложный набор (переключатели сценария).

    Первичный источник — флаг `inputs.required[].switches_scenario: true`: его же
    проверяет `criteria check` (набор флага обязан совпадать со структурным
    набором `scenarios`), поэтому выбор сценария и проверка не расходятся.
    Флага нет ни у одного входа (критерии без него) — структурный набор
    `scenarios.complex.inputs` минус `scenarios.simple.inputs`; нет и секции
    `scenarios` — переносимый дефолт COMPLEX_ONLY_INPUTS. Функция детерминирована:
    порядок — порядок `inputs.required`.
    """
    flagged = [
        spec["id"]
        for spec in _input_specs(criteria)
        if spec.get("switches_scenario") is True
    ]
    if flagged:
        return flagged
    return _scenario_complex_only(criteria) or list(COMPLEX_ONLY_INPUTS)


def scenario_of(records, criteria):
    """Выбрать сценарий по данным: 'complex' | 'simple'.

    Сложный — если хотя бы один вход, относящийся только к сложному набору,
    содержит непустое значение (scenarios.selection.rule). Иначе простой.
    """
    for identifier in complex_only_inputs(criteria):
        record = (records or {}).get(identifier) or {}
        if record.get("has_any"):
            return "complex"
    return "simple"


def blocking_inputs(scenario, criteria):
    """Blocking-набор сценария: simple — 4 входа, complex — все входы."""
    ids = scenario_inputs(criteria, scenario)
    if ids:
        return ids
    # Секции scenarios нет: выводим набор из method/blocking входов.
    method = "detailed" if scenario == "complex" else "express"
    return [
        spec["id"]
        for spec in _input_specs(criteria)
        if spec["blocking"] and spec["method"] in (method, "both")
    ]


def evaluate_gate(info, criteria):
    """ЕДИНАЯ проверка достаточности данных (check / start / score --is).

    Семантика детерминирована:
      1. сценарий = complex, если хотя бы один вход только сложного набора
         (time_to_impact, axes_scores, cia) содержит непустое значение; иначе
         simple (scenarios.selection.rule). Метод расчёта следует за сценарием:
         complex → detailed, simple → express;
      2. все blocking-входы сценария обязаны иметь полное значение И статус не
         missing; иначе BLOCKED. Фолбэк со сложного на простой запрещён:
         частичный детальный набор — BLOCKED, а не express;
      3. входы вне blocking-набора сценария не блокируют, но попадают в WARN.
    """
    info = info if isinstance(info, dict) else {}
    specs = _input_specs(criteria)
    records = {spec["id"]: _input_record(info, spec["id"]) for spec in specs}

    scenario = scenario_of(records, criteria)
    method = "detailed" if scenario == "complex" else "express"
    scenario_ids = set(blocking_inputs(scenario, criteria))

    blocking_specs = [spec for spec in specs if spec["id"] in scenario_ids]
    # advisory — только входы с blocking: false: вне blocking-набора сценария они
    # не блокируют, но и в WARN не попадают (иначе простой сценарий всегда
    # предупреждал бы про незаполненные детальные входы).
    advisory_specs = [spec for spec in specs if not spec["blocking"]]

    def ready(spec):
        # Единственный критерий «закрыт» — общий с листом требований и validate
        # (`_input_closed`): значение полное и статус confirmed/derived/legacy.
        return _input_closed(records[spec["id"]])

    def waived(spec):
        """Вход закрыт явным отказом от данных (R17): гейт его не требует."""
        return records[spec["id"]]["status"] == WAIVED_STATUS

    blocking_missing = [
        spec["id"] for spec in blocking_specs if not ready(spec) and not waived(spec)
    ]
    advisory_missing = [
        spec["id"] for spec in advisory_specs if not ready(spec) and not waived(spec)
    ]
    # Отказ от данных не блокирует гейт, но и не молчит: список уходит в
    # вердикт, расчёт помечается предварительным, артефакты — предупреждением.
    waived_inputs = [
        spec["id"] for spec in specs if records[spec["id"]]["status"] == WAIVED_STATUS
    ]
    # Разделяем два разных случая: набор неполон (значение заполнено частично)
    # и значение не подтверждено (status: missing). Это разные причины BLOCKED.
    unconfirmed = [
        identifier
        for identifier in blocking_missing
        if records[identifier]["has_any"]
        and str(records[identifier]["status"]).strip().lower()
        not in INPUT_CLOSED_STATUSES
    ]
    value_problems = _value_problems(info, criteria, records)

    # Диагностика переключения сценария: detailed-вход заполнен, а time_to_impact
    # нет. Это не «неполный набор вообще», а последствие заполнения advisory
    # полей простого сценария — причина BLOCKED обязана это называть.
    scenario_switch_inputs = [
        identifier
        for identifier in complex_only_inputs(criteria)
        if (records.get(identifier) or {}).get("has_any")
    ]
    scenario_switched = (
        scenario == "complex"
        and bool(scenario_switch_inputs)
        and not (records.get("time_to_impact") or {}).get("has_any")
    )

    reason = None
    if blocking_missing:
        if scenario == "complex":
            reason = (
                "неполный сложный сценарий (не хватает: "
                + ", ".join(blocking_missing)
                + ") — фолбэк на простой сценарий запрещён"
            )
        else:
            reason = (
                "нет полного набора входов для простого сценария (не хватает: "
                + ", ".join(blocking_missing)
                + ")"
            )
        if unconfirmed:
            reason += (
                "; значения без подтверждения (status: missing/unset): "
                + ", ".join(unconfirmed)
            )
    if value_problems:
        value_reason = (
            "значения вне допустимых множеств: " + "; ".join(value_problems)
        )
        reason = value_reason if reason is None else reason + "; " + value_reason
    if scenario_switched and reason is not None:
        reason += (
            " ("
            + SCENARIO_SWITCH_REASON.format(
                inputs="/".join(scenario_switch_inputs)
            )
            + ")"
        )

    return {
        "scenario": scenario,
        "scenario_title": scenario_title(criteria, scenario),
        "scenario_label": SCENARIO_LABELS.get(scenario, scenario),
        "scenario_inputs": list(blocking_inputs(scenario, criteria)),
        "method": method,
        "verdict": "BLOCKED" if (blocking_missing or value_problems) else "OK",
        "reason": reason,
        "value_problems": value_problems,
        "blocking": {
            "total": len(blocking_specs),
            "filled": len(blocking_specs) - len(blocking_missing),
            "missing": blocking_missing,
        },
        "advisory": {
            "total": len(advisory_specs),
            "filled": len(advisory_specs) - len(advisory_missing),
            "missing": advisory_missing,
        },
        "records": records,
        "specs": specs,
        "detailed_present": scenario == "complex",
        "unconfirmed": unconfirmed,
        # Явный отказ от данных (R17): гейт закрыт, но оценка предварительная.
        "waived_inputs": waived_inputs,
        "provisional": bool(waived_inputs),
        "scenario_switched": scenario_switched,
        "scenario_switch_inputs": scenario_switch_inputs,
    }


def _normalized_axes(records):
    axes = records["axes_scores"]["value"]
    if not isinstance(axes, dict):
        raise IncompleteError(["axes_scores"])
    normalized = {}
    for axis in INFORMATION_AXES:
        value = axes.get(axis)
        if value is None:
            raise IncompleteError([f"axes_scores.{axis}"])
        normalized[axis] = int(value)
    return normalized


def _normalized_cia(records):
    raw = records["cia"]["value"]
    if not isinstance(raw, dict):
        raise IncompleteError(["cia"])
    normalized = {}
    for parameter in CIA_PARAMETERS:
        value = raw.get(parameter)
        if value is None:
            value = raw.get(parameter.lower())
        if value is None:
            raise IncompleteError([f"cia.{parameter}"])
        normalized[parameter] = str(value).lower()
    return normalized


def _enum_problem(gate):
    """Проверка enum-полей до записи артефактов (validate — второй рубеж)."""
    checks = (
        ("consumers_type", CONSUMERS_TYPES),
        ("outage_impact", OUTAGE_IMPACTS),
    )
    for identifier, allowed in checks:
        record = gate["records"].get(identifier) or {}
        value = record.get("value")
        if value in (None, ""):
            continue
        text = _canon_text(value)
        if text not in [_canon_text(item) for item in allowed]:
            return (
                f"значение {identifier} вне допустимого enum: {text!r}. Допустимо: "
                + "; ".join(allowed)
            )
    return None


def _compute_for_method(criteria, gate):
    """Результат расчёта по выбранному гейтом методу. Бросает IncompleteError."""
    records = gate["records"]
    if gate["method"] == "detailed":
        axes = _normalized_axes(records)
        business = compute_business(
            criteria, axes, records["time_to_impact"]["value"]
        )
        cia = compute_cia(criteria, _normalized_cia(records))
        total = final_level(criteria, business["level"], cia["protection"])
        return {
            "method": "detailed",
            "status": "complete",
            "business": business,
            "cia": cia,
            "express": None,
            "final": total,
            "calculator_level": None,
        }
    express = compute_express(
        criteria,
        records["peak_hour_load"]["value"],
        records["consumers_type"]["value"],
        records["outage_impact"]["value"],
        records["object_sla"]["value"],
    )
    return {
        "method": "express",
        "status": "preliminary",
        "business": None,
        "cia": None,
        "express": express,
        "final": express["level"],
        "calculator_level": express["calculator_level"],
    }


# --- предварительная оценка: диапазон вместо числа (R17) --------------------
#
# Явный отказ от данных (status: waived) не даёт права на одно число: любое
# значение из домена входа допустимо, значит допустим и любой уровень из
# диапазона. Расчёт обязан перечислить домен (конечный!), посчитать уровень на
# каждом элементе и напечатать {min, max}.

WAIVE_LEVEL_SEP = "–"

# Предел нагрузки, моделирующий `load → +∞`: t → object_sla + ε. Больше 10^9
# не нужно: добавка T·60/(c·i·load) при максимальном пороге (50000) и
# минимальном произведении коэффициентов (0.2·0.2 = 0.04) равна 0.075 — это
# меньше минимальной ширины интервала (10 мин), поэтому при целом object_sla
# ε не перескакивает границу и предел попадает в тот же интервал, что и
# строгий предел `load → +∞`.
WAIVE_LOAD_SENTINEL = 10 ** 9


def _waive_integer_domain(criteria):
    """Домен числа: пороги, границы интервалов и два предела (0 и +∞).

    Уровень экспресс-метода зависит от `t = порог·60/(c·i·load) + sla`:
    по нагрузке `t` монотонно убывает к `sla`, по SLA — монотонно растёт.
    Матрица баллов не возрастает с номером интервала, поэтому балл монотонен
    по обоим входам и экстремумы достигаются на краях домена:
      * `load = 1` — максимальное `t` (минимум балла), `load → +∞` — `t → sla`
        (максимум балла; моделируется `WAIVE_LOAD_SENTINEL`);
      * `sla = 0` — максимум балла, `sla → +∞` — последний интервал (минимум).
    Пороги и границы интервалов добавлены как контрольные точки смены балла.
    Без пределов максимум терялся: при `sla=60`, `c·i=0.1`, `load=200000`
    получается `t=210` → балл 4 → Mission critical, а на пороге `load=50000`
    (`t=660`) — балл 3 → Business critical.
    """
    values = {0, 1, WAIVE_LOAD_SENTINEL}
    express = criteria.get("express_method") or {}
    for value in (express.get("thresholds") or {}).values():
        number = _coerce_int(value)
        if number is not None:
            values.add(number)
    for item in ((express.get("intervals") or {}).get("items") or []):
        if not isinstance(item, dict):
            continue
        for key in ("lo", "hi"):
            number = _coerce_int(item.get(key))
            if number is not None:
                values.add(number)
    return sorted(values)


def _waive_domain(criteria, identifier):
    """Домен допустимых значений входа; None — домен не перечислим.

    None — это «твёрдое условие расчёта»: угадывать вместо перебора запрещено
    (R1/R10), поэтому вызывающий обязан остановиться с понятной ошибкой.
    """
    kind = _ask_value_type(criteria, identifier)
    if kind in ("enum", "bucket"):
        return list(_ask_allowed(criteria, identifier))
    if kind == "object":
        # Составные входы перечисляются ПОЛНОСТЬЮ, а не по углам: 5^4 = 625
        # наборов осей и 3^3 = 27 наборов CIA стоят дёшево и снимают
        # недоказанное допущение о монотонности (max по осям / веса CIA).
        if identifier == "axes_scores":
            return [
                dict(zip(INFORMATION_AXES, combo))
                for combo in itertools.product(
                    range(5), repeat=len(INFORMATION_AXES)
                )
            ]
        return [
            dict(zip((lower for _upper, lower in INFORMATION_CIA), combo))
            for combo in itertools.product(
                ("low", "medium", "high"), repeat=len(INFORMATION_CIA)
            )
        ]
    if identifier in ("peak_hour_load", "object_sla"):
        domain = _waive_integer_domain(criteria)
        if identifier == "object_sla":
            return [value for value in domain if value >= 0]
        return [value for value in domain if value > 0]
    return None


def _waive_probe_record(criteria, identifier, value):
    """Запись входа с подставленным значением — той же нормализацией, что enrich."""
    entry = _normalize_requirement(
        identifier, value, {"type": "manual", "ref": "waive"}
    )
    return _input_record({"criteria_inputs": {identifier: entry}}, identifier)


def _level_from_records(criteria, method, records):
    """Уровень по готовым записям входов выбранным методом (без выбора сценария).

    Метод фиксирует гейт: переключение сценария из-за подставленного значения
    откоса было бы подменой вопроса (waive не создаёт новых требований).
    """
    if method == "express":
        express = compute_express(
            criteria,
            records["peak_hour_load"]["value"],
            records["consumers_type"]["value"],
            records["outage_impact"]["value"],
            records["object_sla"]["value"],
        )
        return express["level"]
    axes = _normalized_axes(records)
    business = compute_business(
        criteria, axes, records["time_to_impact"]["value"]
    )
    cia = compute_cia(criteria, _normalized_cia(records))
    return final_level(criteria, business["level"], cia["protection"])


def provisional_score(criteria, gate):
    """Диапазон уровня при отказах (R17) и уровень по режиму допущения.

    Возвращает словарь:
      provisional   — есть ли отказы (оценка предварительная);
      waived_inputs — имена входов со `status: waived`;
      range         — {min, max} по шкале `levels.order` (None без отказов);
      assumptions   — [{input, mode, value_used, reason, values_checked}];
      reported      — уровень, который идёт в паспорт (worst → max, иначе min);
      error         — текст ошибки, если диапазон не перечислим (тогда стоп).
    """
    waived_ids = list(gate.get("waived_inputs") or [])
    if not waived_ids:
        return {
            "provisional": False,
            "waived_inputs": [],
            "range": None,
            "assumptions": [],
            "reported": None,
            "reported_values": {},
            "error": None,
        }
    method = gate.get("method") or "express"
    assumptions = []
    domains = []
    for identifier in waived_ids:
        record = gate.get("records", {}).get(identifier) or {}
        waive = record.get("waive") if isinstance(record.get("waive"), dict) else {}
        fallback = (
            waive.get("fallback") if isinstance(waive.get("fallback"), dict) else {}
        )
        mode = str(fallback.get("mode") or WAIVE_FALLBACK_DEFAULT).strip()
        if mode not in WAIVE_MODES:
            return {
                "provisional": True,
                "waived_inputs": waived_ids,
                "range": None,
                "assumptions": assumptions,
                "reported": None,
                "error": (
                    f"отказ (waive) для входа {identifier}: режим допущения "
                    f"{mode!r} вне допустимого перечня ("
                    + " | ".join(WAIVE_MODES)
                    + ") — диапазон не вычислен"
                ),
            }
        domain = _waive_domain(criteria, identifier)
        if not domain:
            return {
                "provisional": True,
                "waived_inputs": waived_ids,
                "range": None,
                "assumptions": assumptions,
                "reported": None,
                "error": (
                    f"отказ (waive) для входа {identifier}: домен допустимых "
                    "значений не перечислим — это твёрдое условие расчёта, "
                    "диапазон по нему не строится. Подтвердите значение "
                    "(status: confirmed) или укажите "
                    "waive.fallback.mode: assume_value с value"
                ),
            }
        if mode == "assume_value":
            value = fallback.get("value")
            if not _has_value(value):
                return {
                    "provisional": True,
                    "waived_inputs": waived_ids,
                    "range": None,
                    "assumptions": assumptions,
                    "reported": None,
                    "error": (
                        f"отказ (waive) для входа {identifier}: режим "
                        "assume_value требует fallback.value"
                    ),
                }
            problem = _ask_value_problem(criteria, identifier, value)
            if problem:
                return {
                    "provisional": True,
                    "waived_inputs": waived_ids,
                    "range": None,
                    "assumptions": assumptions,
                    "reported": None,
                    "error": (
                        f"отказ (waive) для входа {identifier}: fallback.value — "
                        f"{problem}"
                    ),
                }
            domain = [value]
        assumptions.append(
            {
                "input": identifier,
                "mode": mode,
                "mode_label": WAIVE_ASSUMPTION_LABELS.get(mode, mode),
                "value_used": fallback.get("value") if mode == "assume_value" else None,
                "reason": str(waive.get("reason") or "").strip(),
                "values_checked": len(domain),
            }
        )
        domains.append((identifier, domain, mode))

    levels = []
    combos = []
    for combo in itertools.product(*[domain for _id, domain, _mode in domains]):
        records = dict(gate.get("records") or {})
        for (identifier, _domain, _mode), value in zip(domains, combo):
            records[identifier] = _waive_probe_record(criteria, identifier, value)
        try:
            level = _level_from_records(criteria, method, records)
        except IncompleteError as exc:
            return {
                "provisional": True,
                "waived_inputs": waived_ids,
                "range": None,
                "assumptions": assumptions,
                "reported": None,
                "reported_values": {},
                "error": (
                    "диапазон не вычислен: при подстановке значения отказа "
                    f"не хватает входов {', '.join(exc.missing)} — это твёрдое "
                    "условие расчёта, а не повод для догадки"
                ),
            }
        levels.append(level)
        combos.append((combo, level))
    ranks = level_rank(criteria)
    ordered = sorted(set(levels), key=lambda level: ranks.get(level, 0))
    minimum, maximum = ordered[0], ordered[-1]
    modes = {mode for _id, _domain, mode in domains}
    # Консервативный дефолт: если хоть один вход взят «по худшему», в паспорт
    # идёт максимум диапазона. Иначе (best/value) — минимум; у assume_value
    # домен из одного элемента, поэтому min == max.
    reported = maximum if "assume_worst" in modes else minimum
    # Значения, дающие ровно сообщённый уровень: по ним считается «как если бы»
    # — иначе печать и паспорт расходились бы с диапазоном.
    reported_values = {}
    for combo, level in combos:
        if level != reported:
            continue
        reported_values = {
            identifier: value
            for (identifier, _domain, _mode), value in zip(domains, combo)
        }
        break
    return {
        "provisional": True,
        "waived_inputs": waived_ids,
        "range": {"min": minimum, "max": maximum},
        "assumptions": assumptions,
        "reported": reported,
        "reported_values": reported_values,
        "error": None,
    }


def _print_provisional(provisional, stream=None):
    """Печать предварительной оценки: диапазон + допущения (R17).

    Диапазон обязателен: без него «предварительная» оценка снова выглядела бы
    как одно подтверждённое число.
    """
    stream = stream or sys.stdout
    waive_range = provisional.get("range") or {}
    minimum = waive_range.get("min")
    maximum = waive_range.get("max")
    print(f"{WAIVE_MARKER}: не подтверждены входы", file=stream)
    for assumption in provisional.get("assumptions") or []:
        reason = assumption.get("reason") or "причина не указана"
        print(
            f"  - {assumption['input']}: {reason} "
            f"(допущение: {assumption.get('mode_label') or assumption['mode']})",
            file=stream,
        )
    print(
        f"  диапазон уровня: {minimum} {WAIVE_LEVEL_SEP} {maximum} "
        f"(перебор доменов входов; шкала levels.order)",
        file=stream,
    )
    if minimum == maximum:
        print(
            "  (вход не влияет на уровень выбранного метода: минимум и максимум "
            "диапазона совпадают)",
            file=stream,
        )
    print(
        f"  в паспорт записан: {provisional.get('reported')} — консервативная "
        "оценка по режиму допущения",
        file=stream,
    )
    print(
        "  для точной оценки нужны входы: "
        + ", ".join(provisional.get("waived_inputs") or []),
        file=stream,
    )


def _provisional_trace_block(provisional):
    """Поля score_trace: provisional / provisional_range / waived_inputs / assumptions."""
    provisional = provisional or {}
    waive_range = provisional.get("range") or {}
    return {
        "provisional": bool(provisional.get("provisional")),
        "provisional_range": provisional.get("range"),
        # Вырожденный диапазон (min == max): вход не влияет на уровень
        # выбранного метода — шаблон печатает это рядом с диапазоном.
        "provisional_degenerate": bool(waive_range)
        and waive_range.get("min") == waive_range.get("max"),
        "waived_inputs": list(provisional.get("waived_inputs") or []),
        "assumptions": list(provisional.get("assumptions") or []),
    }


def _start_conflicts(entry, computed, info=None, criteria=None):
    """Расхождения. Молча не перезаписываются, оба значения остаются в артефакте.
    Авторитет значения SSoT — `identity.criticality_ssot` из INFORMATION.yaml
    (источник SSoT). `catalog.yaml` — вторичный. Фиксируются два вида конфликтов:
    `calculation vs ssot` и `ssot vs catalog`.
    """
    conflicts = []
    if not computed:
        return conflicts
    final = computed["final"]
    computed_ssot = (
        dochub_to_ssot_map(criteria).get(final) if criteria is not None else None
    )
    identity = (info or {}).get("identity")
    identity = identity if isinstance(identity, dict) else {}
    ssot_value = identity.get("criticality_ssot")
    catalog_ssot = entry.get("criticality_ssot")

    if ssot_value not in (None, "") and computed_ssot is not None and ssot_value != computed_ssot:
        conflicts.append(
            {
                "field": "criticality_ssot",
                "computed": computed_ssot,
                "actual": ssot_value,
                "rule": "calculation vs ssot",
                "note": (
                    "расчёт ≠ SSoT (INFORMATION.yaml → identity.criticality_ssot); "
                    "требует подтверждения"
                ),
            }
        )
    if (
        ssot_value not in (None, "")
        and catalog_ssot not in (None, "")
        and ssot_value != catalog_ssot
    ):
        conflicts.append(
            {
                "field": "criticality_ssot",
                "computed": ssot_value,
                "actual": catalog_ssot,
                "rule": "ssot vs catalog",
                "note": (
                    "SSoT ≠ catalog.yaml; авторитет — SSoT, реестр не перезаписан "
                    "автоматически; требует подтверждения"
                ),
            }
        )
    actual_crit = entry.get("criticality")
    if actual_crit is not None and actual_crit != final:
        conflicts.append(
            {
                "field": "criticality",
                "computed": final,
                "actual": actual_crit,
                "rule": "object_criticality_estimation (расчёт)",
                "note": "значение реестра не перезаписано автоматически",
            }
        )
    return conflicts


# --- контакты команды (TA/TL) из SSoT ---------------------------------------
# `contacts` в INFORMATION.yaml — копия ростера команды-владельца из
# `ssot/entities/teams/<team>/team.yaml`. Нужна для упоминаний в RocketChat
# (`@<login>`) и для исполнителя задачи Jira (логин, а не ФИО). Соответствия
# login -> ФИО в SSoT нет, поэтому в публикации печатается логин.
CONTACTS_SECTION = "contacts"
CONTACTS_MENTION_GROUPS = ("ta", "tl")
CONTACTS_COMMENT_MARKER = "# contacts"
CONTACTS_COMMENT = (
    "# contacts — контакты команды-владельца (TA/TL/SRE и др.).\n"
    "# contacts: сгенерировано make contacts из ssot/entities/teams/<team>/team.yaml; "
    "вручную не править.\n"
    "# contacts: упоминание в RocketChat — @<login> (соответствия login -> ФИО "
    "в SSoT нет).\n"
)


# Логин/username RocketChat — только безопасный для YAML и для текста сообщения:
# `x] @here` сломал бы inline-список (`ta: [x] @here]`), а `a\n* TL - @all`
# вставил бы в публикацию строку-буллет с пингом канала (подстановка идёт без
# экранирования). Поэтому входной логин проходит allowlist, остальное — скип.
#
# Допустимы обе формы: короткий логин (`dkozlov`) и **полный username** с
# доменом (`dkozlov@ecom.tech`). Вторая форма — то, что реально работает как
# упоминание: в RocketChat username хранится вместе с доменом, и текст
# `@dkozlov@ecom.tech` попадает в `mentions[]` сообщения (проверено на живом
# сообщении), тогда как `@dkozlov` упоминанием не считается.
ROCKETCHAT_USERNAME_RE = re.compile(
    r"[a-z0-9][a-z0-9._-]{0,31}(?:@[a-z0-9][a-z0-9.-]{0,62})?"
)
CONTACTS_LOGIN_RE = ROCKETCHAT_USERNAME_RE
# Служебные адресаты RocketChat: `@all`/`@here` пингуют весь канал, `@channel`
# ведёт себя так же. Упоминание не формируется (логин при этом остаётся
# обычным участником contacts.groups — это факт SSoT, а не ошибка).
ROCKETCHAT_RESERVED_MENTIONS = ("all", "here", "channel")


def _login_display(value) -> str:
    """Логин для сообщения: без переводов строк (иначе WARN рвётся на строки)."""
    text = str(value)
    return text.replace("\\", "\\\\").replace("\n", "\\n").replace("\r", "\\r")


def _clean_logins(value, rejected=None) -> list:
    """Логины из `groups[].members`: строки, без пустых, без дублей, нижний регистр.

    Порядок входа сохраняется (SSoT перечисляет участников по старшинству), а
    логин сравнивается без регистра: `DKozlov` и `dkozlov` — один человек.
    Логин вне allowlist (`CONTACTS_LOGIN_RE`) отбрасывается: он не должен
    попасть ни в YAML-блок, ни в текст публикации. Отброшенные значения
    складываются в `rejected` (если передан список) — их печатает вызывающий.
    """
    if isinstance(value, list):
        items = value
    elif value in (None, ""):
        items = []
    else:
        items = [value]
    logins = []
    for item in items:
        login = str(item or "").strip().lower()
        if not login or login in logins:
            continue
        if not CONTACTS_LOGIN_RE.fullmatch(login):
            if rejected is not None and login not in rejected:
                rejected.append(login)
            continue
        logins.append(login)
    return logins


def _info_contacts(info) -> dict:
    """Секция contacts из INFORMATION.yaml (пустой словарь, если её нет)."""
    contacts = info.get(CONTACTS_SECTION) if isinstance(info, dict) else None
    return contacts if isinstance(contacts, dict) else {}


def _contacts_groups(contacts) -> dict:
    groups = (contacts or {}).get("groups") if isinstance(contacts, dict) else None
    return groups if isinstance(groups, dict) else {}


def _clean_groups(groups) -> dict:
    """Группы контактов после allowlist-фильтра логинов (сравнение блоков)."""
    if not isinstance(groups, dict):
        return {}
    return {name: _clean_logins(members) for name, members in groups.items()}


def _contact_logins(groups, name) -> list:
    """Логины одной группы контактов (`ta`, `tl`, `s-arch`, ...) — без выдумок."""
    if not isinstance(groups, dict):
        return []
    return _clean_logins(groups.get(name))


def _mention_logins(logins, stream=None) -> list:
    """Логины, допустимые как упоминание RocketChat (без служебных адресатов)."""
    allowed = []
    for login in logins:
        if login in ROCKETCHAT_RESERVED_MENTIONS:
            print(
                f"WARN  логин {login} совпадает с зарезервированным упоминанием "
                "RocketChat — упоминание не добавлено",
                file=stream or sys.stderr,
            )
            continue
        allowed.append(login)
    return allowed


def _mentions(logins, stream=None) -> list:
    """Формат упоминания RocketChat: `@<login>`."""
    return [f"@{login}" for login in _mention_logins(logins, stream)]


def _mention_text(logins, stream=None):
    """Несколько логинов -> `@a, @b`; пустая группа -> None (не пустая строка)."""
    mentions = _mentions(logins, stream)
    return ", ".join(mentions) if mentions else None


# --- резолв логина в полный username RocketChat ------------------------------
# Упоминание `@<login>` без домена в RocketChat не срабатывает: username там
# хранится как `<login>@<домен>`. Кеш `catalog.yaml → rocketchat_users` хранит
# результат резолва, поэтому сеть вызывается один раз на логин, а повторные
# прогоны работают офлайн.
ROCKETCHAT_USERS_KEY = "rocketchat_users"
# Таймаут резолва: короткий и без ретраев — это обогащение подписи, а не
# отправка. Недоступность API не должна задерживать `make start`.
ROCKETCHAT_RESOLVE_TIMEOUT = 5


def _rocketchat_users_cache(catalog) -> dict:
    """Кеш резолва username из `catalog.yaml → rocketchat_users`."""
    block = (catalog or {}).get(ROCKETCHAT_USERS_KEY)
    return block if isinstance(block, dict) else {}


def _rocketchat_cached_username(login, cache):
    """Полный username из кеша или None (в т.ч. записанный отказ)."""
    item = (cache or {}).get(login)
    if not isinstance(item, dict):
        return None
    value = str(item.get("username") or "").strip()
    return value or None


def _rocketchat_users_info(base, token, user_id, login):
    """GET /api/v1/users.info?username=<login> → username или None.

    Один запрос, таймаут `ROCKETCHAT_RESOLVE_TIMEOUT`, без ретраев. Сетевой
    слой вынесен отдельной функцией: самопроверка подменяет её, не поднимая
    HTTP.
    """
    request = urllib.request.Request(
        f"{base}/api/v1/users.info?username={quote(login, safe='')}",
        headers={"X-Auth-Token": token, "X-User-Id": user_id},
        method="GET",
    )
    try:
        with urllib.request.urlopen(
            request, timeout=ROCKETCHAT_RESOLVE_TIMEOUT
        ) as response:
            raw = response.read().decode("utf-8", "replace")
        data = json.loads(raw) if raw.strip() else {}
    except (
        urllib.error.URLError,
        urllib.error.HTTPError,
        TimeoutError,
        OSError,
        ValueError,
    ):
        return None
    if not isinstance(data, dict) or data.get("success") is False:
        return None
    user = data.get("user")
    if not isinstance(user, dict):
        return None
    username = str(user.get("username") or "").strip()
    user_id_value = str(user.get("_id") or "").strip()
    if not username:
        return None
    return {"username": username, "user_id": user_id_value or None}


def _rocketchat_users_lookup(login, criteria):
    """Резолв username через REST: единственная точка подмены в самопроверке.

    Нет токена / X-User-Id (или API недоступен) — None: вызывающий вернёт
    исходный логин и WARN. Ретраев нет.
    """
    base, token, user_id, problems = _handoff_api_config(criteria)
    if problems:
        return None
    return _rocketchat_users_info(base, token, user_id, login)


def _rocketchat_resolve_login(login, criteria, cache=None, root=None):
    """(username, warning|None) для одного логина.

    Порядок: полный username (`@` в значении) → кеш → GET users.info.
    Резолв не удался — возвращается исходный логин и текст WARN: падать из-за
    недоступного RocketChat нельзя, но и молчать нельзя — упоминание не
    сработает.
    """
    login = str(login or "").strip().lower()
    if not login:
        return login, None
    # Полный username уже содержит домен — это и есть username RocketChat.
    if "@" in login:
        return login, None
    cached = _rocketchat_cached_username(login, cache)
    if cached:
        return cached, None
    if root is None:
        # Резолв не запрашивали (контекст без корня проекта: dry-run, тесты,
        # производные рендеры). Это не отказ — WARN не нужен, значение остаётся
        # логином, как раньше.
        return login, None
    warning = (
        f"упоминание @{login} не резолвится в RocketChat — уведомление не "
        "придёт; задайте полный username вручную "
        f"(catalog.yaml → {ROCKETCHAT_USERS_KEY}.{login}.username)"
    )
    resolved = _rocketchat_users_lookup(login, criteria)
    if not resolved:
        return login, warning
    if isinstance(cache, dict):
        cache[login] = {
            "username": resolved["username"],
            "user_id": resolved.get("user_id"),
            "resolved_at": today().isoformat(),
        }
        if root is not None:
            _save_rocketchat_users(root, cache)
    return resolved["username"], None


def _save_rocketchat_users(root, cache) -> bool:
    """Записать кеш резолва в `catalog.yaml → rocketchat_users`.

    Блок верхнего уровня: заменяется целиком (это кеш, порядок и комментарии
    внутри не значимы), остальной файл не трогается.
    """
    path = Path(root) / "catalog.yaml"
    if not path.exists():
        return False
    lines = path.read_text(encoding="utf-8").splitlines(True)
    start = None
    for index, raw in enumerate(lines):
        if re.match(rf"^{ROCKETCHAT_USERS_KEY}\s*:", raw):
            start = index
            break
    block = [f"{ROCKETCHAT_USERS_KEY}:\n"]
    for login in sorted(cache or {}):
        item = cache[login] if isinstance(cache.get(login), dict) else {}
        block.append(f"  {login}:\n")
        for key in ("username", "user_id", "resolved_at"):
            block.append(f"    {key}: {yaml_scalar(item.get(key))}\n")
    if start is None:
        text = "".join(lines)
        if text and not text.endswith("\n"):
            text += "\n"
        _atomic_write(path, text + "".join(block))
        return True
    end = len(lines)
    for index in range(start + 1, len(lines)):
        if re.match(r"^[A-Za-z_][A-Za-z0-9_]*\s*:", lines[index]):
            end = index
            break
    _atomic_write(
        path, "".join(lines[:start] + block + lines[end:])
    )
    return True


def _mention_usernames(logins, criteria, cache=None, root=None, warnings=None):
    """Логины → username'ы для упоминаний (резолв с кешем и мягким отказом)."""
    resolved = []
    for login in logins:
        username, warning = _rocketchat_resolve_login(
            login, criteria, cache, root
        )
        if warning and warnings is not None and warning not in warnings:
            warnings.append(warning)
        resolved.append(username)
    return resolved


def _roles_people(info):
    """(PdM, TL) — сначала из contacts (логины), затем из секции roles (ФИО).

    `contacts` — копия ростера команды из SSoT (см. `make contacts`): логин
    годится для Jira (`assignee`), тогда как `roles` хранит ФИО. Приоритет у
    contacts: это машинный источник, а roles заполняется руками.
    """
    people = {"pdm": None, "tl": None}
    groups = _contacts_groups(_info_contacts(info))
    pdm = _contact_logins(groups, "po") or _contact_logins(groups, "dm")
    if pdm:
        people["pdm"] = pdm[0]
    tl = _contact_logins(groups, "tl")
    if tl:
        people["tl"] = tl[0]
    roles = info.get("roles") if isinstance(info, dict) else None
    if not isinstance(roles, list):
        return people
    for item in roles:
        if not isinstance(item, dict):
            continue
        label = " ".join(
            str(item.get(key) or "") for key in ("role", "name", "title", "position")
        ).lower()
        person = item.get("person") or item.get("fio") or item.get("assignee")
        if not person:
            continue
        if people["pdm"] is None and ("pdm" in label or "product manager" in label or "продакт" in label):
            people["pdm"] = str(person)
        if people["tl"] is None and ("tl" in label or "tech lead" in label or "тимлид" in label):
            people["tl"] = str(person)
    return people


def _is_reassessment(entry, info, explicit=None):
    """Переоценка определяется ТОЛЬКО состоянием ДО генерации.

    Признаки: непустые `catalog.yaml` → `review_date`/`approve_link` либо
    записи `history` в INFORMATION.yaml. Сгенерированный паспорт не участвует:
    иначе второй `start --force` с той же `--date` давал бы другой action-пакет
    (первичная оценка → переоценка) и нарушал детерминизм.
    """
    if explicit is not None:
        return bool(explicit)
    entry = entry or {}
    for key in ("review_date", "approve_link"):
        if entry.get(key) not in (None, ""):
            return True
    history = (info or {}).get("history")
    return isinstance(history, list) and any(history)


def _ssot_severity_values(info):
    """(severity.type, [addon…]) из INFORMATION.yaml → ssot_snapshot.base.

    SSoT хранит критичность в kebab-case (`business-critical`), а доп. критерий —
    в `severity.addon` (`contact`). Нормализованное `identity.criticality_ssot`
    (Title Case) для «старой критичности» не годится: в публикации нужен
    исходный вид записи SSoT.
    """
    snapshot = (info or {}).get("ssot_snapshot")
    base = snapshot.get("base") if isinstance(snapshot, dict) else None
    severity = base.get("severity") if isinstance(base, dict) else None
    if not isinstance(severity, dict):
        return None, []
    raw = severity.get("type")
    value = str(raw).strip() if raw not in (None, "") else None
    addon = severity.get("addon")
    addons = []
    for item in addon if isinstance(addon, list) else [addon]:
        text = str(item).strip() if item not in (None, "") else ""
        if text:
            addons.append(text.upper())
    return value, addons


def _publication_extra_info(info):
    """Свободный текст «Дополнительная информация по оценке» (опционально).

    Источник — `INFORMATION.yaml → publication.extra_info` (новый опциональный
    ключ). Поле необязательное: нет значения — буллет в публикации не
    рендерится вовсе (никакого `⛔`, см. `templates/publication.md`).

    `notes` — служебные заметки репозитория (список записей о данных, а не
    текст для треда), поэтому как fallback они НЕ используются. Fallback
    допускается только для свободной строки `notes` — на случай legacy-файла,
    где заметка хранилась строкой.
    """
    if not isinstance(info, dict):
        return None
    publication = info.get("publication")
    value = publication.get("extra_info") if isinstance(publication, dict) else None
    if value in (None, ""):
        notes = info.get("notes")
        # Список/словарь — служебные заметки, для треда не подходят.
        if isinstance(notes, str):
            value = notes
    if value in (None, "") or isinstance(value, (list, dict)):
        return None
    text = str(value).strip()
    return text or None


def _financial_loss_route(criteria):
    """`where` необязательного входа financial_loss (маршрут для GMV)."""
    optional = ((criteria or {}).get("inputs") or {}).get("optional") or []
    for item in optional:
        if isinstance(item, dict) and item.get("id") == "financial_loss":
            return str(item.get("where") or "").strip() or None
    return None


def build_render_context(
    code, entry, info, criteria, computed, date, existing=None, catalog=None,
    reassessment=None, provisional=None, root=None, persist_mentions=True,
):
    """Контекст рендера: всё, что шаблоны имеют право подставлять."""
    entry = entry or {}
    info = info if isinstance(info, dict) else {}
    existing = existing if isinstance(existing, dict) else {}
    if provisional is None:
        provisional = provisional_score(criteria, evaluate_gate(info, criteria))
    name, contour = split_is_code(code)
    identity_src = info.get("identity") if isinstance(info.get("identity"), dict) else {}
    contact_groups = _contacts_groups(_info_contacts(info))
    ta_logins = _contact_logins(contact_groups, "ta")
    tl_logins = _contact_logins(contact_groups, "tl")
    sa_logins = _contact_logins(contact_groups, "sa") or _contact_logins(
        contact_groups, "s-arch"
    )
    # Упоминания в RocketChat — по полному username (`dkozlov@ecom.tech`):
    # короткий логин в `mentions[]` не попадает. Кеш — catalog.yaml →
    # rocketchat_users; сеть трогается только при `root` (реальный прогон), и
    # отказ резолва не ломает рендер, а становится WARN.
    mention_warnings = []
    mention_cache = _rocketchat_users_cache(catalog)
    # dry-run не резолвит вовсе (root=None → ранний возврат): в артефакте
    # остаётся логин из SSoT, сеть не трогается, кеш не пополняется. Реальный
    # прогон резолвит логин через users.info и пишет кеш в catalog.yaml.
    mention_root = root if persist_mentions else None
    ta_mentions = _mention_usernames(
        ta_logins, criteria, mention_cache, mention_root, mention_warnings
    )
    tl_mentions = _mention_usernames(
        tl_logins, criteria, mention_cache, mention_root, mention_warnings
    )
    sa_mentions = _mention_usernames(
        sa_logins, criteria, mention_cache, mention_root, mention_warnings
    )

    facts = facts_block(info.get("facts"))
    block = _criteria_input_block(info)

    def field(key, legacy_keys):
        item = block.get(key)
        if isinstance(item, dict):
            status = str(item.get("status") or "missing").strip().lower()
            # Отказ (R17): значения НЕ существует, поэтому прежний паспорт не
            # может его «подставить» — иначе паспорт утверждает число, которого
            # методика не признаёт.
            if status == WAIVED_STATUS:
                return None, None, "missing"
            value = item.get("value")
            if value not in (None, ""):
                return value, item.get("source"), status
        for legacy in legacy_keys:
            value = _scalar_at(info, legacy)
            if value not in (None, ""):
                return value, None, "legacy"
        for legacy in legacy_keys:
            value = existing.get(legacy)
            if value not in (None, ""):
                return value, "criticality-passport.yaml", "legacy"
        return None, None, "missing"

    workload, workload_source, workload_status = field(
        "peak_hour_load", ("object_workload", "workload")
    )
    # Единица нагрузки: у входа она может быть «запросов/час» (пик снят как RPS
    # шлюза). Подпись в CRITICALITY.md берётся из источника, а не из константы.
    workload_entry = block.get("peak_hour_load")
    workload_unit = None
    if isinstance(workload_entry, dict):
        workload_unit = str(workload_entry.get("unit") or "").strip() or None
    workload_unit = workload_unit or REQUIREMENT_UNIT_DEFAULTS["peak_hour_load"]
    consumers, consumers_source, consumers_status = field(
        "consumers_type", ("object_consumers_type",)
    )
    impact, impact_source, impact_status = field(
        "outage_impact", ("object_outage_impact",)
    )
    sla, sla_source, sla_status = field("object_sla", ("object_sla", "sla"))

    final = computed["final"] if computed else None
    identity_ssot = identity_src.get("criticality_ssot")
    catalog_ssot = entry.get("criticality_ssot")
    if identity_ssot not in (None, ""):
        ssot = identity_ssot
        ssot_source = "INFORMATION.yaml → identity.criticality_ssot (SSoT)"
        ssot_status = "confirmed"
    elif catalog_ssot not in (None, ""):
        ssot = catalog_ssot
        ssot_source = "catalog.yaml → criticality_ssot (SSoT не заполнен)"
        ssot_status = "legacy"
    else:
        ssot = dochub_to_ssot_map(criteria).get(final) if final is not None else None
        ssot_source = "расчёт (levels.dochub_to_ssot)"
        ssot_status = "derived"
    conflicts = _start_conflicts(entry, computed, info, criteria) if computed else []
    ssot_conflict = any(item["field"] == "criticality_ssot" for item in conflicts)
    # `approve_link` — ссылка на тред согласования: её пишет `handoff` в реестр
    # (`approve_link`, а для уже опубликованных тредов — `thread_link`).
    # Версионируемый источник в реестре, прежнее значение паспорта вторично.
    approve = (
        entry.get("approve_link")
        or entry.get(THREAD_LINK_FIELD)
        or existing.get("approve_link")
    )
    # `assigned_date`/`review_date` привязаны к ДАТЕ ГЕНЕРАЦИИ (`generated_at`,
    # параметр --date), а не к моменту `finalize`: иначе даты зависели бы от
    # того, когда человек нажал кнопку. Явно заданное значение реестра или
    # прежнего паспорта остаётся override (первая оценка не сдвигается
    # перегенерацией); `finalize` пишет в реестр ровно эти значения.
    generated_date = date
    assigned_raw = (
        entry.get("assigned_date")
        or existing.get("assigned_date")
        or generated_date.isoformat()
    )
    review_date_value, review_date_source_label = review_date_source(entry, info, existing)
    if review_date_value is None:
        months = review_period(catalog or {}, entry, criteria)
        try:
            review_date_value = add_months(generated_date, int(months))
        except (TypeError, ValueError):
            review_date_value = None
        review_date_source_label = (
            f"generated_at ({generated_date.isoformat()}) + "
            f"review_period_months={months}"
        )
    review_date_warning = None

    identity = {
        "code": code,
        "name": identity_src.get("name") or entry.get("name"),
        "contour": contour,
        # `_fact_value` — плейсхолдер (`⛔`, `E001.A<TODO>`) не становится
        # фактом: значение источника нормализуется до None (repo-уточнение).
        "asset": _fact_value(identity_src.get("asset") or entry.get("asset")),
        "product": _fact_value(identity_src.get("product") or entry.get("product")),
        "product_slug": _slug(
            _fact_value(identity_src.get("product") or entry.get("product"))
        ),
        "arch_code": _fact_value(identity_src.get("arch_code") or entry.get("arch_code")),
        "team": _fact_value(identity_src.get("team") or entry.get("team")),
        "sa": entry.get("tech_architect") or entry.get("sa"),
        # TA/TL — упоминания RocketChat по ПОЛНОМУ username из contacts
        # (`@dkozlov@ecom.tech`): короткий логин в `mentions[]` не попадает.
        # Fallback для TA — ФИО из catalog.yaml (tech_architect, затем sa):
        # упоминания не будет, но подпись в публикации не останется пустой (как
        # обещает templates/catalog.yaml: «при отсутствии берётся sa»).
        "ta": (
            _mention_text(ta_mentions)
            or entry.get("tech_architect")
            or entry.get("sa")
        ),
        "tl": _mention_text(tl_mentions),
        # sa_mention — готовое упоминание системного архитектора (в шаблонах
        # пока не используется: identity.sa остаётся ФИО из catalog.yaml).
        # Служебные адресаты (`all`/`here`/`channel`) упоминанием не становятся.
        "sa_mention": (_mentions(sa_mentions[:1]) or [None])[0],
        # Оценка предварительная (R17): в паспорте нет свободного поля для
        # пометки, поэтому статус артефакта — `draft`, а предупреждение несёт
        # CRITICALITY.md (вариант 2 из templates/criticality-passport.yaml).
        "status": "draft" if provisional.get("provisional") else (entry.get("status") or "draft"),
        "criticality_ssot": ssot,
        "extra_criteria": entry.get("extra_criteria") or [],
        "confluence_page_id": entry.get("confluence_page_id"),
        "dr_page_id": entry.get("dr_page_id"),
        "decision_log_page_id": entry.get("decision_log_page_id"),
        "criticality_source_page_id": entry.get("criticality_source_page_id"),
        "gitlab_group": entry.get("gitlab_group")
        or _external_ref_pattern(
            criteria, "gitlab_group_base", {"contour": contour, "name": name}
        ),
        "dochub_object": entry.get("dochub_object")
        or f"sber.ecom.{contour}.criticality_passport.{name}",
        # Путь публикации в dochub — тот же расчёт, что у publish
        # (_publish_rel_dir + DOCHUB_PASSPORT_FILE): контур латиницей (mm/smkt),
        # имя без суффикса контура. Шаблон печатает его в шапке как есть —
        # никакого актива («СМКТ») и `<name>.<контур>` в пути быть не может.
        "dochub_path": (
            _publish_rel_dir(contour, name) / DOCHUB_PASSPORT_FILE
        ).as_posix(),
        "name_slug": name,
        "criticality_slug": _slug(final),
        "review_date": (
            review_date_value.isoformat() if review_date_value is not None else None
        ),
        "generated_at": date.isoformat(),
        "assigned_date": _iso_date(assigned_raw),
        "components_count": len(info.get("components") or []),
    }

    passport = {
        "id": identity["dochub_object"],
        "evaluated_object": f"sber.ecom.{contour}.{name}",
        "object_workload": workload,
        "object_consumers_type": consumers,
        "object_outage_impact": impact,
        "object_sla": sla,
        "object_criticality_estimation": final,
        "assigned_date": _dot_date(assigned_raw),
        "review_date": (
            review_date_value.strftime("%Y.%m.%d")
            if review_date_value is not None
            else None
        ),
        "generated_at": date.strftime("%Y.%m.%d"),
        "approve_link": approve,
    }

    rows = []

    # «Старая критичность» — факт из SSoT, а не расчёт: severity.type в исходном
    # виде + severity.addon (доп. критерии). Fallback на реестр, затем на null:
    # подставлять сюда новый уровень нельзя — отсутствие данных маскировалось бы
    # под данные (дефект «факт-или-null»).
    ssot_old_value, ssot_addons = _ssot_severity_values(info)
    old_criticality = ssot_old_value or entry.get("criticality")
    catalog_extra = [str(item) for item in identity["extra_criteria"]]
    if ssot_old_value:
        extra_criteria_values = ssot_addons or catalog_extra
        extra_criteria_source = (
            "INFORMATION.yaml → ssot_snapshot.base.severity.addon (SSoT)"
            if ssot_addons
            else "catalog.yaml → extra_criteria (SSoT: addon не задан)"
        )
    else:
        extra_criteria_values = catalog_extra
        extra_criteria_source = "catalog.yaml → extra_criteria"

    def row(field_name, value, status, source):
        rows.append(
            {
                "field": field_name,
                "value": MISSING_MARK if value in (None, "") else _tpl_stringify(value),
                "status": STATUS_MARK.get(status, "⚠️ требует подтверждения"),
                "source": source or "—",
            }
        )

    row(
        "`evaluated_object`",
        passport["evaluated_object"],
        "confirmed",
        "правило `sber.ecom.<контур>.<name_is>` (docs/05-mapping.md)",
    )
    row(
        "`object_workload`",
        workload,
        workload_status if workload is not None else "missing",
        workload_source or "TODO: TL/PdM",
    )
    row(
        "`object_consumers_type`",
        consumers,
        consumers_status if consumers is not None else "missing",
        consumers_source or "TODO: PdM",
    )
    row(
        "`object_outage_impact`",
        impact,
        impact_status if impact is not None else "missing",
        impact_source or "TODO: PdM + TL",
    )
    row(
        "`object_sla`",
        sla,
        sla_status if sla is not None else "missing",
        sla_source or "TODO: SRE",
    )
    row(
        "`object_criticality_estimation`",
        final,
        "confirmed" if final else "missing",
        f"расчёт `criticality.py start` ({computed['method']}, {computed['status']})"
        if computed
        else "—",
    )
    # Источник `assigned_date` — реестр (`catalog.yaml → assigned_date`), поэтому
    # статус производный: подтверждённая запись реестра = подтверждённое
    # значение. Хардкод `legacy` помечал заполненную дату «требует
    # подтверждения» даже при `status: confirmed`. Дата, выведенная из
    # `generated_at` (записи реестра нет), остаётся `derived`.
    assigned_from_source = bool(
        entry.get("assigned_date") or existing.get("assigned_date")
    )
    row(
        "`assigned_date`",
        _dot_date(assigned_raw),
        registry_row_status(entry, assigned_raw)
        if assigned_from_source
        else "derived",
        "реестр / прежний паспорт"
        if assigned_from_source
        else f"generated_at ({generated_date.isoformat()})",
    )
    row(
        "`review_date`",
        passport["review_date"],
        "confirmed" if review_date_value is not None else "missing",
        review_date_source_label or "TODO: зафиксировать дату текущей оценки",
    )
    row(
        "`generated_at`",
        passport["generated_at"],
        "derived",
        f"дата генерации ({date.isoformat()}, --date)",
    )
    # `approve_link` — тоже факт реестра (`catalog.yaml → approve_link`): статус
    # производный, как у `assigned_date`. Заполненная подтверждённая ссылка —
    # «подтверждено», а не «требует подтверждения».
    row(
        "`approve_link`",
        approve,
        registry_row_status(entry, approve),
        "реестр / предыдущий паспорт (ссылка на тред согласования)"
        if approve
        else "нет треда: make handoff IS=<код> SEND=auto",
    )
    row(
        "`criticality_ssot`",
        ssot,
        "derived" if ssot_conflict else ssot_status,
        ssot_source,
    )
    row(
        "`extra_criteria`",
        ", ".join(str(item) for item in extra_criteria_values) or "нет",
        "confirmed",
        extra_criteria_source,
    )

    # Именованные ячейки паспорта: шаблон печатает нужные поля, не дублируя
    # всю сводку. `passport_rows` остаётся полным списком (совместимость).
    passport_cells = {}
    for item in rows:
        passport_cells[str(item["field"]).strip("`")] = item

    trace = _score_trace(criteria, computed, info, provisional=provisional)
    people = _roles_people(info)

    components = []
    for item in info.get("components") or []:
        if isinstance(item, dict):
            components.append(
                {
                    "name": item.get("name"),
                    "description": item.get("description"),
                    "language": item.get("language"),
                    "git_repository": item.get("git_repository"),
                    "clone_status": item.get("clone_status"),
                }
            )

    resources = [item for item in (info.get("resources") or []) if isinstance(item, dict)]
    links = {}
    raw_links = info.get("links")
    if isinstance(raw_links, dict):
        for key, value in raw_links.items():
            links[str(key)] = _tpl_stringify(value)

    sources, source_warnings = _start_sources(identity, criteria, catalog)
    refs, ref_warnings = _external_refs(criteria, entry)
    confluence_url = _page_url(criteria, identity.get("confluence_page_id"))
    refs["confluence_page"] = {
        "id": identity.get("confluence_page_id"),
        "title": "Страница ИС в Confluence",
        "note": None,
        "url": confluence_url,
    }
    if not confluence_url:
        ref_warnings.append(
            "identity.confluence_page_id не задан — refs.confluence_page будет "
            f"{MISSING_MARK}"
        )
    source_warnings = list(source_warnings) + ref_warnings
    if review_date_warning:
        source_warnings.append(review_date_warning)
    # Отказ резолва упоминания — WARN в GENERATION.md и консоль: уведомление
    # в треде не придёт, но расчёт и рендер от этого не блокируются.
    for mention_warning in mention_warnings:
        if mention_warning not in source_warnings:
            source_warnings.append(mention_warning)
    todo = _start_todo(passport, facts, conflicts, people)
    history = _start_history(info, date, final)
    # Если у всех E2E-процессов влияние и статус одинаковы (типовой случай
    # reverse-import карты процессов), они печатаются один раз, а список
    # остаётся перечнем процессов: один факт — одно место.
    e2e_shared = None
    e2e_items = [item for item in facts["e2e_processes"] if isinstance(item, dict)]
    if e2e_items:
        impacts = {str(item.get("impact")) for item in e2e_items}
        e2e_sources = {str(item.get("source")) for item in e2e_items}
        statuses = {str(item.get("status")) for item in e2e_items}
        if len(impacts) == 1 and len(statuses) == 1:
            e2e_shared = {
                "impact": e2e_items[0].get("impact"),
                "status": e2e_items[0].get("status"),
                "source": (
                    e2e_items[0].get("source") if len(e2e_sources) == 1 else None
                ),
            }
    e2e_names = e2e_list_values(criteria, facts)
    adr_link, adr_basis = adr_link_value(criteria, facts, entry, catalog)
    adr_warning = adr_orphan_warning(facts)
    if adr_warning:
        source_warnings.append(adr_warning)
    scope_page_id = entry.get("product_scope_page_id") or (catalog or {}).get(
        "product_scope_page_id"
    )
    e2e_text = e2e_missing_text(code, facts, criteria, scope_page_id)

    # Действующий процесс D6.1.1 — источник правил оценки. Ссылка рендерится
    # только когда источник объявлен в criteria.meta.sources (role
    # process_current): «⛔ не заполнено» здесь было бы шумом, а не задачей.
    process_link = None
    process_source = _criteria_source(criteria, "process_current")
    if isinstance(process_source, dict):
        page_id = process_source.get("page_id")
        url = _page_url(criteria, page_id)
        if url:
            title = str(process_source.get("title") or "").strip()
            version = process_source.get("version")
            label = f"«{title}» [{page_id}] " if title else ""
            suffix = (
                f" (действующий, v{version})"
                if version not in (None, "")
                else " (действующий)"
            )
            process_link = f"{label}{url}{suffix}"

    # Карточка ИС в SSoT: шаблон URL — в criteria.external_refs.ssot_card_base
    # (шаблон публикации задаёт формат дословно), в скрипте адрес не хардкодится.
    ssot_card_link = _external_ref_pattern(criteria, "ssot_card_base", {"code": code})
    if not ssot_card_link:
        source_warnings.append(
            "criteria.external_refs.ssot_card_base не задан — ссылка на карточку "
            f"ИС в SSoT будет {MISSING_MARK}"
        )

    # Раздел 3 публикации: финансовые потери (GMV). Вход необязательный, поэтому
    # голое «⛔ не заполнено» запрещено — печатается маршрут, где данные взять.
    gmv_block = block.get("financial_loss")
    gmv_block = gmv_block if isinstance(gmv_block, dict) else {}
    gmv_value, gmv_source, _gmv_status = field(
        "financial_loss", ("object_financial_loss", "financial_loss")
    )
    if gmv_value not in (None, ""):
        # Значение печатается вместе с единицей измерения и обоснованием:
        # голое «0» без «руб/час» читается как незаполненное поле, а источник
        # без обоснования не объясняет, почему ноль.
        value_text = _tpl_stringify(gmv_value)
        unit = str(gmv_block.get("unit") or "").strip()
        if unit:
            value_text = f"{value_text} {unit}"
        raw_source = gmv_block.get("source")
        if isinstance(raw_source, dict):
            # Печатается `ref` (человекочитаемое основание), а не дамп словаря:
            # `type: manual` — служебная деталь, читателю канала она не нужна.
            source_text = str(
                raw_source.get("ref") or raw_source.get("url") or ""
            ).strip() or _tpl_stringify(raw_source)
        elif raw_source not in (None, ""):
            source_text = _tpl_stringify(raw_source)
        elif gmv_source not in (None, ""):
            source_text = _tpl_stringify(gmv_source)
        else:
            source_text = ""
        note = str(gmv_block.get("note") or "").strip()
        gmv_impact = value_text
        if note:
            gmv_impact = f"{gmv_impact}. {note}"
        if source_text:
            gmv_impact = f"{gmv_impact} (источник: {source_text})"
    else:
        route = []
        where = _financial_loss_route(criteria)
        if where:
            route.append(f"где взять: {where}")
        inputs_ref = refs.get("inputs_page") or {}
        inputs_link = _page_link(
            criteria, inputs_ref.get("id"), inputs_ref.get("title")
        )
        if inputs_link:
            route.append(f"требования к входу — {inputs_link}")
        route.append("лист недостающих данных — DATA-REQUIREMENTS.md")
        gmv_impact = MISSING_MARK + (" — " + "; ".join(route) if route else "")

    if reassessment is None:
        reassessment = _is_reassessment(entry, info)
    else:
        reassessment = bool(reassessment)
    labels = ["Mission_Assesment"]
    if reassessment:
        labels.append("Reassessment")

    jira_status = "requested" if getattr(_START_FLAGS, "create_task", False) else "pending_manual"
    confluence_status = (
        "requested" if getattr(_START_FLAGS, "create_confluence", False) else "pending_manual"
    )
    message_status = (
        "requested" if getattr(_START_FLAGS, "create_message", False) else "pending_manual"
    )
    # Jira-задача: ключ из реестра (`catalog.yaml → jira_task`, `is.yaml → task`)
    # и ссылка по шаблону `criteria.external_refs.jira_base`. Ключ известен —
    # в треде печатается ссылка, а не `⛔`: номер задачи уже есть.
    jira_task_key = _publish_task(entry, info, None)
    jira_task_link = (
        _external_ref_pattern(criteria, "jira_base", {"key": jira_task_key})
        if jira_task_key
        else None
    )
    # «Дополнительная информация по оценке» — опциональное свободное поле:
    # нет значения — буллет не рендерится (не `⛔` и не блокер публикации).
    extra_info = _publication_extra_info(info)

    # --- Ссылки action-пакета из штатных артефактов -------------------------
    # MR — только артефакт соответствующего этапа: `.publish/<код>-MR.url`
    # пишет `publish` после пуша, `.ssot/<код>-MR.url` — `ssot`. Проверка та же,
    # что у publish/ssot (`_mr_url_problem`): битая ссылка в артефакт не идёт.
    # Пустое значение не финально: `_start_one` перезапишет его, если артефакт
    # появится позже в том же прогоне.
    mr_link = None
    ssot_mr_link = None
    ssot_mr_note = None
    if root is not None:
        artifact = _mr_url_artifact_read(root, code, DOCHUB_MR_DIR)
        if artifact and _mr_url_problem(artifact) is None:
            mr_link = artifact
        artifact = _mr_url_artifact_read(
            Path(root) / SSOT_DEFAULT_DIR, code, SSOT_MR_DIR
        )
        if artifact and _mr_url_problem(artifact) is None:
            ssot_mr_link = artifact
        elif _ssot_level_matches(root, code, entry, criteria) is True:
            # Уровень критичности в SSoT уже целевой: `ssot` не изменит
            # `severity.type`, MR по критичности не требуется. Это не «забыли
            # заполнить», а «не нужно».
            ssot_mr_note = "не требуется — критичность в SSoT уже совпадает"
    # `ssot_mr_ref` — то, что печатается в публикации: ссылка, иначе честная
    # пометка «не требуется». Пусто — оба варианта неизвестны (⛔).
    ssot_mr_ref = ssot_mr_link or ssot_mr_note

    # --- handoff: ограничения и что требуется от SRE ------------------------
    # Только факты состояния: происхождение E2E-карты, статусы входов,
    # расхождения с реестром, заполненность approve_link. Ничего не
    # досочиняется — пустой список печатается как «не зафиксировано».
    handoff_limits = []
    if e2e_shared and str(e2e_shared.get("status") or "").lower() == "derived":
        handoff_limits.append(
            "состав E2E-процессов получен обратным импортом карты "
            "(status: derived) — владелец ИС его не подтверждал"
        )
    for item in trace["inputs"]:
        if str(item.get("status") or "").lower() == "derived":
            handoff_limits.append(
                f"`{item['id']}` — значение производное (derived), "
                "не подтверждено владельцем"
            )
    for conflict in conflicts:
        handoff_limits.append(
            f"расхождение с реестром `{conflict['field']}`: "
            f"расчёт {conflict['computed']} ≠ реестр {conflict['actual']}"
        )
    handoff_needs_sre = []
    if str(sla_status).lower() not in ("confirmed", "legacy"):
        handoff_needs_sre.append(
            "подтвердить норматив простоя (`object_sla`) и показатели "
            "поддержки (`facts.support`)"
        )
    if str(impact_status).lower() not in ("confirmed", "legacy"):
        handoff_needs_sre.append(
            "подтвердить характер влияния при простое (`object_outage_impact`)"
        )
    if any("E2E" in item for item in handoff_limits):
        handoff_needs_sre.append("подтвердить состав E2E-процессов")
    if approve in (None, ""):
        handoff_needs_sre.append(HANDOFF_APPROVE_ASK + " (`approve_link`)")

    actions = {
        "reassessment": reassessment,
        "labels": labels,
        # Ссылки на MR появляются только после внешних шагов: паспорт — после
        # `publish --push` (dochub-MR), критичность — после `ssot --push`
        # (SSoT-MR). Тред `handoff` ссылается на ОБА, поэтому в action-пакете
        # два отдельных поля; выдумывать URL скрипт не может.
        # `mr_link` — имя, которое читают шаблоны; `publish_mr_link` — то же
        # значение под явным именем этапа (заполняются вместе в `_start_one`).
        "mr_link": mr_link,
        "publish_mr_link": mr_link,
        "ssot_mr_link": ssot_mr_link,
        "ssot_mr_note": ssot_mr_note,
        "ssot_mr_ref": ssot_mr_ref,
        # Текст строки «MR в SSoT»: ссылка, «не требуется» (ssot_status:
        # no_change) или None → ⛔. Ссылка появляется позже (`_start_one`),
        # поэтому поле пересчитывается там же через `_ssot_mr_text`.
        # Текст строки «MR в SSoT»: артефакт этапа (`ssot_mr_ref`) приоритетнее
        # статуса реестра; иначе — решение по `ssot_status: no_change`.
        "ssot_mr_text": ssot_mr_ref or _ssot_mr_cell_text(entry, None, info),
        "ssot_status": str(entry.get(SSOT_STATUS_FIELD) or "").strip() or None,
        # Карточка ИС в SSoT собирается из шаблона URL, а не остаётся пустой:
        # чек-лист публикации требует именно эту ссылку.
        "ssot_card_link": ssot_card_link,
        "task_link": jira_task_link,
        # Номер задачи на уровне actions — тот же факт, что
        # `actions.jira.task_key` и `task_key` в корне контекста.
        "task_key": jira_task_key,
        # Старая критичность — факт из SSoT (severity.type) или реестра; новый
        # уровень сюда не подставляется (см. вычисление old_criticality).
        "old_criticality": old_criticality,
        "extra_criteria": ", ".join(str(item) for item in extra_criteria_values) or None,
        # Опциональное поле: None — буллет в публикации не рендерится.
        "extra_info": extra_info,
        # Ссылка на действующий процесс D6.1.1 (None — источника нет, буллет не
        # рендерится).
        "process_link": process_link,
        # Раздел 3: потери GMV/влияние на аудиторию (значение или маршрут).
        "gmv_impact": gmv_impact,
        "adr_link": adr_link,
        # Основание ссылки: adr | architecture | is_page | none — публикация не
        # выдаёт архитектуру ИС за АДР (GENERATION.md печатает это же).
        "adr_basis": adr_basis,
        "e2e_list": e2e_names,
        # Готовая строка «чего именно не хватает» для шаблонов без #each.
        "e2e_text": e2e_text,
        "handoff_limits": handoff_limits,
        "handoff_needs_sre": handoff_needs_sre,
        "jira": {
            "status": jira_status,
            "summary": f"Оценка критичности ИС {code} ({identity['name'] or 'название не задано'})",
            "task_key": jira_task_key,
            "task_link": jira_task_link,
            "assignee_pdm": people["pdm"],
            "assignee_tl": people["tl"],
            "author": people["tl"] or identity["sa"],
            "project_type": "не задано процессом",
        },
        "confluence": {
            "status": confluence_status,
            "title": f"Оценка критичности ИС {code} — {identity['name'] or 'название не задано'}",
            "parent_page_id": identity["confluence_page_id"],
        },
        "message": {
            "status": message_status,
            "channel": "#Criticality_assessment",
            "text": None,
            # Гейт `handoff`: заполняется в `_start_one` после рендера текста
            # сообщения — статус `requested` ставится только без `⛔`.
            "blocked": False,
            "blocked_count": 0,
            "blocked_fields": [],
        },
    }

    return {
        "meta": {
            "date": date.isoformat(),
            "date_dot": date.strftime("%Y.%m.%d"),
            "generator": "criticality.py start",
            "code": code,
            # Фингерпринт влияющих секций критериев: по нему видно, что
            # артефакты собраны на другой версии критериев (mtime не годится).
            "criteria_fingerprint": criteria_fingerprint(criteria),
        },
        "identity": identity,
        "passport": passport,
        "passport_rows": rows,
        "passport_cells": passport_cells,
        "workload_unit": workload_unit,
        "levels": {
            "order": level_order(criteria),
            # `calculated` — то, что может выдать расчёт (levels.order).
            "calculated": level_order(criteria),
            "inline_calculated": " | ".join(level_order(criteria)),
            # `all`/`inline` — включая dochub-extra: только для публикации в
            # dochub (внешний уровень, методикой не производится).
            "all": level_set(criteria),
            "inline": " | ".join(level_set(criteria)),
            "extra": dochub_extra_level(criteria),
        },
        "facts": facts,
        "e2e_shared": e2e_shared,
        "criteria_inputs": block,
        "score_trace": trace,
        "components": components,
        "resources": resources,
        "duties": [
            item for item in (info.get("duties") or []) if isinstance(item, dict)
        ],
        "links": links,
        "refs": refs,
        "sources": sources,
        "source_warnings": source_warnings,
        "todo_items": todo,
        "history": history,
        "conflicts": conflicts,
        "actions": actions,
        "generation": {},
        # Ключ задачи на верхнем уровне — для шаблонов, читающих `task_key`
        # напрямую (actions/jira-task.md). Нет ключа — None (в шаблоне ⛔).
        "task_key": jira_task_key,
    }


def _rule_source_label(rule):
    """Подпись источника правила для артефактов: page_id, артефакт или convention."""
    if rule.get("kind") == "documented":
        page = rule.get("page_id") or rule.get("source_page_id")
        if page is not None:
            return f"page {page}"
        artifact = str(rule.get("source_artifact") or "").strip()
        return f"артефакт {artifact}" if artifact else "источник не указан"
    return f"convention ({rule.get('status')})"


def _score_trace(criteria, computed, info, provisional=None):
    """Блок §7: метод, входы, промежуточные значения, конвенции, статус."""
    provisional_fields = _provisional_trace_block(provisional)
    definitions = (criteria.get("time_buckets") or {}).get("definitions") or {}
    titles = {str(item.get("id")): str(item.get("title")) for item in axis_items(criteria)}
    weights = cia_weights_hundredths(criteria)
    required = [
        str(item.get("id"))
        for item in ((criteria.get("inputs") or {}).get("required") or [])
        if isinstance(item, dict)
    ]
    found, missing, derived = _information_inputs(criteria, info)
    block = _criteria_input_block(info)

    def external_source(identifier):
        """Адрес источника значения (`type: ref`) — для колонки «Источник».

        `source` остаётся путём в `INFORMATION.yaml` (провенанс в репозитории),
        `source_brief` — внешний адрес: page_id / uid дашборда / «решение PdM».
        """
        entry = block.get(identifier) if isinstance(block, dict) else None
        if not isinstance(entry, dict):
            return None
        source = entry.get("source")
        if not isinstance(source, dict):
            return None
        kind = str(source.get("type") or "").strip()
        ref = str(source.get("ref") or "").strip()
        if not ref:
            return None
        return f"{kind}: {ref}" if kind else ref

    # Отказ (R17) — не «недостающий» вход: он закрыт осознанным решением, и в
    # §4 GENERATION.md («Недостающие обязательные входы») попадать не должен.
    waived_set = set(provisional_fields.get("waived_inputs") or [])
    inputs = []
    for identifier in required:
        if identifier in waived_set:
            inputs.append(
                {
                    "id": identifier,
                    "value": "null (waive)",
                    "source": "явный отказ от данных (R17)",
                    "status": WAIVED_STATUS,
                }
            )
            continue
        if identifier in found:
            value, ref, status = found[identifier]
            inputs.append(
                {
                    "id": identifier,
                    "value": _tpl_stringify(value),
                    "source": f"INFORMATION.yaml → {ref}",
                    "source_brief": external_source(identifier)
                    or f"INFORMATION.yaml → {ref}",
                    "status": status,
                }
            )
        else:
            inputs.append(
                {
                    "id": identifier,
                    "value": MISSING_MARK,
                    "source": "—",
                    "source_brief": "—",
                    "status": "missing",
                }
            )
    for identifier, ref in derived:
        for item in inputs:
            if item["id"] == identifier:
                item["status"] = "derived"

    conventions = []
    method_key = computed["method"] if computed else "detailed"
    for path in CONVENTION_PATHS.get(method_key, []):
        rule = _at(criteria, path)
        if not isinstance(rule, dict) or rule.get("kind") != "convention":
            continue
        conventions.append(
            {
                "name": ".".join(path),
                "status": rule.get("status") or "status не указан",
                "rationale": rule.get("rationale") or "—",
            }
        )

    rules = []
    for path in START_METHOD_RULES.get(computed["method"] if computed else "detailed", []):
        rule = _at(criteria, path)
        if not isinstance(rule, dict):
            continue
        source = _rule_source_label(rule)
        page = rule.get("page_id") or rule.get("source_page_id")
        url = _page_url(criteria, page) if page is not None else None
        rules.append(
            {
                "name": ".".join(path),
                "kind": rule.get("kind") or "—",
                # `source` — для консоли (`score`), `source_md` — для артефактов:
                # page N рендерится ссылкой через external_refs.base_url.
                "source": source,
                "source_md": f"[{source}]({url})" if url else source,
                # Сноска: правило осознанно опирается на архивную страницу —
                # единственный носитель части канона (source_note объясняет).
                "note": (
                    str(rule.get("source_note") or "").strip()
                    if str(rule.get("source_status") or "").strip()
                    == "archived_carrier"
                    else ""
                ),
            }
        )
    rule_notes = [
        {"name": item["name"], "note": item["note"]}
        for item in rules
        if item.get("note")
    ]

    if computed is None:
        return {
            "method": "—",
            "method_label": "расчёт не выполнялся",
            "status": "missing",
            "axes": [],
            "max_score": None,
            "bucket": None,
            "bucket_definition": None,
            "business_level": None,
            "cia_rows": [],
            "cia_value": None,
            "protection": None,
            "protection_business": None,
            "protection_scale": None,
            "final_level": None,
            "express": None,
            "inputs": inputs,
            "conventions": conventions,
            "rules": rules,
            "rule_notes": rule_notes,
            **provisional_fields,
        }

    if computed["method"] == "detailed":
        business = computed["business"]
        cia = computed["cia"]
        axes = [
            {
                "id": axis,
                "title": titles.get(axis, axis),
                "score": business["axes"][axis],
                "scale": ((next((item for item in axis_items(criteria) if str(item.get("id")) == axis), {})).get("scale") or {}).get(
                    str(business["axes"][axis]), ""
                ),
            }
            for axis in axis_ids(criteria)
        ]
        cia_rows = [
            {
                "parameter": parameter,
                "level": cia["cia"][parameter],
                "weight": f"{weights[cia['cia'][parameter]] / 100:.2f}",
            }
            for parameter in CIA_PARAMETERS
        ]
        return {
            "method": "detailed",
            "method_label": "детальный: оценки осей 0..4 → impact_matrix",
            "status": "complete",
            "axes": axes,
            "max_score": business["max"],
            "bucket": business["bucket"],
            "bucket_definition": definitions.get(business["bucket"], "—"),
            "business_level": business["level"],
            "cia_rows": cia_rows,
            "cia_value": cia["value_display"],
            "protection": cia["protection"],
            "protection_business": cia["business"],
            "protection_scale": protection_scale_text(criteria),
            "final_level": computed["final"],
            "express": None,
            "inputs": inputs,
            "conventions": conventions,
            "rules": rules,
            "rule_notes": rule_notes,
            **provisional_fields,
        }

    express = computed["express"]
    trace = express["trace"]
    times = express["t"]
    rows = [
        {
            "label": "Тип клиентов",
            "value": f"{_tpl_stringify(express['consumers'])} (коэф. {_fmt_num(trace['client_coef'])})",
        },
        {
            "label": "Характер влияния",
            "value": (
                f"{_tpl_stringify(express['impact'])} (коэф. {_fmt_num(trace['impact_coef'])}"
                + (f", {trace['impact_category']}" if trace.get("impact_category") else "")
                + ")"
            ),
        },
        {"label": "Пиковая нагрузка", "value": f"{_fmt_num(trace['load'])} клиентов/час"},
        {"label": "SLA (допустимый простой)", "value": f"{_fmt_num(trace['sla'])} мин"},
        {
            "label": "E = коэф. типа × коэф. влияния × нагрузка",
            "value": f"{_fmt_num(express['E'])} баллов/час",
        },
    ]
    for severity in trace["thresholds"]:
        rows.append(
            {
                "label": f"t «{severity}» = {_fmt_num(trace['thresholds'][severity])}/E×60 + SLA",
                "value": f"{_fmt_num(times[severity], 3)} мин",
            }
        )
    rows.append(
        {
            "label": "Интервал, в котором наступили последствия",
            "value": f"#{express['interval']} {express['interval_label']}",
        }
    )
    rows.append(
        {
            "label": "Балл = max по интервалам (матрица 4×6)",
            "value": str(express["score"]),
        }
    )
    rows.append(
        {
            "label": "Уровень калькулятора → уровень паспорта",
            "value": (
                f"{express['calculator_level']} → {computed['final']}"
                " (levels.dochub_to_ssot)"
            ),
        }
    )
    return {
        "method": "express",
        "method_label": (
            "экспресс: калькулятор критичности "
            "(E = коэф. типа × коэф. влияния × клиентов/час; t = порог/E×60 + SLA)"
        ),
        "status": "preliminary",
        "axes": [],
        "max_score": express["score"],
        "bucket": express["interval_label"],
        "bucket_definition": f"интервал #{express['interval']} (express_method.intervals)",
        "business_level": computed["final"],
        "calculator_level": express["calculator_level"],
        "cia_rows": [],
        "cia_value": None,
        "protection": None,
        "protection_business": None,
        "protection_scale": protection_scale_text(criteria),
        "final_level": computed["final"],
        "express": {
            "impact": express["impact"],
            "consumers": express["consumers"],
            "score": express["score"],
            "sla": trace["sla"],
            "E": express["E"],
            "t": times,
            "interval": express["interval"],
            "interval_label": express["interval_label"],
            "calculator_level": express["calculator_level"],
            "trace": trace,
            "rows": rows,
        },
        "inputs": inputs,
        "conventions": conventions,
        "rules": rules,
        "rule_notes": rule_notes,
        **provisional_fields,
    }


def _criteria_source(criteria, *needles):
    """Источник из criteria.meta.sources: сначала по `role`, затем по заголовку.

    Роль — машинный идентификатор (`express_artifact`, `process_current`,
    `methodology`, …): заголовок страницы может меняться, роль — нет. Поиск по
    подстроке роли и заголовка оставлен как обратная совместимость для вызовов
    со старыми «словами» (`экспресс`, `d6.1.1`).

    Порядок поиска: точное равенство роли → подстрока роли → подстрока заголовка.
    Точное равенство идёт первым: иначе частичный needle (`process`) попадал бы
    в `process_draft`, который стоит выше `process_current` в списке источников.
    """
    sources = ((criteria or {}).get("meta") or {}).get("sources") or []
    wanted = [str(needle).strip().lower() for needle in needles if str(needle).strip()]
    if not wanted:
        return None
    for item in sources:
        if not isinstance(item, dict):
            continue
        role = str(item.get("role") or "").strip().lower()
        if role and all(needle == role for needle in wanted):
            return item
    for item in sources:
        if not isinstance(item, dict):
            continue
        role = str(item.get("role") or "").strip().lower()
        if role and all(needle in role for needle in wanted):
            return item
    for item in sources:
        if not isinstance(item, dict):
            continue
        title = str(item.get("title") or "").lower()
        if all(needle in title for needle in wanted):
            return item
    return None


def _external_refs_base(criteria):
    """base_url для ссылок на внешние документы (criteria.external_refs.base_url)."""
    block = (criteria or {}).get("external_refs") or {}
    if not isinstance(block, dict):
        return None
    base = block.get("base_url")
    text = str(base).strip() if base not in (None, "") else ""
    return text or None


def _page_url(criteria, page_id):
    """URL страницы Confluence из page_id; None, если id или base_url не заданы."""
    if page_id in (None, ""):
        return None
    base = _external_refs_base(criteria)
    if not base:
        return None
    return f"{base}{page_id}"


def _page_link(criteria, page_id, title=None):
    """Ссылка по правилу `confluence-links`: «title» [page_id] url.

    Заголовок берётся ТОЛЬКО из кеша проверенных заголовков
    (`catalog.yaml → page_titles`, заполняет `verify-titles --fix`). Аргумент
    `title` сохранён для совместимости и игнорируется: название из контекста,
    из имени ИС или из домена — это выдумка, которая уже попадала в публичный
    тред («Прикладная архитектура ИС» для страницы операционного CRM).
    Нет зафиксированного заголовка — рендерится `[page <id>] <url>`, без
    человекочитаемого названия.
    """
    url = _page_url(criteria, page_id)
    if not url:
        return None
    label = page_title_cached(page_id)
    if label:
        return f"«{label}» [{page_id}] {url}"
    return f"[page {page_id}] {url}"


# ---------------------------------------------------------------------------
# FIX 1: заголовки страниц Confluence — кеш проверки и REST-доступ
# ---------------------------------------------------------------------------
# Причина появления секции: в реальном прогоне для page 3910775884 в артефакт
# попало название «E001.A06 Прикладная архитектура ИС», а страница называется
# «E001.A06 Операционный CRM CМКТ (opercrm.smkt)». Правдоподобная ложь в
# публичном канале — худший класс дефекта, поэтому:
#   1. артефакт печатает заголовок только из кеша проверенных заголовков;
#   2. кеш заполняет `verify-titles --fix` после REST-запроса к Confluence;
#   3. `validate` — гейт: нет кеша или кеш старее страницы → ERROR;
#   4. REST недоступен → ERROR/WARN «проверка не выполнена», никогда «OK».
PAGE_TITLES_SECTION = "page_titles"
CONFLUENCE_TOKEN_ENV = "CONFLUENCE_TOKEN"
CONFLUENCE_BASE_ENV = "CONFLUENCE_BASE_URL"
CONFLUENCE_TIMEOUT = 15
# 429/5xx — не отказ, а «повтори позже»: без ретраев research/validate
# получают «HTTP 429» и выдают «не найдено» вместо результата. Пауза между
# запросами держит нагрузку ниже лимита Confluence (пачка CQL + страниц).
CONFLUENCE_RETRY_STATUSES = (429, 500, 502, 503, 504)
CONFLUENCE_RETRIES = 4
CONFLUENCE_RETRY_DELAY = 2.0
CONFLUENCE_MAX_WAIT = 30.0
CONFLUENCE_MIN_INTERVAL = 0.3
_CONFLUENCE_LAST_CALL = [0.0]

# Кеш на процесс: {page_id: {title, version, verified_at}}. Заполняется
# `page_title_cache(root)`; рендер читает его через `page_title_cached()`.
_PAGE_TITLES = {}
_PAGE_TITLES_ROOT = None
_PAGE_TITLES_LOADED = False


class ConfluenceError(Exception):
    """REST Confluence недоступен: нет токена, адреса, сети или страницы."""


def confluence_base_url(criteria=None):
    """Адрес Confluence: env CONFLUENCE_BASE_URL, иначе base_url критериев.

    `criteria.external_refs.base_url` — это адрес ссылки на страницу
    (`.../pages/viewpage.action?pageId=`), поэтому из него вырезается путь
    страницы: для REST нужен только корень инстанса.
    """
    base = str(os.environ.get(CONFLUENCE_BASE_ENV) or "").strip()
    if base:
        return base.rstrip("/")
    ref = _external_refs_base(criteria)
    if not ref:
        return None
    for suffix in ("/pages/viewpage.action?pageId=", "/pages/viewpage.action"):
        if suffix in ref:
            return ref.split(suffix, 1)[0].rstrip("/")
    return ref.rstrip("/")


def _confluence_pause(seconds):
    """Пауза перед запросом: не чаще `CONFLUENCE_MIN_INTERVAL` в секунду."""
    wait = float(seconds or 0)
    now = time.monotonic()
    gap = now - _CONFLUENCE_LAST_CALL[0]
    if gap < CONFLUENCE_MIN_INTERVAL:
        wait = max(wait, CONFLUENCE_MIN_INTERVAL - gap)
    if wait > 0:
        time.sleep(min(wait, CONFLUENCE_MAX_WAIT))
    _CONFLUENCE_LAST_CALL[0] = time.monotonic()


def _confluence_retry_after(exc):
    """Сколько ждать по `Retry-After` (секунды), иначе None."""
    try:
        value = exc.headers.get("Retry-After") if exc.headers else None
    except AttributeError:
        value = None
    text = str(value or "").strip()
    if not text:
        return None
    try:
        return max(0.0, float(text))
    except ValueError:
        return None


def confluence_request(path, criteria=None, timeout=CONFLUENCE_TIMEOUT):
    """GET к REST Confluence: разобранный JSON.

    Нет адреса/токена/сети — `ConfluenceError` с явной причиной. Молчаливый
    пустой результат запрещён: «не проверили» нельзя выдавать за «проверили».
    429/5xx повторяются с паузой (`Retry-After`, иначе экспоненциальный
    backoff): лимит Confluence — не доказательство «ничего не найдено».
    """
    base = confluence_base_url(criteria)
    if not base:
        raise ConfluenceError(
            "не задан адрес Confluence: env CONFLUENCE_BASE_URL или "
            "criteria.external_refs.base_url"
        )
    token = str(os.environ.get(CONFLUENCE_TOKEN_ENV) or "").strip()
    if not token:
        raise ConfluenceError(
            f"{CONFLUENCE_TOKEN_ENV} не задан — запросы к Confluence невозможны "
            "(проверка не выполнена)"
        )
    url = f"{base}{path}"
    request = urllib.request.Request(
        url,
        headers={
            "Authorization": f"Bearer {token}",
            "Accept": "application/json",
        },
    )
    body = ""
    for attempt in range(CONFLUENCE_RETRIES + 1):
        _confluence_pause(0)
        try:
            with urllib.request.urlopen(request, timeout=timeout) as response:
                body = response.read().decode("utf-8", "replace")
            break
        except urllib.error.HTTPError as exc:
            retryable = exc.code in CONFLUENCE_RETRY_STATUSES
            if not retryable or attempt >= CONFLUENCE_RETRIES:
                raise ConfluenceError(f"HTTP {exc.code} на {url}") from exc
            delay = _confluence_retry_after(exc)
            if delay is None:
                delay = CONFLUENCE_RETRY_DELAY * (2 ** attempt)
            _confluence_pause(delay)
        except (urllib.error.URLError, OSError, ValueError) as exc:
            raise ConfluenceError(f"{type(exc).__name__}: {exc} ({url})") from exc
    try:
        return json.loads(body) if body.strip() else {}
    except ValueError as exc:
        raise ConfluenceError(f"ответ не JSON ({url})") from exc


def confluence_page(page_id, criteria=None, expand="version"):
    """Страница Confluence по id: словарь REST-ответа."""
    if page_id in (None, ""):
        raise ConfluenceError("page_id не задан")
    data = confluence_request(
        f"/rest/api/content/{quote(str(page_id), safe='')}?expand={expand}",
        criteria,
    )
    if not isinstance(data, dict) or not data.get("id"):
        raise ConfluenceError(f"страница {page_id}: ответ без id")
    return data


def confluence_search(cql, criteria=None, limit=100, expand="version,ancestors"):
    """CQL-поиск по Confluence: список результатов REST."""
    text = str(cql or "").strip()
    if not text:
        return []
    data = confluence_request(
        f"/rest/api/content/search?cql={quote(text, safe='')}"
        f"&limit={int(limit)}&expand={quote(expand, safe=',')}",
        criteria,
    )
    results = data.get("results") if isinstance(data, dict) else None
    return results if isinstance(results, list) else []


def _page_title_record(record):
    """Нормализованная запись кеша (None — запись непригодна).

    В `catalog.yaml` поля называются `title_version` / `title_verified_at`
    (как требует процесс), внутри инструмента — `version` / `verified_at`.
    Читаются оба написания: кеш, записанный прежней версией, не теряется.
    """
    if not isinstance(record, dict):
        return None
    title = str(record.get("title") or "").strip()
    if not title:
        return None
    raw_version = record.get("title_version", record.get("version"))
    try:
        version = int(raw_version)
    except (TypeError, ValueError):
        version = None
    verified = (
        str(record.get("title_verified_at") or record.get("verified_at") or "").strip()
        or None
    )
    return {"title": title, "version": version, "verified_at": verified}


def page_title_cache(root, reload=False):
    """Кеш проверенных заголовков из `catalog.yaml → page_titles`.

    Заполняет модульный кеш, который читает рендер. Кеш привязан к корню:
    смена проекта перечитывает файл (иначе тесты и мультипроектный запуск
    видели бы чужие заголовки).
    """
    global _PAGE_TITLES, _PAGE_TITLES_ROOT, _PAGE_TITLES_LOADED
    root = Path(root)
    if not reload and _PAGE_TITLES_LOADED and _PAGE_TITLES_ROOT == root:
        return _PAGE_TITLES
    cache = {}
    path = root / "catalog.yaml"
    data = {}
    if path.exists():
        try:
            data = load_yaml(path)
        except (YamlError, OSError):
            data = {}
    block = data.get(PAGE_TITLES_SECTION) if isinstance(data, dict) else None
    if isinstance(block, dict):
        for page_id, record in block.items():
            normalized = _page_title_record(record)
            if normalized:
                cache[str(page_id)] = normalized
    _PAGE_TITLES, _PAGE_TITLES_ROOT, _PAGE_TITLES_LOADED = cache, root, True
    return cache


def page_title_cached(page_id):
    """Проверенный заголовок страницы или None (рендер без названия)."""
    if page_id in (None, ""):
        return None
    record = _PAGE_TITLES.get(str(page_id))
    return record.get("title") if record else None


def page_title_record(page_id):
    """Запись кеша страницы: {title, version, verified_at} или None."""
    if page_id in (None, ""):
        return None
    return _PAGE_TITLES.get(str(page_id))


def _catalog_page_titles_write(root, updates):
    """Записать/обновить `catalog.yaml → page_titles` (строчный splice).

    Комментарии, порядок полей и остальные секции реестра сохраняются:
    пересборка файла целиком потеряла бы документацию схемы.
    """
    path = Path(root) / "catalog.yaml"
    if not path.exists():
        return False
    cache = dict(page_title_cache(root, reload=True))
    for page_id, record in (updates or {}).items():
        normalized = _page_title_record(record)
        if normalized:
            cache[str(page_id)] = normalized
    block = [f"{PAGE_TITLES_SECTION}:\n"]
    for page_id in sorted(cache, key=lambda value: (len(value), value)):
        record = cache[page_id]
        block.append(f'  "{page_id}":\n')
        block.append(f"    title: {yaml_scalar(record['title'])}\n")
        if record.get("version") is not None:
            block.append(f"    title_version: {record['version']}\n")
        if record.get("verified_at"):
            block.append(f'    title_verified_at: "{record["verified_at"]}"\n')
    lines = path.read_text(encoding="utf-8").splitlines(True)
    start = None
    end = len(lines)
    for index, raw in enumerate(lines):
        if re.match(rf"^{PAGE_TITLES_SECTION}:\s*$", raw):
            start = index
            for nxt in range(index + 1, len(lines)):
                if lines[nxt].strip() and not lines[nxt].startswith((" ", "\t", "#")):
                    end = nxt
                    break
            break
    if start is None:
        text = "".join(lines)
        if text and not text.endswith("\n"):
            text += "\n"
        _atomic_write(path, text + "\n" + "".join(block))
    else:
        head = lines[:start]
        while head and not head[-1].strip():
            head.pop()
        tail = lines[end:]
        separator = "\n" if tail else ""
        _atomic_write(path, "".join(head) + "".join(block) + separator + "".join(tail))
    page_title_cache(root, reload=True)
    return True


def _catalog_top_scalar_write(root, key, value):
    """Записать/обновить скаляр верхнего уровня `catalog.yaml` (splice)."""
    path = Path(root) / "catalog.yaml"
    if not path.exists():
        return False
    lines = path.read_text(encoding="utf-8").splitlines(True)
    rendered = f"{key}: {value}\n"
    for index, raw in enumerate(lines):
        if re.match(rf"^{re.escape(key)}:\s*", raw):
            lines[index] = rendered
            _atomic_write(path, "".join(lines))
            return True
    # Новая запись — после шапки-комментария, а не перед ней: документация
    # схемы должна оставаться в начале файла.
    insert_at = 0
    while insert_at < len(lines) and lines[insert_at].startswith("#"):
        insert_at += 1
    while insert_at < len(lines) and not lines[insert_at].strip():
        insert_at += 1
    lines.insert(insert_at, rendered)
    _atomic_write(path, "".join(lines))
    return True


# Поля реестра и критериев, значения которых печатаются в артефактах ссылкой
# с заголовком. Список — источник для `verify-titles` и гейта `validate`.
PAGE_TITLE_FIELDS = (
    "confluence_page_id",
    "architecture_page_id",
    "dr_page_id",
    "decision_log_page_id",
    "criticality_source_page_id",
    "product_scope_page_id",
)


def _criteria_title_spans(lines):
    """Спаны записей с `page_id`/`id` в `external_refs.refs` и `meta.sources`.

    Возвращает список `{start, end, indent, fields}`: `fields` — имя поля →
    индекс строки. Нужен строчному splice: комментарии, порядок ключей и
    остальные секции файла критериев обязаны остаться байт-в-байт.
    """
    spans = []
    section = None
    block = None  # (начало блока, отступ полей)
    for index, raw in enumerate(lines):
        stripped = raw.strip()
        if not stripped or stripped.startswith("#"):
            continue
        indent = len(raw) - len(raw.lstrip())
        if indent == 0:
            section = stripped.split(":", 1)[0].strip() if ":" in stripped else None
            block = None
            continue
        if section not in ("external_refs", "meta"):
            continue
        if indent == 2 and stripped.startswith(("refs:", "sources:")):
            name = stripped.split(":", 1)[0].strip()
            if (section, name) in (("external_refs", "refs"), ("meta", "sources")):
                block = (section, name)
            else:
                block = None
            continue
        if block is None or indent <= 2:
            continue
        entry_indent = 4
        if indent != entry_indent:
            continue
        spans.append({"start": index, "end": len(lines), "indent": indent, "fields": {}})
    # Границы записей: до следующей записи того же блока (или до конца файла).
    for position, span in enumerate(spans):
        span["end"] = spans[position + 1]["start"] if position + 1 < len(spans) else len(lines)
    for span in spans:
        for index in range(span["start"], span["end"]):
            raw = lines[index]
            stripped = raw.strip()
            if not stripped or stripped.startswith("#"):
                continue
            indent = len(raw) - len(raw.lstrip())
            body = stripped[2:] if stripped.startswith("- ") else stripped
            if indent not in (span["indent"], span["indent"] + 2):
                continue
            if ":" not in body:
                continue
            key = body.split(":", 1)[0].strip()
            if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", key):
                continue
            span["fields"].setdefault(key, index)
    return spans


def _criteria_page_titles_write(root, updates):
    """Записать `title`/`title_version`/`title_verified_at` в файл критериев.

    Обновляются только записи, у которых уже есть `title`:
    `external_refs.refs.<имя>` и `meta.sources[]`. Запись строчная (splice):
    комментарии-документация схемы и порядок ключей сохраняются, поэтому файл
    остаётся читаемым человеком, а `criteria check` не меняет вердикт.
    """
    path = criteria_path()
    if not path.exists() or not updates:
        return False
    try:
        lines = path.read_text(encoding="utf-8").splitlines(True)
    except (OSError, UnicodeDecodeError):
        return False
    spans = _criteria_title_spans(lines)
    edits = []
    for span in spans:
        fields = span["fields"]
        id_index = fields.get("page_id", fields.get("id"))
        title_index = fields.get("title")
        if id_index is None or title_index is None:
            continue
        page_id = _page_id_text(
            lines[id_index].strip().split(":", 1)[1].strip().strip('"\'')
        )
        record = (updates or {}).get(str(page_id)) if page_id else None
        normalized = _page_title_record(record)
        if not normalized:
            continue
        title_line = lines[title_index]
        prefix = title_line[: len(title_line) - len(title_line.lstrip())]
        new_title_line = f"{prefix}title: {_yaml_quote(normalized['title'])}\n"
        extra = []
        if normalized.get("version") is not None:
            extra.append(f"{prefix}title_version: {normalized['version']}\n")
        if normalized.get("verified_at"):
            extra.append(
                f'{prefix}title_verified_at: "{normalized["verified_at"]}"\n'
            )
        # Уже существующие поля — заменить на месте, новые — сразу за title.
        remaining = []
        for line in extra:
            key = line.split(":", 1)[0].strip()
            if key in fields:
                existing = lines[fields[key]]
                existing_prefix = existing[: len(existing) - len(existing.lstrip())]
                edits.append((fields[key], existing_prefix + line.lstrip()))
            else:
                remaining.append(line)
        edits.append((title_index, new_title_line + "".join(remaining)))
    if not edits:
        return False
    for index, text in sorted(edits, key=lambda item: item[0], reverse=True):
        lines[index] = text
    _atomic_write(path, "".join(lines))
    return True


def _page_id_text(value):
    """page_id как строка цифр (None — значение не является page_id)."""
    if value in (None, ""):
        return None
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return str(value) if value > 0 else None
    text = str(value).strip()
    if text.isdigit() and int(text) > 0:
        return text
    return None


def collect_rendered_pages(root, criteria, systems=None, info_by_code=None, only=None):
    """Страницы, которые рендерятся в артефактах с заголовком.

    Запись: `{page_id, where, saved_title, cached}`.
    `saved_title` — то, что уже зафиксировано (кеш → критерии → реестр);
    `cached` — запись кеша (только она даёт право печатать название).

    Источники: `catalog.yaml` (продукт, Product scope, поля записи ИС),
    `criteria.external_refs.refs`, `criteria.meta.sources`,
    `INFORMATION.yaml → facts.e2e_source_page` (заголовок печатается в
    CRITICALITY.md).
    """
    page_title_cache(root)
    criteria = criteria or {}
    catalog = {}
    if systems is None:
        try:
            catalog, systems = load_catalog(root)
        except (YamlError, OSError):
            systems = []
    else:
        try:
            catalog = load_catalog(root)[0]
        except (YamlError, OSError):
            catalog = {}
    pages = {}
    only = str(only or "").strip() or None

    def add(page_id, where, saved=None):
        text = _page_id_text(page_id)
        if not text:
            return
        record = pages.get(text)
        if record is None:
            record = pages[text] = {
                "page_id": text,
                "where": where,
                "saved_title": str(saved or "").strip() or None,
                "cached": page_title_record(text),
            }
        elif record["saved_title"] is None and str(saved or "").strip():
            record["saved_title"] = str(saved).strip()

    for entry in systems or []:
        code = str(entry.get("code") or "")
        if only and code != only:
            continue
        rel = str(entry.get("path") or "") or f"is/{code}"
        for field in PAGE_TITLE_FIELDS:
            saved = (
                entry.get(f"{field[:-3]}_title")
                if field == "architecture_page_id"
                else None
            )
            add(entry.get(field), f"{rel} ({field})", saved)
        # `facts.e2e_source_page` печатается в CRITICALITY.md/публикации —
        # значит проверяется всегда, а не только при `--is`: иначе выдуманный
        # заголовок в INFORMATION.yaml доходил бы до MR без сверки (R19).
        info = (info_by_code or {}).get(code)
        if info is None:
            info_path = root / rel / INFORMATION_FILE
            if info_path.exists():
                try:
                    loaded = load_yaml(info_path)
                    info = loaded if isinstance(loaded, dict) else {}
                except (YamlError, OSError):
                    info = {}
        source = ((info or {}).get("facts") or {}).get("e2e_source_page")
        if isinstance(source, dict):
            add(
                source.get("page_id"),
                f"{rel} (facts.e2e_source_page)",
                source.get("title"),
            )
        # Страницы процессов печатаются названиями в разделе «E2E-процессы»:
        # их заголовки тоже обязаны быть в кеше (R19).
        for item in ((info or {}).get("facts") or {}).get("e2e_processes") or []:
            if isinstance(item, dict):
                add(
                    item.get("page_id"),
                    f"{rel} (facts.e2e_processes)",
                    item.get("name"),
                )
    # Страницы продукта печатаются в артефактах каждой ИС: проверяются и в
    # режиме `--is` (иначе продуктовая ссылка остаётся без названия).
    add(
        catalog.get("product_confluence_page_id"),
        "catalog.yaml (product_confluence_page_id)",
    )
    add(catalog.get("product_scope_page_id"), "catalog.yaml (product_scope_page_id)")

    block = (criteria.get("external_refs") or {}).get("refs")
    if isinstance(block, dict):
        for name, item in block.items():
            item = item if isinstance(item, dict) else {}
            add(item.get("id"), f"criteria.external_refs.refs.{name}", item.get("title"))
    for item in ((criteria.get("meta") or {}).get("sources") or []):
        if isinstance(item, dict):
            add(
                item.get("page_id"),
                "criteria.meta.sources",
                item.get("title"),
            )
    return [pages[page_id] for page_id in sorted(pages, key=lambda v: (len(v), v))]


def _title_fix_hint(where):
    """Подсказка «чем устраняется» для гейта заголовков страниц."""
    match = re.match(r"^is/([A-Za-z0-9._-]+)", str(where or ""))
    is_arg = f" IS={match.group(1)}" if match else ""
    return (
        f"устраняется: make verify-titles{is_arg} FIX=1 "
        "(требует доступа к Confluence)"
    )


def _title_gate_soft(systems):
    """Заголовки не зафиксированы — WARN для черновиков, ERROR для confirmed.

    Свежий проект (все ИС в `status: draft`) не может заполнить кеш заголовков
    без доступа к Confluence: 20+ ERROR на `make init && make scaffold &&
    make validate` блокировали первый шаг конвейера. Как только хотя бы одна ИС
    подтверждена (`status: confirmed`), проверка снова строгая — существующие
    проекты не ослабляются. Расхождение с фактическим заголовком и устаревшая
    версия страницы остаются ERROR всегда: это дефект данных, а не «кеш пуст».
    """
    for entry in systems or []:
        if not isinstance(entry, dict):
            continue
        if str(entry.get("status") or "").strip().lower() == "confirmed":
            return False
    return True


def _title_report(report, where, message, soft):
    """ERROR (по умолчанию) или WARN (черновик) + подсказка об устранении."""
    text = f"{message} — {_title_fix_hint(where)}"
    if soft:
        report.warn(where, text)
    else:
        report.error(where, text)


def _check_page_titles(report, root, criteria, systems, offline=False):
    """Гейт validate: заголовки страниц зафиксированы и не устарели.

    ERROR — нет записи кеша, нет `verified_at`, версия страницы новее
    проверенной или заголовок разошёлся. REST недоступен — один WARN «проверка
    заголовков не выполнена» (молчаливый OK запрещён). Пока в проекте нет ни
    одной подтверждённой ИС, «заголовок не зафиксирован» — WARN: свежему
    проекту кеш заполнить нечем (нужен Confluence).
    """
    pages = collect_rendered_pages(root, criteria, systems)
    if not pages:
        return
    soft = _title_gate_soft(systems)
    if offline:
        report.warn(
            "catalog.yaml",
            "проверка заголовков не выполнена (--no-network): сверка title с "
            "Confluence пропущена",
        )
        _check_page_title_cache_only(report, pages, soft=soft)
        return
    unreachable = None
    for page in pages:
        record = page["cached"]
        if record is None:
            _title_report(
                report,
                page["where"],
                f"page {page['page_id']}: заголовок не зафиксирован — в артефакте "
                "будет «[page id] url» без названия",
                soft,
            )
            continue
        if not record.get("verified_at"):
            _title_report(
                report,
                page["where"],
                f"page {page['page_id']}: нет title_verified_at — заголовок "
                "не проверен",
                soft,
            )
            continue
        if unreachable is not None:
            continue
        try:
            actual = confluence_page(page["page_id"], criteria)
        except ConfluenceError as exc:
            unreachable = str(exc)
            continue
        _title_gate_problem(report, page, record, actual)
    if unreachable is not None:
        report.warn(
            "catalog.yaml",
            f"проверка заголовков не выполнена ({unreachable}) — title не "
            "сверены с Confluence; запустите make verify-titles",
        )


def _title_gate_problem(report, page, record, actual):
    """Сравнить кеш с фактической страницей; расхождение — ERROR."""
    title = str((actual or {}).get("title") or "").strip()
    try:
        version = int(((actual or {}).get("version") or {}).get("number"))
    except (TypeError, ValueError):
        version = None
    if title and title != record.get("title"):
        report.error(
            page["where"],
            f"page {page['page_id']}: сохранённый заголовок "
            f"{record.get('title')!r} ≠ фактический {title!r} — "
            "make verify-titles --fix",
        )
        return
    if record.get("version") is None:
        # Кеш без title_version: свежесть проверить нечем. Молчаливый пропуск
        # проверки запрещён — иначе запись, заполненная вручную, навсегда
        # считалась бы актуальной.
        report.warn(
            page["where"],
            f"page {page['page_id']}: в кеше нет title_version — свежесть "
            "заголовка не проверена; выполните make verify-titles --fix",
        )
        return
    if version is not None and version > int(record["version"]):
        report.error(
            page["where"],
            f"page {page['page_id']}: версия страницы {version} новее "
            f"проверенной {record['version']} — заголовок мог измениться: "
            "make verify-titles --fix",
        )


def _check_page_title_cache_only(report, pages, soft=False):
    """Без сети проверяется только наличие кеша и даты проверки."""
    for page in pages:
        record = page["cached"]
        if record is None:
            _title_report(
                report,
                page["where"],
                f"page {page['page_id']}: заголовок не зафиксирован — в артефакте "
                "будет «[page id] url» без названия",
                soft,
            )
        elif not record.get("verified_at"):
            _title_report(
                report,
                page["where"],
                f"page {page['page_id']}: нет title_verified_at — заголовок "
                "не проверен",
                soft,
            )


# Секции критериев, которые реально влияют на артефакты. Фингерпринт считается
# только от них: mtime файла критериев не годится — файл правится постоянно и
# давал бы вечно «устаревшие» артефакты.
CRITERIA_FINGERPRINT_SECTIONS = (
    "meta",
    "levels",
    "axes",
    "time_buckets",
    "impact_matrix",
    "cia",
    "final_matrix",
    "express_method",
    "enum_selection",
    "inputs",
    "scenarios",
    "provenance",
)
CRITERIA_FINGERPRINT_RE = re.compile(
    r"^criteria_fingerprint:\s*([0-9a-f]{6,64})\s*$", re.MULTILINE
)


def criteria_fingerprint(criteria):
    """sha256 (первые 12 символов) от влияющих на артефакты секций критериев."""
    payload = {}
    if isinstance(criteria, dict):
        for key in CRITERIA_FINGERPRINT_SECTIONS:
            if key in criteria:
                payload[key] = criteria[key]
    text = json.dumps(payload, sort_keys=True, ensure_ascii=False, default=str)
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:12]


def artifact_fingerprint(path):
    """Фингерпринт критериев из артефакта (CRITICALITY.md/GENERATION.md) или None."""
    try:
        text = Path(path).read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return None
    match = CRITERIA_FINGERPRINT_RE.search(text)
    return match.group(1) if match else None


def _trim_frontmatter_gap(text):
    """Одна пустая строка между frontmatter и телом (без двойной)."""
    if not text.startswith("---\n"):
        return text
    end = text.find("\n---\n", 4)
    if end < 0:
        return text
    head = text[: end + len("\n---\n")]
    tail = text[end + len("\n---\n"):].lstrip("\n")
    return head + ("\n" + tail if tail else "")


def _ref_page_id(value):
    """page_id из ссылочной строки: `?pageId=`, `page_id=`, `id=` или голое число."""
    text = str(value or "").strip()
    if not text:
        return None
    if text.isdigit():
        return text
    match = re.search(r"page_?id\s*=\s*(\d{5,12})", text, re.IGNORECASE)
    return match.group(1) if match else None


def _e2e_source_url(criteria, item):
    """URL источника E2E-процесса: `source.url`, ссылка в `ref` или page_id."""
    raw = (item or {}).get("source_raw")
    if isinstance(raw, dict):
        url = str(raw.get("url") or "").strip()
        if url.startswith("http"):
            return url
        return _page_url(criteria, _ref_page_id(raw.get("ref")))
    text = str(raw or "").strip()
    if text.startswith("http"):
        return text
    return _page_url(criteria, _ref_page_id(text))


def e2e_list_values(criteria, facts):
    """`actions.e2e_list`: процесс + сила подтверждения + ссылка на источник.

    Сила подтверждения (`шагов N из M`, «прямое доказательство») — то, что SRE
    проверяет при согласовании: без неё список процессов неотличим от
    «перечислено на глаз». Порядок — по силе доказательства (тот же ключ, что и
    в паспорте): сильнейшее участие ИС первым.
    """
    values = []
    processes = [
        item
        for item in (facts or {}).get("e2e_processes") or []
        if str(item.get("name") or "").strip()
    ]
    for item in sorted(processes, key=_e2e_process_sort_key):
        name = str(item.get("name") or "").strip()
        if not name:
            continue
        strength = []
        steps_label = item.get("steps_label")
        if steps_label not in (None, ""):
            strength.append(f"шагов {steps_label}")
        evidence = item.get("evidence")
        if evidence not in (None, ""):
            strength.append(_tpl_stringify(evidence))
        url = _e2e_source_url(criteria, item)
        parts = []
        if strength:
            parts.append(", ".join(strength))
        if url:
            parts.append(f"источник: {url}")
        values.append(f"{name} ({'; '.join(parts)})" if parts else name)
    return values


def e2e_missing_text(code, facts, criteria=None, scope_page_id=None):
    """Строка «E2E-процессов нет» с указанием, где именно их не хватает.

    `not_filled` — функциональная область Product scope ИС называет, но её
    колонка e2e пуста; `not_found` — такой области нет вовсе; без статуса —
    нейтральное «⛔ не заполнено» (прежнее поведение).
    """
    facts = facts or {}
    status = facts.get("e2e_status")
    page = facts.get("e2e_source_page") or {}
    if status == "not_filled" and page:
        url = page.get("url") or _page_url(criteria, page.get("page_id"))
        if url:
            page_id = page.get("page_id")
            # Название — только из кеша проверенных заголовков (R19): поле
            # `title` в INFORMATION.yaml в артефакт не попадает.
            title = page_title_cached(page_id)
            # Формат confluence-links: «title» [page_id] url — голый pageId=
            # человеку ничего не говорит. Нет кеша — без названия.
            if title:
                scope = (
                    f"«{title}» [{page_id}]"
                    if page_id not in (None, "")
                    else f"«{title}»"
                )
            elif page_id not in (None, ""):
                scope = f"[page {page_id}]"
            else:
                scope = "Product scope"
            return (
                f"{MISSING_MARK} — колонка «Сквозной бизнес-процесс (e2e)» "
                f"в Product scope {scope} не заполнена: {url}"
            )
    if status == "not_found":
        url = _page_url(criteria, scope_page_id)
        where = url or "catalog.yaml → product_scope_page_id не заполнен"
        return (
            f"⛔ не найдено — ни одна функциональная область Product scope не "
            f"указывает {code}; проверьте Product scope: {where}"
        )
    return MISSING_MARK


def adr_link_value(criteria, facts, entry=None, catalog=None):
    """(ссылка, основание) для `actions.adr_link`.

    Цепочка: первая ссылка `facts.adr` → архитектура ИС
    (`catalog.yaml → systems.<код>.architecture_page_id`) → страница ИС
    (`confluence_page_id`) → None. Основание пишется в `actions.adr_basis`,
    чтобы публикация не выдавала архитектуру за АДР.
    """
    for item in (facts or {}).get("adr") or []:
        if isinstance(item, dict) and item.get("link"):
            return item["link"], "adr"
    entry = entry or {}
    catalog = catalog or {}
    architecture_id = entry.get("architecture_page_id") or catalog.get(
        "architecture_page_id"
    )
    url = _page_url(criteria, architecture_id)
    if url:
        # Название — только из кеша проверенных заголовков. Поля
        # `architecture_page_title` в реестре и `title` в критериях не
        # печатаются: они не сверены с Confluence (именно так в публикацию
        # попало «Прикладная архитектура ИС» вместо реального названия).
        label = (
            f"«{page_title_cached(architecture_id)}» [{architecture_id}] "
            if page_title_cached(architecture_id)
            else ""
        )
        return f"{label}{url} (архитектура ИС; АДР не найден)", "architecture"
    url = _page_url(criteria, entry.get("confluence_page_id"))
    if url:
        return f"{url} (страница ИС; АДР не найден)", "is_page"
    return None, "none"


def adr_orphan_warning(facts):
    """WARN-текст: `facts.adr` заполнен, но ни у одной записи нет ссылки.

    None — записей нет или хотя бы одна даёт ссылку. Молчаливое падение в
    `adr_basis: architecture` выдавало бы архитектуру ИС за найденный АДР.
    """
    items = (facts or {}).get("adr") or []
    if not items:
        return None
    for item in items:
        if isinstance(item, dict) and item.get("link"):
            return None
    return (
        "в facts.adr есть записи, но ни у одной нет ссылки — ссылка на АДР не "
        "построена, подставлена архитектура ИС"
    )


# WARN «base_url не задан» печатается один раз на команду.
_BASE_URL_WARNED = set()


def _warn_missing_base_url(criteria, context):
    """WARN один раз на команду: criteria.external_refs.base_url не задан."""
    if _external_refs_base(criteria) is not None:
        return False
    if context not in _BASE_URL_WARNED:
        _BASE_URL_WARNED.add(context)
        print(
            f"WARN: criteria.external_refs.base_url не задан — {context} "
            f"не собираются, вместо ссылки {MISSING_MARK}"
        )
    return True


def _warn_missing_external_ref(key, what):
    """WARN один раз на команду: внешний шаблон/ссылка не задана в критериях."""
    if key not in _BASE_URL_WARNED:
        _BASE_URL_WARNED.add(key)
        print(f"WARN: criteria.{key} не задан — {what} будет {MISSING_MARK}")


def _external_ref_pattern(criteria, key, values):
    """Шаблон из criteria.external_refs.<key> с подстановкой {contour}/{name}.

    None — ключ не задан или шаблон битый: инструмент переносимый, значения
    по умолчанию не подставляются.
    """
    block = (criteria or {}).get("external_refs") or {}
    pattern = block.get(key) if isinstance(block, dict) else None
    text = str(pattern).strip() if pattern not in (None, "") else ""
    if not text:
        return None
    try:
        return text.format(**values)
    except (KeyError, IndexError, ValueError):
        return None


def _external_refs(criteria, entry=None):
    """(refs, warnings): именованные внешние ссылки из criteria.external_refs.

    Каждая запись — словарь {id, title, note, url}; url = base_url + id.
    Нет id или base_url — url: None (в шаблоне рендерится ⛔ не заполнено).
    `decision_log` переопределяется записью реестра
    `catalog.yaml → systems.<код>.decision_log_page_id`.
    """
    block = (criteria or {}).get("external_refs") or {}
    named = block.get("refs") if isinstance(block, dict) else None
    named = named if isinstance(named, dict) else {}
    refs = {}
    for name, item in named.items():
        item = item if isinstance(item, dict) else {}
        page_id = item.get("id")
        refs[str(name)] = {
            "id": page_id,
            # Название — только из кеша проверенных заголовков: заголовок из
            # критериев не сверяется с Confluence и мог устареть/быть выдуман.
            "title": page_title_cached(page_id),
            "note": item.get("note"),
            "url": _page_url(criteria, page_id),
        }
    override = (entry or {}).get("decision_log_page_id")
    if override not in (None, ""):
        ref = refs.setdefault(
            "decision_log", {"id": None, "title": None, "note": None, "url": None}
        )
        ref["id"] = override
        ref["url"] = _page_url(criteria, override)
    warnings = []
    if _external_refs_base(criteria) is None and any(
        ref.get("id") not in (None, "") for ref in refs.values()
    ):
        warnings.append(
            "criteria.external_refs.base_url не задан — ссылки на внешние "
            "документы не собираются"
        )
    for name in sorted(refs):
        if not refs[name].get("url"):
            warnings.append(
                f"external_refs.{name} не задан — в артефакте будет {MISSING_MARK}"
            )
    return refs, warnings


def _source_entry(criteria, label, item):
    page_id = (item or {}).get("page_id")
    return {"label": label, "link": _page_url(criteria, page_id) or MISSING_MARK}


def _start_sources(identity, criteria=None, catalog=None):
    """(sources, warnings). Источники — только из criteria.meta.sources и catalog."""
    criteria = criteria or {}
    catalog = catalog or {}
    sources = []
    warnings = []
    if identity.get("confluence_page_id"):
        sources.append(
            {
                "label": "Confluence, архитектура ИС",
                "link": _page_url(criteria, identity["confluence_page_id"])
                or MISSING_MARK,
            }
        )
    if identity.get("dr_page_id"):
        sources.append(
            {
                "label": "Confluence, DR",
                "link": _page_url(criteria, identity["dr_page_id"]) or MISSING_MARK,
            }
        )
    if identity.get("decision_log_page_id"):
        sources.append(
            {
                "label": "Confluence, Decision Log",
                "link": _page_url(criteria, identity["decision_log_page_id"])
                or MISSING_MARK,
            }
        )
    if identity.get("criticality_source_page_id"):
        sources.append(
            {
                "label": "Confluence, оценка критичности",
                "link": _page_url(criteria, identity["criticality_source_page_id"])
                or MISSING_MARK,
            }
        )

    product_code = catalog.get("product") or identity.get("product")
    product_name = catalog.get("product_name")
    if product_code and product_name:
        product_label = f"Продукт {product_code} «{product_name}»"
    elif product_name:
        product_label = f"Продукт «{product_name}»"
    elif product_code:
        product_label = f"Продукт {product_code}"
    else:
        product_label = "Продукт"
    product_page = catalog.get("product_confluence_page_id")
    if product_page:
        product_link = _page_url(criteria, product_page) or MISSING_MARK
    else:
        product_link = MISSING_MARK
        warnings.append(
            "источник «Продукт»: нет catalog.product_confluence_page_id — ⛔ не заполнено"
        )
    sources.append({"label": product_label, "link": product_link})

    express_source = _criteria_source(criteria, "express_artifact")
    sources.append(_source_entry(criteria, "Методика (экспресс)", express_source))
    if express_source is None:
        warnings.append(
            "источник «Методика (экспресс)»: нет в criteria.meta.sources — ⛔ не заполнено"
        )

    process_source = _criteria_source(criteria, "process_current")
    sources.append(_source_entry(criteria, "Процесс D6.1.1", process_source))
    if process_source is None:
        warnings.append(
            "источник «Процесс D6.1.1»: нет в criteria.meta.sources — ⛔ не заполнено"
        )

    if identity.get("gitlab_group"):
        sources.append({"label": "GitLab", "link": identity["gitlab_group"]})
    sources.append({"label": "Реестр ИС репозитория", "link": "catalog.yaml"})
    sources.append({"label": "Индекс паспортов", "link": "INDEX.md"})
    return sources, warnings


def _start_todo(passport, facts, conflicts, people):
    todo = []
    if passport["object_workload"] in (None, ""):
        todo.append("Пиковая нагрузка (`object_workload`), клиентов/час — подтверждает TL")
    if passport["object_sla"] in (None, ""):
        todo.append("SLA / RTO / RPO (`object_sla`) — подтверждает SRE")
    if passport["object_consumers_type"] in (None, ""):
        todo.append("Тип клиентов (`object_consumers_type`) — подтверждает PdM")
    if passport["object_outage_impact"] in (None, ""):
        todo.append("Влияние при простое (`object_outage_impact`) — подтверждает PdM + TL")
    if not facts["e2e_processes"]:
        todo.append("Перечень E2E-процессов (`facts.e2e_processes`) — подтверждает PdM")
    if not facts["adr"]:
        todo.append("Ссылка на ADR (`facts.adr`) — TL / архитектор")
    if facts["support"]["status"] in (None, "", "missing"):
        todo.append("Показатели поддержки: SLA инцидентов, доступность, часы (`facts.support`) — SRE")
    if not facts["data_classification"]:
        todo.append("Классификация данных: ПДн / КТ / SORM (`facts.data_classification`) — TL + ИБ")
    if not facts["risks"]:
        todo.append("Реестр рисков (`facts.risks`) — TL")
    if passport["approve_link"] in (None, ""):
        todo.append(
            "Ссылка на тред согласования (`approve_link`) — сделает `make handoff`"
        )
    if people["pdm"] is None:
        todo.append("Владелец со стороны PdM (секция `roles`) — TL")
    for conflict in conflicts:
        todo.append(
            "Устранить расхождение `{}`: расчёт {} ≠ реестр {} — TL + SRE".format(
                conflict["field"], conflict["computed"], conflict["actual"]
            )
        )
    return todo


def _start_history(info, date, final):
    raw = info.get("history") if isinstance(info, dict) else None
    if isinstance(raw, list) and raw:
        history = []
        for item in raw:
            if isinstance(item, dict):
                history.append(
                    {
                        "date": item.get("date"),
                        "criticality": item.get("criticality"),
                        "who": item.get("who"),
                        "link": item.get("link"),
                    }
                )
        if history:
            return history
    return [
        {
            "date": date.isoformat(),
            "criticality": final,
            "who": "criticality.py start",
            "link": "GENERATION.md",
        }
    ]


