def _check_catalog(report: Report, root: Path, systems, criteria=None, catalog=None):
    by_code = {}
    catalog = catalog or {}
    for field, what in CATALOG_PAGE_FIELDS:
        problem = catalog_page_id_problem(catalog.get(field))
        if problem:
            report.error(
                "catalog.yaml",
                f"{field}={problem} (top-level: page_id {what})",
            )
    for entry in systems:
        code = entry.get("code")
        where = "catalog.yaml"
        if code in by_code:
            report.error(where, f"повторяющийся код ИС {code!r}")
        by_code[code] = entry
        if not CODE_RE.match(str(code)):
            report.error(where, f"код ИС {code!r} не соответствует <name_is>.<контур>")
        contour = entry.get("contour")
        name = split_is_code(code)[0] if code else ""
        if contour and name and not str(code).endswith("." + str(contour)):
            report.error(where, f"код {code!r} не совпадает с contour={contour!r}")
        expected_path = f"is/{code}"
        if entry.get("path") != expected_path:
            report.error(
                where,
                f"{code}: path={entry.get('path')!r}, ожидалось {expected_path!r}",
            )
        crit = entry.get("criticality")
        if crit is not None and criteria is not None and crit not in level_set(criteria):
            report.error(where, f"{code}: criticality={crit!r} вне допустимых значений")
        ssot = entry.get("criticality_ssot")
        if ssot is not None and criteria is not None and ssot not in ssot_level_set(criteria):
            report.error(
                where,
                f"{code}: criticality_ssot={ssot!r} вне допустимых значений "
                f"({', '.join(ssot_level_set(criteria))})",
            )
        if criteria is not None and ssot is not None:
            mapping = dochub_to_ssot_map(criteria)
            if crit in mapping:
                expected = mapping[crit]
                if ssot != expected:
                    report.error(
                        where,
                        f"{code}: маппинг нарушен — criticality={crit!r} даёт "
                        f"criticality_ssot={expected!r}, а указано {ssot!r}",
                    )
        if entry.get("status") not in ("draft", "confirmed", None):
            report.error(where, f"{code}: status={entry.get('status')!r} (допустимо draft/confirmed)")
        # `ssot_status` — производная прогона `ssot` (no_change | mr_pending |
        # mr_created). Иное значение — опечатка, которая исказит публикацию.
        ssot_stage = entry.get(SSOT_STATUS_FIELD)
        if ssot_stage is not None and ssot_stage not in SSOT_STATUS_VALUES:
            report.error(
                where,
                f"{code}: {SSOT_STATUS_FIELD}={ssot_stage!r} "
                f"(допустимо {', '.join(SSOT_STATUS_VALUES)}; "
                "выставляется командой make ssot)",
            )
        # Этап handoff: режим и статус отправки — производные команд
        # `handoff`/`handoff-result`. Опечатка исказила бы идемпотентность
        # (повторная отправка запрещена по `thread_link`), поэтому — ERROR.
        handoff_mode = entry.get(HANDOFF_MODE_FIELD)
        if handoff_mode is not None and handoff_mode not in HANDOFF_MODE_VALUES:
            report.error(
                where,
                f"{code}: {HANDOFF_MODE_FIELD}={handoff_mode!r} "
                f"(допустимо {', '.join(HANDOFF_MODE_VALUES)}; "
                "выставляется командой make handoff)",
            )
        handoff_status = entry.get(HANDOFF_STATUS_FIELD)
        if handoff_status is not None and handoff_status not in HANDOFF_STATUS_VALUES:
            report.error(
                where,
                f"{code}: {HANDOFF_STATUS_FIELD}={handoff_status!r} "
                f"(допустимо {', '.join(HANDOFF_STATUS_VALUES)}; "
                "выставляется командами make handoff/handoff-result)",
            )
        thread_link = entry.get(THREAD_LINK_FIELD)
        if thread_link:
            problem = _thread_link_problem(thread_link, criteria)
            if problem:
                report.error(where, f"{code}: {THREAD_LINK_FIELD}={problem}")
        # transport_used / fallback_reason — производные прогона handoff:
        # по ним видно, каким транспортом ушло сообщение и почему MCP уступил
        # API. Опечатка исказила бы разбор инцидента, поэтому — ERROR.
        transport_used = entry.get(TRANSPORT_USED_FIELD)
        if transport_used is not None and transport_used not in HANDOFF_TRANSPORT_VALUES:
            report.error(
                where,
                f"{code}: {TRANSPORT_USED_FIELD}={transport_used!r} "
                f"(допустимо {', '.join(HANDOFF_TRANSPORT_VALUES)}; "
                "выставляется командами make handoff/handoff-result)",
            )
        fallback_reason = entry.get(FALLBACK_REASON_FIELD)
        if fallback_reason is not None and fallback_reason not in HANDOFF_FALLBACK_VALUES:
            report.error(
                where,
                f"{code}: {FALLBACK_REASON_FIELD}={fallback_reason!r} "
                f"(допустимо {', '.join(HANDOFF_FALLBACK_VALUES)})",
            )
        if thread_link and handoff_status not in (None, HANDOFF_STATUS_PUBLISHED):
            report.warn(
                where,
                f"{code}: {THREAD_LINK_FIELD} заполнен, а "
                f"{HANDOFF_STATUS_FIELD}={handoff_status!r} — ожидалось published",
            )
        excluded = entry.get("excluded")
        if excluded not in (None, True, False):
            report.error(
                where,
                f"{code}: excluded={excluded!r} (допустимо true или false)",
            )
        elif excluded is True and not str(entry.get("reason") or "").strip():
            report.error(
                where,
                f"{code}: excluded: true без непустого reason — укажите причину "
                "исключения (make exclude IS=... REASON=... EXCLUDE_SCOPE=catalog)",
            )
        if entry.get("extra_criteria") is None:
            report.warn(where, f"{code}: extra_criteria не задан (ожидался список, возможно [])")
        elif not isinstance(entry.get("extra_criteria"), list):
            report.error(where, f"{code}: extra_criteria должен быть списком")
        for field, what in CATALOG_PAGE_FIELDS:
            problem = catalog_page_id_problem(entry.get(field))
            if problem:
                report.error(where, f"{code}: {field}={problem} (page_id {what})")
    return by_code


def _check_git_repositories(report: Report, root: Path, systems):
    """WARN о `git_repository`, который открывается в браузере, а не клонируется.

    Тот же контроль, что в `prepare` (`component_plan`), но до запуска git:
    `github.com/bitnami/containers/tree/...` — веб-страница, клон по ней
    падает, и без проверки это выясняется уже на этапе сборки данных. WARN, а
    не ERROR: значение приходит из SSoT, клон компонента необязателен.
    """
    for entry in systems:
        code = str(entry.get("code") or "")
        if not code:
            continue
        rel, _legacy = is_folder(root, code, entry)
        info = _load_info_file(root / rel)
        components = (info or {}).get("components") if isinstance(info, dict) else None
        if not isinstance(components, list):
            continue
        for item in components:
            if not isinstance(item, dict):
                continue
            problem = _git_web_ui_problem(item.get("git_repository"))
            if problem:
                report.warn(
                    f"{rel}/{INFORMATION_FILE}",
                    f"components[{item.get('name') or '?'}]: {problem}",
                )


def _check_contacts(report: Report, root: Path, systems):
    """WARN о контактах TA/TL: не собраны или ключевая группа пуста.

    Проверка мягкая: публикация без упоминания — не ошибка паспорта, а
    недоделанный шаг `make contacts`. ERROR здесь не ставится, чтобы гейт
    публикации не менялся.
    """
    for entry in systems:
        code = str(entry.get("code") or "")
        if not code:
            continue
        rel, _legacy = is_folder(root, code, entry)
        info_path = root / rel / INFORMATION_FILE
        info = _load_info_file(root / rel)
        contacts = _info_contacts(info) if isinstance(info, dict) else {}
        groups = _contacts_groups(contacts)
        team = _normalize_team(entry.get("team"))
        team_file, _team_problem = _team_contacts_path(root, team)
        # Пустой блок пишется как `contacts: {team: null, groups: {}}` — это
        # truthy-словарь, поэтому «не собраны» проверяется по содержимому.
        if not _contacts_groups(contacts) and not contacts.get("team"):
            if team_file is not None and team_file.exists():
                report.warn(
                    f"{rel}/{INFORMATION_FILE}",
                    "контакты TA/TL не собраны — выполните "
                    f"make contacts IS={code} APPLY=1",
                )
            continue
        for name in CONTACTS_MENTION_GROUPS:
            if not _contact_logins(groups, name):
                report.warn(
                    f"{rel}/{INFORMATION_FILE}",
                    f"группа {name} пуста в contacts — обновите: "
                    f"make contacts IS={code} APPLY=1",
                )


def _check_mentions(report: Report, root: Path, systems, catalog=None):
    """WARN об упоминаниях, которые не сработают в RocketChat.

    Упоминание работает только по полному username (`dkozlov@ecom.tech`).
    Короткий логин без домена валиден как идентификатор в SSoT, но в тексте
    треда он не создаёт mention: уведомление не придёт. Резолв делает `start`
    и складывает результат в `catalog.yaml → rocketchat_users`; здесь
    проверяется, что для каждого TA/TL он есть. Нет блока кеша вовсе — проект
    ещё не прогонял резолв: молчим, чтобы не шуметь на старых проектах.
    """
    cache = _rocketchat_users_cache(catalog)
    if not cache:
        return
    for entry in systems:
        code = str(entry.get("code") or "")
        if not code:
            continue
        rel, _legacy = is_folder(root, code, entry)
        info = _load_info_file(root / rel)
        groups = _contacts_groups(_info_contacts(info))
        for name in CONTACTS_MENTION_GROUPS:
            for login in _contact_logins(groups, name):
                if "@" in login or _rocketchat_cached_username(login, cache):
                    continue
                report.warn(
                    f"{rel}/{INFORMATION_FILE}",
                    f"упоминание @{login} не резолвится в RocketChat — "
                    "уведомление не придёт; задайте полный username вручную "
                    f"(catalog.yaml → {ROCKETCHAT_USERS_KEY}.{login}.username)",
                )


def _check_passport(
    report: Report, root: Path, path: Path, by_code, criteria=None,
    base=None, catalog=None,
):
    rel = path.relative_to(root).as_posix()
    parts = path.relative_to(root).parts
    if len(parts) != 3:
        report.error(rel, "ожидался путь is/<код ИС>/criticality-passport.yaml")
        return None
    code = parts[1]
    name, contour = split_is_code(code)
    if not contour:
        report.error(
            rel,
            f"имя папки {code!r} должно быть кодом ИС <name_is>.<контур>",
        )
        return None

    try:
        doc = load_yaml(path)
    except YamlError as exc:
        report.error(rel, f"YAML не разобран: {exc}")
        return code

    if not isinstance(doc, dict):
        report.error(rel, "ожидался словарь верхнего уровня")
        return code

    extra_top = sorted(set(doc) - {"ecom.criticality_passport"})
    if extra_top:
        report.error(rel, f"лишние ключи верхнего уровня: {', '.join(extra_top)}")

    section = doc.get("ecom.criticality_passport")
    if not isinstance(section, dict) or not section:
        report.error(rel, "нет секции 'ecom.criticality_passport'")
        return code
    if len(section) != 1:
        report.error(
            rel,
            f"в 'ecom.criticality_passport' должен быть ровно один объект, найдено {len(section)}",
        )
        return code

    object_id = next(iter(section))
    body = section[object_id]
    if not isinstance(body, dict):
        report.error(rel, f"объект {object_id} должен быть словарём")
        return code

    expected_id = f"sber.ecom.{contour}.criticality_passport.{name}"
    if object_id != expected_id:
        report.error(rel, f"id={object_id!r}, ожидалось {expected_id!r}")
    if not ID_RE.match(object_id):
        report.error(rel, f"id={object_id!r} не соответствует шаблону sber.ecom.<контур>.criticality_passport.<name_is>")

    missing = [key for key in PASSPORT_KEYS if key not in body]
    unknown = [
        key for key in body if key not in PASSPORT_KEYS + PASSPORT_OPTIONAL_KEYS
    ]
    if missing:
        report.error(rel, f"нет канонических полей: {', '.join(missing)}")
    if unknown:
        report.error(
            rel,
            f"неканонические поля (dochub такой файл не примет): {', '.join(unknown)}",
        )

    expected_object = f"sber.ecom.{contour}.{name}"
    if body.get("evaluated_object") != expected_object:
        report.error(
            rel,
            f"evaluated_object={body.get('evaluated_object')!r}, ожидалось {expected_object!r}",
        )

    consumers = body.get("object_consumers_type")
    if consumers is None:
        report.warn(rel, "object_consumers_type не заполнен")
    elif _canon_text(consumers) not in [_canon_text(item) for item in CONSUMERS_TYPES]:
        report.error(rel, f"object_consumers_type={consumers!r} вне enum")

    impact = body.get("object_outage_impact")
    if impact is None:
        report.warn(rel, "object_outage_impact не заполнен")
    elif _canon_text(impact) not in [_canon_text(item) for item in OUTAGE_IMPACTS]:
        report.error(rel, f"object_outage_impact={impact!r} вне enum")

    criticality = body.get("object_criticality_estimation")
    if criticality is None:
        report.warn(rel, "object_criticality_estimation не заполнен")
    elif criteria is not None and criticality not in level_set(criteria):
        report.error(
            rel,
            f"object_criticality_estimation={criticality!r} вне enum "
            f"({', '.join(level_set(criteria))})",
        )
    elif criteria is not None:
        extra = dochub_extra_level(criteria)
        if extra and criticality == extra:
            # D3: уровень существует только в dochub-реестре как внешний.
            # Расчёт его не производит — значит, в паспорт он попал из реестра
            # или вписан руками; это повод проверить происхождение, не ошибка.
            report.warn(
                rel,
                f"уровень {extra!r} не производится методикой (dochub-уровень) — "
                "проверьте происхождение",
            )

    for field, label in (
        ("object_sla", "object_sla (минуты)"),
        ("object_workload", "object_workload (клиентов/час)"),
    ):
        value = body.get(field)
        if value is None:
            report.warn(rel, f"{label} не заполнен")
        elif isinstance(value, bool) or not isinstance(value, int) or value < 0:
            if field == "object_sla":
                report.error(
                    rel,
                    f"{field}={value!r} — ожидалось целое число >= 0 "
                    "(0 = простой недопустим) или null",
                )
            else:
                report.error(rel, f"{field}={value!r} — ожидалось целое число > 0 или null")

    for field in ("assigned_date", "review_date", "generated_at"):
        value = body.get(field)
        if value is None:
            # Даты оценки заполняются при генерации от `generated_at`, поэтому
            # пустыми не бывают: WARN «не заполнен» снят. `generated_at` —
            # необязательное поле (старые паспорта валидны до перегенерации).
            continue
        try:
            parse_date(value)
        except ValueError as exc:
            report.error(rel, f"{field}: {exc}")

    # Просрочка переоценки: дата — из реестра (effective_review_date), иначе
    # паспорт маскировал бы её датой генерации (дефект C1).
    registry_review = (by_code.get(code) or {}).get("review_date")
    passport_review = body.get("review_date")
    if passport_review not in (None, "") and registry_review not in (None, ""):
        try:
            same_review = parse_date(passport_review) == parse_date(registry_review)
        except ValueError:
            same_review = True
        if not same_review:
            # Копия в паспорте вторична (инвариант 13): реестр авторитетен, но
            # расхождение нельзя игнорировать молча (N7).
            report.warn(
                rel,
                f"review_date в паспорте ({passport_review}) не совпадает с "
                f"реестром ({registry_review}) — перегенерируйте "
                f"make start-apply IS={code}",
            )
    # Просрочка — по due_date (review_date + период переоценки), а не по
    # review_date: дата оценки не просрочивается на следующий же день.
    review_date, review_due, review_overdue = review_staleness(
        by_code.get(code), body, catalog=catalog, criteria=criteria,
        reference=base or today(),
    )
    if review_overdue:
        reference = base or today()
        days = (reference - review_due).days
        report.warn(
            rel,
            f"переоценка просрочена (due_date {review_due.isoformat()} < "
            f"{reference.isoformat()}, {days} дн.; review_date "
            f"{review_date.isoformat()}): make reassess IS={code}, затем "
            f"make reassess-apply IS={code}",
        )

    approve = body.get("approve_link")
    if approve is None:
        report.warn(
            rel,
            "approve_link не заполнен (нет треда согласования) — "
            "выполните make handoff IS=<код> SEND=auto",
        )
    else:
        problem = approve_link_problem(approve, criteria)
        if problem:
            report.warn(rel, f"approve_link={approve!r}: {problem}")

    entry = by_code.get(code)
    if entry is None:
        report.error(rel, f"ИС {code!r} отсутствует в catalog.yaml")
    else:
        if entry.get("path") != f"is/{code}":
            report.error(
                rel,
                f"path в catalog.yaml = {entry.get('path')!r}, а папка is/{code}",
            )
        cat_crit = entry.get("criticality")
        cat_ssot = entry.get("criticality_ssot")
        if criticality is not None:
            # Расхождение расчёта с реестром — не структурная ошибка паспорта:
            # оно фиксируется в GENERATION.md → conflicts, §7 CRITICALITY.md и
            # INDEX.md и требует подтверждения у TL/SRE. Один WARN CONFLICT на
            # ИС, без дублей (catalog.criticality и catalog.criticality_ssot
            # схлопываются по значению).
            registry = []
            for value in (cat_crit, cat_ssot):
                if value is not None and value != criticality and value not in registry:
                    registry.append(value)
            if registry:
                shown = ", ".join(repr(value) for value in registry)
                report.warn(
                    code,
                    "CONFLICT: расхождение расчёта с реестром: "
                    f"расчёт {criticality!r}, реестр {shown} "
                    "(см. GENERATION.md → conflicts; подтвердить у TL/SRE "
                    "или обновить реестр)",
                )
            elif cat_crit is None and cat_ssot is None:
                # Конфликт не проверялся: сверять не с чем. Молчаливое «0
                # расхождений» читалось бы как подтверждённая сверка, поэтому
                # отсутствие данных в реестре — отдельный WARN.
                report.warn(
                    code,
                    "критичность в реестре не заполнена "
                    "(catalog.yaml → criticality / criticality_ssot = null), "
                    "конфликт с реестром не проверен; заполняется командой "
                    "`make finalize` после мержа MR (подтверждение = мерж)",
                )
        if criticality is None and cat_crit is not None:
            report.warn(
                rel,
                f"в реестре criticality={cat_crit!r}, но в паспорте поле не заполнено",
            )
        if entry.get("status") == "confirmed" and approve is None:
            report.error(rel, "status=confirmed в реестре, но approve_link пуст")

    _check_criticality_md(
        report, root, path.parent / "CRITICALITY.md", code, body, by_code, criteria
    )

    # --- ссылка на АДР и глубокий поиск -----------------------------------
    # Оба WARN: это не структурная ошибка паспорта, а незакрытый этап сбора.
    info = _load_info_file(path.parent)
    if info is not None and criteria is not None:
        facts = facts_block(info.get("facts"))
        _link, adr_basis = adr_link_value(criteria, facts, entry or {}, catalog)
        adr_warning = adr_orphan_warning(facts)
        if adr_warning:
            report.warn(rel, adr_warning)
        for warning in e2e_fact_warnings(info):
            report.warn(rel, warning)
        if adr_basis == "none":
            report.warn(
                rel,
                "ссылка на АДР не собрана: нет facts.adr, "
                "catalog.yaml → architecture_page_id и confluence_page_id — "
                f"в публикации будет {MISSING_MARK}",
            )
        gate = evaluate_gate(info, criteria)
        missing_blocking = [
            str(item).split(".")[0] for item in gate["blocking"]["missing"]
        ]
        if missing_blocking:
            known_ids = {spec["id"] for spec in gate["specs"]}
            blocks, _problems, _has = _ask_candidate_blocks(
                path.parent, criteria, known_ids, code=code
            )
            search, _search_problems = read_search_records(path.parent, code=code)
            for identifier in dict.fromkeys(missing_blocking):
                # Только `done: true` снимает WARN — как в `ask`: запись
                # `search.<вход>` без выполненного tier 2 (или с одним weak-
                # кандидатом) ничего не доказывает.
                if blocks.get(identifier) or _search_covers(search, identifier):
                    continue
                report.warn(
                    rel,
                    f"{identifier}: blocking-вход без значения, кандидатов нет и "
                    "глубокий поиск не зафиксирован — выполните tier 2 "
                    "(references/search.md) и запишите search: в CANDIDATES.yaml",
                )

    return code


def _check_requirements_sheet(report: Report, root: Path, code: str, entry, criteria):
    """Инвариант листа: только открытые входы и верные счётчики.

    Лист `DATA-REQUIREMENTS.*` производен от `INFORMATION.yaml`. Поэтому:
      * поле, которое по `_input_closed` уже закрыто (значение + status
        confirmed/derived/legacy), в листе — ERROR: его там быть не должно;
      * `blocking_count`/`advisory_count` в YAML — это число ОТКРЫТЫХ полей
        соответствующей роли; расхождение — ERROR (лист и гейт разошлись).

    Расхождение состава `.md` и `.yaml` — WARN: оба файла рендерятся из одного
    контекста, поэтому расхождение означает правку руками.
    """
    folder_rel, folder, md_path, yaml_path = _requirements_paths(root, code, entry)
    if not yaml_path.exists():
        return
    rel = yaml_path.relative_to(root).as_posix()
    try:
        doc = load_yaml(yaml_path)
    except (YamlError, OSError):
        doc = None
    inputs = doc.get("inputs") if isinstance(doc, dict) else None
    if not isinstance(inputs, dict):
        report.error(
            rel,
            "лист недостающих данных не разобран (ожидалась секция inputs: "
            f"словарь) — перегенерируйте: make requirements IS={code} APPLY=1",
        )
        return

    info = _load_info_file(folder)
    if info is None:
        report.warn(
            rel,
            f"нет читаемого {INFORMATION_FILE} — инвариант листа не проверен",
        )
        return
    gate = evaluate_gate(info, criteria)
    scenario_ids = set(gate.get("scenario_inputs") or [])
    closed = {
        spec["id"]
        for spec in gate["specs"]
        if _input_closed(gate["records"][spec["id"]])
    }
    open_ids = [spec["id"] for spec in gate["specs"] if spec["id"] not in closed]
    blocking_open = [identifier for identifier in open_ids if identifier in scenario_ids]
    advisory_open = [identifier for identifier in open_ids if identifier not in scenario_ids]

    known_ids = {spec["id"] for spec in gate["specs"]}
    for identifier in sorted(str(item) for item in inputs):
        if identifier in closed:
            report.error(
                rel,
                f"лист содержит уже заполненное поле {identifier} — удалите его: "
                f"make requirements IS={code} APPLY=1",
            )
        elif identifier not in known_ids:
            report.error(
                rel,
                f"лист содержит неизвестный вход {identifier!r} "
                f"(допустимые: {', '.join(sorted(known_ids))}) — "
                f"перегенерируйте: make requirements IS={code} APPLY=1",
            )

    declared = doc.get("blocking_count")
    declared_int = _coerce_int(declared)
    if declared_int != len(blocking_open):
        report.error(
            rel,
            f"blocking_count = {declared!r}, а открытых blocking-полей "
            f"{len(blocking_open)} ({', '.join(blocking_open) or '—'}) — "
            f"перегенерируйте: make requirements IS={code} APPLY=1",
        )
    declared = doc.get("advisory_count")
    declared_int = _coerce_int(declared)
    if declared_int != len(advisory_open):
        report.error(
            rel,
            f"advisory_count = {declared!r}, а открытых advisory-полей "
            f"{len(advisory_open)} ({', '.join(advisory_open) or '—'}) — "
            f"перегенерируйте: make requirements IS={code} APPLY=1",
        )

    absent = [identifier for identifier in open_ids if identifier not in inputs]
    if absent:
        report.warn(
            rel,
            "лист не содержит открытые поля: " + ", ".join(absent)
            + f" — перегенерируйте: make requirements IS={code} APPLY=1",
        )

    if not md_path.exists():
        report.warn(
            md_path.relative_to(root).as_posix(),
            f"нет {DATA_REQUIREMENTS_MD} при существующем {DATA_REQUIREMENTS_YAML} — "
            f"перегенерируйте: make requirements IS={code} APPLY=1",
        )
        return
    try:
        md_text = md_path.read_text(encoding="utf-8")
    except OSError:
        return
    md_ids = set(re.findall(r"^### .*\(`([A-Za-z0-9_]+)`\)\s*$", md_text, re.M))
    if md_ids != set(str(item) for item in inputs):
        report.warn(
            md_path.relative_to(root).as_posix(),
            "состав полей в .md и .yaml расходится "
            f"(только в .md: {', '.join(sorted(md_ids - set(map(str, inputs)))) or '—'}; "
            f"только в .yaml: {', '.join(sorted(set(map(str, inputs)) - md_ids)) or '—'}) — "
            f"перегенерируйте: make requirements IS={code} APPLY=1",
        )


def _check_waived_inputs(report, root, systems, criteria, exclusions=None):
    """R17: у отказа есть причина/допущение, и предупреждение есть в артефакте.

    Проверки:
      * `status: waived` без `waive.reason` (>= 10 символов) или без
        `waive.fallback.mode` — отказ без причины нельзя ни проверить, ни
        воспроизвести;
      * у waived-входа не может быть значения (`value: null` обязателен);
      * `status: waived` есть, а `CRITICALITY.md` не помечает оценку
        предварительной — диапазон потерян, уровень читается как факт;
      * обратное: блок предварительной оценки остался, а waived-входов нет —
        пометка устарела (иначе `(предв.)` висит вечно);
      * уровень паспорта обязан совпадать с текущей предварительной оценкой.
    ИС, исключённые из расчёта, пропускаются: их устаревшие артефакты не
    должны поднимать ERROR (как в `enrich`/`start`).
    """
    exclusions = exclusions or {}
    for entry in systems or []:
        code = str(entry.get("code") or "")
        if code and code in exclusions:
            continue
        rel = str(entry.get("path") or "")
        if not rel and code:
            rel = is_layout(root, code)[0]
        if not rel:
            continue
        info_path = root / rel / INFORMATION_FILE
        if not info_path.exists():
            continue
        try:
            info = load_yaml(info_path)
        except (YamlError, OSError):
            continue
        if not isinstance(info, dict):
            continue
        block = _criteria_input_block(info)
        waived = [
            str(identifier)
            for identifier, value in block.items()
            if isinstance(value, dict)
            and str(value.get("status") or "").strip().lower() == WAIVED_STATUS
        ]
        md_path = root / rel / "CRITICALITY.md"
        text = ""
        if md_path.exists():
            try:
                text = md_path.read_text(encoding="utf-8")
            except (OSError, UnicodeDecodeError):
                text = ""
        marker = WAIVE_MARKER in text
        if not waived:
            # Зеркальная проверка: пометка без отказа — устаревший артефакт.
            if marker:
                report.error(
                    f"{rel}/CRITICALITY.md",
                    "в CRITICALITY.md остался блок предварительной оценки, а "
                    "waived-входов нет — перегенерируйте: "
                    f"make start-apply IS={code} FORCE=1",
                )
            continue
        if criteria is not None:
            for identifier in waived:
                record = block.get(identifier) or {}
                problem = _waive_problem(
                    criteria, identifier, record.get("waive"),
                    value=record.get("value"),
                )
                if problem:
                    report.error(
                        f"{rel}/{INFORMATION_FILE}", f"{identifier}: {problem}"
                    )
        if not marker:
            report.error(
                f"{rel}/CRITICALITY.md",
                "есть вход со status: waived ("
                + ", ".join(waived)
                + "), но предупреждение «"
                + WAIVE_MARKER
                + "» отсутствует — оценка выдаётся за подтверждённую; "
                "перегенерируйте артефакты: make start-apply FORCE=1",
            )
            continue
        # Уровень паспорта обязан совпадать с текущей предварительной оценкой:
        # после удаления отказа паспорт мог остаться со старым уровнем.
        if criteria is not None:
            body = passport_body(root, {"path": rel})
            passport_level = (
                body.get("object_criticality_estimation")
                if isinstance(body, dict)
                else None
            )
            provisional = provisional_score(criteria, evaluate_gate(info, criteria))
            reported = provisional.get("reported")
            if passport_level and reported and passport_level != reported:
                report.error(
                    f"{rel}/criticality-passport.yaml",
                    "object_criticality_estimation="
                    f"{passport_level!r} ≠ предварительной оценке {reported!r} "
                    "(уровень/диапазон пересчитан) — перегенерируйте: "
                    f"make start-apply IS={code} FORCE=1",
                )


def _fingerprint_findings(root, passport_path, current):
    """WARN о фингерпринте критериев у артефактов ИС: (где, сообщение)[].

    Старые артефакты без фингерпринта — WARN (не ERROR): отсутствие поля не
    означает неверный расчёт, но означает, что версию критериев не сверить.
    """
    folder = Path(passport_path).parent
    artifact = folder / "CRITICALITY.md"
    if not artifact.exists():
        return []
    try:
        where = artifact.relative_to(root).as_posix()
    except ValueError:
        where = artifact.as_posix()
    stored = artifact_fingerprint(artifact)
    if stored is None:
        return [
            (
                where,
                "артефакты собраны без фингерпринта критериев — версия правил "
                "не проверяется: make start-apply FORCE=1",
            )
        ]
    if stored != current:
        return [
            (
                where,
                f"criteria_fingerprint не совпадает: артефакты собраны на "
                f"{stored}, критерии {current} → перезапустите "
                "make start-apply FORCE=1",
            )
        ]
    return []


# ---------------------------------------------------------------------------
# Гейт внешних изменений (publish / ssot)
# ---------------------------------------------------------------------------
# Порядок конвейера — инвариант: исследование → критерии → расчёт → валидация
# ВСЕХ артефактов → внешние изменения (dochub, SSoT) → тред. Формировать MR до
# зелёной валидации запрещено (references/rules.md, R18): внешняя ветка живёт
# дольше локального прогона и видна другим командам.
GATE_LOG_FILE = ".gate-overrides.log"


def _passport_validate_errors(root, path, code, entry, criteria, catalog):
    """ERROR-сообщения validate по паспорту ИС (пусто — паспорт проходит)."""
    try:
        if not path.exists():
            return ["паспорт не найден"]
        report = Report()
        _check_passport(
            report, root, path, {code: entry}, criteria, base=today(),
            catalog=catalog,
        )
    except (YamlError, OSError, ValueError, KeyError, TypeError) as exc:
        return [f"проверка не выполнена: {type(exc).__name__}: {exc}"]
    return [message for _where, message in report.errors]


def _gate_validate_problems(root, code, entry, criteria, catalog, passport):
    """Причина отказа: паспорт не проходит validate."""
    errors = _passport_validate_errors(
        root, passport, code, entry, criteria, catalog
    )
    if not errors:
        return []
    head = errors[0]
    tail = f" (всего {len(errors)})" if len(errors) > 1 else ""
    return [
        f"validate не пройден: {head}{tail} — исправьте ERROR и повторите "
        "make validate"
    ]


def _gate_fingerprint_problems(passport, criteria, code):
    """Причина отказа: артефакты собраны на другой версии критериев."""
    artifact = Path(passport).parent / "CRITICALITY.md"
    current = criteria_fingerprint(criteria)
    rerun = f"make start-apply IS={code} FORCE=1"
    if not artifact.exists():
        return [
            f"нет CRITICALITY.md — артефакты не сгенерированы: {rerun}"
        ]
    stored = artifact_fingerprint(artifact)
    if stored is None:
        return [
            "в CRITICALITY.md нет criteria_fingerprint — версия критериев не "
            f"проверяется: {rerun}"
        ]
    if stored != current:
        return [
            f"criteria_fingerprint не совпадает: артефакты собраны на {stored}, "
            f"критерии {current} — {rerun}"
        ]
    return []


def _gate_blocking_problems(info, criteria, code):
    """Причина отказа: в паспорте/INFORMATION остались незакрытые blocking-входы."""
    gate = evaluate_gate(info or {}, criteria)
    if gate.get("verdict") == "OK":
        return []
    missing = list((gate.get("blocking") or {}).get("missing") or [])
    text = str(gate.get("reason") or "BLOCKED")
    if missing:
        text += "; не закрыты blocking-входы: " + ", ".join(missing)
    return [
        f"{text} — make check IS={code}, затем make enrich-apply IS={code}"
    ]


def _gate_log_write(passport, label, problems, reason=None):
    """Записать осознанный обход гейта в `is/<код>/.gate-overrides.log`."""
    path = Path(passport).parent / GATE_LOG_FILE
    reason = reason or "обход гейта валидации (--force)"
    line = (
        f"{dt.datetime.now().isoformat(timespec='seconds')} {label}: {reason}: "
        + "; ".join(problems) + "\n"
    )
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("a", encoding="utf-8") as handle:
            handle.write(line)
    except OSError as exc:
        print(f"WARN: не удалось записать {path}: {exc}")
        return None
    return path


def external_change_gate(
    root, criteria, code, entry, catalog, info, passport, label, force=False
):
    """Гейт перед внешними изменениями (publish/ssot): True — можно идти дальше.

    Три предусловия, каждое называется своей причиной и следующим шагом:
    зелёный `validate`, совпавший `criteria_fingerprint`, закрытые
    blocking-входы. `--force` обходит гейт осознанно: печатает WARN и пишет
    строку в `is/<код>/.gate-overrides.log`.
    """
    problems = (
        _gate_validate_problems(root, code, entry, criteria, catalog, passport)
        + _gate_fingerprint_problems(passport, criteria, code)
        + _gate_blocking_problems(info, criteria, code)
    )
    if not problems:
        return True
    if force:
        print(
            f"WARN: {label} {code} — гейт валидации обойдён осознанно (--force):"
        )
        for problem in problems:
            print(f"  - {problem}")
        log_path = _gate_log_write(passport, label, problems)
        if log_path is not None:
            print(f"  обход записан: {log_path}")
        return True
    print(
        f"ERROR: {label} {code} заблокирован — внешние изменения (dochub, SSoT) "
        "допустимы только после зелёной валидации всех артефактов:"
    )
    for problem in problems:
        print(f"  - {problem}")
    print(f"Следующий шаг: make validate → make start-apply IS={code} FORCE=1 "
          f"→ make check IS={code}")
    print(
        "Осознанный обход: --force (с предупреждением и записью в "
        f"is/{code}/{GATE_LOG_FILE})"
    )
    return False


def cmd_validate(args) -> int:
    root = repo_root_from_args(args)
    print_project_root(root, args)
    report = Report()
    try:
        base = parse_date_arg(args.date, "--date") if getattr(args, "date", None) else None
    except ValueError as exc:
        print(f"ERROR: {exc}")
        return 1
    base = base or today()
    try:
        catalog, systems = load_catalog(root)
    except YamlError as exc:
        print(f"ERROR catalog.yaml: {exc}")
        print()
        print("Итого: 1 ERROR, 0 WARN")
        print("Результат: FAIL")
        return 1

    try:
        criteria = load_criteria()
    except YamlError as exc:
        print(
            f"WARN: критерии не прочитаны ({exc}) — approve_link проверяется "
            "только по схеме http(s)"
        )
        criteria = None

    if criteria is not None:
        # Архивный источник, выданный за действующий, — WARN: расчёт не
        # меняется, но провенанс правила требует ревизии.
        for where, message in _archived_source_warnings(criteria):
            report.warn(where, message)

    by_code = _check_catalog(report, root, systems, criteria, catalog=catalog)
    _check_cyrillic_codes(report, root)
    if criteria is not None:
        # Инвариант листа недостающих данных: только открытые поля и верные
        # счётчики (см. `_check_requirements_sheet`).
        for entry in systems:
            code = str(entry.get("code") or "").strip()
            if code:
                _check_requirements_sheet(report, root, code, entry, criteria)
    # Контакты TA/TL — WARN, не ERROR: отсутствие упоминания не ломает паспорт.
    _check_contacts(report, root, systems)
    # Упоминания: короткий логин без домена в RocketChat не срабатывает.
    _check_mentions(report, root, systems, catalog=catalog)
    # git_repository — WARN: веб-страница вместо clone URL ломает `prepare`.
    _check_git_repositories(report, root, systems)
    # R17: явный отказ от данных обязан быть оформлен и отражён в CRITICALITY.md.
    _check_waived_inputs(
        report, root, systems, criteria, exclusions=_exclusions(root, systems)
    )
    # R16: язык свободного текста — мягкая проверка (WARN, значение остаётся).
    for where, message in _language_findings(root, systems):
        report.warn(where, message)
    info_paths = []
    for entry in systems:
        code = str(entry.get("code") or "")
        rel = str(entry.get("path") or "")
        if not rel and code:
            rel = is_layout(root, code)[0]
        if rel:
            info_paths.append(f"{rel}/{INFORMATION_FILE}")
    for rel in _untracked_information(root, info_paths):
        report.warn(
            rel,
            "INFORMATION.yaml не отслеживается git — ручные данные "
            "(criteria_inputs, facts, conflicts, notes) могут быть потеряны; "
            "закоммитьте файл",
        )
    is_dir = root / "is"
    files = sorted(is_dir.glob("*/criticality-passport.yaml")) if is_dir.is_dir() else []

    for legacy_path in legacy_is_folders(root):
        report.warn(
            legacy_path.relative_to(root).as_posix(),
            "legacy-раскладка is/<контур>/<name_is>/ не поддержана "
            "validate/index/due; перенесите в is/<код ИС>/",
        )

    if not files:
        print(
            "Паспортов не найдено: в is/<код ИС>/criticality-passport.yaml "
            "пока нет ни одного файла."
        )
        print(
            f"Реестр catalog.yaml прочитан: ИС — {len(systems)}, паспортов — 0."
        )
        for where, message in report.errors:
            print(f"ERROR {where}: {message}")
        if report.errors:
            print()
            print(f"Итого: {len(report.errors)} ERROR, {len(report.warns)} WARN")
            print("Результат: FAIL")
            return 1
        print(
            "Это ожидаемое состояние до первой сессии заполнения. Создать паспорт: "
            "make scaffold CONTOUR=<mm|smkt> NAME=<name_is>"
        )
        for where, message in report.warns:
            print(f"WARN  {where}: {message}")
        print()
        print(f"Итого: 0 ERROR, {len(report.warns)} WARN")
        print("Результат: OK")
        _emit_next_steps(root, criteria, args)
        return 0

    seen = set()
    for path in files:
        code = _check_passport(
            report, root, path, by_code, criteria, base=base, catalog=catalog
        )
        if code:
            seen.add(code)

    # Артефакты собраны на другой версии критериев — WARN: расчёт не меняется,
    # но паспорт описывает ушедшие вперёд правила. Сравнивается фингерпринт, а не
    # mtime: файл критериев правится постоянно.
    if criteria is not None:
        current_fingerprint = criteria_fingerprint(criteria)
        for path in files:
            for where, message in _fingerprint_findings(
                root, path, current_fingerprint
            ):
                report.warn(where, message)
        # FIX 1: заголовки страниц. Название печатается в артефактах только из
        # кеша проверенных заголовков; нет кеша/даты/версия устарела — ERROR.
        _check_page_titles(
            report, root, criteria, systems,
            offline=bool(getattr(args, "no_network", False)),
        )

    for code in by_code:
        if code not in seen:
            report.warn(
                "catalog.yaml",
                f"ИС {code!r} есть в реестре, но паспорта в is/ нет",
            )

    for where, message in report.errors:
        print(f"ERROR {where}: {message}")
    for where, message in report.warns:
        print(f"WARN  {where}: {message}")
    if report.errors or report.warns:
        print()
    print(
        f"Проверено паспортов: {len(files)}. "
        f"Итого: {len(report.errors)} ERROR, {len(report.warns)} WARN"
    )
    if report.errors:
        print("Результат: FAIL")
        _emit_next_steps(root, criteria, args)
        return 1
    print("Результат: OK")
    _emit_next_steps(root, criteria, args)
    return 0


# ---------------------------------------------------------------------------
# index
# ---------------------------------------------------------------------------

INDEX_BEGIN = "<!-- BEGIN:generated -->"
INDEX_END = "<!-- END:generated -->"

INDEX_HEADER = """---
title: Индекс паспортов критичности — {product_label}
purpose: Сводная таблица паспортов всех ИС продукта; таблица генерируется командой make index.
audience: [ai-agent, human]
read_when: [нужен список всех ИС и их статусов, проверка просроченных переоценок]
updated: {generated}
status: actual
related: [catalog.yaml]
---

# Индекс паспортов критичности — {product_label}

## Когда читать

- Читать, когда нужен список всех ИС с критичностью, командой и статусом.
- Читать, когда проверяете, у каких ИС просрочена переоценка.
- Читать, когда ищете ссылку на `CRITICALITY.md` конкретной ИС.

## Кратко

- Источник данных — [`catalog.yaml`](catalog.yaml) плюс `criticality-passport.yaml` каждой ИС; значения из паспорта приоритетнее.
- Таблица между маркерами `BEGIN:generated` / `END:generated` генерируется командой `make index`; руками не править.
- Статус `draft` — оценка не подтверждена SRE; `confirmed` — есть `approve_link`.
- Просрочка считается по `due_date = review_date + период переоценки` (по умолчанию 12 месяцев).

- Продукт: {product_line}
- Документация: [docs/README.md](docs/README.md)
- Процесс и runbook: [docs/01-process.md](docs/01-process.md), [docs/04-reassessment.md](docs/04-reassessment.md)
"""


def _index_header(catalog=None, criteria=None, generated=None) -> str:
    """Заголовок INDEX.md: метка продукта и ссылка — из catalog.yaml."""
    catalog = catalog or {}
    product_code = catalog.get("product")
    product_name = catalog.get("product_name")
    if product_code and product_name:
        label = f"{product_code} «{product_name}»"
    elif product_name:
        label = str(product_name)
    else:
        label = str(product_code or "продукт")
    page_id = catalog.get("product_confluence_page_id")
    if page_id:
        product_url = _page_url(criteria, page_id)
        if product_url is None:
            _warn_missing_base_url(criteria, "ссылки INDEX.md")
            product_line = (
                f"{label} — {MISSING_MARK} (criteria.external_refs.base_url)"
            )
        else:
            product_line = f"[{label}]({product_url})"
    else:
        product_line = f"{label} — {MISSING_MARK} (catalog.product_confluence_page_id)"
    return INDEX_HEADER.format(
        product_label=label,
        product_line=product_line,
        generated=(generated or today()).isoformat(),
    )


def _index_cell(value) -> str:
    text = "—" if value in (None, "", []) else str(value)
    return text.replace("|", "\\|")


def _passport_provisional(root, entry):
    """Оценка предварительная (R17)? Признак — предупреждение в `CRITICALITY.md`.

    Паспорт `criticality-passport.yaml` — канонический 9-полевой формат dochub:
    произвольных полей в нём нет, поэтому пометка живёт в человекочитаемом
    `CRITICALITY.md`, а индекс читает её оттуда.
    """
    rel = str(entry.get("path") or "")
    if not rel:
        return False
    path = root / rel / "CRITICALITY.md"
    if not path.exists():
        return False
    try:
        return WAIVE_MARKER in path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return False


def build_index_block(
    root: Path, systems, catalog=None, criteria=None, exclusions=None, current=None
) -> str:
    """Таблица INDEX.md. `current` — дата отчёта (--date), по умолчанию today().

    Исключённая ИС (`excluded: true`) печатается статусом `SKIPPED` с причиной:
    в `check`/`start` она уже SKIPPED, и индекс не должен выглядеть так, будто
    она участвует в расчёте.
    """
    current = current or today()
    catalog = catalog or {}
    exclusions = exclusions or {}
    if any(entry.get("confluence_page_id") for entry in systems):
        _warn_missing_base_url(criteria, "ссылки INDEX.md")
    rows = []
    confirmed = 0
    overdue = 0
    with_passport = 0
    skipped = 0

    for entry in systems:
        code = entry.get("code", "")
        body = passport_body(root, entry)
        if body is not None:
            with_passport += 1
        excluded = code in exclusions

        criticality = effective(entry, body, "object_criticality_estimation") or entry.get(
            "criticality"
        )
        ssot = entry.get("criticality_ssot") or (
            dochub_to_ssot_map(criteria).get(criticality)
            if criteria is not None
            else None
        )
        assigned = effective(entry, body, "assigned_date")
        review_raw = effective_review_date(entry, body)
        status = entry.get("status") or "draft"
        months = review_period(catalog, entry, criteria)

        overdue_cell = "—"
        if excluded:
            skipped += 1
            status_cell = "SKIPPED — " + _exclusion_text(exclusions[code])
        else:
            status_cell = status
            if review_raw:
                try:
                    review_date = parse_date(review_raw)
                except ValueError:
                    review_date = None
                if review_date is not None:
                    if due_date(review_date, months) < current:
                        overdue_cell = "⚠️ да"
                        overdue += 1
                    else:
                        overdue_cell = "нет"
            if status == "confirmed":
                confirmed += 1

        page_id = entry.get("confluence_page_id")
        if page_id:
            code_url = _page_url(criteria, page_id)
            code_cell = f"[{code}]({code_url})" if code_url else f"{code} — {MISSING_MARK}"
        else:
            code_cell = code

        md_path = root / str(entry.get("path", "")) / "CRITICALITY.md"
        rel_md = f"{entry.get('path', '')}/CRITICALITY.md"
        passport_cell = f"[CRITICALITY.md]({rel_md})" if md_path.exists() else "— нет файла"

        # Предварительная оценка (R17): уровень есть, но вход не подтверждён —
        # индекс обязан это показать, иначе «Business critical» читается как факт.
        criticality_cell = _index_cell(criticality)
        if not excluded and _passport_provisional(root, entry):
            criticality_cell += " (предв.)"

        rows.append(
            "| {is_} | {contour} | {product} | {crit} | {ssot} | {team} | {assigned} "
            "| {review} | {overdue} | {status} | {passport} |".format(
                is_=code_cell,
                contour=_index_cell(entry.get("contour")),
                product=_index_cell(entry.get("product")),
                crit=criticality_cell,
                ssot=_index_cell(ssot),
                team=_index_cell(entry.get("team")),
                assigned=fmt_date(assigned),
                review=fmt_date(review_raw),
                overdue=overdue_cell,
                status=_index_cell(status_cell),
                passport=passport_cell,
            )
        )

    lines = [
        f"Сформировано: {current.isoformat()}. Всего ИС: {len(systems)}. "
        f"С паспортом: {with_passport}. Подтверждено: {confirmed}. Просрочено: {overdue}. "
        f"Исключено (SKIPPED): {skipped}.",
        "",
        "| ИС | Контур | Продукт | Критичность (dochub) | Критичность SSoT | Команда "
        "| assigned_date | review_date | Просрочено? | Статус | Паспорт |",
        "|----|--------|---------|----------------------|------------------|---------"
        "|---------------|-------------|-------------|--------|---------|",
    ]
    lines.extend(rows)
    lines.append("")
    lines.append(
        "Пометка `(предв.)` — оценка предварительная: вход закрыт явным отказом "
        "от данных (`status: waived`, R17), уровень посчитан по диапазону; "
        "подробности — в `CRITICALITY.md` этой ИС."
    )
    lines.append(
        "Статусы: `draft` — оценка не подтверждена SRE; `confirmed` — есть подтверждение "
        "(см. `approve_link` в паспорте); `SKIPPED` — ИС исключена из расчёта "
        "(`excluded: true`), причина указана рядом. «Просрочено?» считается по `due_date = "
        "review_date + период переоценки` (по умолчанию 12 месяцев, "
        "`review_period_months_default`; у ИС может быть переопределён полем "
        "`review_period_months`). `review_date` берётся из `catalog.yaml` "
        "(паспорт — копия)."
    )
    return "\n".join(lines)


def cmd_index(args) -> int:
    root = repo_root_from_args(args)
    try:
        current = (
            parse_date_arg(getattr(args, "date", None), "--date")
            if getattr(args, "date", None)
            else None
        )
    except ValueError as exc:
        print(f"ERROR: {exc}")
        return 1
    current = current or today()
    try:
        catalog, systems = load_catalog(root)
    except YamlError as exc:
        print(f"ERROR catalog.yaml: {exc}")
        return 1
    try:
        criteria = load_criteria()
    except YamlError as exc:
        print(f"WARN: критерии не прочитаны ({exc}) — ссылки будут {MISSING_MARK}")
        criteria = None

    block = build_index_block(
        root, systems, catalog, criteria,
        exclusions=_exclusions(root, systems),
        current=current,
    )

    if not args.write:
        print(block)
        return 0

    path = root / "INDEX.md"
    if path.exists():
        text = path.read_text(encoding="utf-8")
        begins = text.count(INDEX_BEGIN)
        ends = text.count(INDEX_END)
        if begins != ends:
            # Повреждённые маркеры: раньше блок дописывался вторым и старый
            # оставался. Файл не трогаем — пусть маркеры починят руками.
            print(
                "ERROR: INDEX.md: маркеры генерируемого блока повреждены "
                f"({INDEX_BEGIN}: {begins}, {INDEX_END}: {ends}) — файл не изменён. "
                "Восстановите парные маркеры и повторите make index."
            )
            return 1
        if begins:
            # Генерируемая область — от первого BEGIN до последнего END:
            # дубли от прошлых прогонов схлопываются в один блок.
            head = text.split(INDEX_BEGIN, 1)[0]
            tail = text.rsplit(INDEX_END, 1)[1]
            text = f"{head}{INDEX_BEGIN}\n{block}\n{INDEX_END}{tail}"
        else:
            text = text.rstrip() + f"\n\n{INDEX_BEGIN}\n{block}\n{INDEX_END}\n"
    else:
        text = (
            f"{_index_header(catalog, criteria, current)}\n"
            f"{INDEX_BEGIN}\n{block}\n{INDEX_END}\n"
        )

    _atomic_write(path, text)
    print(f"INDEX.md обновлён: {path}")
    print(f"ИС в таблице: {len(systems)}")
    _emit_next_steps(root, criteria, args)
    return 0


# ---------------------------------------------------------------------------
# next-step
# ---------------------------------------------------------------------------


def cmd_next_step(args) -> int:
    """Следующий шаг конвейера: одна ИС (--is) или все ИС проекта.

    Ровно та же логика, что в подсказке после каждой команды (`_emit_next_steps`
    → `next_step`), но вызывается явно: навигация по флоу одной командой
    `make next-step IS=<код>`.
    """
    root = repo_root_from_args(args)
    code = getattr(args, "is_", None)
    try:
        criteria = load_criteria()
    except YamlError as exc:
        print(f"ERROR: критерии не прочитаны: {exc}")
        return 1
    offline = bool(getattr(args, "no_clone", False)) or bool(
        os.environ.get("NO_CLONE")
    )
    try:
        state = collect_state(root, criteria, [code] if code else None, offline=offline)
    except (YamlError, OSError, KeyError, TypeError, ValueError) as exc:
        print(f"ERROR: состояние конвейера не прочитано: {exc}")
        return 1
    rows = state.get("rows") or []
    if code:
        row = rows[0] if rows else {}
        if not row:
            print(f"ERROR: ИС {code!r} нет в конвейере (is.yaml/catalog.yaml)")
            return 1
        if row.get("excluded"):
            print(f"{code}: SKIPPED — ИС исключена из расчёта")
            return 0
        line = _next_step_line(row)
        print(line if line else f"{code}: все этапы пройдены")
        return 0
    if not rows:
        step = project_next_step(root)
        if step:
            print(f"Следующий шаг: {step['command']} — {step['reason']}")
        else:
            print("Все этапы пройдены.")
        return 0
    pending = [
        (row["code"], _next_step_text(row))
        for row in rows
        if _next_step_text(row) is not None
    ]
    if not pending:
        print("Все этапы пройдены.")
        return 0
    print("Следующие шаги:")
    for row_code, text in pending:
        print(f"  {row_code}: {text}")
    return 0


# ---------------------------------------------------------------------------
# due
# ---------------------------------------------------------------------------


def cmd_due(args) -> int:
    root = repo_root_from_args(args)
    try:
        catalog, systems = load_catalog(root)
    except YamlError as exc:
        print(f"ERROR catalog.yaml: {exc}")
        return 1

    try:
        base = parse_date_arg(args.today, "--today") if args.today else today()
    except ValueError as exc:
        print(f"ERROR: {exc}")
        return 1

    try:
        criteria = load_criteria()
    except YamlError:
        criteria = None

    default_months = review_period(catalog, {}, criteria)
    forced_months = args.months

    overdue = []
    upcoming = []
    never = []

    for entry in systems:
        code = entry.get("code", "")
        body = passport_body(root, entry)
        months = (
            forced_months
            if forced_months is not None
            else review_period(catalog, entry, criteria)
        )
        raw = effective_review_date(entry, body)
        if not raw:
            hint = ""
            assigned_raw = effective(entry, body, "assigned_date")
            if assigned_raw:
                try:
                    hint = due_date(parse_date(assigned_raw), months).isoformat()
                except ValueError:
                    hint = f"некорректный assigned_date={assigned_raw!r}"
            never.append((code, entry.get("name") or "—", hint))
            continue
        try:
            review_date = parse_date(raw)
        except ValueError:
            never.append((code, entry.get("name") or "—", f"некорректная дата {raw!r}"))
            continue
        due = due_date(review_date, months)
        if due < base:
            overdue.append(
                (code, review_date.isoformat(), due.isoformat(), (base - due).days)
            )
        elif (due - base).days <= args.soon_days:
            upcoming.append(
                (code, review_date.isoformat(), due.isoformat(), (due - base).days)
            )

    print(
        f"Дата отсчёта: {base.isoformat()}. Период переоценки: "
        f"{forced_months if forced_months is not None else default_months} мес."
        f"{' (--months)' if forced_months is not None else ' (review_period_months_default)'}. "
        f"Горизонт «скоро»: {args.soon_days} дн."
    )
    print(
        "due_date = review_date + период (review_period_months системы, иначе "
        "review_period_months_default). Период — конвенция репозитория; процессом "
        "D6.1.1 календарный срок переоценки не задан."
    )
    print()

    print(f"## Просроченные (due_date < today) ({len(overdue)})")
    if overdue:
        print("| ИС | review_date | due_date | Просрочено дней |")
        print("|----|-------------|----------|-----------------|")
        for code, review, due, days in overdue:
            print(f"| {code} | {review} | {due} | {days} |")
    else:
        print("Нет.")
    print()

    print(
        f"## Ближайшие {args.soon_days} дн. "
        f"(today <= due_date <= today+{args.soon_days}) ({len(upcoming)})"
    )
    if upcoming:
        print("| ИС | review_date | due_date | Осталось дней |")
        print("|----|-------------|----------|---------------|")
        for code, review, due, days in upcoming:
            print(f"| {code} | {review} | {due} | {days} |")
    else:
        print("Нет.")
    print()

    print(f"## Не оценено (review_date пуст) ({len(never)})")
    if never:
        print("| ИС | Название | Ожидаемый due_date от assigned_date |")
        print("|----|----------|-------------------------------------|")
        for code, name, hint in never:
            print(f"| {code} | {name} | {hint or '—'} |")
    else:
        print("Нет.")
    print()
    print("Действия: make reassess IS=<код> → правка паспорта → make validate → MR с меткой criticality.")
    _emit_next_steps(root, None, args)
    return 0

