# scaffold
# ---------------------------------------------------------------------------

NAME_RE = re.compile(r"^[a-z0-9][a-z0-9-]*$")
CONTOUR_RE = re.compile(r"^[a-z0-9][a-z0-9-]*$")


def catalog_assets(systems):
    """контур -> подпись актива из catalog.yaml (данные проекта, не кода)."""
    result = {}
    for entry in systems or []:
        if not isinstance(entry, dict):
            continue
        contour = str(entry.get("contour") or "").strip()
        asset = str(entry.get("asset") or "").strip()
        if contour and asset and contour not in result:
            result[contour] = asset
    return result


# Контур → актив по умолчанию: документированное соответствие контуров и активов
# (docs/README.md: «Контур: `mm` (ММ) или `smkt` (СМКТ)»; enum актива —
# templates/catalog.yaml и docs/03-fields.md: ММ / СМКТ / СБЛ / СМ).
# Нужно только для ПЕРВОЙ ИС контура: пока в catalog.yaml нет ни одной записи
# этого контура с активом, catalog_assets() возвращает пусто.
CONTOUR_ASSET_DEFAULTS = {"mm": "ММ", "smkt": "СМКТ"}


CATALOG_FIELD_ORDER = [
    "name",
    "contour",
    "asset",
    "path",
    "product",
    "arch_code",
    "team",
    "sa",
    "criticality",
    "criticality_ssot",
    "extra_criteria",
    "criticality_source_page_id",
    "confluence_page_id",
    "architecture_page_id",
    "dr_page_id",
    "decision_log_page_id",
    "gitlab_group",
    "dochub_object",
    "assigned_date",
    "review_date",
    "status",
]


def _page_id_value(raw):
    """page_id из аргумента CLI: int для числового, иначе строка, None если пусто."""
    if raw is None:
        return None
    text = str(raw).strip()
    if not text:
        return None
    if _INT_RE.match(text):
        return int(text)
    return text


def _render_catalog_entry(entry: dict) -> str:
    lines = [f"  - code: {yaml_scalar(entry.get('code'))}"]
    for key in CATALOG_FIELD_ORDER:
        lines.append(f"    {key}: {yaml_scalar(entry.get(key))}")
    return "\n".join(lines)


def _append_catalog_entry(path: Path, entry: dict) -> None:
    """Дописать запись в конец блока systems:, сохранив остальное форматирование."""
    text = path.read_text(encoding="utf-8")
    lines = text.splitlines()
    start = None
    for index, line in enumerate(lines):
        if line.rstrip() == "systems:":
            start = index
            break
    if start is None:
        raise YamlError(f"{path}: не найдена секция 'systems:' на нулевом отступе")
    end = len(lines)
    for index in range(start + 1, len(lines)):
        line = lines[index]
        if line.strip() and not line.startswith((" ", "\t", "#")):
            end = index
            break
    insert_at = end
    while insert_at - 1 > start and not lines[insert_at - 1].strip():
        insert_at -= 1
    block = _render_catalog_entry(entry).splitlines()
    new_lines = lines[:insert_at] + [""] + block + lines[insert_at:]
    _atomic_write(path, "\n".join(new_lines).rstrip() + "\n")


def _append_is_entry(path: Path, code: str) -> bool:
    """Дописать код ИС в секцию `is:` файла is.yaml (идемпотентно).

    True — запись добавлена, False — код уже был (повтор не дублирует).
    Остальные строки, комментарии и порядок сохраняются: правится только
    блок `is:` на нулевом отступе. Секция должна существовать (её создаёт
    `make init` или сам `scaffold` из шаблона скилла).
    """
    text = path.read_text(encoding="utf-8")
    lines = text.splitlines()
    start = None
    for index, line in enumerate(lines):
        if not line.startswith("is:"):
            continue
        rest = line[len("is:"):].strip()
        if rest and not rest.startswith("#"):
            if rest not in ("[]", "{}"):
                raise YamlError(
                    f"{path}: секция 'is' задана не блоком ({rest!r}) — "
                    "приведите её к виду 'is:' со списком кодов"
                )
            # Пустая flow-запись `is: []` / `is: {}` → обычный блок.
            lines[index] = "is:"
            lines.insert(index + 1, f"  {code}:")
            _atomic_write(path, "\n".join(lines).rstrip() + "\n")
            return True
        start = index
        break
    if start is None:
        raise YamlError(f"{path}: не найдена секция 'is:' на нулевом отступе")
    end = len(lines)
    for index in range(start + 1, len(lines)):
        line = lines[index]
        if line.strip() and not line.startswith((" ", "\t", "#")):
            end = index
            break
    for index in range(start + 1, end):
        stripped = lines[index].strip()
        if not stripped or stripped.startswith("#"):
            continue
        key = stripped.split(":", 1)[0].strip()
        if key == code:
            return False
    insert_at = end
    while insert_at - 1 > start and not lines[insert_at - 1].strip():
        insert_at -= 1
    new_lines = lines[:insert_at] + [f"  {code}:"] + lines[insert_at:]
    _atomic_write(path, "\n".join(new_lines).rstrip() + "\n")
    return True


def cmd_scaffold(args) -> int:
    root = repo_root_from_args(args)
    contour = args.contour
    name = args.name

    if not CONTOUR_RE.match(contour):
        print(
            f"ERROR: контур {contour!r} должен быть латиницей в нижнем регистре "
            "(буквы, цифры, дефис)"
        )
        return 1
    if not NAME_RE.match(name):
        print(
            f"ERROR: имя ИС {name!r} должно быть латиницей в нижнем регистре "
            "(буквы, цифры, дефис)"
        )
        return 1

    catalog_path = root / CATALOG_FILE
    if not catalog_path.exists():
        # Курица-яйцо: scaffold требует реестр, но и первая ИС появляется здесь.
        # Пустой реестр создаётся из шаблона скилла (как в `make init`).
        template = project_template(CATALOG_FILE)
        if not template.exists():
            print(
                f"ERROR: нет {CATALOG_FILE} и нет шаблона {template} — "
                "выполните make init"
            )
            return 1
        _atomic_write(catalog_path, template.read_text(encoding="utf-8"))
        print(f"Создан пустой {CATALOG_FILE} из шаблона скилла (make init).")
    # is.yaml — второй реестр: по нему конвейер (check/prepare/start) выбирает
    # ИС. Без записи здесь созданная ИС невидима для конвейера, поэтому
    # scaffold синхронизирует оба файла.
    is_path = root / IS_CONFIG
    is_created = False
    if not is_path.exists():
        is_template = _is_example_path(root)
        if not is_template.exists():
            print(
                f"ERROR: нет {IS_CONFIG} и нет шаблона {is_template} — "
                "выполните make init"
            )
            return 1
        _atomic_write(is_path, is_template.read_text(encoding="utf-8"))
        is_created = True
        print(f"Создан {IS_CONFIG} из шаблона скилла (make init).")
    try:
        catalog, systems = load_catalog(root)
    except YamlError as exc:
        print(f"ERROR catalog.yaml: {exc}")
        return 1

    code = f"{name}.{contour}"
    by_code = catalog_by_code(systems)
    if code in by_code:
        print(f"ERROR: ИС {code!r} уже есть в catalog.yaml — scaffold не перезаписывает")
        return 1

    target = root / "is" / code
    if target.exists():
        print(f"ERROR: папка уже существует: {target}")
        return 1

    templates = SKILL_DIR / "templates"
    passport_tpl = templates / "criticality-passport.yaml"
    criticality_tpl = templates / "CRITICALITY.md"
    missing = [str(p) for p in (passport_tpl, criticality_tpl) if not p.exists()]
    if missing:
        print(f"ERROR: нет шаблонов: {', '.join(missing)}")
        return 1

    asset = getattr(args, "asset", None) or catalog_assets(systems).get(contour)
    if not asset:
        # Первая ИС контура: в реестре ещё нет записи с активом — берём
        # документированное соответствие контур → актив.
        asset = CONTOUR_ASSET_DEFAULTS.get(contour)
    product_code = catalog.get("product")
    if not product_code:
        print(
            "ERROR: catalog.yaml → product не задан (код продукта нужен для "
            "arch_code и записи реестра)"
        )
        return 1
    try:
        criteria = load_criteria()
    except YamlError as exc:
        print(f"ERROR: критерии не прочитаны: {exc}")
        return 1
    product_name = catalog.get("product_name")
    arch_code = args.arch_code or f"{product_code}.A<TODO>"
    team = args.team or "T<TODO>"
    page_id = _page_id_value(args.page_id)
    criticality_page_id = _page_id_value(args.criticality_page_id)
    dochub_object = f"sber.ecom.{contour}.criticality_passport.{name}"
    gitlab_group = _external_ref_pattern(
        criteria, "gitlab_group_base", {"contour": contour, "name": name}
    )
    if gitlab_group is None:
        _warn_missing_external_ref(
            "external_refs.gitlab_group_base", "ссылка на GitLab"
        )

    target.mkdir(parents=True, exist_ok=True)

    entry = {
        "code": code,
        "name": name,
        "contour": contour,
        "asset": asset,
        "path": f"is/{code}",
        "product": product_code,
        "arch_code": arch_code,
        "team": team,
        "sa": None,
        "criticality": None,
        "criticality_ssot": None,
        "extra_criteria": [],
        "criticality_source_page_id": criticality_page_id,
        "confluence_page_id": page_id,
        "dr_page_id": None,
        "decision_log_page_id": None,
        "gitlab_group": gitlab_group,
        "dochub_object": dochub_object,
        "assigned_date": None,
        "review_date": None,
        "status": "draft",
    }

    try:
        ctx = build_render_context(
            code, entry, {"components": []}, criteria, None, today(), catalog=catalog
        )
        ctx["passport"]["review_date"] = None
        ctx["identity"]["review_date"] = None
        passport_text = render_template_file(passport_tpl, ctx)
        criticality_text = _trim_frontmatter_gap(render_template_file(criticality_tpl, ctx))
    except (YamlError, TemplateError) as exc:
        print(f"ERROR: шаблоны не отрендерены: {exc}")
        return 1

    product_page = catalog.get("product_confluence_page_id")
    if product_page:
        product_link = _page_url(criteria, product_page) or MISSING_MARK
        _warn_missing_base_url(criteria, "ссылки README.md")
    else:
        product_link = MISSING_MARK
    is_link = _page_url(criteria, page_id) if page_id is not None else None
    if page_id is not None and is_link is None:
        _warn_missing_base_url(criteria, "ссылки README.md")
    readme_text = (
        "---\n"
        f"title: {code}\n"
        f'purpose: "Карточка ИС {code}: ссылки на Confluence, GitLab и паспорт критичности."\n'
        "audience: [ai-agent, human]\n"
        "read_when: [нужна страница ИС в Confluence, нужен GitLab-репозиторий ИС, переход к паспорту]\n"
        f"updated: {today().isoformat()}\n"
        "status: draft\n"
        "related: [CRITICALITY.md, criticality-passport.yaml, INFORMATION.yaml, ../../catalog.yaml]\n"
        f"source_confluence_product: {product_link}\n"
        "source_confluence_is: "
        f"{is_link or MISSING_MARK}\n"
        f"source_gitlab: {gitlab_group or MISSING_MARK}\n"
        "---\n"
        "\n"
        f"# {code}\n"
        "\n"
        f"Продукт: {product_code}"
        + (f" «{product_name}»" if product_name else "")
        + "\n"
        "\n"
        f"Паспорт критичности: [CRITICALITY.md](CRITICALITY.md) · "
        "реестр: [catalog.yaml](../../catalog.yaml)\n"
        "Заполнить: название ИС, arch code, команду, затем `make validate`.\n"
    )
    # Порядок записи: сначала реестры (catalog.yaml, is.yaml), потом файлы ИС.
    # Ошибка на любом шаге — откат: реестры возвращаются к прежнему тексту,
    # созданная папка удаляется. Иначе остаётся осиротевшая is/<код>/ без
    # записи в catalog.yaml или без записи в is.yaml (ИС невидима конвейеру).
    catalog_before = catalog_path.read_text(encoding="utf-8")
    is_before = is_path.read_text(encoding="utf-8")
    try:
        _append_catalog_entry(catalog_path, entry)
        is_added = _append_is_entry(is_path, code)
        target.mkdir(parents=True, exist_ok=True)
        _atomic_write(target / "criticality-passport.yaml", passport_text)
        _atomic_write(target / "CRITICALITY.md", criticality_text)
        _atomic_write(target / "README.md", readme_text)
    except (YamlError, OSError) as exc:
        _atomic_write(catalog_path, catalog_before)
        if is_created:
            try:
                is_path.unlink()
            except OSError:
                pass
        else:
            _atomic_write(is_path, is_before)
        shutil.rmtree(target, ignore_errors=True)
        print(f"ERROR: scaffold отменён ({type(exc).__name__}): {exc}")
        print(
            f"  откат: {CATALOG_FILE} и {IS_CONFIG} восстановлены, "
            f"{entry['path']}/ удалена"
        )
        return 1

    print(f"Создана ИС {code}:")
    print(f"  {target / 'README.md'}")
    print(f"  {target / 'criticality-passport.yaml'}")
    print(f"  {target / 'CRITICALITY.md'}")
    print("  catalog.yaml: добавлена запись в systems")
    if not asset:
        print(
            "  WARN: актив (asset) не определён — укажите ASSET=<ММ|СМКТ|СБЛ|СМ> "
            f"или заполните catalog.yaml → systems[{code}].asset вручную"
        )
    if is_added:
        print(f"  {IS_CONFIG}: добавлена запись is.{code}")
    else:
        print(f"  {IS_CONFIG}: запись is.{code} уже есть (не дублируется)")
    print()
    print("Дальше:")
    print(f"  1. заполнить название/arch code/команду в {entry['path']}/README.md")
    print("  2. заполнить 9 полей в criticality-passport.yaml")
    print(
        f"  3. проверить актив (asset: {asset or 'не определён'}) — "
        f"catalog.yaml → systems[{code}].asset (ММ / СМКТ / СБЛ / СМ)"
    )
    print("  4. make validate")
    _emit_next_steps(root, None, args, codes=[code], single=True)
    return 0


