class IncompleteError(Exception):
    """Расчёт невозможен: не хватает обязательных входных данных."""

    def __init__(self, missing, message=None):
        self.missing = list(missing)
        super().__init__(
            message
            or "не хватает обязательных критериев: " + ", ".join(self.missing)
        )


def criteria_path() -> Path:
    """Файл критериев принадлежит инструменту, а не проекту."""
    return SKILL_DIR / CRITERIA_REL


def _criteria_display_path() -> str:
    """Путь критериев для вывода: относительный от корня проекта, если внутри него.

    Абсолютный путь длиннее 100 символов и ломает ширину справки, поэтому
    печатаем `criteria/criticality-criteria.yaml` — так же, как в `источник:`.
    Если проекта нет (глобальная установка, запуск из /tmp), путь печатается
    абсолютным: относительный от произвольного cwd («opencode/clean/home1/…»)
    вводит в заблуждение.
    """
    path = criteria_path()
    try:
        root = resolve_project_root()
    except YamlError:
        return str(path)
    if path.is_relative_to(root):
        return path.relative_to(root).as_posix()
    return str(path)


def load_criteria():
    """Прочитать файл критериев. Бросает YamlError с понятным текстом."""
    path = criteria_path()
    if not path.exists():
        raise YamlError(f"{path}: файл критериев не найден (ожидался {CRITERIA_REL} в каталоге скилла)")
    data = load_yaml(path)
    if not isinstance(data, dict):
        raise YamlError(f"{path}: ожидался словарь верхнего уровня")
    return data


def _at(data, path):
    """Достать вложенное значение по пути из ключей."""
    current = data
    for key in path:
        if not isinstance(current, dict) or key not in current:
            return None
        current = current[key]
    return current


def _inherited_page(criteria, path):
    """page_id ближайшего родителя, у которого он задан."""
    for length in range(len(path) - 1, 0, -1):
        node = _at(criteria, path[:length])
        if isinstance(node, dict):
            page = node.get("page_id") or node.get("source_page_id")
            if page is not None:
                return page
    return None


def rule_info(criteria, path):
    """(kind, page_id, status) правила по пути; None, если правила нет."""
    node = _at(criteria, path)
    if not isinstance(node, dict):
        return None
    kind = node.get("kind")
    page = node.get("page_id") or node.get("source_page_id") or _inherited_page(criteria, path)
    return kind, page, node.get("status")


def level_order(criteria):
    levels = criteria.get("levels") or {}
    order = levels.get("order")
    if not isinstance(order, list) or not order:
        raise YamlError("критерии: levels.order пуст или не список")
    return [str(level) for level in order]


def level_rank(criteria):
    levels = criteria.get("levels") or {}
    rank = levels.get("rank") or {}
    return {str(key): int(value) for key, value in rank.items()}


def dochub_extra_level(criteria):
    """Дополнительный dochub-уровень (Mission critical+), если объявлен в критериях."""
    node = (criteria.get("levels") or {}).get("dochub_extra_level") or {}
    value = node.get("value") if isinstance(node, dict) else None
    return str(value) if value else None


def level_set(criteria):
    """Все уровни, которые может содержать паспорт: levels.order + dochub-уровень.

    Единственный источник — файл критериев. Списков уровней в коде нет: если
    уровень удалить из критериев, набор уменьшится сам.
    """
    result = list(level_order(criteria))
    extra = dochub_extra_level(criteria)
    if extra and extra not in result:
        result.append(extra)
    return result


def dochub_to_ssot_map(criteria):
    """Маппинг dochub → SSoT из criteria.levels.dochub_to_ssot.map."""
    node = (criteria.get("levels") or {}).get("dochub_to_ssot") or {}
    mapping = node.get("map") if isinstance(node, dict) else None
    if not isinstance(mapping, dict) or not mapping:
        raise YamlError("критерии: levels.dochub_to_ssot.map отсутствует")
    return {str(key): str(value) for key, value in mapping.items()}


def ssot_level_set(criteria):
    """Уровни SSoT — уникальные значения dochub_to_ssot.map."""
    return sorted(set(dochub_to_ssot_map(criteria).values()))


def max_level(criteria, values):
    """Максимальный уровень по rank из файла критериев."""
    rank = level_rank(criteria)
    known = [str(value) for value in values if value]
    if not known:
        raise IncompleteError(["levels"])
    unknown = [value for value in known if value not in rank]
    if unknown:
        raise YamlError(f"критерии: levels.rank не знает уровни {unknown}")
    return max(known, key=lambda value: rank[value])


def axis_items(criteria):
    items = (criteria.get("axes") or {}).get("items")
    if not isinstance(items, list) or not items:
        raise YamlError("критерии: axes.items пуст или не список")
    return [item for item in items if isinstance(item, dict)]


def axis_ids(criteria):
    return [str(item.get("id")) for item in axis_items(criteria)]


def time_bucket_columns(criteria):
    order = (criteria.get("time_buckets") or {}).get("order")
    if not isinstance(order, list) or not order:
        raise YamlError("критерии: time_buckets.order пуст или не список")
    return [str(bucket) for bucket in order]


def normalize_time_bucket(raw):
    """Привести время к канонической корзине: <1h / 1-12h / 12-24h / >24h.

    Принимает '<1h', '<1 часа', '1-12h', '12–24 ч', '>24h', '> 24 часов'.
    """
    text = str(raw).strip().lower()
    for dash in ("\u2013", "\u2014", "\u2212"):
        text = text.replace(dash, "-")
    text = re.sub(r"\s+", "", text)
    for word in ("часов", "часа", "час", "ч.", "ч", "hours", "hour", "h"):
        text = text.replace(word, "")
    aliases = {
        "<1": "<1h",
        "1-12": "1-12h",
        "12-24": "12-24h",
        ">24": ">24h",
    }
    if text in aliases:
        return aliases[text]
    raise ValueError(
        f"время {raw!r} не распознано; допустимо: <1h, 1-12h, 12-24h, >24h "
        "(или '<1 часа', '12-24 ч', '>24 часов')"
    )


def impact_level(criteria, score, bucket):
    """Уровень по impact_matrix: строка — max по осям, колонка — корзина времени."""
    cells = (criteria.get("impact_matrix") or {}).get("cells")
    if not isinstance(cells, dict):
        raise YamlError("критерии: impact_matrix.cells отсутствует")
    bucket = normalize_time_bucket(bucket)
    row = cells.get(str(score))
    if not isinstance(row, dict):
        raise YamlError(f"критерии: impact_matrix.cells[{score}] отсутствует")
    level = row.get(bucket)
    if level is None:
        raise YamlError(f"критерии: impact_matrix.cells[{score}][{bucket}] отсутствует")
    return str(level)


def parse_axes_arg(criteria, text):
    """'legal=3,economic=2,...' -> {axis_id: int 0..4}."""
    scores = {}
    for part in str(text).split(","):
        part = part.strip()
        if not part:
            continue
        if "=" not in part:
            raise ValueError(
                f"оценка оси {part!r} не в формате <ось>=<0..4>, например legal=3"
            )
        key, value = part.split("=", 1)
        key = key.strip()
        value = value.strip()
        if key not in axis_ids(criteria):
            raise ValueError(
                f"ось {key!r} не найдена; допустимо: {', '.join(axis_ids(criteria))}"
            )
        if not _INT_RE.match(value) or not 0 <= int(value) <= 4:
            raise ValueError(f"оценка оси {key!r} = {value!r} вне диапазона 0..4")
        scores[key] = int(value)
    if not scores:
        raise ValueError("не указано ни одной оценки оси")
    return scores


def cia_weights_hundredths(criteria):
    """Веса F(x) в сотых, чтобы арифметика была целочисленной и детерминированной."""
    weights = (criteria.get("cia") or {}).get("weights")
    if not isinstance(weights, dict):
        raise YamlError("критерии: cia.weights отсутствует")
    result = {}
    for level in ("low", "medium", "high"):
        value = weights.get(level)
        if value is None:
            raise YamlError(f"критерии: cia.weights.{level} отсутствует")
        result[level] = int(round(float(value) * 100))
    return result


def cia_thresholds(criteria):
    """Границы V уровней защищённости из criteria.cia.thresholds.

    Единственный источник чисел для рендера артефактов: шаблоны не содержат
    захардкоженных 2.8 / 5.6 / 8. Согласованность с
    cia.protection_levels.ranges проверяет `criteria check`.
    """
    node = (criteria.get("cia") or {}).get("thresholds")
    if not isinstance(node, dict):
        raise YamlError("критерии: cia.thresholds отсутствует")
    result = {}
    for key in ("low_upper", "medium_upper", "high_upper"):
        value = node.get(key)
        if value is None:
            raise YamlError(f"критерии: cia.thresholds.{key} отсутствует")
        try:
            result[key] = float(value)
        except (TypeError, ValueError):
            raise YamlError(
                f"критерии: cia.thresholds.{key} = {value!r} не число"
            )
    if not (
        result["low_upper"] < result["medium_upper"] < result["high_upper"]
    ):
        raise YamlError(
            "критерии: cia.thresholds должны возрастать "
            "low_upper < medium_upper < high_upper"
        )
    return result


def protection_scale_text(criteria):
    """Строка «Low <2.8 / Medium 2.8–5.6 / High 5.6–8 / Critical ≥8» из критериев."""
    thresholds = cia_thresholds(criteria)
    levels = [
        str(item.get("level"))
        for item in (
            ((criteria.get("cia") or {}).get("protection_levels") or {}).get("ranges")
            or []
        )
    ]
    if len(levels) != 4:
        raise YamlError(
            "критерии: cia.protection_levels.ranges должен содержать 4 уровня"
        )
    low, medium, high, critical = levels
    low_upper = _fmt_num(thresholds["low_upper"], 3)
    medium_upper = _fmt_num(thresholds["medium_upper"], 3)
    high_upper = _fmt_num(thresholds["high_upper"], 3)
    return (
        f"{low} <{low_upper} / {medium} {low_upper}–{medium_upper} / "
        f"{high} {medium_upper}–{high_upper} / {critical} ≥{high_upper}"
    )


def parse_cia_arg(criteria, text):
    """'c=high,i=medium,a=low' -> {'C': 'high', ...}."""
    levels = [str(level) for level in (criteria.get("cia") or {}).get("levels") or []]
    result = {}
    for part in str(text).split(","):
        part = part.strip()
        if not part:
            continue
        if "=" not in part:
            raise ValueError(
                f"оценка CIA {part!r} не в формате <C|I|A>=<{'|'.join(levels)}>"
            )
        key, value = part.split("=", 1)
        key = key.strip().upper()
        value = value.strip().lower()
        if key not in CIA_PARAMETERS:
            raise ValueError(f"параметр CIA {key!r} неизвестен (допустимо C, I, A)")
        if value not in levels:
            raise ValueError(
                f"уровень CIA {value!r} неизвестен (допустимо: {', '.join(levels)})"
            )
        result[key] = value
    if not result:
        raise ValueError("не указано ни одной оценки CIA")
    return result


def cia_value_hundredths(criteria, cia):
    """V = 6*(F(C)+F(I)+F(A)) в сотых долях."""
    weights = cia_weights_hundredths(criteria)
    missing = [parameter for parameter in CIA_PARAMETERS if parameter not in cia]
    if missing:
        raise IncompleteError([f"cia.{parameter}" for parameter in missing])
    total = sum(weights[cia[parameter]] for parameter in CIA_PARAMETERS)
    return 6 * total


def protection_level_from_hundredths(criteria, value):
    """Уровень защищённости по V (значение в сотых) из protection_levels.ranges."""
    ranges = ((criteria.get("cia") or {}).get("protection_levels") or {}).get("ranges")
    if not isinstance(ranges, list) or not ranges:
        raise YamlError("критерии: cia.protection_levels.ranges отсутствует")
    for item in ranges:
        low = item.get("min")
        high = item.get("max")
        if low is not None and value < int(round(float(low) * 100)):
            continue
        if high is not None:
            high_value = int(round(float(high) * 100))
            if item.get("max_inclusive"):
                if value > high_value:
                    continue
            elif value >= high_value:
                continue
        return str(item.get("level"))
    raise YamlError(f"критерии: для V={value / 100:.2f} не нашлось уровня защищённости")


def protection_level_from_value(criteria, value):
    return protection_level_from_hundredths(criteria, int(round(float(value) * 100)))


def protection_business_level(criteria, protection):
    mapping = ((criteria.get("cia") or {}).get("protection_to_level") or {}).get("map")
    if not isinstance(mapping, dict):
        raise YamlError("критерии: cia.protection_to_level.map отсутствует")
    level = mapping.get(protection)
    if level is None:
        raise YamlError(f"критерии: cia.protection_to_level.map не знает {protection!r}")
    return str(level)


def final_level(criteria, business, protection):
    cells = (criteria.get("final_matrix") or {}).get("cells")
    if not isinstance(cells, dict):
        raise YamlError("критерии: final_matrix.cells отсутствует")
    row = cells.get(business)
    if not isinstance(row, dict):
        raise YamlError(f"критерии: final_matrix.cells[{business!r}] отсутствует")
    level = row.get(protection)
    if level is None:
        raise YamlError(
            f"критерии: final_matrix.cells[{business!r}][{protection!r}] отсутствует"
        )
    return str(level)


def _express_block(criteria):
    block = criteria.get("express_method")
    if not isinstance(block, dict):
        raise YamlError("критерии: express_method отсутствует")
    return block


def _express_map(block, name):
    """Карта express_method.<name>.map; ключи канонизированы."""
    node = block.get(name)
    table = node.get("map") if isinstance(node, dict) else None
    if not isinstance(table, dict) or not table:
        raise YamlError(f"критерии: express_method.{name}.map отсутствует")
    return {_canon_text(key): value for key, value in table.items()}


def express_thresholds(criteria):
    """Пороги t по уровням последствий (баллы/час)."""
    block = _express_block(criteria)
    thresholds = block.get("thresholds")
    if not isinstance(thresholds, dict) or not thresholds:
        raise YamlError("критерии: express_method.thresholds отсутствует")
    result = {}
    for severity, value in thresholds.items():
        try:
            number = float(value)
        except (TypeError, ValueError):
            raise YamlError(
                f"критерии: express_method.thresholds[{severity!r}] = {value!r} не число"
            )
        if number <= 0:
            raise YamlError(
                f"критерии: express_method.thresholds[{severity!r}] = {value!r} должно быть > 0"
            )
        result[_canon_text(severity)] = number
    return result


def express_intervals(criteria):
    """Интервалы недоступности: [(index, lo, hi, label)]; hi = None — «до ∞»."""
    block = _express_block(criteria)
    node = block.get("intervals")
    items = node.get("items") if isinstance(node, dict) else None
    if not isinstance(items, list) or not items:
        raise YamlError("критерии: express_method.intervals.items отсутствует")
    result = []
    for position, item in enumerate(items):
        if not isinstance(item, dict):
            raise YamlError(
                f"критерии: express_method.intervals.items[{position}] не словарь"
            )
        index = item.get("index")
        lo = item.get("lo")
        hi = item.get("hi")
        if index is None or lo is None:
            raise YamlError(
                f"критерии: express_method.intervals.items[{position}]: нужны index и lo"
            )
        result.append(
            (
                int(index),
                float(lo),
                None if hi is None else float(hi),
                str(item.get("label") or f"{lo}-{hi}"),
            )
        )
    return result


def express_matrix(criteria):
    """Строки матрицы в порядке проверки: [(severity, [баллы по интервалам])]."""
    block = _express_block(criteria)
    node = block.get("matrix")
    rows = node.get("rows") if isinstance(node, dict) else None
    if not isinstance(rows, list) or not rows:
        raise YamlError("критерии: express_method.matrix.rows отсутствует")
    result = []
    for position, item in enumerate(rows):
        if not isinstance(item, dict):
            raise YamlError(f"критерии: express_method.matrix.rows[{position}] не словарь")
        severity = _canon_text(item.get("severity"))
        scores = item.get("scores")
        if not severity or not isinstance(scores, list) or not scores:
            raise YamlError(
                f"критерии: express_method.matrix.rows[{position}]: нужны severity и scores"
            )
        result.append((severity, [int(value) for value in scores]))
    return result


def express_score_to_level(criteria):
    """Балл (max по интервалам) -> уровень калькулятора (OP..MC+)."""
    table = _express_map(_express_block(criteria), "score_to_level")
    return {int(key): str(value) for key, value in table.items()}


def express_level_codes(criteria):
    """Код уровня калькулятора (OP..MC+) -> полный уровень levels.order."""
    table = _express_map(_express_block(criteria), "calculator_level_codes")
    return {str(key): str(value) for key, value in table.items()}


def express_calculator_level_to_ssot(criteria, calculator_level):
    """Код уровня калькулятора (OP..MC+) -> уровень SSoT/паспорта."""
    codes = express_level_codes(criteria)
    level = codes.get(str(calculator_level))
    if level is None:
        raise YamlError(
            f"критерии: express_method.calculator_level_codes.map не знает код "
            f"{calculator_level!r}"
        )
    mapping = (criteria.get("levels") or {}).get("dochub_to_ssot")
    table = mapping.get("map") if isinstance(mapping, dict) else None
    if not isinstance(table, dict):
        raise YamlError("критерии: levels.dochub_to_ssot.map отсутствует")
    ssot = table.get(str(level))
    if ssot is None:
        raise YamlError(
            f"критерии: levels.dochub_to_ssot.map не знает уровень {level!r}"
        )
    return str(ssot)


def _interval_index(intervals, value):
    """Индекс интервала, в который попадает t (проверка строго lo < t <= hi)."""
    for index, lo, hi, _label in intervals:
        if value > lo and (hi is None or value <= hi):
            return index
    return None


def express_score(criteria, load, consumers, impact, sla):
    """Экспресс-оценка по алгоритму калькулятора. Бросает IncompleteError.

    E = client_coefficients[consumers] × impact_coefficients[impact] × load
    t[severity] = thresholds[severity] / E × 60 + sla
    score[interval] = matrix[первая подходящая severity][interval]
    J = max(score); level = score_to_level[J] -> levels.dochub_to_ssot
    """
    missing = []
    if load in (None, ""):
        missing.append("peak_hour_load")
    if consumers in (None, ""):
        missing.append("consumers_type")
    if impact in (None, ""):
        missing.append("outage_impact")
    if sla in (None, ""):
        missing.append("object_sla")
    if missing:
        raise IncompleteError(missing)

    try:
        load_value = float(load)
    except (TypeError, ValueError):
        raise ValueError(f"нагрузка {load!r} не число")
    if load_value <= 0:
        raise IncompleteError(["peak_hour_load"])

    block = _express_block(criteria)
    clients = _express_map(block, "client_coefficients")
    impacts = _express_map(block, "impact_coefficients")
    categories = _express_map(block, "impact_categories")
    thresholds = express_thresholds(criteria)
    intervals = express_intervals(criteria)
    matrix = express_matrix(criteria)
    score_map = express_score_to_level(criteria)

    consumers_key = _canon_text(consumers)
    impact_key = _canon_text(impact)
    if consumers_key not in clients:
        raise ValueError(
            f"тип клиентов {consumers!r} не найден в express_method.client_coefficients.map"
        )
    if impact_key not in impacts:
        raise ValueError(
            f"влияние {impact!r} не найдено в express_method.impact_coefficients.map"
        )
    client_coef = float(clients[consumers_key])
    impact_coef = float(impacts[impact_key])

    digits = int((block.get("numerics") or {}).get("round_digits") or 9)
    sla_value = float(sla)
    if sla_value < 0:
        raise ValueError(f"object_sla {sla!r} не может быть отрицательным")
    energy = client_coef * impact_coef * load_value
    if energy <= 0:
        # Деление на E — единственное деление в формуле: нулевая энергия
        # (нулевая нагрузка или нулевой коэффициент) даёт ZeroDivisionError.
        raise ValueError(
            "E = коэф. типа × коэф. влияния × нагрузка должна быть > 0 "
            f"(получено {energy!r}); проверьте нагрузку и коэффициенты"
        )

    times = {}
    for severity, threshold in thresholds.items():
        times[severity] = round(threshold / energy * 60.0 + sla_value, digits)

    per_interval = []
    scores = []
    for index, lo, hi, label in intervals:
        score = 0
        hit = None
        for severity, row in matrix:
            value = times.get(severity)
            if value is None:
                raise YamlError(
                    f"критерии: express_method.thresholds не содержит {severity!r} "
                    "(нужен для строки матрицы)"
                )
            if value > lo and (hi is None or value <= hi):
                score = row[index]
                hit = severity
                break
        scores.append(score)
        per_interval.append(
            {"index": index, "label": label, "lo": lo, "hi": hi, "severity": hit, "score": score}
        )

    best = max(scores)
    if best <= 0:
        raise ValueError(
            "экспресс-оценка не определена: ни одно время наступления последствий "
            "не попало в интервал (проверьте интервалы express_method)"
        )
    interval_index = scores.index(best)
    calculator_level = score_map.get(best)
    if calculator_level is None:
        raise YamlError(
            f"критерии: express_method.score_to_level.map не знает балл {best}"
        )
    level = express_calculator_level_to_ssot(criteria, calculator_level)

    return {
        "E": energy,
        "t": times,
        "interval": interval_index,
        "interval_label": intervals[interval_index][3],
        "score": best,
        "consumers": consumers_key,
        "impact": impact_key,
        "calculator_level": calculator_level,
        "level": level,
        "trace": {
            "client_coef": client_coef,
            "impact_coef": impact_coef,
            "impact_category": categories.get(impact_key),
            "load": load_value,
            "sla": sla_value,
            "thresholds": thresholds,
            "times": times,
            "per_interval": per_interval,
            "round_digits": digits,
        },
    }


def compute_business(criteria, axes, time_bucket):
    """Детальная бизнес-часть: max по осям -> impact_matrix. Бросает IncompleteError."""
    missing = []
    if not isinstance(axes, dict) or not axes:
        missing.append("axes_scores")
    else:
        for axis in axis_ids(criteria):
            if axes.get(axis) is None:
                missing.append(f"axes_scores.{axis}")
    if time_bucket in (None, ""):
        missing.append("time_to_impact")
    if missing:
        raise IncompleteError(missing)
    bucket = normalize_time_bucket(time_bucket)
    maximum = max(int(value) for value in axes.values())
    return {
        "axes": {axis: int(axes[axis]) for axis in axis_ids(criteria)},
        "max": maximum,
        "bucket": bucket,
        "level": impact_level(criteria, maximum, bucket),
    }


def compute_cia(criteria, cia):
    """V и уровень защищённости. Бросает IncompleteError."""
    value = cia_value_hundredths(criteria, cia)
    protection = protection_level_from_hundredths(criteria, value)
    return {
        "cia": {parameter: cia[parameter] for parameter in CIA_PARAMETERS},
        "value": value,
        "value_display": f"{value / 100:.2f}",
        "protection": protection,
        "business": protection_business_level(criteria, protection),
    }


def compute_express(criteria, load, consumers, impact, sla):
    """Экспресс-оценка по алгоритму калькулятора. Бросает IncompleteError/ValueError."""
    return express_score(criteria, load, consumers, impact, sla)


def _express_record(value):
    return {"has_any": value not in (None, ""), "value": value}


def express_records(load, consumers, impact, sla):
    """Синтетические records для проверки отклонений от артефакта."""
    return {
        "peak_hour_load": _express_record(load),
        "consumers_type": _express_record(consumers),
        "outage_impact": _express_record(impact),
        "object_sla": _express_record(sla),
    }


def express_artifact_warnings(criteria, records):
    """Отклонения текущего экспресс-расчёта от артефакта-калькулятора (D4).

    Возвращает список человекочитаемых причин, по которым расчёт скилла
    расходится с xlsx. Пустой список — расхождений нет. Тексты отклонений
    живут в criteria.express_method.deviations_from_artifact; здесь только
    условия, при которых конкретное отклонение реально влияет на результат.
    """
    block = criteria.get("express_method")
    documented = (block or {}).get("deviations_from_artifact") or []
    if not documented:
        return []

    def value(name):
        record = records.get(name) or {}
        return record.get("value") if record.get("has_any") else None

    load = value("peak_hour_load")
    consumers = value("consumers_type")
    impact = value("outage_impact")
    sla = value("object_sla")
    warnings = []

    if sla in (None, ""):
        warnings.append(
            "SLA не задан: артефакт считает пустой SLA как 0, скилл требует "
            "значение (object_sla — blocking-вход; 0 — валидный норматив "
            "«простой недопустим»)"
        )
    if load in (None, "") or consumers in (None, "") or impact in (None, ""):
        warnings.append(
            "не заполнены нагрузка/тип клиентов/характер влияния: артефакт даёт "
            "E = 0 и уровень #N/A, скилл возвращает BLOCKED"
        )
    for name, raw in (("consumers_type", consumers), ("outage_impact", impact)):
        if isinstance(raw, str) and raw != _canon_text(raw):
            warnings.append(
                f"{name}: в артефакте значение записано с лишними пробелами, "
                "скилл сравнивает канонические значения"
            )
    if None not in (load, consumers, impact, sla):
        try:
            express = compute_express(criteria, load, consumers, impact, sla)
        except Exception:  # noqa: BLE001 - отклонение не должно ломать вывод
            express = None
        if express is not None:
            codes = express_level_codes(criteria)
            full_level = codes.get(str(express["calculator_level"]))
            extra = dochub_extra_level(criteria)
            if extra and full_level == extra and express["level"] != full_level:
                warnings.append(
                    f"уровень калькулятора {express['calculator_level']} ({full_level}) "
                    f"записан в паспорт как {express['level']} (levels.dochub_to_ssot)"
                )
    return warnings


def print_artifact_warnings(code, warnings, stream=None):
    """Печать WARN о расхождении с артефактом-калькулятором."""
    if not warnings:
        return
    out = stream or sys.stdout
    print(
        "WARN: расчёт разошёлся с артефактом-калькулятором"
        + (f" ({code})" if code else "")
        + ":",
        file=out,
    )
    for item in warnings:
        print(f"  - {item}", file=out)


def express_zero_sla_warning(result):
    """WARN при SLA = 0 или None — уровень не должен молча стать крайним.

    SLA = 0 — валидный норматив «простой недопустим»: калькулятор считает
    t = порог/E×60 + 0, поэтому уровень определяется самой ранней границей.
    Это законный, но крайний случай: расчёт обязан сказать об этом вслух.
    """
    trace = (result or {}).get("trace") or {}
    sla = trace.get("sla")
    if sla is None:
        return None
    try:
        sla_value = float(sla)
    except (TypeError, ValueError):
        return None
    if sla_value != 0.0:
        return None
    return (
        "SLA = 0: допустимый простой не задан (простой недопустим), время до "
        "последствий = t = порог/E×60 без добавки; уровень "
        f"{result.get('level')} определён по этой границе — подтвердите "
        "норматив у SRE"
    )


def gate_missing(criteria, present):
    """Список id обязательных критериев, которых нет в present (id -> bool)."""
    required = ((criteria.get("inputs") or {}).get("required")) or []
    missing = []
    for item in required:
        identifier = str(item.get("id")) if isinstance(item, dict) else str(item)
        if not present.get(identifier):
            missing.append(identifier)
    return missing


# --- вывод правил и результатов --------------------------------------------


def _print_rule_list(criteria, paths):
    print("Использованные правила:")
    for path in paths:
        name = ".".join(path)
        info = rule_info(criteria, path)
        if info is None:
            print(f"  {name} — НЕ НАЙДЕНО в файле критериев")
            continue
        kind, page, status = info
        node = _at(criteria, path)
        if kind == "documented":
            if page is not None:
                extra = f"page {page}"
            else:
                artifact = str(
                    (node.get("source_artifact") if isinstance(node, dict) else "") or ""
                )
                extra = f"артефакт {artifact}" if artifact else "источник не указан"
        elif kind == "convention":
            extra = f"status {status}" if status else "status не указан"
        else:
            extra = "kind не указан"
        print(f"  {name} — {kind} ({extra})")


def _print_conventions(criteria, paths):
    print("Convention-правила (не из источника, требуют подтверждения):")
    found = False
    for path in paths:
        info = rule_info(criteria, path)
        if info is None or info[0] != "convention":
            continue
        found = True
        name = ".".join(path)
        node = _at(criteria, path) or {}
        status = info[2] or "status не указан"
        print(f"  {name} — {status}")
        rationale = node.get("rationale")
        if rationale:
            print(f"    rationale: {rationale}")
    if not found:
        print("  нет")


def _print_levels(criteria, level):
    print(f"Уровень: {level}")
    rank = level_rank(criteria)
    if level in rank:
        print(f"Ранг: {rank[level]} из {len(rank)} (levels.rank)")


def _score_axes(criteria, args):
    axes = parse_axes_arg(criteria, args.axes)
    result = compute_business(criteria, axes, args.time)
    titles = {str(item.get("id")): str(item.get("title")) for item in axis_items(criteria)}

    print(f"Критерии: {criteria_path()} (schema_version {criteria.get('schema_version')})")
    print("Расчёт: детальный — оценки осей 0..4 -> impact_matrix")
    print()
    print("Оси (0..4):")
    for axis in axis_ids(criteria):
        print(f"  {axis} — {titles.get(axis, '')}: {result['axes'][axis]}")
    print(f"  max по осям: {result['max']}")
    print()
    definitions = (criteria.get("time_buckets") or {}).get("definitions") or {}
    print(
        f"Время до негативных последствий: {result['bucket']}"
        f" ({definitions.get(result['bucket'], '—')})"
    )
    print(f"Уровень по impact_matrix: {result['level']}")
    print()
    _print_levels(criteria, result["level"])
    print()
    _print_rule_list(
        criteria,
        [("axes",), ("time_buckets",), ("impact_matrix",), ("levels",)],
    )
    return 0


def _score_cia(criteria, args):
    cia = parse_cia_arg(criteria, args.cia)
    result = compute_cia(criteria, cia)
    weights = cia_weights_hundredths(criteria)

    print(f"Критерии: {criteria_path()} (schema_version {criteria.get('schema_version')})")
    print("Расчёт: ИБ-часть — V = 6*(F(C)+F(I)+F(A))")
    print()
    print("CIA:")
    terms = []
    for parameter in CIA_PARAMETERS:
        level = result["cia"][parameter]
        term = weights[level] / 100
        terms.append(f"{term:.2f}")
        print(f"  {parameter} = {level}  F = {term:.2f}")
    print(f"  V = 6*({' + '.join(terms)}) = {result['value_display']}")
    print()
    print(f"Уровень защищённости: {result['protection']}")
    print(f"Соответствует критичности: {result['business']}")
    print()
    _print_rule_list(
        criteria,
        [
            ("cia",),
            ("cia", "weights"),
            ("cia", "protection_levels"),
            ("cia", "protection_to_level"),
        ],
    )
    print()
    _print_conventions(
        criteria, [("cia", "protection_levels", "boundary_convention")]
    )
    print(
        "  Граница V = 8.0 трактуется как Critical (convention); "
        "источник задаёт только V > 8."
    )
    if args.business:
        print()
        total = final_level(criteria, args.business, result["protection"])
        print(f"Итог по final_matrix (бизнес {args.business} × ИБ {result['protection']}): {total}")
        print()
        _print_rule_list(criteria, [("final_matrix",), ("levels",)])
    return 0


def _score_final(criteria, args):
    business = str(args.business)
    protection = str(args.cia_level)
    rank = level_rank(criteria)
    if business not in rank:
        raise ValueError(
            f"бизнес-уровень {business!r} неизвестен (допустимо: {', '.join(level_order(criteria))})"
        )
    protections = [
        str(item.get("level"))
        for item in ((criteria.get("cia") or {}).get("protection_levels") or {}).get("ranges") or []
    ]
    if protection not in protections:
        raise ValueError(
            f"уровень защищённости {protection!r} неизвестен "
            f"(допустимо: {', '.join(protections)})"
        )
    total = final_level(criteria, business, protection)

    print(f"Критерии: {criteria_path()} (schema_version {criteria.get('schema_version')})")
    print("Расчёт: итоговая критичность по матрице final_matrix (бизнес-уровень × уровень защищённости)")
    print()
    print(f"Бизнес-уровень: {business} (ранг {rank[business]})")
    print(f"Уровень защищённости: {protection}")
    print(
        f"ИБ соответствует критичности: {protection_business_level(criteria, protection)}"
    )
    print(f"Итог по final_matrix: {total}")
    print()
    _print_levels(criteria, total)
    print()
    _print_rule_list(criteria, [("final_matrix",), ("cia", "protection_to_level"), ("levels",)])
    return 0


def _score_express(criteria, args):
    consumers_values = [
        str(value)
        for value in (((criteria.get("enum_selection") or {}).get("consumers_type") or {}).get("values") or [])
    ]
    if args.consumers is not None and _canon_text(args.consumers) not in [
        _canon_text(value) for value in consumers_values
    ]:
        raise ValueError(
            f"тип клиентов {args.consumers!r} не из enum_selection.consumers_type.values"
        )
    if args.workload is not None and int(args.workload) <= 0:
        raise ValueError("--workload должен быть целым числом > 0")

    result = express_score(
        criteria, args.workload, args.consumers, args.impact, args.sla
    )
    trace = result["trace"]

    print(f"Критерии: {criteria_path()} (schema_version {criteria.get('schema_version')})")
    print("Расчёт: экспресс — калькулятор критичности (express_method), статус: preliminary")
    print()
    print(f"Тип клиентов: {result['consumers']} (коэф. {_fmt_num(trace['client_coef'])})")
    print(
        f"Влияние при простое: {result['impact']} "
        f"(коэф. {_fmt_num(trace['impact_coef'])}, "
        f"{trace.get('impact_category') or '—'})"
    )
    print(f"Пиковая нагрузка: {_fmt_num(trace['load'])} клиентов/час")
    print(f"SLA: {_fmt_num(trace['sla'])} мин")
    print(f"E = коэф. типа × коэф. влияния × нагрузка: {_fmt_num(result['E'])} баллов/час")
    print()
    print("Время наступления последствий (t = порог/E×60 + SLA):")
    for severity in trace["thresholds"]:
        print(
            f"  {severity}: {_fmt_num(result['t'][severity], 3)} мин "
            f"(порог {_fmt_num(trace['thresholds'][severity])})"
        )
    print()
    print("Баллы по интервалам (матрица 4×6, первая подходящая severity):")
    for item in trace["per_interval"]:
        print(
            f"  #{item['index']} {item['label']}: "
            f"{item['severity'] or '—'} → {item['score']}"
        )
    print()
    print(f"Интервал последствий: #{result['interval']} {result['interval_label']}")
    print(f"Балл (max по интервалам): {result['score']}")
    print(
        f"Уровень калькулятора: {result['calculator_level']} → "
        f"уровень паспорта: {result['level']} (levels.dochub_to_ssot)"
    )
    print()
    _print_levels(criteria, result["level"])
    print()
    _print_rule_list(criteria, START_METHOD_RULES["express"])
    print()
    _print_conventions(criteria, CONVENTION_PATHS["express"])
    print()
    print("Статус: preliminary")
    validation = ((criteria.get("express_method") or {}).get("validation_required")) or ""
    print(f"Требует: {validation or 'подтверждения SRE'}")
    warnings = express_artifact_warnings(
        criteria,
        express_records(args.workload, args.consumers, args.impact, args.sla),
    )
    if warnings:
        print()
        print_artifact_warnings(None, warnings)
    zero_sla = express_zero_sla_warning(result)
    if zero_sla:
        print()
        print(f"WARN: {zero_sla}")
    return 0


# --- score --is -------------------------------------------------------------


def _dig(data, path):
    current = data
    for part in path.split("."):
        if not isinstance(current, dict) or part not in current:
            return None
        current = current[part]
    return current


def _has_value(value):
    if value is None:
        return False
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, (list, dict)):
        return bool(value)
    return True


# Маркеры «значения нет» в источнике: scaffold пишет `E001.A<TODO>` / `T<TODO>`,
# шаблоны рендерят `⛔ не заполнено`. Это не факт — в INFORMATION.yaml такое
# значение обязано остаться null (иначе плейсхолдер уезжает в паспорт).
PLACEHOLDER_RE = re.compile(r"<TODO>|⛔|^не заполнено$", re.IGNORECASE)


def _is_placeholder(value):
    """Плейсхолдер вместо значения (не факт): пустая строка, `<TODO>`, `⛔`."""
    if not isinstance(value, str):
        return False
    text = value.strip()
    if not text:
        return True
    return bool(PLACEHOLDER_RE.search(text))


def _fact_value(value):
    """Значение источника как факт: плейсхолдер (`E001.A<TODO>`, `⛔`) -> None."""
    return None if _is_placeholder(value) else value


INFORMATION_AXES = ("legal", "economic", "reputational", "client")
INFORMATION_CIA = (("C", "c"), ("I", "i"), ("A", "a"))


def _criteria_input_block(info):
    block = info.get("criteria_inputs") if isinstance(info, dict) else None
    return block if isinstance(block, dict) else {}


def _criteria_entry_value(identifier, entry):
    """(значение, есть ли оно) для одного входа из criteria_inputs."""
    if identifier == "axes_scores":
        axes = {axis: entry.get(axis) for axis in INFORMATION_AXES}
        return axes, all(value is not None for value in axes.values())
    if identifier == "cia":
        cia = {}
        for upper, lower in INFORMATION_CIA:
            value = entry.get(lower)
            if value is None:
                value = entry.get(upper)
            cia[upper] = value
        return cia, all(value is not None for value in cia.values())
    if identifier == "time_to_impact":
        value = entry.get("bucket")
        if value in (None, ""):
            value = entry.get("value")
        return value, _has_value(value)
    value = entry.get("value")
    return value, _has_value(value)


def _information_inputs(criteria, info):
    """(found, missing, derived) по обязательным критериям.

    found:   id -> (value, ref, status);
    missing: id без значения или со status: missing;
    derived: [(id, ref)] — значения со status: derived (нужно подтверждение).
    """
    required = ((criteria.get("inputs") or {}).get("required")) or []
    block = _criteria_input_block(info)
    found = {}
    missing = []
    derived = []
    for item in required:
        identifier = str(item.get("id")) if isinstance(item, dict) else str(item)
        entry = block.get(identifier)
        if isinstance(entry, dict):
            value, ok = _criteria_entry_value(identifier, entry)
            status = str(entry.get("status") or "").strip().lower()
            ref = f"criteria_inputs.{identifier}"
            if status == "missing" or not ok:
                missing.append(identifier)
                continue
            found[identifier] = (value, ref, status or "unset")
            if status == "derived":
                derived.append((identifier, ref))
            continue
        paths = INFORMATION_FIELD_PATHS.get(identifier, [identifier])
        value = None
        used = None
        for candidate in paths:
            candidate_value = _dig(info or {}, candidate)
            if _has_value(candidate_value):
                value = candidate_value
                used = candidate
                break
        if value is None:
            missing.append(identifier)
        else:
            found[identifier] = (value, used, "legacy")
    return found, missing, derived


def _score_is(root: Path, criteria, code):
    folder_rel, _legacy = is_layout(root, code)
    folder = root / folder_rel
    path = folder / INFORMATION_FILE
    rel = path.relative_to(root).as_posix() if path.is_relative_to(root) else str(path)

    print(f"ИС: {code}")
    print(f"Файл: {rel}")

    info = None
    if not path.exists():
        print("Статус файла: не найден")
    else:
        try:
            info = load_yaml(path)
            if not isinstance(info, dict):
                print("Статус файла: ожидался словарь верхнего уровня")
                info = None
            else:
                print("Статус файла: прочитан")
        except YamlError as exc:
            print(f"Статус файла: не разобран ({exc})")
            info = None

    gate = evaluate_gate(info or {}, criteria)
    records = gate["records"]
    print()

    present = {
        identifier: record
        for identifier, record in records.items()
        if record["has_any"]
    }
    if present:
        print("Провенанс входных данных:")
        for identifier, record in present.items():
            print(
                f"  {identifier} = {record['value']!r}  <- {rel}:{record['ref']} "
                f"(status: {record['status']})"
            )
        print()

    derived = [
        identifier
        for identifier, record in records.items()
        if record["status"] == "derived"
    ]
    if derived:
        print("Предупреждение: значения со status: derived требуют подтверждения:")
        for identifier in derived:
            print(f"  - {identifier} <- {rel}:{records[identifier]['ref']}")
        print()

    print(f"Сценарий (по данным): {gate['scenario_label']} — {gate['scenario_title']}")
    print(f"Метод (по гейту): {gate['method']}")
    print(
        "Blocking-входы: {filled}/{total}; advisory: {afilled}/{atotal}".format(
            filled=gate["blocking"]["filled"],
            total=gate["blocking"]["total"],
            afilled=gate["advisory"]["filled"],
            atotal=gate["advisory"]["total"],
        )
    )
    print()

    if gate["verdict"] != "OK":
        required = ((criteria.get("inputs") or {}).get("required")) or []
        by_id = {
            str(item.get("id")): item for item in required if isinstance(item, dict)
        }
        rule = rule_info(criteria, ("inputs", "gate")) or (None, None, None)
        print("Статус: incomplete")
        print(
            "Расчёт не выполняется: inputs.gate (documented"
            + (f", page {rule[1]}" if rule[1] else "")
            + ")."
        )
        print(f"Причина: {gate['reason']}")
        print(f"Не хватает blocking-входов ({len(gate['blocking']['missing'])}):")
        for identifier in gate["blocking"]["missing"]:
            item = by_id.get(identifier.split(".")[0]) or {}
            print(f"  - {identifier} — {item.get('description', '')}")
            hint = item.get("source_hint")
            if hint:
                print(f"      где взять: {hint}")
        print()
        if gate["advisory"]["missing"]:
            print(
                "WARN: не заполнено, требуется для полноты паспорта (не блокирует): "
                + ", ".join(gate["advisory"]["missing"])
            )
            print()
        print("Требуется: указать источник или значение для каждого blocking-критерия.")
        return 1

    print(f"Статус: {gate['method']} — complete/preliminary по выбранному методу")
    print()

    # Явный отказ от данных (R17): сначала диапазон, потом расчёт. Ошибка
    # диапазона — стоп: молча посчитать по одному значению значило бы выдать
    # отказ за подтверждённые данные.
    provisional = provisional_score(criteria, gate)
    if provisional.get("error"):
        print("ERROR: " + provisional["error"])
        print()
        print(
            "Расчёт не выполнен: подтвердите значения (status: confirmed) или "
            "задайте режим допущения waive.fallback.mode (R17)."
        )
        return 1
    compute_gate = gate
    if provisional.get("provisional"):
        records = dict(gate["records"])
        for identifier, value in (provisional.get("reported_values") or {}).items():
            records[identifier] = _waive_probe_record(criteria, identifier, value)
        compute_gate = dict(gate)
        compute_gate["records"] = records

    try:
        computed = _compute_for_method(criteria, compute_gate)
    except IncompleteError as exc:
        print("Статус: incomplete")
        print("Расчёт не выполнен: не хватает " + ", ".join(exc.missing))
        return 1
    except (KeyError, ValueError, TypeError, YamlError) as exc:
        print("Статус: incomplete")
        print(f"Расчёт не выполнен: {type(exc).__name__}: {exc}")
        return 1
    if provisional.get("provisional") and provisional.get("reported"):
        computed["final"] = provisional["reported"]
    business = computed["business"]
    protection = computed["cia"]["protection"] if computed["cia"] else None

    if business is not None:
        print("Бизнес-часть (детальный расчёт):")
        for axis in axis_ids(criteria):
            print(f"  {axis}: {business['axes'][axis]}")
        print(f"  max по осям: {business['max']}")
        print(f"  время: {business['bucket']}")
        print(f"  уровень: {business['level']}")
        print()

    if computed["cia"] is not None:
        cia_result = computed["cia"]
        print("ИБ-часть:")
        print(f"  V = {cia_result['value_display']}")
        print(f"  уровень защищённости: {protection}")
        print(f"  соответствует критичности: {cia_result['business']}")
        print()

    if computed["method"] == "express":
        express = computed["express"]
        trace = express["trace"]
        print("Экспресс-расчёт (калькулятор критичности, express_method):")
        print(f"  тип клиентов: {express['consumers']} (коэф. {_fmt_num(trace['client_coef'])})")
        print(
            f"  outage_impact: {express['impact']} "
            f"(коэф. {_fmt_num(trace['impact_coef'])})"
        )
        print(f"  peak_hour_load: {_fmt_num(trace['load'])} клиентов/час")
        print(f"  object_sla: {_fmt_num(trace['sla'])} мин")
        print(f"  E: {_fmt_num(express['E'])} баллов/час")
        for severity in trace["thresholds"]:
            print(f"  t «{severity}»: {_fmt_num(express['t'][severity], 3)} мин")
        print(
            f"  интервал: #{express['interval']} {express['interval_label']} "
            f"(score {express['score']})"
        )
        print(
            f"  уровень: {express['calculator_level']} → {express['level']} "
            f"(status: {computed['status']})"
        )
        print()

    if protection is not None and business is not None:
        print(f"Итог по final_matrix: {computed['final']}")
    elif business is not None:
        print(f"Итог (бизнес-часть): {business['level']}")
    elif protection is not None:
        print(f"Итог (ИБ-часть): {protection_business_level(criteria, protection)}")
    else:
        print(f"Итог (экспресс): {computed['final']}")
    if provisional.get("provisional"):
        print()
        _print_provisional(provisional)
    print()
    _print_rule_list(
        criteria,
        START_METHOD_RULES.get(computed["method"], []),
    )
    if computed["method"] == "express":
        warnings = express_artifact_warnings(criteria, gate["records"])
        if warnings:
            print()
            print_artifact_warnings(code, warnings)
    return 0


