GOLDEN_VECTORS_REL = "scripts/fixtures/express-golden-vectors.csv"


def _load_golden_vectors():
    """Золотые векторы экспресс-расчёта (см. scripts/fixtures/README.md)."""
    path = SKILL_DIR / GOLDEN_VECTORS_REL
    if not path.exists():
        raise YamlError(f"{path}: нет файла золотых векторов ({GOLDEN_VECTORS_REL})")
    with path.open(encoding="utf-8", newline="") as handle:
        rows = list(csv.DictReader(handle))
    if not rows:
        raise YamlError(f"{path}: файл золотых векторов пуст")
    return rows


