        expect("P15: локальная ветка создана без push",
               (rc, bool(first_sha)), (0, True))
        expect("P15: ветки нет на origin", ok_origin, False)
        rc, reuse_out = run_publish(
            apply=True, branch=reuse_branch, reuse_local=True
        )
        ok, reuse_sha = run_git(
            "git", "-C", str(dochub), "rev-parse", f"refs/heads/{reuse_branch}"
        )
