    # 15.1. review_staleness: просрочка — по due_date, а не по review_date.
    #      Границы: ровно период — ещё не просрочено, период + 1 день — да.
    staleness_entry = {"code": "x.mm", "review_date": "2026-11-12"}
    staleness_catalog = {"review_period_months_default": 12}
    staleness_criteria = {"staleness": {"review_period_months": 12}}
    expect(
        "staleness: следующий день после оценки — не просрочено",
        review_staleness(
            staleness_entry, None, staleness_catalog, staleness_criteria,
            reference=dt.date(2026, 11, 13),
        ),
        (dt.date(2026, 11, 12), dt.date(2027, 11, 12), False),
    )
    expect(
        "staleness: ровно период (due_date == reference) — не просрочено",
        review_staleness(
            staleness_entry, None, staleness_catalog, staleness_criteria,
            reference=dt.date(2027, 11, 12),
        ),
        (dt.date(2026, 11, 12), dt.date(2027, 11, 12), False),
    )
    expect(
        "staleness: период + 1 день — просрочено",
        review_staleness(
            staleness_entry, None, staleness_catalog, staleness_criteria,
            reference=dt.date(2027, 11, 13),
        ),
        (dt.date(2026, 11, 12), dt.date(2027, 11, 12), True),
    )
    expect(
        "staleness: период ИС переопределяет реестр (6 мес → просрочено раньше)",
        review_staleness(
            dict(staleness_entry, review_period_months=6), None,
            staleness_catalog, staleness_criteria,
            reference=dt.date(2027, 6, 1),
        )[2],
        True,
    )
    expect(
        "staleness: дата не зафиксирована — не просрочено",
        review_staleness({}, None, staleness_catalog, staleness_criteria),
        (None, None, False),
    )
    expect(
        "staleness: паспорт — запасной источник, если реестр пуст",
        review_staleness(
            {}, {"review_date": "2025-07-14"}, staleness_catalog,
            staleness_criteria, reference=dt.date(2026, 11, 13),
        )[2],
        True,
    )

    # 16. info: все секции рендерятся, значения — из файла критериев.
    def render_section(name, data):
        buffer = io.StringIO()
        with contextlib.redirect_stdout(buffer):
            INFO_RENDERERS[name](data)
        return buffer.getvalue()

    for name in INFO_SECTIONS:
        checks += 1
        try:
            text = render_section(name, criteria)
        except Exception as exc:  # noqa: BLE001 - диагностика самопроверки
            failures.append(
                f"info[{name}]: исключение {type(exc).__name__}: {exc}"
            )
            continue
        if not text.strip():
            failures.append(f"info[{name}]: пустой вывод")
        if "источник: " not in text:
            failures.append(f"info[{name}]: нет строки-источника")

    fixture = copy.deepcopy(criteria)
    original_express = render_section("express", criteria)
    fixture_express = render_section("express", fixture)
    expect(
        "info: подмена fixture не меняет оригинал",
        fixture_express == original_express,
        True,
    )
    checks += 1
    try:
        fixture["express_method"]["score_to_level"]["map"]["1"] = "2"
    except (KeyError, TypeError):
        failures.append("info: в критериях нет express_method.score_to_level.map")
    fixture_express = render_section("express", fixture)
    expect(
        "info: значения читаются из критериев (map['1'] → 2)",
        fixture_express != original_express,
        True,
    )
    changed_row = [
        line for line in fixture_express.splitlines() if line.startswith("| 1 ")
    ]
    original_row = [
        line for line in original_express.splitlines() if line.startswith("| 1 ")
    ]
    expect(
        "info: подмена score_to_level.map['1'] видна в таблице",
        changed_row != original_row,
        True,
    )

    without_section = copy.deepcopy(criteria)
    without_section.pop("service_lifecycle", None)
    absent_text = render_section("service_lifecycle", without_section)
    expect(
        "info: отсутствующая секция не роняет вывод",
        "секция отсутствует в критериях" in absent_text,
        True,
    )

    buffer = io.StringIO()
    with contextlib.redirect_stdout(buffer):
        info_rc = cmd_info(argparse.Namespace(section="nope", json=False))
    info_out = buffer.getvalue()
    expect("info --section: неверное имя → код 2", info_rc, 2)
    expect(
        "info --section: перечислены допустимые секции",
        "Допустимые: " + ", ".join(INFO_SECTIONS) in info_out,
        True,
    )

    buffer = io.StringIO()
    with contextlib.redirect_stdout(buffer):
        json_rc = cmd_info(argparse.Namespace(section="levels", json=True))
    json_out = buffer.getvalue()
    expect("info --json: код 0", json_rc, 0)
    checks += 1
    try:
        parsed = json.loads(json_out)
    except ValueError as exc:
        failures.append(f"info --json: невалидный JSON ({exc})")
    else:
        if not isinstance(parsed, dict) or "sections" not in parsed:
            failures.append("info --json: нет секции sections")
        if parsed.get("sections", {}).get("levels") is None:
            failures.append("info --json: секция levels пуста")

    # 17. help --no-state: работает без is.yaml и без обращения к данным.
    buffer = io.StringIO()
