        _atomic_write(pipeline_ssot / "roles.yaml", "roles:\n  - name: owner\n")

        def pipeline_next():
            rows = collect_state(pipeline_root, criteria, ["test.mm"])["rows"]
            step = next_step(rows[0]) if rows else None
            return step["command"] if step else None

        def run_quiet(func, args):
            buffer = io.StringIO()
            with contextlib.redirect_stdout(buffer):
                rc = func(args)
            return rc, buffer.getvalue()

        pipeline_common = {
            "is_": "test.mm",
            "no_next": True,
            "quiet": True,
            "root": str(pipeline_root),
            "path": None,
        }
        expect("pipeline: нет is.yaml — make init", pipeline_next(), "make init")
        run_quiet(cmd_init, argparse.Namespace(force=False, **pipeline_common))
        expect(
            "pipeline: init создал is.yaml",
            (pipeline_root / IS_CONFIG).exists(),
            True,
        )
        expect(
            "pipeline: после init шаг сменился",
            pipeline_next() == "make init",
            False,
        )
        expect(
            "pipeline: нет INFORMATION.yaml — make prepare-apply",
            pipeline_next(),
            "make prepare-apply",
        )
        run_quiet(cmd_prepare, prepare_args(root=str(pipeline_root)))
        expect(
            "pipeline: prepare-apply создал INFORMATION.yaml",
            (pipeline_folder / INFORMATION_FILE).exists(),
            True,
        )
        expect(
            "pipeline: после prepare шаг сменился",
            pipeline_next() == "make prepare-apply",
            False,
        )
        expect(
            "pipeline: BLOCKED — make collect-apply",
            pipeline_next(),
            "make collect-apply IS=test.mm",
        )
        run_quiet(
            cmd_collect,
            argparse.Namespace(apply=True, date=None, **pipeline_common),
        )
        expect(
            "pipeline: collect создал RESEARCH-PLAN.md",
            (pipeline_folder / RESEARCH_PLAN).exists(),
            True,
        )
        expect(
            "pipeline: после collect шаг сменился",
            pipeline_next() == "make collect-apply IS=test.mm",
            False,
        )
        expect(
            "pipeline: — make links-apply",
            pipeline_next(),
            "make links-apply IS=test.mm",
        )
        run_quiet(
            cmd_links,
            argparse.Namespace(
                apply=True,
                force=False,
                limit=LINK_DEFAULT_LIMIT,
                date=None,
                **pipeline_common,
            ),
        )
        expect(
            "pipeline: links создал LINK-MAP.yaml",
            (pipeline_folder / LINK_MAP_YAML).exists(),
            True,
        )
        expect(
            "pipeline: после links шаг сменился",
            pipeline_next() == "make links-apply IS=test.mm",
            False,
        )
        expect(
            "pipeline: — make sources-apply",
            pipeline_next(),
            "make sources-apply IS=test.mm",
        )
        _atomic_write(
            pipeline_folder / SOURCES_FINDINGS,
            "schema_version: 1\nis: test.mm\nfindings: []\nnot_found: []\n",
        )
        run_quiet(
            cmd_sources,
            argparse.Namespace(apply=True, date=None, **pipeline_common),
        )
        expect(
            "pipeline: после sources — пересчёт гейта (make check)",
            pipeline_next(),
            "make check IS=test.mm",
        )
        run_quiet(cmd_check, argparse.Namespace(date=None, **pipeline_common))
