DOCS_METHODOLOGY_REL = "docs/02-methodology.md"

# Человекочитаемая копия маршрутов сбора. Канон — criteria.inputs[].where;
# файл обязан это объявлять и не вводить page_id, которых нет в критериях.
DATA_SOURCES_REL = "references/data-sources.md"
DATA_SOURCES_SECTION = "## 1. Карта источников"

# §1.1 — зеркало чисел экспресс-метода (формула E/t, пороги, коэффициенты).
# Канон — criteria.express_method: копия обязана объявлять себя копией, иначе
# числа в документации читаются как первоисточник.
DATA_SOURCES_EXPRESS_SECTION = "## 1.1. Как значения превращаются в уровень (экспресс)"

# Блоки генерируемых таблиц. Идентификатор обязан совпадать с маркерами
# <!-- BEGIN GENERATED: <id> --> / <!-- END GENERATED: <id> --> в docs/02.
DOCS_BLOCK_NAMES = ("axes", "impact-matrix", "cia", "final-matrix")

_CIA_TITLES = {
    "C": "Конфиденциальность",
    "I": "Целостность",
    "A": "Доступность",
}


def _md_cell(value) -> str:
    """Значение для ячейки markdown-таблицы: без переводов строк и без '|'."""
    return (
        str(value)
        .replace("|", "\\|")
        .replace("\r\n", " ")
        .replace("\n", " ")
        .replace("\r", " ")
        .strip()
    )


def _format_number(value) -> str:
    """Число из критериев без хвостовых нулей: 8.0 -> 8, 0.10 -> 0.1."""
    number = float(value)
    if number == int(number):
        return str(int(number))
    return f"{number:.4f}".rstrip("0").rstrip(".")


def _md_table(header, rows) -> str:
    lines = [
        "| " + " | ".join(_md_cell(cell) for cell in header) + " |",
        "|" + "|".join("---" for _ in header) + "|",
    ]
    for row in rows:
        lines.append("| " + " | ".join(_md_cell(cell) for cell in row) + " |")
    return "\n".join(lines)


def _render_axes_block(criteria) -> str:
    """Шкала 0–4 по всем осям: строки — оценки, колонки — оси в порядке YAML."""
    items = axis_items(criteria)
    header = ["Оценка"] + [
        f"{item.get('title')} (`{item.get('id')}`)" for item in items
    ]
    rows = []
    for score in range(5):
        row = [score]
        for item in items:
            value = (item.get("scale") or {}).get(str(score))
            if value is None:
                raise YamlError(
                    f"критерии: axes.items[{item.get('id')}].scale[{score}] отсутствует"
                )
            row.append(value)
        rows.append(row)
    return _md_table(header, rows)


def _render_impact_matrix_block(criteria) -> str:
    """impact_matrix: строки — max по осям 0..4, колонки — корзины времени."""
    buckets = time_bucket_columns(criteria)
    cells = (criteria.get("impact_matrix") or {}).get("cells")
    if not isinstance(cells, dict):
        raise YamlError("критерии: impact_matrix.cells отсутствует")
    header = ["Оценка"] + [f"`{bucket}`" for bucket in buckets]
    rows = []
    for score in range(5):
        row = cells.get(str(score))
        if not isinstance(row, dict):
            raise YamlError(f"критерии: impact_matrix.cells[{score}] отсутствует")
        values = []
        for bucket in buckets:
            level = row.get(bucket)
            if level is None:
                raise YamlError(
                    f"критерии: impact_matrix.cells[{score}][{bucket}] отсутствует"
                )
            values.append(level)
        rows.append([score] + values)
    return _md_table(header, rows)


def _protection_range_text(item) -> str:
    """Диапазон V в человекочитаемом виде: '2.8 ≤ V < 5.6'."""
    low = item.get("min")
    high = item.get("max")
    inclusive = bool(item.get("max_inclusive"))
    low_text = None if low is None else _format_number(low)
    high_text = None if high is None else _format_number(high)
    if low_text is None and high_text is None:
        return "любое V"
    if low_text is None:
        return f"V ≤ {high_text}" if inclusive else f"V < {high_text}"
    if high_text is None:
        return f"V ≥ {low_text}"
    if inclusive:
        return f"{low_text} ≤ V ≤ {high_text}"
    return f"{low_text} ≤ V < {high_text}"


def _render_cia_block(criteria) -> str:
    """CIA: описания уровней + веса + границы уровня защищённости."""
    cia = criteria.get("cia") or {}
    levels = [str(level) for level in cia.get("levels") or []]
    parameters = [str(parameter) for parameter in cia.get("parameters") or []]
    descriptions = cia.get("descriptions") or {}
    if not levels or not parameters:
        raise YamlError("критерии: cia.levels/cia.parameters пусты")

    header = ["Уровень"] + [
        f"{_CIA_TITLES.get(parameter, parameter)} ({parameter})"
        for parameter in parameters
    ]
    rows = []
    for level in levels:
        row = [f"**{level}**"]
        for parameter in parameters:
            text = (descriptions.get(parameter) or {}).get(level)
            if text is None:
                raise YamlError(
                    f"критерии: cia.descriptions.{parameter}.{level} отсутствует"
                )
            row.append(text)
        rows.append(row)
    parts = [_md_table(header, rows)]

    weights = cia.get("weights") or {}
    weight_row = []
    for level in levels:
        value = weights.get(level)
        if value is None:
            raise YamlError(f"критерии: cia.weights.{level} отсутствует")
        weight_row.append(_format_number(value))
    parts.append(
        "Веса:\n\n" + _md_table([f"F({level})" for level in levels], [weight_row])
    )

    ranges = (cia.get("protection_levels") or {}).get("ranges") or []
    if not ranges:
        raise YamlError("критерии: cia.protection_levels.ranges отсутствует")
    range_rows = [
        [f"**{item.get('level')}**", _protection_range_text(item)] for item in ranges
    ]
    parts.append(
        "Уровень защищённости:\n\n" + _md_table(["Уровень", "Диапазон V"], range_rows)
    )
    return "\n\n".join(parts)


def _render_final_matrix_block(criteria) -> str:
    """final_matrix: соответствие уровню защищённости + матрица 4 × 4."""
    cia = criteria.get("cia") or {}
    ranges = (cia.get("protection_levels") or {}).get("ranges") or []
    if not ranges:
        raise YamlError("критерии: cia.protection_levels.ranges отсутствует")
    mapping = (cia.get("protection_to_level") or {}).get("map") or {}
    mapping_rows = []
    for item in ranges:
        protection = str(item.get("level"))
        level = mapping.get(protection)
        if level is None:
            raise YamlError(
                f"критерии: cia.protection_to_level.map[{protection}] отсутствует"
            )
        mapping_rows.append([f"**{protection}**", level])
    parts = [
        _md_table(["Уровень защищённости", "Соответствует критичности"], mapping_rows)
    ]

    cells = (criteria.get("final_matrix") or {}).get("cells")
    if not isinstance(cells, dict) or not cells:
        raise YamlError("критерии: final_matrix.cells отсутствует")
    business_order = [str(key) for key in cells]
    first_row = cells[business_order[0]]
    if not isinstance(first_row, dict) or not first_row:
        raise YamlError(f"критерии: final_matrix.cells[{business_order[0]!r}] пуст")
    protection_order = [str(key) for key in first_row]
    header = ["Бизнес-уровень \\ Защищённость"] + protection_order
    rows = []
    for business in business_order:
        row = cells.get(business)
        if not isinstance(row, dict):
            raise YamlError(f"критерии: final_matrix.cells[{business!r}] отсутствует")
        values = [f"**{business}**"]
        for protection in protection_order:
            level = row.get(protection)
            if level is None:
                raise YamlError(
                    f"критерии: final_matrix.cells[{business!r}][{protection!r}] отсутствует"
                )
            values.append(level)
        rows.append(values)
    parts.append("Итоговая матрица:\n\n" + _md_table(header, rows))
    return "\n\n".join(parts)


_DOCS_RENDERERS = {
    "axes": _render_axes_block,
    "impact-matrix": _render_impact_matrix_block,
    "cia": _render_cia_block,
    "final-matrix": _render_final_matrix_block,
}


def _docs_block_pattern(name: str):
    return re.compile(
        r"<!-- BEGIN GENERATED: " + re.escape(name) + r" -->\n"
        r"(.*?)"
        r"<!-- END GENERATED: " + re.escape(name) + r" -->",
        re.S,
    )


def _markdown_section(text, heading):
    """Тело markdown-раздела: от строки `heading` до следующего `## `."""
    lines = text.splitlines()
    start = None
    for index, line in enumerate(lines):
        if line.strip() == heading:
            start = index + 1
            break
    if start is None:
        return None
    body = []
    for line in lines[start:]:
        if line.startswith("## "):
            break
        body.append(line)
    return "\n".join(body)


def _data_sources_problems(criteria):
    """references/data-sources.md: канон маршрутов и page_id только из критериев.

    §1 обязан объявлять себя человекочитаемой копией `criteria.inputs[].where`
    (канон маршрутов — файл критериев, не эта страница), а каждый page_id в
    файле — существовать в `meta.sources` или `external_refs.refs`.
    """
    path = SKILL_DIR / DATA_SOURCES_REL
    if not path.exists():
        return [f"{DATA_SOURCES_REL}: файл не найден"]
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as exc:  # noqa: BLE001 - диагностика
        return [f"{DATA_SOURCES_REL}: не читается ({exc})"]
    problems = []
    section = _markdown_section(text, DATA_SOURCES_SECTION)
    if section is None:
        problems.append(f"{DATA_SOURCES_REL}: нет раздела «{DATA_SOURCES_SECTION}»")
    else:
        # Сравнение по схлопнутым пробелам: объявление может переноситься по
        # строкам markdown-цитаты, а её маркер «>» — попадать внутрь фразы.
        flat = " ".join(section.replace(">", " ").split())
        if "criteria.inputs" not in flat or "человекочитаемая копия" not in flat:
            problems.append(
                f"{DATA_SOURCES_REL} §1: нет объявления, что таблица — "
                "человекочитаемая копия criteria.inputs[].where"
            )
    # §1.1 воспроизводит числа экспресс-метода (E/t, пороги, коэффициенты).
    # Канон — criteria.express_method; копия обязана это объявлять, иначе
    # документация читается как первоисточник чисел.
    express_section = _markdown_section(text, DATA_SOURCES_EXPRESS_SECTION)
    if express_section is None:
        problems.append(
            f"{DATA_SOURCES_REL}: нет раздела «{DATA_SOURCES_EXPRESS_SECTION}»"
        )
    else:
        flat = " ".join(express_section.replace(">", " ").split()).lower()
        if "канон" not in flat or "express_method" not in flat or "копия" not in flat:
            problems.append(
                f"{DATA_SOURCES_REL} §1.1: нет пометки «копия для чтения; канон — "
                "criteria/criticality-criteria.yaml → express_method»"
            )
    known = _criteria_source_ids(criteria) | _external_ref_ids(criteria)
    for lineno, line in enumerate(text.splitlines(), 1):
        for match in PAGE_ID_LIKE_RE.finditer(line):
            page = match.group(0)
            if page not in known:
                problems.append(
                    f"{DATA_SOURCES_REL}:{lineno}: page_id {page} нет ни в "
                    "meta.sources, ни в external_refs.refs"
                )
    return problems


def _docs_methodology_path(root: Path):
    """`(путь, как показать)` файла методики: проект → каталог скилла.

    Первый найденный побеждает: в проекте файл — данные проекта, в скилле —
    поставляемый инструментом. `(None, None)` — нет нигде.
    """
    project = root / DOCS_METHODOLOGY_REL
    if project.exists():
        return project, f"{DOCS_METHODOLOGY_REL} (проект)"
    bundled = SKILL_DIR / DOCS_METHODOLOGY_REL
    if bundled.exists():
        return bundled, f"{DOCS_METHODOLOGY_REL} (скилл)"
    return None, None


def _sync_docs(root: Path, criteria, check_only: bool) -> int:
    """Перегенерировать таблицы docs/02 из критериев (или проверить их).

    Документация методики ищется в двух местах: сначала в проекте
    (`<root>/docs/02-methodology.md` — данные проекта), затем в каталоге скилла
    (`<SKILL_DIR>/docs/02-methodology.md` — файл поставляется вместе с
    инструментом). Раньше проверялся только проектный путь: в установленной
    раскладке файла там нет, гейт молча «пропускался» и рапортовал OK.
    """
    source_problems = _data_sources_problems(criteria)
    path, path_where = _docs_methodology_path(root)
    if path is None:
        print(
            f"WARN: {DOCS_METHODOLOGY_REL} не найден — проверка документации "
            "пропущена"
        )
        print(f"  ожидался один из путей: {root / DOCS_METHODOLOGY_REL}")
        print(f"                          {SKILL_DIR / DOCS_METHODOLOGY_REL}")
        print(f"Источники данных: {DATA_SOURCES_REL}")
        for problem in source_problems:
            print(f"ERROR: {problem}")
        if source_problems:
            print()
            print(f"Результат: FAIL ({len(source_problems)} нарушений)")
            return 1
        print("  канон маршрутов и page_id: OK")
        print("Результат: OK (проверка docs/02 пропущена)")
        return 0
    text = path.read_text(encoding="utf-8")
    updated = text
    changed = []
    problems = []

    for name in DOCS_BLOCK_NAMES:
        pattern = _docs_block_pattern(name)
        matches = list(pattern.finditer(updated))
        if not matches:
            problems.append(
                f"блок {name}: маркеры <!-- BEGIN/END GENERATED: {name} --> "
                f"не найдены в {path_where}"
            )
            continue
        if len(matches) > 1:
            problems.append(
                f"блок {name}: маркеры встречаются {len(matches)} раза, ожидался один"
            )
            continue
        match = matches[0]
        rendered = _DOCS_RENDERERS[name](criteria)
        if match.group(1).strip("\n") == rendered:
            continue
        changed.append(name)
        if not check_only:
            replacement = (
                f"<!-- BEGIN GENERATED: {name} -->\n"
                f"{rendered}\n"
                f"<!-- END GENERATED: {name} -->"
            )
            updated = updated[: match.start()] + replacement + updated[match.end():]

    problems.extend(source_problems)

    if problems:
        for problem in problems:
            print(f"ERROR: {problem}")
        print()
        print(f"Результат: FAIL ({len(problems)} нарушений)")
        return 1

    if check_only:
        print(f"Документация: {path_where}")
        for name in DOCS_BLOCK_NAMES:
            state = "ОТЛИЧАЕТСЯ" if name in changed else "OK"
            print(f"  блок {name}: {state}")
        print(f"Источники данных: {DATA_SOURCES_REL}")
        print("  канон маршрутов и page_id: OK")
        if changed:
            print()
            print(f"Результат: FAIL (расхождение с {criteria_path()})")
            return 1
        print("Результат: OK")
        return 0

    if updated != text:
        if path != root / DOCS_METHODOLOGY_REL:
            # Файл взят из каталога скилла (проектной копии нет): это
            # поставляемый инструмент, а не данные проекта. Писать в него
            # нельзя — иначе `docs-sync` молча правит установленный скилл.
            print(
                f"ERROR: {DOCS_METHODOLOGY_REL} найден только в каталоге скилла "
                f"({path}) — запись в него запрещена"
            )
            print(
                "  скопируйте файл в проект и повторите: "
                f"cp {path} {root / DOCS_METHODOLOGY_REL}"
            )
            print()
            print("Результат: FAIL (документация проекта отсутствует)")
            return 1
        _atomic_write(path, updated)
    print(f"Документация: {path_where}")
    if changed:
        for name in changed:
            print(f"  блок {name}: обновлён")
        print(f"Результат: OK (обновлено блоков: {len(changed)})")
    else:
        print("  все блоки совпадают с критериями")
        print("Результат: OK (изменений нет)")
    print(f"Источники данных: {DATA_SOURCES_REL}")
    print("  канон маршрутов и page_id: OK")
    return 0


def cmd_criteria(args) -> int:
    # Корень проекта нужен только sync-docs: он пишет docs/02-methodology.md
    # проекта. show и check читают файл критериев скилла, поэтому работают и на
    # чистой системе, где проекта ещё нет (SKIP подсказки шага, без ERROR).
    try:
        root = repo_root_from_args(args)
    except YamlError as exc:
        if args.criteria_command == "sync-docs":
            print(f"ERROR: {exc}")
            return 1
        root = None
    try:
        criteria = load_criteria()
    except YamlError as exc:
        print(f"ERROR: {exc}")
        return 1
    if args.criteria_command == "show":
        if args.json:
            print(json.dumps(criteria, ensure_ascii=False, indent=2, default=str))
        else:
            _show_criteria(criteria)
        if root is not None:
            _emit_next_steps(root, criteria, args)
        return 0
    if args.criteria_command == "sync-docs":
        rc = _sync_docs(root, criteria, bool(getattr(args, "check", False)))
        _emit_next_steps(root, criteria, args)
        return rc
    rc = _criteria_check(root, criteria)
    if root is not None:
        _emit_next_steps(root, criteria, args)
    return rc


# --- init: каркас проекта из шаблонов скилла --------------------------------

IS_CONFIG = "is.yaml"
IS_EXAMPLE = "is.example.yaml"
CATALOG_FILE = "catalog.yaml"
INDEX_FILE = "INDEX.md"
IS_DIR = "is"

# Каркас проекта, который создаёт `make init`: (файл проекта, шаблон скилла).
# Шаблоны лежат в скилле (templates/), а не в корне проекта: инструмент
# переносим, поэтому init работает в пустом каталоге.
PROJECT_TEMPLATES = (
    (IS_CONFIG, "is.example.yaml"),
    (CATALOG_FILE, "catalog.yaml"),
    (INDEX_FILE, "INDEX.md"),
)


def project_template(name: str) -> Path:
    """Путь к шаблону каркаса проекта: templates/<name> в каталоге скилла."""
    return SKILL_DIR / "templates" / name


def _is_example_path(root: Path) -> Path:
    """Шаблон is.yaml: свой в проекте (совместимость) либо шаблон скилла.

    В чистом проекте шаблона в корне нет — берётся `templates/is.example.yaml`
    рядом со скриптом, поэтому `init` работает сразу после переноса `.opencode/`.
    Проектный `is.example.yaml` (если он есть) остаётся приоритетным: в нём
    может лежать список ИС этого проекта.
    """
    local = root / IS_EXAMPLE
    if local.exists():
        return local
    return project_template(IS_EXAMPLE)


def cmd_init(args) -> int:
    """Создать каркас проекта: is.yaml, catalog.yaml, INDEX.md и папку is/.

    Существующие файлы не перезаписываются (кроме is.yaml с --force).
    В пустом каталоге (нет корня проекта) init работает в текущем каталоге —
    это единственная команда, которая проект создаёт.
    """
    try:
        root = repo_root_from_args(args)
    except YamlError:
        root = Path.cwd().resolve()
    force = bool(getattr(args, "force", False))
    created, skipped, missing = [], [], []
    extended = []

    for target_name, template_name in PROJECT_TEMPLATES:
        target = root / target_name
        if target.exists() and not (target_name == IS_CONFIG and force):
            skipped.append(target_name)
            continue
        template = (
            _is_example_path(root)
            if target_name == IS_CONFIG
            else project_template(template_name)
        )
        if not template.exists():
            missing.append(template_name)
            continue
        _atomic_write(target, template.read_text(encoding="utf-8"))
        created.append(target_name)

    is_folder = root / IS_DIR
    if is_folder.is_dir():
        skipped.append(IS_DIR + "/")
    else:
        is_folder.mkdir(parents=True, exist_ok=True)
        created.append(IS_DIR + "/")

    # .gitignore — часть каркаса: prepare-apply кладёт в корень проекта клоны
    # ssot/ и apps/ (~40 МБ чужого кода), и без .gitignore `git add -A` забрал
    # бы их в коммит. Существующий файл только дополняется (см. _ensure_gitignore).
    gitignore_action, gitignore_added = _ensure_gitignore(root)
    if gitignore_action == "created":
        created.append(GITIGNORE_FILE)
    elif gitignore_action == "extended":
        extended.append((GITIGNORE_FILE, gitignore_added))
    else:
        skipped.append(GITIGNORE_FILE)

    print(f"Каркас проекта: {root}")
    for name in created:
        print(f"  создан   {name}")
    for name in skipped:
        print(f"  пропущен {name} (уже существует)")
    for name, count in extended:
        print(f"  дополнен {name} ({count} записей)")
    for name in missing:
        print(f"  ERROR: нет шаблона {name} в {SKILL_DIR / 'templates'}")
    if missing:
        print()
        print("Каркас создан не полностью: восстановите шаблоны скилла.")
        return 1

    print()
    print("Дальше:")
    print("  1. заведите первую ИС:")
    print("       make scaffold IS=<name_is>.<mm|smkt>")
    print("     (создаёт папку is/<код>/, запись в catalog.yaml и код в is.yaml)")
    print(f"  2. заполните {IS_CONFIG} → ssot.url (адрес SSoT-репозитория)")
    print(f"  3. заполните {CATALOG_FILE}: product, product_name и поля записи systems")
    print("  4. make prepare        # план подготовки данных (dry-run)")
    print("  5. make prepare-apply  # сформировать INFORMATION.yaml и клонировать компоненты")
    print(
        f"  6. клоны {SSOT_DIR}/, {APPS_DIR}/, dochub/ и бэкапы уже в "
        f"{GITIGNORE_FILE} — в коммит они не попадут"
    )
    _emit_next_steps(root, None, args)
    return 0


