APPS_DIR = "apps"
# Доступность репозиториев (criteria.external_refs.repos) в prepare:
# git ls-remote с таймаутом 10 с. Недоступность — WARN, не ERROR.
# Самопроверка эту проверку выключает: selftest не зависит от сети/SSH-ключа.
REPO_LS_REMOTE_TIMEOUT = 10
REPO_REACHABILITY_ENABLED = True
