# Шесть файлов карточки ИС в SSoT (INFORMATION.md, раздел «Структура репозитория»).
SSOT_FILES = ("base", "components", "duty", "links", "resources", "roles")

# Допустимые переопределения в is.yaml (INFORMATION.md, «Структура файла is.yaml»).
IS_OVERRIDE_KEYS = ("product", "teamName", "excluded", "reason")

GIT_TIMEOUT = 120

# --- .gitignore: init создаёт/дополняет его вместе с каркасом ----------------
# prepare-apply клонирует SSoT (ssot/, ~40 МБ) и компоненты (apps/) прямо в
# корень проекта. Без .gitignore `git status` показывает `?? ssot/` и `?? apps/`,
# а `git add -A` закоммитил бы чужой код. Записи — данные, а не шаблон:
# существующий .gitignore не перезаписывается, дополняются только пропуски.
GITIGNORE_FILE = ".gitignore"
GITIGNORE_HEADER = (
    "# criticality-gen: локальные клоны и служебные данные (не коммитятся)"
)
GITIGNORE_ENTRIES = (
    GITIGNORE_HEADER,
    f"/{SSOT_DIR}/",
    f"/{APPS_DIR}/",
    "/dochub/",
    # Ссылки на MR, которые пишут publish --push / ssot --push: локальный
    # служебный кеш, в репозиторий не идёт.
    "/.dochub/",
    "is/*/*.bak-*",
    "# criticality-gen: журнал осознанного обхода гейта — аудит, не версионируется",
    "is/*/.gate-overrides.log",
    "# criticality-gen: временные артефакты атомарной записи",
    "*.new",
    "*.broken",
    "*.tmp",
    "*.bak*",
    "DATA-REQUIREMENTS.yaml.new",
    "DATA-REQUIREMENTS.yaml.broken",
    "# criticality-gen: кеш Python (импорт скрипта в тестах и отладке)",
    "__pycache__/",
    "*.pyc",
)


def _ensure_gitignore(root: Path):
    """Идемпотентно создать/дополнить .gitignore проекта: (action, added).

    action: `created` (файла не было) | `extended` (добавлено `added` строк) |
    `ok` (все записи уже есть). Сравнение — по строке без пробелов, поэтому
    повторный `make init` ничего не дублирует. Ошибка чтения/записи не валит
    init: каркас уже создан, .gitignore — вспомогательный артефакт.
    """
    path = root / GITIGNORE_FILE
    try:
        existing = path.read_text(encoding="utf-8") if path.exists() else None
    except OSError as exc:
        print(f"  WARN: {GITIGNORE_FILE} не прочитан: {exc}")
        return "ok", 0

    present = {line.strip() for line in (existing or "").splitlines()}
    missing = [entry for entry in GITIGNORE_ENTRIES if entry not in present]
    if existing is not None and not missing:
        return "ok", 0

    if existing is None:
        text = "\n".join(GITIGNORE_ENTRIES) + "\n"
        action = "created"
    else:
        # Новые записи отделяем пустой строкой от чужого содержимого.
        separator = ""
        if existing:
            separator = "\n" if existing.endswith("\n") else "\n\n"
        text = existing + separator + "\n".join(missing) + "\n"
        action = "extended"
    try:
        _atomic_write(path, text)
    except OSError as exc:
        print(f"  WARN: {GITIGNORE_FILE} не записан: {exc}")
        return "ok", 0
    return action, len(missing)


