# Статус E2E-процессов ИС (facts.e2e_status):
#   filled     — процессы перечислены в facts.e2e_processes;
#   not_filled — функциональная область Product scope ИС называет, но колонка
#                «Сквозной бизнес-процесс (e2e)» не заполнена (есть e2e_source_page);
#   not_found  — ни одна функциональная область Product scope не указывает ИС.
E2E_STATUSES = ("filled", "not_filled", "not_found")

# Основание ссылки на АДР в action-пакете (actions.adr_basis).
ADR_BASIS_LABELS = {
    "adr": "АДР",
    "architecture": "не найден → подставлена архитектура ИС",
    "is_page": "не найден → подставлена страница ИС",
    "none": "не найден — ссылки нет (⛔)",
}


def _e2e_source_text(source):
    """Источник E2E-процесса одной строкой (для CRITICALITY.md §4)."""
    if isinstance(source, dict):
        kind = str(source.get("type") or "").strip()
        ref = str(source.get("ref") or source.get("url") or "").strip()
        if kind and ref:
            return f"{kind}: {ref}"
        return kind or ref or None
    text = str(source or "").strip()
    return text or None


E2E_EVIDENCE_LABELS = {
    "direct": "прямое доказательство",
    "indirect": "косвенное доказательство",
}


def _e2e_evidence_text(value):
    """Машинная оценка доказательства -> человеческие слова для артефактов.

    `direct`/`indirect` — значения для RESEARCH.md/CANDIDATES.yaml; в паспорте,
    публикации и треде человек читает «прямое/косвенное доказательство».
    """
    text = str(value or "").strip()
    if not text:
        return None
    return E2E_EVIDENCE_LABELS.get(text.lower(), text)


def _e2e_archived(item, name=None):
    """Признак архивного процесса в `facts.e2e_processes`.

    Явное `archived: true` (пишет человек/`research`) или архивная пометка в
    заголовке («🪓 Архив процессов», «Архив BP…»). Проверка по предку страницы
    здесь невозможна — в `normalize` нет сети; оттуда архивность приходит уже
    флагом, а `research`/`ask` отбрасывают архивного кандидата по предку
    (`page_is_archived`).
    """
    if not isinstance(item, dict):
        return False
    marker = item.get("archived")
    if marker is True:
        return True
    if isinstance(marker, str) and marker.strip().lower() in ("true", "yes", "1", "да"):
        return True
    return title_is_archived(name or item.get("name"))


def normalize_e2e_process(item):
    """Запись E2E-процесса: строка (legacy) или словарь -> словарь.

    Обе формы допустимы (обратная совместимость): строка — «просто название»,
    словарь — `{name, page_id, impact, status, source: {type, ref}}`. `source` в
    результате — готовая строка для шаблона, `source_raw` — исходное значение
    (по нему собирается ссылка на источник). `name` при известном `page_id`
    берётся из кеша проверенных заголовков (R19).
    """
    if isinstance(item, dict):
        source = item.get("source")
        page_id = item.get("page_id")
        # Название процесса — ТОЛЬКО из проверенного кеша заголовков (R19):
        # вписанное руками имя страницы не сверено с Confluence и в публикацию
        # не попадает. Кеша нет — «[page <id>]» + URL, а не догадка.
        name = page_title_cached(page_id)
        if not name and page_id not in (None, ""):
            name = f"[page {page_id}]"
        if not name:
            name = item.get("name")
        archived = _e2e_archived(item, name)
        steps = item.get("steps")
        total_steps = item.get("total_steps")
        # Сила подтверждения одной строкой: «1 из 202». Шаблоны не умеют
        # арифметику/склейку, поэтому строка считается здесь.
        steps_label = None
        if steps not in (None, ""):
            steps_label = (
                f"{steps} из {total_steps}"
                if total_steps not in (None, "")
                else _tpl_stringify(steps)
            )
        evidence_raw = str(item.get("evidence") or "").strip() or None
        return {
            "name": name,
            "page_id": page_id,
            "url": item.get("url"),
            "impact": item.get("impact"),
            "status": item.get("status"),
            # В артефактах и в треде — человеческие слова, машинное значение
            # остаётся в `evidence_raw` (RESEARCH.md/CANDIDATES.yaml).
            "evidence": _e2e_evidence_text(evidence_raw),
            "evidence_raw": evidence_raw,
            "steps": steps,
            "total_steps": total_steps,
            "steps_label": steps_label,
            "archived": archived,
            "source": _e2e_source_text(source),
            "source_raw": source,
        }
    text = str(item if item is not None else "").strip()
    return {
        "name": text or None,
        "page_id": None,
        "url": None,
        "impact": None,
        "status": None,
        "evidence": None,
        "evidence_raw": None,
        "steps": None,
        "total_steps": None,
        "steps_label": None,
        "archived": title_is_archived(text),
        "source": None,
        "source_raw": None,
    }


def e2e_drop_archived_processes(value):
    """Список E2E-процессов без архивных записей: `(cleaned, [отброшенные])`.

    Применяется при приёме ответа на факт `e2e_processes`: архивный процесс не
    может попасть в паспорт через `ANSWERS.yaml`, даже если человек скопировал
    его из старого `CANDIDATES.yaml`.
    """
    kept, dropped = [], []
    for item in _as_list(value):
        if item in (None, ""):
            continue
        if _e2e_archived(item if isinstance(item, dict) else {"name": str(item)}):
            name = item.get("name") if isinstance(item, dict) else item
            dropped.append(str(name or item))
            continue
        kept.append(item)
    return kept, dropped


def _e2e_process_sort_key(process):
    """Порядок процессов по силе доказательства (детерминированный).

    Сначала процесс, где ИС участвует в большем числе шагов («20 из 91» весомее
    «1 из 202»), при равенстве — с меньшим общим числом шагов, затем по имени.
    Нет числа шагов — в конец: неизвестная сила не должна выглядеть сильной.
    """
    steps = process.get("steps")
    total = process.get("total_steps")
    steps_rank = -steps if isinstance(steps, int) and not isinstance(steps, bool) else 1
    total_rank = (
        total if isinstance(total, int) and not isinstance(total, bool) else 10**9
    )
    return (steps_rank, total_rank, str(process.get("name") or ""))


def e2e_processes_block(raw):
    """Нормализованный список E2E-процессов (строки legacy приводятся к словарю).

    Архивные процессы (`archived: true` или «Архив» в заголовке) отбрасываются:
    «🪓 Архив процессов» — история, а не действующий процесс. Отброшенное не
    теряется молча — `e2e_fact_warnings` даёт WARN на расхождение числа записей.
    Порядок — по силе доказательства (`_e2e_process_sort_key`), чтобы в паспорте
    и в треде процесс с 1 шагом из 202 не стоял выше процесса с 20 из 91.
    """
    processes = []
    for item in _as_list(raw):
        if item in (None, ""):
            continue
        process = normalize_e2e_process(item)
        if process.get("archived"):
            continue
        processes.append(process)
    return sorted(processes, key=_e2e_process_sort_key)


def e2e_source_page_block(raw):
    """facts.e2e_source_page — {page_id, title, url} или None (нет данных).

    `title` берётся ТОЛЬКО из кеша проверенных заголовков
    (`catalog.yaml → page_titles`, заполняет `verify-titles --fix`). Поле
    `title` в INFORMATION.yaml игнорируется: заголовок, вписанный руками, не
    сверен с Confluence и в артефакт не попадает (R19). Нет кеша — title None,
    шаблон печатает `[page <id>]` + url без названия.
    """
    if not isinstance(raw, dict):
        return None
    page_id = raw.get("page_id")
    title = page_title_cached(page_id)
    url = raw.get("url")
    if title and page_id not in (None, ""):
        link = f"«{title}» [{page_id}]" + (f" {url}" if url else "")
    elif page_id not in (None, ""):
        link = f"[page {page_id}]" + (f" {url}" if url else "")
    else:
        link = str(url or "").strip() or None
    page = {
        "page_id": page_id,
        "title": title,
        "url": url,
        "link": link,
    }
    if page["page_id"] in (None, "") and not page["url"]:
        return None
    return page


def e2e_status_value(raw):
    """facts.e2e_status: член E2E_STATUSES или None (неизвестное значение — WARN в validate)."""
    text = str(raw or "").strip().lower()
    return text if text in E2E_STATUSES else None


def e2e_fact_warnings(info):
    """WARN по `facts.e2e_status`: нормализация не должна терять проблему молча.

    Проверяются три случая: статус не задан при заполненных E2E-данных; статус
    записан, но не входит в E2E_STATUSES (значение приведено к None); статус
    `filled` при пустом `e2e_processes`. Ошибкой это не считается — паспорт
    остаётся валидным, но WARN требует внимания человека.
    """
    raw_facts = info.get("facts") if isinstance(info, dict) else None
    raw_facts = raw_facts if isinstance(raw_facts, dict) else {}
    raw = raw_facts.get("e2e_status")
    raw_text = "" if raw in (None, "") else str(raw).strip()
    normalized = e2e_status_value(raw)
    processes = e2e_processes_block(raw_facts.get("e2e_processes"))
    page = e2e_source_page_block(raw_facts.get("e2e_source_page"))
    warnings = []
    if raw_text and normalized is None:
        warnings.append(
            f"facts.e2e_status={raw!r} вне допустимого перечня "
            f"({', '.join(E2E_STATUSES)}) — значение не учтено"
        )
    if not raw_text and (processes or page):
        warnings.append(
            "facts.e2e_status не задан, хотя заполнены e2e_processes/"
            "e2e_source_page — статус E2E не зафиксирован"
        )
    if normalized == "filled" and not processes:
        warnings.append(
            "facts.e2e_status: filled, но e2e_processes пуст — статус "
            "противоречит данным"
        )
    raw_processes = [
        item for item in _as_list(raw_facts.get("e2e_processes")) if item not in (None, "")
    ]
    archived = len(raw_processes) - len(processes)
    if archived:
        warnings.append(
            f"facts.e2e_processes: {archived} архивных процессов отброшено — "
            "«🪓 Архив процессов» не является действующим процессом; удалите "
            "записи из INFORMATION.yaml (или поставьте archived: true осознанно)"
        )
    return warnings


def _as_list(value):
    return value if isinstance(value, list) else []


def facts_block(raw) -> dict:
    """Секция facts с гарантированной структурой (пустое — это [] / null)."""
    data = raw if isinstance(raw, dict) else {}
    dependencies = data.get("dependencies")
    if not isinstance(dependencies, dict):
        dependencies = {}
    support = data.get("support")
    if not isinstance(support, dict):
        support = {}
    return {
        "impact_chain": _as_list(data.get("impact_chain")),
        "e2e_processes": e2e_processes_block(data.get("e2e_processes")),
        "e2e_source_page": e2e_source_page_block(data.get("e2e_source_page")),
        "e2e_status": e2e_status_value(data.get("e2e_status")),
        "dependencies": {
            "upstream": _as_list(dependencies.get("upstream")),
            "downstream": _as_list(dependencies.get("downstream")),
        },
        "data_classification": _as_list(data.get("data_classification")),
        "risks": _as_list(data.get("risks")),
        "support": {
            "sla_incidents": support.get("sla_incidents"),
            "availability": support.get("availability"),
            "hours": support.get("hours"),
            "source": support.get("source"),
            "status": support.get("status") or "missing",
        },
        "adr": _as_list(data.get("adr")),
        "decision_log": data.get("decision_log"),
    }


def _load_template_skeleton() -> dict:
    """Скелет ручных секций из templates/INFORMATION.yaml (принадлежит инструменту)."""
    path = SKILL_DIR / INFORMATION_TEMPLATE
    if not path.exists():
        raise ConfigError(f"нет шаблона {INFORMATION_TEMPLATE}")
    try:
        data = parse_yaml(path.read_text(encoding="utf-8"), str(path))
    except YamlError as exc:
        raise ConfigError(f"{INFORMATION_TEMPLATE} не разобран: {exc}") from exc
    if not isinstance(data, dict):
        raise ConfigError(f"{INFORMATION_TEMPLATE}: ожидался словарь верхнего уровня")
    return data


def build_information(code, layout_rel, override, snapshot, missing, unreadable,
                      catalog_entry, ssot_url, skeleton, criteria=None, warnings=None,
                      contacts=None) -> dict:
    """Собрать документ INFORMATION.yaml (без ручных правок).

    Маппинг SSoT -> identity/components/resources/duties — в docs/09-pipeline.md
    (§4.3). Любое значение получает провенанс `{type, ref}`; значение без
    источника остаётся null, а не заполняется «похожим».
    """
    if warnings is None:
        warnings = []
    name, contour = split_is_code(code)
    base_doc = snapshot.get("base")
    if not isinstance(base_doc, dict):
        base_doc = {}
    other = base_doc.get("other")
    if not isinstance(other, dict):
        other = {}
    severity = base_doc.get("severity")
    if not isinstance(severity, dict):
        severity = {}
    catalog_entry = catalog_entry or {}
    base_ref = f"{SSOT_IS_ROOT}/{code}/base.yaml"

    title_ssot = _first_value(base_doc, ("title", "name", "fullName"))
    product_ssot, product_key = _first_pair(other, ("product",))
    product_ref = f"{base_ref}#other.{product_key}" if product_key else None
    if product_ssot is None:
        product_ssot, product_key = _first_pair(base_doc, ("product",))
        product_ref = f"{base_ref}#{product_key}" if product_key else None
    team_ssot, team_key = _first_pair(base_doc, ("team", "teamName", "team_name"))
    severity_raw = _first_value(severity, ("type",))
    criticality = normalize_ssot_severity(criteria, severity_raw)
    if severity_raw not in (None, "") and criticality is None:
        warnings.append(f"неизвестный severity.type: {severity_raw}")
    lifecycle = _first_value(base_doc, ("lifecycle",))
    is_type = _first_value(other, ("type",)) or _first_value(
        base_doc, ("type", "isType", "systemType")
    )
    type_ref = f"{base_ref}#other.type" if _first_value(other, ("type",)) else f"{base_ref}#type"

    # catalog.yaml может содержать плейсхолдеры scaffold (`E001.A<TODO>`,
    # `T<TODO>`, `⛔ не заполнено`). Это не значение: пишем null и источник null,
    # иначе плейсхолдер попадает в паспорт как факт.
    asset = _fact_value(catalog_entry.get("asset"))
    arch_code = _fact_value(catalog_entry.get("arch_code"))

    product_override = _fact_value(override.get("product"))
    team_override = _fact_value(override.get("teamName"))
    if _is_placeholder(product_ssot):
        product_ssot, product_ref = None, None
    if _is_placeholder(team_ssot):
        team_ssot, team_key = None, None

    product = _normalize_product(product_override or product_ssot)
    team = _normalize_team(team_override or team_ssot)

    identity = {
        "code": code,
        "name": title_ssot,
        "name_source": (
            {"type": "ssot", "ref": f"{base_ref}#title"}
            if title_ssot not in (None, "") else None
        ),
        "contour": contour,
        "asset": asset,
        "asset_source": (
            {"type": "catalog", "ref": f"catalog.yaml#systems.{code}.asset"}
            if asset not in (None, "") else None
        ),
        "type": is_type,
        "type_source": (
            {"type": "ssot", "ref": type_ref}
            if is_type not in (None, "") else None
        ),
        "status": _first_value(base_doc, ("status",)),
        "lifecycle": lifecycle,
        "lifecycle_source": (
            {"type": "ssot", "ref": f"{base_ref}#lifecycle"}
            if lifecycle not in (None, "") else None
        ),
        "product": product,
        "product_source": (
            {"type": "is_yaml_override", "ref": f"{IS_CONFIG}#is.{code}.product"}
            if product_override
            else (
                {"type": "ssot", "ref": product_ref}
                if product_ssot is not None else None
            )
        ),
        "team": team,
        "team_source": (
            {"type": "is_yaml_override", "ref": f"{IS_CONFIG}#is.{code}.teamName"}
            if team_override
            else (
                {"type": "ssot", "ref": f"{base_ref}#{team_key}"}
                if team_ssot is not None else None
            )
        ),
        "criticality_ssot": criticality,
        "criticality_source": (
            {"type": "ssot", "ref": f"{base_ref}#severity.type"}
            if criticality is not None else None
        ),
        "arch_code": arch_code,
        "arch_code_source": (
            {"type": "catalog", "ref": f"catalog.yaml#systems.{code}"}
            if arch_code is not None else None
        ),
    }

    sources = [
        {"type": "ssot", "ref": f"{SSOT_IS_ROOT}/{code}/{file_name}.yaml"}
        for file_name in SSOT_FILES
        if file_name in snapshot
    ]
    sources.append({"type": "is_yaml_override", "ref": f"{IS_CONFIG}#is.{code}"})

    meta = {
        "generated_by": "criticality-gen",
        "layout": layout_rel,
        "sources": sources,
        "ssot_url": ssot_url,
        "missing_sources": list(missing),
        "unreadable_sources": list(unreadable),
    }

    criteria_inputs = skeleton.get("criteria_inputs")
    if not isinstance(criteria_inputs, dict):
        criteria_inputs = {}

    return {
        "schema_version": 1,
        "is": code,
        "meta": meta,
        "identity": identity,
        # contacts — копия ростера команды из SSoT (make contacts). Пустой
        # словарь, если team.yaml не прочитан: prepare пишет WARN, а не падает.
        "contacts": contacts if isinstance(contacts, dict) else {},
        "components": extract_components(snapshot.get("components"), code),
        "resources": extract_resources(snapshot.get("resources"), code),
        "duties": extract_duties(snapshot.get("duty"), code),
        "links": _section_dict(snapshot.get("links"), "links"),
        "roles": _section_list(snapshot.get("roles"), "roles"),
        "ssot_snapshot": snapshot,
        "criteria_inputs": criteria_inputs,
        "facts": facts_block(skeleton.get("facts")),
        "conflicts": skeleton.get("conflicts") if isinstance(skeleton.get("conflicts"), list) else [],
        "notes": skeleton.get("notes") if isinstance(skeleton.get("notes"), list) else [],
    }


def merge_manual_sections(generated: dict, existing) -> dict:
    """Ручные секции из существующего файла переживают prepare."""
    if not isinstance(existing, dict):
        return generated
    merged = dict(generated)
    for section in MANUAL_SECTIONS:
        if section in existing:
            merged[section] = existing[section]
    return merged


# Автоматические секции INFORMATION.yaml и файл SSoT, из которого каждая
# собирается (docs/09-pipeline.md §4.3). Секция, отсутствующая в SSoT,
# сохраняется из прежней версии файла, а не превращается в пустую.
SSOT_SECTIONS = {
    "identity": "base",
    "components": "components",
    "resources": "resources",
    "duties": "duty",
    "links": "links",
    "roles": "roles",
}

# Ключ внутри файла SSoT, из которого берётся секция (None — файл целиком).
SSOT_SECTION_KEYS = {
    "identity": None,
    "components": "components",
    "resources": None,  # resources.yaml: любой ключ из RESOURCE_GROUPS
    "duties": ("onCallSchedule", "duties"),
    "links": "links",
    "roles": "roles",
}


def _ssot_section_present(snapshot, section) -> bool:
    """Есть ли секция в SSoT: файл прочитан и нужный ключ в нём есть."""
    file_key = SSOT_SECTIONS.get(section)
    if not file_key or file_key not in snapshot:
        return False
    doc = snapshot.get(file_key)
    if section == "identity":
        return isinstance(doc, dict) and bool(doc)
    if section == "resources":
        return isinstance(doc, dict) and any(
            key in doc for key, _kind in RESOURCE_GROUPS
        )
    keys = SSOT_SECTION_KEYS.get(section)
    if keys is None:
        return doc is not None
    if isinstance(keys, str):
        keys = (keys,)
    return isinstance(doc, dict) and any(key in doc for key in keys)


def _section_records(value) -> int:
    """Сколько записей в секции (для сообщения о сохранении/удалении)."""
    if value is None or value == "":
        return 0
    if isinstance(value, (list, tuple, dict)):
        return len(value)
    return 1


BACKUP_KEEP_DEFAULT = 10


def _backup_stamp(now=None) -> str:
    """Метка бэкапа: UTC `YYYYMMDDTHHMMSSZ` (не зависит от TZ, дефект N2)."""
    moment = now or dt.datetime.now(dt.timezone.utc)
    return moment.astimezone(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")


def _backup_serial(name: str, stem: str) -> int:
    """Порядковый номер бэкапа из суффикса `-N` (0 — без суффикса)."""
    rest = name[len(stem):]
    if "-" in rest:
        tail = rest.rsplit("-", 1)[1]
        if tail.isdigit():
            return int(tail)
    return 0


def _backup_path(path: Path) -> Path:
    """Свободное имя бэкапа: метка UTC + суффикс `-N` при коллизии в секунду."""
    stem = f"{path.name}.bak-"
    stamp = _backup_stamp()
    candidate = path.parent / f"{stem}{stamp}"
    index = 1
    while candidate.exists():
        candidate = path.parent / f"{stem}{stamp}-{index}"
        index += 1
    return candidate


def _rotate_backups(path: Path, keep: int = BACKUP_KEEP_DEFAULT) -> int:
    """Оставить `keep` последних бэкапов файла; вернуть число удалённых.

    Порядок — по mtime, затем по номеру суффикса: имена в одну секунду
    различаются только `-N`, лексикографическая сортировка их путает.
    """
    keep = max(int(keep), 1)
    stem = f"{path.name}.bak-"
    if not path.parent.is_dir():
        return 0
    items = [
        item
        for item in path.parent.iterdir()
        if item.is_file() and item.name.startswith(stem)
    ]
    if len(items) <= keep:
        return 0

    def sort_key(item):
        try:
            mtime = item.stat().st_mtime_ns
        except OSError:
            mtime = 0
        return (mtime, _backup_serial(item.name, stem))

    items.sort(key=sort_key)
    removed = 0
    for item in items[: len(items) - keep]:
        try:
            item.unlink()
            removed += 1
        except OSError:
            continue
    return removed


def _write_backup(path: Path, text: str, keep: int = BACKUP_KEEP_DEFAULT):
    """Записать бэкап файла и применить ротацию. Возвращает (имя, удалено)."""
    backup = _backup_path(path)
    _atomic_write(backup, text)
    return backup, _rotate_backups(path, keep)


def _top_level_span(lines, key):
    """(start, end) блока секции key верхнего уровня в списке строк."""
    start = None
    for index, line in enumerate(lines):
        if line.startswith(key + ":"):
            start = index
            break
    if start is None:
        return None
    end = len(lines)
    for index in range(start + 1, len(lines)):
        line = lines[index]
        if not line.strip() or line.startswith((" ", "\t", "#")):
            continue
        if re.match(r"^[A-Za-z_][A-Za-z0-9_]*:", line):
            end = index
            break
    return start, end


def splice_manual_sections(text: str, existing_text: str) -> str:
    """Перенести ручные секции из существующего файла в новый ДОСЛОВНО.

    Сохраняются комментарии, кавычки, порядок и форматирование ручных блоков:
    секция вырезается по маркеру начала и следующей секции верхнего уровня.
    """
    if not existing_text:
        return text
    lines = text.splitlines(True)
    old_lines = existing_text.splitlines(True)
    for section in MANUAL_SECTIONS:
        old_span = _top_level_span(old_lines, section)
        if old_span is None:
            continue
        new_span = _top_level_span(lines, section)
        if new_span is None:
            continue
        lines[new_span[0]:new_span[1]] = old_lines[old_span[0]:old_span[1]]
    return "".join(lines)


def _repo_reachability_lines(criteria, root: Path, ssot_url=None, catalog=None):
    """Строки статуса репозиториев: criteria.external_refs.repos, затем
    catalog.yaml → repos.<key>, затем is.yaml → ssot.url.

    Одна строка на репозиторий. Недоступность — WARN, не ERROR: prepare
    работает и офлайн, клон создаётся отдельной командой (`publish --clone`).
    """
    catalog_repos = (catalog or {}).get("repos")
    catalog_repos = catalog_repos if isinstance(catalog_repos, dict) else {}
    lines = []
    for key in ("dochub", "ssot"):
        url, branch, _note = _criteria_repo(criteria, key)
        if not url:
            item = catalog_repos.get(key)
            if isinstance(item, dict):
                url = str(item.get("url") or "").strip() or None
                branch = branch or (str(item.get("branch") or "").strip() or None)
        if key == "ssot" and not url:
            url = ssot_url
        if not url:
            continue
        command = ["git", "ls-remote", "--heads", url]
        if branch:
            command.append(branch)
        ok, output = _run_git(command, root, timeout=REPO_LS_REMOTE_TIMEOUT)
        if ok and (not branch or output.strip()):
            lines.append(f"  репозиторий {key}: OK — {url}")
        elif ok:
            lines.append(
                f"  WARN: репозиторий {key}: ветка {branch} не найдена — {url}"
            )
        else:
            lines.append(
                f"  WARN: репозиторий {key} недоступен: {url} — {output[:160]}"
            )
    return lines


def cmd_prepare(args) -> int:
    root = repo_root_from_args(args)
    apply = bool(args.apply)
    no_clone = bool(args.no_clone)
    force_overwrite = bool(getattr(args, "force_overwrite", False))
    allow_empty_sections = bool(getattr(args, "allow_empty_sections", False))
    no_backup = bool(getattr(args, "no_backup", False))
    backup_keep = getattr(args, "backup_keep", None)
    backup_keep = BACKUP_KEEP_DEFAULT if backup_keep is None else int(backup_keep)
    mode = "APPLY" if apply else "DRY-RUN"
    print(f"Подготовка данных ({mode}). Корень: {root}")
    print()

    try:
        config = load_is_config(root)
        skeleton = _load_template_skeleton()
        criteria = load_criteria()
    except (ConfigError, YamlError) as exc:
        print(f"ERROR: {exc}")
        return 1

    try:
        catalog_doc, systems = load_catalog(root)
        catalog_map = catalog_by_code(systems)
    except YamlError as exc:
        print(f"WARN: catalog.yaml не прочитан ({exc}) — arch_code не будет заполнен.")
        catalog_doc, catalog_map = {}, {}

    codes = list(config["codes"])
    if REPO_REACHABILITY_ENABLED:
        reachability = _repo_reachability_lines(
            criteria, root, config["ssot_url"], catalog_doc
        )
        for line in reachability:
            print(line)
        if reachability:
            print()
    if args.is_:
        if args.is_ not in config["overrides"]:
            # N6: код ищется в обоих источниках, подсказка ведёт к тому, где
            # его заводить; пустой INFORMATION.yaml не создаётся.
            print(f"ERROR: ИС {args.is_!r} нет в {IS_CONFIG} (список ИС проекта).")
            if args.is_ in catalog_map:
                print(
                    f"  В catalog.yaml ИС есть — добавьте её в секцию is: файла "
                    f"{IS_CONFIG}."
                )
            else:
                print(
                    f"  ИС нет ни в {IS_CONFIG}, ни в catalog.yaml — проверьте код. "
                    f"Новый проект: make init (создаст {IS_CONFIG} из "
                    "is.example.yaml), затем внесите ИС в catalog.yaml."
                )
            print(f"  Доступные: {', '.join(codes)}")
            return 1
        codes = [args.is_]

    # --- шаг 1: ssot/ ------------------------------------------------------
    # Без SSoT автоматические секции INFORMATION.yaml (components, resources,
    # duties, links, roles, identity) пусты. Писать файл в этом состоянии
    # нельзя: prepare --apply молча затёр бы данные ИС. Клонирование — только
    # в apply и без --no-clone.
    ssot_dir = root / SSOT_DIR
    ssot_url = config["ssot_url"]
    ssot_commands = []
    ssot_available = ssot_dir.is_dir() and any(ssot_dir.iterdir())
    if not ssot_available:
        if apply and not no_clone:
            if not ssot_url:
                print(f"ERROR: нет {SSOT_DIR}/ и не задан ssot.url в {IS_CONFIG}")
                return 1
            ssot_commands.append(["git", "clone", "--", ssot_url, SSOT_DIR])
        elif not no_clone:
            print(f"ERROR: нет {SSOT_DIR}/ — SSoT-репозиторий не склонирован.")
            if ssot_url:
                print(f"  выполните: git clone {ssot_url} {SSOT_DIR}")
            else:
                print(f"  укажите ssot.url в {IS_CONFIG} и выполните: git clone <url> {SSOT_DIR}")
        else:
            print(f"ERROR: нет {SSOT_DIR}/ (--no-clone: клон не создаётся).")
    elif apply and not no_clone:
        _prepare_clone_for_pull(root, SSOT_DIR, "ssot")
        ssot_commands.append(["git", "-C", SSOT_DIR, "pull", "--ff-only"])

    for command in ssot_commands:
        print(f"  $ {' '.join(command)}")
        if apply:
            ok, output = _run_git(command, root)
            if not ok:
                print(f"    WARN: {output}")
            else:
                print("    OK")
    ssot_available = ssot_dir.is_dir() and any(ssot_dir.iterdir())
    ssot_blocked = not ssot_available
    if ssot_blocked:
        print(
            "ERROR: prepare: нет клона SSoT (ssot/) — данные ИС не обновлены; "
            "выполните make prepare-apply после клонирования"
        )
    print()

    # --- architecture_page_id: ссылка на архитектуру ИС вместо АДР ----------
    # Поле заполняется из SSoT (links.yaml карточки ИС) один раз: непустое
    # значение — решение человека, prepare его не перезаписывает. Источник
    # значения — первая запись `type: page` (иначе первая ссылка на страницу
    # Confluence): архитектура ИС, а не АДР — это фиксирует adr_basis.
    architecture_fills = []
    for code in codes:
        entry = catalog_map.get(code) or {}
        if str(entry.get("architecture_page_id") or "").strip():
            continue
        if ssot_blocked:
            continue
        page_id, page_ref = ssot_page_link(root, code)
        if not page_id:
            print(
                f"WARN: {code}: architecture_page_id не найден в SSoT "
                f"({SSOT_IS_ROOT}/{code}/links.yaml — нет type: page) — остаётся "
                "null; в публикации будет подставлена страница ИС"
            )
            continue
        architecture_fills.append((code, page_id, page_ref))
        print(
            f"  {code}: catalog.yaml → architecture_page_id = {page_id} "
            f"({page_ref}){' — записано' if apply else ' — будет записано'}"
        )
        if apply and catalog_map:
            _set_catalog_entry_field(root, code, "architecture_page_id", page_id)

    # --- шаги 2-8: по каждой ИС -------------------------------------------
    rows = []
    clone_failures = []
    unreadable_notes = []
    prepare_errors = []
    invalid_repositories = []
    missing_ssot_codes = []
    preserved_notes = []
    removed_notes = []
    ssot_skips = []
    contacts_errors = []
    skip_lifecycles = _skip_lifecycles(criteria)
    skipped_lifecycles = 0
    for code in codes:
        override = config["overrides"][code]
        layout_rel, legacy = is_layout(root, code)
        identity_warnings = []
        if legacy:
            print(
                f"WARN: {code}: используется legacy-раскладка {layout_rel}/ "
                "(каноническая: is/<код ИС>)"
            )
        folder = root / layout_rel
        info_path = folder / INFORMATION_FILE

        if ssot_available:
            snapshot, missing, unreadable = read_ssot_files(root, code)
        else:
            snapshot, missing, unreadable = {}, [
                f"{SSOT_IS_ROOT}/{code}/{file_name}.yaml" for file_name in SSOT_FILES
            ], []

        ssot_code_dir = root / SSOT_IS_ROOT / code
        if ssot_available and not ssot_code_dir.is_dir():
            # N6: код есть в is.yaml/catalog.yaml, но карточки ИС в SSoT нет.
            # Пустой скелет (components: [], 0/6) маскировал бы опечатку в коде —
            # это ошибка, а не «ИС без данных».
            print(
                f"  {code}: ERROR: ИС {code} не найдена в SSoT "
                f"({INFORMATION_FILE} не создан)"
            )
            print(
                f"  {code}: ожидалась папка {SSOT_IS_ROOT}/{code}/ — "
                "проверьте код ИС в is.yaml и catalog.yaml "
                "(опечатка в коде даёт пустой скелет)"
            )
            missing_ssot_codes.append(code)
            rows.append(
                [
                    code,
                    layout_rel,
                    f"0/{len(SSOT_FILES)}",
                    0,
                    0,
                    "ERROR (нет в SSoT)",
                    "—",
                    0,
                    0,
                ]
            )
            continue

        # contacts — копия ростера команды (TA/TL/SRE). Отсутствие команды в
        # SSoT не блокирует prepare: блок остаётся пустым, печатается WARN.
        base_doc = snapshot.get("base") if isinstance(snapshot.get("base"), dict) else {}
        catalog_entry = catalog_map.get(code) or {}
        team_code = _normalize_team(
            override.get("teamName")
            or _first_value(base_doc, ("team", "teamName", "team_name"))
            or catalog_entry.get("team")
        )
        # catalog.yaml → systems[].team: команда, прочитанная из SSoT, должна
        # попасть в реестр. Иначе `contacts` (читает catalog) видит плейсхолдер
        # `T<TODO>` и падает, хотя INFORMATION.yaml уже заполнен.
        if (
            apply
            and team_code
            and _TEAM_CODE_RE.match(str(team_code).strip())
            and _normalize_team(catalog_entry.get("team")) != team_code
            and _set_catalog_entry_field(root, code, "team", team_code)
        ):
            catalog_entry["team"] = team_code
            print(f"  {code}: catalog.yaml → team = {team_code} — записано")
        contacts, contacts_problem = _load_team_contacts(root, team_code)
        contacts_failed = contacts is None
        if contacts_failed:
            print(
                f"  {code}: WARN: {contacts_problem['message']} — блок contacts "
                f"оставлен пустым; {contacts_problem['hint']}"
            )

        generated = build_information(
            code, layout_rel, override, snapshot, missing, unreadable,
            catalog_map.get(code), ssot_url, skeleton, criteria=criteria,
            warnings=identity_warnings, contacts=contacts,
        )
        for message in identity_warnings:
            print(f"  {code}: WARN {message}")
            unreadable_notes.append(f"{code}: {message}")

        cloned = 0
        skipped_lifecycle = 0
        invalid_for_code = False
        for component in generated["components"]:
            skipped, lifecycle = _component_skipped(component, skip_lifecycles)
            if skipped:
                # Закрытый сервис не клонируется: он выведен из эксплуатации и не
                # может быть основанием для входов критичности (criteria.service_lifecycle).
                skipped_lifecycle += 1
                skipped_lifecycles += 1
                print(
                    f"  {code}/{component.get('name')}: skip (lifecycle: {lifecycle}) — "
                    "не клонируется и не анализируется"
                )
                component["cloned_to"] = _component_target(code, component)
                component["clone_status"] = "not_cloned"
                continue
            plan = component_plan(root, code, component)
            if plan["action"] == "web_ui":
                # N3+: веб-страница репозитория (GitHub/GitLab `/tree/`, `/blob/`)
                # вместо URL клона. Это WARN, а не отказ: раньше такой URL
                # доходил до `git clone` и падал с кодом 128 — прогон
                # продолжался, поэтому и здесь он не блокирующий.
                print(f"  {code}/{component.get('name')}: WARN: {plan['problem']}")
                clone_failures.append(
                    {
                        "is": code,
                        "component": component.get("name"),
                        "target": plan["target"],
                        "error": plan["problem"],
                    }
                )
                component["cloned_to"] = plan["target"]
                component["clone_status"] = "error"
                continue
            if plan["action"] == "invalid":
                # N3: схема git_repository проверяется до любого git-вызова.
                invalid_for_code = True
                invalid_repositories.append(
                    f"{code}/{component.get('name')}: {plan['problem']}"
                )
                print(
                    f"  {code}/{component.get('name')}: ERROR: {plan['problem']}"
                )
                component["cloned_to"] = plan["target"]
                component["clone_status"] = "error"
                continue
            line = _component_plan_line(code, plan, apply, no_clone)
            if line:
                print(line)
            status, problem = apply_component_plan(root, plan, apply, no_clone)
            component["cloned_to"] = plan["target"]
            component["clone_status"] = status
            if status in ("cloned", "updated"):
                cloned += 1
            if problem:
                clone_failures.append(
                    {
                        "is": code,
                        "component": component.get("name"),
                        "target": plan["target"],
                        "error": problem,
                    }
                )
                print(f"  {code}: WARN: компонент {component.get('name')!r}: {problem}")

        existing = None
        existing_text = None
        parse_failed = False
        if info_path.exists():
            existing_text = info_path.read_text(encoding="utf-8")
            try:
                existing = load_yaml(info_path)
            except YamlError as exc:
                parse_failed = True
                existing = None
                print(
                    f"  {code}: ERROR: существующий {INFORMATION_FILE} не разобран ({exc})"
                )
                print(
                    f"  {code}: файл НЕ перезаписан — иначе ручные секции "
                    "(criteria_inputs, facts, conflicts, notes) будут потеряны."
                )
                print(
                    f"  {code}: исправьте YAML либо перезапишите осознанно: "
                    "--force-overwrite"
                )
        for item in unreadable:
            message = f"{item['ref']}: {item['error']}"
            print(f"  {code}: WARN {message}")
            unreadable_notes.append(f"{code}: {message}")

        if parse_failed and not force_overwrite:
            prepare_errors.append(code)
            rows.append(
                [
                    code,
                    layout_rel,
                    f"{len(snapshot)}/{len(SSOT_FILES)}",
                    len(generated["components"]),
                    cloned,
                    "ERROR (не перезаписан)",
                    "—",
                    0,
                    len(unreadable),
                ]
            )
            continue

        document = merge_manual_sections(generated, existing)
        absent_sections = [
            section
            for section in SSOT_SECTIONS
            if not _ssot_section_present(snapshot, section)
        ]
        preserved_sections = []
        removed_sections = []
        if existing is not None:
            for section in absent_sections:
                if section not in existing:
                    continue
                count = _section_records(existing.get(section))
                if allow_empty_sections:
                    if count:
                        removed_sections.append((section, count))
                else:
                    document[section] = existing[section]
                    preserved_sections.append((section, count))
        if contacts_failed and existing is not None:
            # Команда в SSoT не прочитана — прежние контакты не затираются:
            # иначе один прогон prepare без SSoT-команды обнулил бы упоминания.
            previous_contacts = _info_contacts(existing)
            if previous_contacts:
                document[CONTACTS_SECTION] = previous_contacts
                print(
                    f"  {code}: WARN: contacts сохранены из прежней версии "
                    f"{INFORMATION_FILE} ({len(_contacts_groups(previous_contacts))} групп)"
                )
                # Блок пишется только из team/source/groups: остальные ключи
                # прежней секции перенести некуда — о них предупреждаем.
                extra_contact_keys = sorted(
                    set(previous_contacts) - {"team", "source", "groups"}
                )
                if extra_contact_keys:
                    print(
                        f"  {code}: WARN: в сохранённых contacts есть ключи вне "
                        "team/source/groups — они не перенесены: "
                        + ", ".join(extra_contact_keys)
                    )
        text = INFORMATION_HEADER.format(code=code) + dump_yaml(document)
        text = _splice_contacts_section(
            text, _contacts_yaml_block(document.get(CONTACTS_SECTION))
        )
        if existing is not None:
            text = splice_manual_sections(text, existing_text)

        for section, count in preserved_sections:
            print(
                f"  {code}: WARN: секция {section} отсутствует в SSoT — "
                f"сохранена прежняя версия ({count} записей)"
            )
            preserved_notes.append(f"{code}: {section} ({count} записей)")
        for section, count in removed_sections:
            print(
                f"  {code}: секция {section} отсутствует в SSoT — "
                f"удалено записей: {count} (--allow-empty-sections)"
            )
            removed_notes.append(f"{code}: {section} ({count} записей)")
        if absent_sections and not preserved_sections and not removed_sections:
            print(
                f"  {code}: WARN: секции отсутствуют в SSoT, сохранять нечего: "
                + ", ".join(absent_sections)
            )

        state = "unchanged"
        if not info_path.exists():
            state = "created"
        elif existing_text != text:
            state = "updated"
        if invalid_for_code:
            # Схема git_repository недопустима — файл не пишем: данные ИС не
            # обновлены, ошибка возвращается кодом 1 (N3).
            state_label = "ERROR (схема git_repository)"
        elif ssot_blocked:
            # Нет SSoT — файл не пишется никогда: иначе автоматические секции
            # становятся пустыми (A1). Пишем только диагностику.
            state_label = "ERROR (нет SSoT)"
            ssot_skips.append(code)
        else:
            state_label = state if apply else f"{state} (dry-run)"
            if state != "unchanged" and apply:
                # Обратная проверка до записи: битый блок contacts сделал бы
                # INFORMATION.yaml неразбираемым, и следующий prepare получил бы
                # existing=None — splice_manual_sections потерял бы ручные
                # секции (criteria_inputs, facts). Не пишем вовсе.
                contacts_problem = _contacts_roundtrip_problem(
                    text, document.get(CONTACTS_SECTION), info_path
                )
                if contacts_problem is not None:
                    state_label = "ERROR (contacts)"
                    contacts_errors.append(code)
                    print(
                        f"  {code}: ERROR: блок contacts не прошёл обратную "
                        "проверку — файл не записан"
                    )
                    print(f"    причина: {contacts_problem}")
                else:
                    folder.mkdir(parents=True, exist_ok=True)
                    if existing_text is not None and not no_backup:
                        backup_path, removed_backups = _write_backup(
                            info_path, existing_text, backup_keep
                        )
                        print(f"  {code}: бэкап: {backup_path.name}")
                        if removed_backups:
                            print(
                                f"  {code}: удалено старых бэкапов: {removed_backups} "
                                f"(--backup-keep {backup_keep})"
                            )
                    _atomic_write(info_path, text)

        found, absent, warnings = _information_inputs(criteria, document)
        rows.append(
            [
                code,
                layout_rel,
                f"{len(snapshot)}/{len(SSOT_FILES)}",
                len(generated["components"]),
                cloned,
                state_label,
                f"{len(found)}/{len(found) + len(absent)}",
                len(warnings),
                len(unreadable),
            ]
        )

    print()
    _print_table(
        [
            "ИС", "раскладка", "SSoT (n/6)", "компонентов", "клонировано",
            INFORMATION_FILE, "критерии (n/m)", "derived", "unreadable",
        ],
        rows,
    )
    print()
    if apply:
        print(f"APPLY: обработано ИС — {len(rows)}.")
    else:
        print(
            "DRY-RUN: файлы не изменены, git-команды не выполнялись. "
            "Применить: prepare --apply"
        )
    if skipped_lifecycles:
        print(
            "Пропущено по lifecycle: "
            f"{skipped_lifecycles} (закрытые сервисы не клонируются — "
            f"criteria.{SERVICE_LIFECYCLE_SECTION})."
        )
    if unreadable_notes:
        print(f"WARN: нечитаемые SSoT-файлы — {len(unreadable_notes)}:")
        for note in unreadable_notes:
            print(f"  - {note}")
    if clone_failures:
        print(f"Ошибки клонирования: {len(clone_failures)} (прогон не прерван)")
        for failure in clone_failures:
            label = f"{failure['is']}/{failure['component']}"
            print(f"  - {label}: {failure['error']}")
    # Итог по компонентам одной строкой: ошибка клонирования одного сервиса не
    # должна растворяться в таблице прогона (дефект: `prepare` писал WARN и
    # «продолжал», а в итоге выглядел успешным).
    component_problems = len(clone_failures) + len(invalid_repositories)
    if component_problems:
        print(f"проблемы компонентов: {component_problems}")
        for failure in clone_failures:
            print(
                f"  - {failure['is']}/{failure['component']}: "
                f"{failure['error']}"
            )
        for item in invalid_repositories:
            print(f"  - {item}")
    if preserved_notes:
        print(
            f"Секции, сохранённые из-за отсутствия в SSoT: {len(preserved_notes)}"
        )
        for note in preserved_notes:
            print(f"  - {note}")
        if not apply:
            print(
                "DRY-RUN: эти секции остались бы прежними — пустыми их сделает "
                "только --allow-empty-sections."
            )
    if removed_notes:
        print(f"Секции, очищенные по --allow-empty-sections: {len(removed_notes)}")
        for note in removed_notes:
            print(f"  - {note}")
    if ssot_skips:
        print(
            "ERROR: prepare: нет клона SSoT (ssot/) — данные ИС не обновлены; "
            "выполните make prepare-apply после клонирования"
        )
        print(
            f"  файлы не записаны ({len(ssot_skips)}): " + ", ".join(ssot_skips)
        )
        return 1
    print(
        "Дальше: make check (гейт достаточности данных) -> "
        "make start (генерация артефактов)."
    )
    if prepare_errors:
        print(
            "ERROR: не перезаписаны неразобранные "
            f"{INFORMATION_FILE} ({len(prepare_errors)}): "
            + ", ".join(prepare_errors)
            + ". Исправьте YAML или запустите с --force-overwrite."
        )
        return 1
    if contacts_errors:
        print(
            "ERROR: блок contacts не прошёл обратную проверку — файлы не записаны "
            f"({len(contacts_errors)}): " + ", ".join(contacts_errors)
        )
        return 1
    if invalid_repositories:
        print(
            "ERROR: недопустимая схема git_repository "
            f"({len(invalid_repositories)}): git-команды не выполнялись."
        )
        for item in invalid_repositories:
            print(f"  - {item}")
        return 1
    if missing_ssot_codes:
        print(
            f"ERROR: ИС нет в SSoT ({len(missing_ssot_codes)}): "
            + ", ".join(missing_ssot_codes)
            + f" — {INFORMATION_FILE} не создан."
        )
        print(
            f"  Проверьте коды в {IS_CONFIG} и catalog.yaml, затем повторите: "
            "make prepare-apply"
        )
        return 1
    _emit_next_steps(root, None, args)
    return 0


def _write_contacts_section(info_path: Path, contacts) -> tuple:
    """Записать секцию contacts в INFORMATION.yaml: `(state, problem)`.

    Остальной файл не меняется: заменяется только блок contacts (вместе с его
    шапкой-комментарием). Перед записью результат разбирается мини-парсером —
    повреждённый файл не пишется (`state` = `error`, `problem` — причина).
    """
    text = info_path.read_text(encoding="utf-8")
    new_text = _splice_contacts_section(text, _contacts_yaml_block(contacts))
    problem = _contacts_roundtrip_problem(new_text, contacts, info_path)
    if problem is not None:
        return "error", f"{problem} — файл не изменён"
    if new_text == text:
        return "unchanged", None
    _atomic_write(info_path, new_text)
    return "updated", None


def cmd_contacts(args) -> int:
    """Контакты команды из SSoT: таблица, `--apply` (запись), `--json`.

    Источник — `ssot/entities/teams/<team>/team.yaml` (ключ `groups`): `name`
    группы — роль (`ta`, `tl`, `sa`, ...), `members[]` — логины. Соответствия
    login -> ФИО в SSoT нет, поэтому упоминание RocketChat — `@<login>`.
    Без `--apply` — dry-run: печатает блок, который был бы записан.
    """
    root = repo_root_from_args(args)
    json_mode = bool(getattr(args, "json", False))
    apply = bool(getattr(args, "apply", False))
    code = args.is_
    # В --json stdout принадлежит JSON: сообщения и WARN уходят в stderr.
    stream = sys.stderr if json_mode else sys.stdout

    def _fail(message, hint=None, rc=1):
        print(message, file=stream)
        if hint:
            print(f"  {hint}", file=stream)
        return rc

    try:
        _, systems = load_catalog(root)
    except YamlError as exc:
        return _fail(f"ERROR: {exc}")

    by_code = catalog_by_code(systems)
    entry = by_code.get(code)
    if entry is None:
        available = ", ".join(sorted(by_code)) or "—"
        return _fail(
            f"ERROR: ИС {code!r} нет в catalog.yaml — контакты не собраны.",
            f"Доступные ИС: {available}",
        )

    folder_rel, legacy = is_folder(root, code, entry)
    info_path = root / folder_rel / INFORMATION_FILE
    info = _load_info_file(root / folder_rel)
    identity_src = (
        info.get("identity")
        if isinstance(info, dict) and isinstance(info.get("identity"), dict)
        else {}
    )
    team_code = _normalize_team(
        _pick_team_code(entry.get("team"), identity_src.get("team"))
    )
    contacts, problem = _load_team_contacts(root, team_code)
    if problem is not None:
        return _fail(f"ERROR: {problem['message']}", f"подсказка: {problem['hint']}")

    groups = _contacts_groups(contacts)
    rejected = contacts.get("rejected") or []
    if rejected:
        print(
            "WARN  в team.yaml пропущены некорректные логины: "
            + ", ".join(_login_display(item) for item in rejected),
            file=stream,
        )
    ta = _contact_logins(groups, "ta")
    tl = _contact_logins(groups, "tl")
    for name in CONTACTS_MENTION_GROUPS:
        if not _contact_logins(groups, name):
            print(
                f"WARN  группа {name} пуста — контакт не будет отмечен",
                file=stream,
            )

    state = "dry-run"
    if apply:
        if not info_path.exists():
            return _fail(
                f"ERROR: нет {folder_rel}/{INFORMATION_FILE} — contacts некуда записать.",
                "соберите файл: make prepare-apply",
            )
        try:
            state, write_problem = _write_contacts_section(info_path, contacts)
        except (OSError, UnicodeDecodeError) as exc:
            return _fail(
                f"ERROR: {folder_rel}/{INFORMATION_FILE} не прочитан/не записан: {exc}"
            )
        if write_problem is not None:
            return _fail(
                f"ERROR: {folder_rel}/{INFORMATION_FILE}: {write_problem}",
                "проверьте файл вручную: contacts пишется отдельной секцией",
            )
        if state == "updated":
            print(
                f"WARN  обновлён {folder_rel}/{INFORMATION_FILE}: секция contacts "
                "перезаписана из SSoT",
                file=stream,
            )
        else:
            print(
                f"contacts без изменений — {folder_rel}/{INFORMATION_FILE} не тронут",
                file=stream,
            )

    if json_mode:
        payload = {
            "is": code,
            "team": contacts["team"],
            "source": contacts["source"],
            "groups": groups,
            "mentions": {
                "ta": _mentions(ta, stream),
                "tl": _mentions(tl, stream),
            },
        }
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        if apply:
            with contextlib.redirect_stdout(sys.stderr):
                _emit_next_steps(root, None, args, codes=[code], single=True)
        return 0

    mode = "APPLY" if apply else "DRY-RUN"
    print(f"Контакты команды ({mode}): {code}")
    if legacy:
        print(
            f"  WARN: используется legacy-раскладка {folder_rel}/ "
            "(каноническая: is/<код ИС>)"
        )
    print(f"  команда: {contacts['team']}")
    print(f"  источник: {contacts['source']['ref']}")
    print(f"  файл: {folder_rel}/{INFORMATION_FILE}")
    print()
    _print_table(
        ["группа", "логины", "упоминания"],
        [
            [
                name,
                ", ".join(groups[name]) or "—",
                ", ".join(_mentions(groups[name], stream)) or "—",
            ]
            for name in groups
        ],
    )
    print()
    for name, logins in (("ta", ta), ("tl", tl)):
        label = "Технический архитектор (ta)" if name == "ta" else "TL (tl)"
        print(f"  {label}: {_mention_text(logins, stream) or '— (группа пуста)'}")
    print()
    if apply:
        if state == "updated":
            print(f"Записано: {folder_rel}/{INFORMATION_FILE} → секция contacts.")
        else:
            print(
                f"Файл не изменён: {folder_rel}/{INFORMATION_FILE} → contacts "
                "уже соответствуют SSoT."
            )
    else:
        print("DRY-RUN: файл не изменён. Блок, который был бы записан:")
        print()
        print(_contacts_yaml_block(contacts), end="")
        print()
        print(f"Применить: make contacts IS={code} APPLY=1")
    if apply:
        # В dry-run «следующий шаг» уже напечатан выше («Применить: …»):
        # общая подсказка конвейера здесь только сбивает с толку.
        _emit_next_steps(root, None, args, codes=[code], single=True)
    return 0


# --- check: гейт достаточности данных ---------------------------------------


def _is_codes(root: Path):
    """Коды ИС из is.yaml (список для анализа) или None, если файла нет."""
    path = root / "is.yaml"
    if not path.exists():
        return None
    data = load_yaml(path)
    block = data.get("is") if isinstance(data, dict) else None
    if isinstance(block, dict):
        return [str(code) for code in block]
    if isinstance(block, list):
        codes = []
        for item in block:
            if isinstance(item, dict):
                codes.extend(str(key) for key in item)
            elif item is not None:
                codes.append(str(item))
        return codes
    return None


# Пустой is.yaml — не «файла нет»: подсказка должна вести к scaffold, а не
# к catalog.yaml и не к make init.
EMPTY_IS_ERROR = "ERROR: is.yaml пуст — добавьте ИС (make scaffold IS=<код>)"


def _is_codes_state(root: Path):
    """(коды ИС, состояние): 'ok' | 'missing' (файла нет) | 'empty' (файл пуст)."""
    path = root / IS_CONFIG
    if not path.exists():
        return None, "missing"
    codes = _is_codes(root)
    if not codes:
        return [], "empty"
    return codes, "ok"


def all_is_codes(root: Path):
    """Коды ИС проекта для команд без `--is`: is.yaml, иначе catalog.yaml.

    Один порядок для `ask`/`enrich`/`check`: команда без аргумента обрабатывает
    все ИС (с текущим статусом), а не падает «укажите IS=».
    """
    codes, _state = _is_codes_state(root)
    if codes:
        return list(codes)
    try:
        _catalog, systems = load_catalog(root)
    except (YamlError, OSError):
        systems = []
    return [str(entry.get("code")) for entry in systems if entry.get("code")]


def _loop_all_is(args, func, root, label, json_mode=False):
    """Выполнить команду по всем ИС: код возврата — худший из результатов."""
    codes = all_is_codes(root)
    if not codes:
        message = (
            "Нет ИС: is.yaml пуст и catalog.yaml не содержит записей — "
            "добавьте ИС (make scaffold IS=<код>)"
        )
        print(message, file=sys.stderr if json_mode else sys.stdout)
        return 0
    worst = 0
    for index, code in enumerate(codes):
        if index:
            print()
        print(f"=== {label}: {code} ===")
        child = argparse.Namespace(**{**vars(args), "is_": code})
        worst = max(worst, func(child))
    return worst


def _print_table(headers, rows):
    widths = [len(str(header)) for header in headers]
    for row in rows:
        for index, cell in enumerate(row):
            widths[index] = max(widths[index], len(str(cell)))
    print("| " + " | ".join(str(header).ljust(widths[index]) for index, header in enumerate(headers)) + " |")
    print("|" + "|".join("-" * (width + 2) for width in widths) + "|")
    for row in rows:
        print("| " + " | ".join(str(cell).ljust(widths[index]) for index, cell in enumerate(row)) + " |")


def _components_count(info):
    for key in ("components", "apps"):
        value = info.get(key)
        if isinstance(value, list):
            return len([item for item in value if item])
        if isinstance(value, dict):
            return len(value)
    return 0


