# URL страницы Confluence: page_id из `pageId=`/`page_id=`. Нужен, чтобы
# провенанс ответа `source_url` указывал на страницу, а не на голый URL.
CONFLUENCE_URL_RE = re.compile(r"pageId=(\d+)", re.IGNORECASE)
# Домен Confluence по умолчанию: тип `confluence` выдаётся только URL с этого
# хоста (или с хоста criteria.external_refs.base_url). Иначе `pageId=` в чужом
# редиректе выдавал бы ссылку за проверенную страницу.
CONFLUENCE_DEFAULT_HOST = "space.samokat.ru"
HTTP_URL_RE = re.compile(r"^https?://[^\s]+$", re.IGNORECASE)


def _truthy_flag(value):
    """YAML-bool в любом написании: true/yes/1."""
    if value is True:
        return True
    if value in (None, "", False):
        return False
    return str(value).strip().lower() in ("true", "yes", "1")


def _exclusion_record(reason, source):
    return {
        "reason": str(reason).strip() if reason not in (None, "") else "",
        "source": source,
    }


def _exclusion_text(record, default_reason="исключена из расчёта"):
    """Причина + источник исключения для вердикта SKIPPED."""
    record = record or {}
    reason = record.get("reason") or default_reason
    source = record.get("source") or "is.yaml"
    return f"{reason} (источник: {source})"


def _exclusions(root: Path, systems=None):
    """Код ИС -> {"reason", "source"}: исключение из расчёта.

    Приоритет: is.yaml (локальное переопределение) > catalog.yaml (общее).
    `excluded: false` в is.yaml явно включает ИС обратно, даже если в каталоге
    стоит `excluded: true`.

    Читается мягко: неизвестные ключи здесь не проверяются (это делает
    `prepare` через load_is_config), потому что гейт должен работать даже с
    черновым is.yaml.
    """
    found = {}
    if systems is None:
        try:
            _, systems = load_catalog(root)
        except (YamlError, OSError):
            systems = []
    for entry in systems or []:
        code = str(entry.get("code") or "").strip()
        if not code or not _truthy_flag(entry.get("excluded")):
            continue
        found[code] = _exclusion_record(entry.get("reason"), "catalog.yaml")

    path = root / IS_CONFIG
    if not path.exists():
        return found
    try:
        data = load_yaml(path)
    except (YamlError, OSError):
        return found
    block = data.get("is") if isinstance(data, dict) else None
    if not isinstance(block, dict):
        return found
    for code, value in block.items():
        if not isinstance(value, dict) or "excluded" not in value:
            continue
        code_text = str(code)
        if _truthy_flag(value.get("excluded")):
            found[code_text] = _exclusion_record(value.get("reason"), "is.yaml")
        else:
            found.pop(code_text, None)
    return found


def _requirements_date(entry, info, explicit=None):
    """Дата листа требований: --date -> catalog -> history -> null (не now()).

    Файл обязан быть воспроизводимым: текущая дата сюда не попадает.
    """
    if explicit:
        return explicit.isoformat() if hasattr(explicit, "isoformat") else str(explicit)
    for key in ("review_date", "assigned_date"):
        value = (entry or {}).get(key)
        if value in (None, ""):
            continue
        try:
            return parse_date(value).isoformat()
        except ValueError:
            continue
    history = (info or {}).get("history")
    if isinstance(history, list):
        for item in reversed(history):
            if not isinstance(item, dict):
                continue
            value = item.get("date") or item.get("assessed_date")
            if value in (None, ""):
                continue
            try:
                return parse_date(value).isoformat()
            except ValueError:
                continue
    return None


def _input_guidance(criteria, identifier):
    block = criteria.get("inputs") or {}
    for group in ("required", "optional"):
        for item in block.get(group) or []:
            if isinstance(item, dict) and str(item.get("id")) == identifier:
                return item
    return {}


def _requirement_value_fields(identifier):
    if identifier == "axes_scores":
        return list(INFORMATION_AXES)
    if identifier == "cia":
        return [lower for _upper, lower in INFORMATION_CIA]
    return None


def _requirement_value_yaml(fields):
    if not fields:
        return "    value: null\n"
    return "    value:\n" + "".join(f"      {field}: null\n" for field in fields)


def _requirement_value_yaml_from(identifier, value):
    """YAML-фрагмент `value` из существующего листа (слияние при записи).

    У составных входов (`axes_scores`, `cia`) под-оси идут в порядке шаблона;
    непустые под-оси пользователя сохраняются как есть.
    """
    fields = _requirement_value_fields(identifier)
    if fields is None:
        return f"    value: {dump_scalar(value)}\n"
    if not isinstance(value, dict):
        return f"    value: {dump_scalar(value)}\n"
    filled = [field for field in fields if _has_value(value.get(field))]
    if not filled:
        return _requirement_value_yaml(fields)
    lines = ["    value:\n"]
    for field in fields:
        lines.append(f"      {field}: {dump_scalar(value.get(field))}\n")
    for key, item in value.items():
        if str(key) in fields or isinstance(item, (dict, list)):
            continue
        lines.append(f"      {dump_key(key)}: {dump_scalar(item)}\n")
    return "".join(lines)


def _requirement_block_value(identifier, entry):
    """`value` блока листа из нормализованной записи `_normalize_requirement`.

    У составных входов (`axes_scores`, `cia`) `_normalize_requirement` кладёт
    под-оси в ВЕРХНИЙ уровень записи (форма `INFORMATION.yaml.criteria_inputs`),
    а в листе они живут под `value:`. Без этого преобразования в лист писался
    `value: null` при непустых под-осях — и `enrich` вход не принимал.
    """
    fields = _requirement_value_fields(identifier)
    if fields is None:
        return entry.get("value")
    return {field: entry.get(field) for field in fields}


def _requirement_source_yaml(source):
    """`source` из листа: ` null` либо блок `type`/`ref` (+ прочие скаляры)."""
    lines = ["\n", f"      type: {dump_scalar(source.get('type'))}\n"]
    lines.append(f"      ref: {dump_scalar(source.get('ref'))}")
    for key, item in source.items():
        if key in ("type", "ref") or isinstance(item, (dict, list)):
            continue
        lines.append(f"\n      {dump_key(key)}: {dump_scalar(item)}")
    return "".join(lines)


def _requirement_overlay(identifier, block):
    """Пользовательские поля существующего листа → поля элемента рендера.

    Переносятся `value`, `source` (при непустом `ref`), `status` (не `missing`),
    `bucket`/`unit`/`notes`. Вычисляемые `switches_scenario`/`scenario_note`
    из листа не берутся никогда: они всегда считаются по критериям.
    """
    overlay = {
        "value_yaml": _requirement_value_yaml(_requirement_value_fields(identifier)),
        "value_extra_yaml": "",
        "source_yaml": " null",
        "status": "missing",
        "extra_yaml": "",
        "carried": False,
    }
    if not isinstance(block, dict):
        return overlay
    value = block.get("value")
    value_filled = _has_value(value) or (
        isinstance(value, dict) and any(_has_value(item) for item in value.values())
    )
    if value_filled:
        overlay["value_yaml"] = _requirement_value_yaml_from(identifier, value)
        overlay["carried"] = True
    source = block.get("source")
    if isinstance(source, dict) and _has_value(source.get("ref")):
        overlay["source_yaml"] = _requirement_source_yaml(source)
    status = str(block.get("status") or "").strip().lower()
    if status and status != "missing":
        overlay["status"] = status
    value_extra = []
    for key in ("bucket", "unit"):
        item = block.get(key)
        if not _has_value(item) or isinstance(item, (dict, list)):
            continue
        value_extra.append(f"    {key}: {dump_scalar(item)}\n")
    overlay["value_extra_yaml"] = "".join(value_extra)
    extra = []
    for key in ("notes",):
        item = block.get(key)
        if not _has_value(item) or isinstance(item, (dict, list)):
            continue
        extra.append(f"\n    {key}: {dump_scalar(item)}")
    overlay["extra_yaml"] = "".join(extra)
    return overlay


def _requirement_value_count(identifier, block):
    """Сколько непустых значений у входа в листе (составной — по под-осям)."""
    if not isinstance(block, dict):
        return 1 if _has_value(block) else 0
    value = block.get("value")
    if isinstance(value, dict):
        return len([item for item in value.values() if _has_value(item)])
    return 1 if _has_value(value) else 0


def _requirements_sheet_inputs(yaml_path):
    """Секция `inputs` существующего листа: (inputs | None, проблема | None)."""
    path = Path(yaml_path)
    if not path.exists():
        return None, None
    try:
        data = load_yaml(path)
    except (YamlError, OSError):
        return None, "не разобран"
    if not isinstance(data, dict) or not isinstance(data.get("inputs"), dict):
        return None, "ожидалась секция inputs: словарь"
    return data.get("inputs"), None


def _requirements_sheet_facts(yaml_path):
    """Секция `facts` существующего листа (пусто — фактов нет)."""
    path = Path(yaml_path)
    if not path.exists():
        return {}
    try:
        data = load_yaml(path)
    except (YamlError, OSError):
        return {}
    facts = data.get("facts") if isinstance(data, dict) else None
    return facts if isinstance(facts, dict) else {}


def _accepted_input_ids(info, criteria):
    """Входы, уже принятые в INFORMATION.yaml (закрытые по `_input_closed`).

    Именно закрытые, а не «есть хоть какое-то значение»: частично заполненный
    вход расчёт не закрывает, поэтому значения листа по нему всё ещё требуют
    приёма через `enrich`.
    """
    accepted = set()
    for spec in _input_specs(criteria):
        if _input_closed(_input_record(info or {}, spec["id"])):
            accepted.add(spec["id"])
    return accepted


def _requirements_pending_ids(existing_inputs, info, criteria):
    """Заполненные значения листа, ещё не принятые через `enrich`."""
    if not existing_inputs:
        return []
    accepted = _accepted_input_ids(info, criteria)
    pending = []
    for identifier, block in existing_inputs.items():
        identifier = str(identifier)
        if identifier in accepted or not isinstance(block, dict):
            continue
        status = str(block.get("status") or "").strip().lower()
        if status in ("", "missing"):
            continue
        if _requirement_value_count(identifier, block):
            pending.append(identifier)
    return pending


def _requirements_lost_values(existing_inputs, new_inputs, info, criteria):
    """Входы, у которых рендер потерял заполненные значения.

    Сравнивается факт «до/после», а не флаг: потеря — это значение, которого
    нет ни в новом листе, ни в `INFORMATION.yaml.criteria_inputs`. Значение,
    принятое `enrich`, уходит из листа законно и потерей не считается.
    """
    if not existing_inputs:
        return []
    known = {spec["id"] for spec in _input_specs(criteria)}
    accepted = _accepted_input_ids(info, criteria)
    lost = []
    for identifier, block in existing_inputs.items():
        identifier = str(identifier)
        if identifier not in known or identifier in accepted:
            continue
        before = _requirement_value_count(identifier, block)
        if not before:
            continue
        after = _requirement_value_count(identifier, (new_inputs or {}).get(identifier))
        if after < before:
            lost.append(identifier)
    return lost


def _requirement_current_label(record):
    if not record.get("has_any"):
        return "не заполнено"
    if record.get("status") == "missing":
        return "значение есть, но status: missing (не подтверждено)"
    if not record.get("complete"):
        return "заполнено частично"
    return "заполнено"


def _requirements_items(criteria, gate, existing=None):
    """ТОЛЬКО незакрытые входы в порядке критериев, с привязкой к сценарию.

    «Закрыт» — единый критерий `_input_closed` (тот же, что у гейта): значение
    полное и статус confirmed/derived/legacy. Закрытый вход в лист не попадает
    никогда — он уже задан для расчёта; лист производен от INFORMATION.yaml.

    `mandatory` — вход входит в blocking-набор выбранного сценария (4 в простом,
    все 7 в сложном). Незакрытые входы вне набора остаются в листе как advisory:
    они не блокируют расчёт, но нужны для полноты паспорта.

    `switches_scenario` — advisory-вход простого сценария, который входит только
    в сложный набор: его заполнение переключает ИС на сложный сценарий
    (`scenarios.selection.rule`) и делает обязательным `time_to_impact`.
    В сложном сценарии флаг всегда false — там все 7 входов уже обязательны.

    `existing` — секция `inputs` существующего листа: значения, ещё НЕ принятые
    в INFORMATION.yaml (человек заполнил, enrich не прогоняли), переносятся в
    новый рендер, чтобы `check` не затирал работу. Принятые значения в лист не
    возвращаются: они закрыты и отфильтрованы выше.
    """
    items = []
    scenario_ids = set(gate.get("scenario_inputs") or blocking_inputs(gate["scenario"], criteria))
    scenario_is_simple = gate.get("scenario") == "simple"
    switchers = set(complex_only_inputs(criteria)) if scenario_is_simple else set()
    # Отказ (R17) из листа, ещё не перенесённый в INFORMATION.yaml: рендерится
    # отдельным блоком (`waived_items`), иначе блок `waive` терялся бы в overlay.
    waived_pending = {
        str(identifier)
        for identifier, block in (existing or {}).items()
        if isinstance(block, dict)
        and str(block.get("status") or "").strip().lower() == WAIVED_STATUS
    }
    for spec in gate["specs"]:
        record = gate["records"].get(spec["id"]) or {}
        # Явный отказ (R17) закрывает вход для гейта и для вопросов: спрашивать
        # повторно то, от чего человек отказался, — это не вопрос, а нажим.
        if record.get("status") == WAIVED_STATUS:
            continue
        if spec["id"] in waived_pending:
            continue
        # «Закрыт» — единый критерий `_input_closed` (тот же, что у гейта).
        if _input_closed(record):
            continue
        identifier = spec["id"]
        guidance = _input_guidance(criteria, identifier)
        fields = _requirement_value_fields(identifier)
        mandatory = identifier in scenario_ids
        switches = (not mandatory) and identifier in switchers
        item = {
            "id": identifier,
            "title": guidance.get("title") or spec.get("description") or identifier,
            "description": spec.get("description") or guidance.get("description") or "",
            "definition": guidance.get("definition") or spec.get("description") or "",
            "why": guidance.get("why") or "",
            "acceptable": guidance.get("acceptable") or "",
            "where": guidance.get("where") or spec.get("source_hint") or "",
            "whom": guidance.get("whom") or "",
            "confirm": guidance.get("confirm") or "",
            "example": guidance.get("example") or "",
            "method": spec.get("method") or "both",
            "mandatory": mandatory,
            "blocking_label": "blocking" if mandatory else "advisory",
            "switches_scenario": switches,
            "scenario_note": SCENARIO_SWITCH_NOTE if switches else "",
            "current_label": _requirement_current_label(record),
            "value_fields": fields,
            "value_yaml": _requirement_value_yaml(fields),
            "is_load": identifier == "peak_hour_load",
        }
        item.update(_requirement_overlay(identifier, (existing or {}).get(identifier)))
        items.append(item)
    return items


def _requirement_waived_yaml(identifier, block):
    """YAML-фрагмент отказа (R17) в форме листа: `status: waived` + `waive`."""
    waive = block.get("waive") if isinstance(block.get("waive"), dict) else {}
    fallback = waive.get("fallback") if isinstance(waive.get("fallback"), dict) else {}
    body = {
        identifier: {
            "value": None,
            "source": None,
            "status": WAIVED_STATUS,
            "waive": {
                "reason": waive.get("reason"),
                "decided_by": waive.get("decided_by"),
                "date": waive.get("date"),
                "fallback": {
                    "mode": fallback.get("mode"),
                    **(
                        {"value": fallback.get("value")}
                        if fallback.get("value") is not None
                        else {}
                    ),
                },
            },
        }
    }
    return "".join("  " + line for line in dump_yaml(body).splitlines(True))


def _requirements_waived_items(criteria, gate, existing):
    """Отказы (R17), ещё не перенесённые в `INFORMATION.yaml`.

    Лист обязан донести блок `waive` до `enrich`: если вход закрыт отказом в
    листе, но отказ не записан в `criteria_inputs`, следующий рендер не должен
    его молча выбросить (иначе причина и режим допущения теряются, а расчёт
    перестаёт быть предварительным без следа).
    """
    applied = {
        spec["id"]
        for spec in gate["specs"]
        if (gate["records"].get(spec["id"]) or {}).get("status") == WAIVED_STATUS
    }
    items = []
    for raw_identifier, block in (existing or {}).items():
        identifier = str(raw_identifier)
        if identifier in applied or not isinstance(block, dict):
            continue
        if str(block.get("status") or "").strip().lower() != WAIVED_STATUS:
            continue
        waive = block.get("waive") if isinstance(block.get("waive"), dict) else {}
        fallback = waive.get("fallback") if isinstance(waive.get("fallback"), dict) else {}
        guidance = _input_guidance(criteria, identifier)
        items.append(
            {
                "id": identifier,
                "title": guidance.get("title") or identifier,
                "reason": str(waive.get("reason") or ""),
                "decided_by": str(waive.get("decided_by") or ""),
                "date": str(waive.get("date") or ""),
                "mode": str(fallback.get("mode") or ""),
                "mode_label": WAIVE_ASSUMPTION_LABELS.get(
                    str(fallback.get("mode") or ""), "—"
                ),
                "value": fallback.get("value"),
                "yaml": _requirement_waived_yaml(identifier, block),
            }
        )
    return items


def _requirements_context(criteria, code, entry, info, date, existing=None,
                          existing_facts=None):
    gate = evaluate_gate(info or {}, criteria)
    items = _requirements_items(criteria, gate, existing=existing)
    waived_items = _requirements_waived_items(criteria, gate, existing)
    blocking = [item for item in items if item["mandatory"]]
    advisory = [item for item in items if not item["mandatory"]]
    scenario_is_simple = gate["scenario"] == "simple"
    advisory_switches = any(item["switches_scenario"] for item in items)
    return {
        "requirements": {
            "is_code": code,
            "generated_at": _requirements_date(entry, info, date),
            "scenario": gate["scenario"],
            "scenario_title": gate["scenario_title"],
            "scenario_label": gate["scenario_label"],
            "scenario_is_simple": scenario_is_simple,
            "advisory_switches_scenario": scenario_is_simple and advisory_switches,
            "scenario_inputs": list(gate.get("scenario_inputs") or []),
            "scenario_inputs_count": len(gate.get("scenario_inputs") or []),
            "method": gate["method"],
            "status": "complete"
            if not items and not waived_items
            else "incomplete",
            "blocking_count": len(blocking),
            "advisory_count": len(advisory),
            "total_count": len(items),
            "carried_count": len([item for item in items if item.get("carried")]),
            "items": items,
            "blocking_items": blocking,
            "advisory_items": advisory,
            # Отказы (R17): лист обязан донести их до `enrich`, иначе причина и
            # режим допущения теряются молча.
            "waived_items": waived_items,
            "waived_count": len(waived_items),
            # Факты паспорта, ещё не принятые `enrich`: тот же лист, тот же
            # писатель — ответ на факт-вопрос не требует ручной правки YAML.
            "facts_yaml": dump_yaml({"facts": existing_facts}) if existing_facts else "",
            "facts": existing_facts or {},
            "gate_verdict": gate["verdict"],
            "gate_reason": gate["reason"],
        }
    }


def _render_requirements(criteria, code, entry, info, date, existing=None,
                         existing_facts=None):
    context = _requirements_context(
        criteria, code, entry, info, date, existing=existing,
        existing_facts=existing_facts,
    )
    rendered = {
        key: render_template_file(SKILL_DIR / template, context)
        for key, template in REQUIREMENTS_TEMPLATES.items()
    }
    return context, rendered


def _requirements_paths(root, code, entry):
    folder_rel, _legacy = is_folder(root, code, entry)
    folder = root / folder_rel
    return folder_rel, folder, folder / DATA_REQUIREMENTS_MD, folder / DATA_REQUIREMENTS_YAML


def _write_requirements(root, criteria, code, entry, info, date, apply=True):
    """Отрендерить и (с apply) записать лист требований.

    ИНВАРИАНТ: лист содержит ТОЛЬКО открытые входы и производен от
    `INFORMATION.yaml` (источник истины), а не накопителен. Вход закрыт по
    единому критерию `_input_closed` (значение полное + статус
    confirmed/derived/legacy — то же, что засчитывает гейт) — такой вход в
    лист не попадает никогда, даже если он остался в прошлой версии файла.
    Закрытие даёт: `enrich`/`enrich-apply`, `sources`/`sources-apply`, расчёт
    (`status: derived`), ручная правка `INFORMATION.yaml`.

    Защита от потери ручных данных: значения существующего листа, которые ещё
    НЕ приняты в `INFORMATION.yaml` (человек заполнил, `enrich` не прогоняли),
    переносятся в новый рендер — `value`, `source` (при непустом `ref`),
    `status` (не `missing`) и `bucket`/`unit`/`notes`. Это открытые поля, терять
    их нельзя. Вычисляемые `switches_scenario`/`scenario_note` всегда берутся из
    критериев. Пользовательские комментарии `#` при перегенерации не
    сохраняются — сохраняются значения.

    Защита от потери: если рендер уменьшил число заполненных значений
    относительно существующего файла (и значения нет в `INFORMATION.yaml`),
    файл не перезаписывается, новый рендер пишется в `DATA-REQUIREMENTS.yaml.new`,
    а `result["integrity_error"]` = True — вызывающая команда возвращает
    ненулевой код.

    Нет недостающих входов — файлы удаляются: лист существует только пока
    есть что дозаполнять.
    """
    folder_rel, folder, md_path, yaml_path = _requirements_paths(root, code, entry)
    if not folder.is_dir():
        return {
            "status": "no_folder",
            "folder_rel": folder_rel,
            "blocking": 0,
            "advisory": 0,
            "total": 0,
            "integrity_error": False,
            "lost": [],
            "unaccepted": [],
            "carried": 0,
        }
    existing_inputs, existing_problem = _requirements_sheet_inputs(yaml_path)
    if existing_problem:
        print(
            f"WARN: {folder_rel}/{DATA_REQUIREMENTS_YAML}: существующий "
            "DATA-REQUIREMENTS.yaml не разобран, значения не перенесены"
        )
    context, rendered = _render_requirements(
        criteria, code, entry, info, date, existing=existing_inputs,
        existing_facts=_requirements_sheet_facts(yaml_path),
    )
    summary = context["requirements"]
    result = {
        "status": "complete"
        if not summary["total_count"] and not summary.get("waived_count")
        else "incomplete",
        "folder_rel": folder_rel,
        "blocking": summary["blocking_count"],
        "advisory": summary["advisory_count"],
        "waived": summary.get("waived_count", 0),
        "total": summary["total_count"],
        "carried": summary.get("carried_count", 0),
        "md_path": f"{folder_rel}/{DATA_REQUIREMENTS_MD}",
        "yaml_path": f"{folder_rel}/{DATA_REQUIREMENTS_YAML}",
        "removed": [],
        "integrity_error": False,
        "lost": [],
        "closed_leaked": [],
        "unaccepted": _requirements_pending_ids(existing_inputs, info, criteria),
        "backup": None,
    }
    new_inputs = {}
    render_problem = None
    try:
        parsed = parse_yaml(rendered["yaml"], f"{folder_rel}/{DATA_REQUIREMENTS_YAML}")
    except YamlError as exc:
        parsed = None
        render_problem = str(exc)
    if isinstance(parsed, dict) and isinstance(parsed.get("inputs"), dict):
        new_inputs = parsed["inputs"]
    if render_problem and summary["total_count"]:
        print(
            f"ОШИБКА: рендер листа не разобран ({render_problem}); "
            f"файл не перезаписан (IS={code})"
        )
        result["integrity_error"] = True
        if apply:
            new_path = yaml_path.parent / (DATA_REQUIREMENTS_YAML + ".new")
            _atomic_write(new_path, rendered["yaml"])
            print(f"  новый рендер: {new_path.relative_to(root).as_posix()}")
        return result
    # Defense in depth: рендер обязан содержать только открытые входы. Если
    # закрытый вход всё-таки попал в YAML (баг контекста/шаблона), файл не
    # перезаписываем: инвариант «лист = только открытые поля» важнее вывода.
    closed_ids = {
        spec["id"]
        for spec in _input_specs(criteria)
        if _input_closed(_input_record(info or {}, spec["id"]))
    }
    leaked = sorted({str(identifier) for identifier in new_inputs} & closed_ids)
    if leaked:
        print(
            f"ОШИБКА: рендер листа содержит уже закрытый вход "
            f"({', '.join(leaked)}) — нарушен инвариант «в листе только открытые "
            f"поля» (IS={code}); файл не перезаписан"
        )
        result["integrity_error"] = True
        result["closed_leaked"] = leaked
        if apply:
            new_path = yaml_path.parent / (DATA_REQUIREMENTS_YAML + ".new")
            _atomic_write(new_path, rendered["yaml"])
            print(f"  новый рендер: {new_path.relative_to(root).as_posix()}")
        return result
    lost = (
        _requirements_lost_values(existing_inputs, new_inputs, info, criteria)
        if apply
        else []
    )
    if lost:
        print(
            f"ОШИБКА: рендер листа потерял {len(lost)} заполненных значений "
            f"(IS={code}); файл не перезаписан"
        )
        result["integrity_error"] = True
        result["lost"] = lost
        if apply:
            new_path = yaml_path.parent / (DATA_REQUIREMENTS_YAML + ".new")
            _atomic_write(new_path, rendered["yaml"])
            print(f"  новый рендер: {new_path.relative_to(root).as_posix()}")
        return result
    if not summary["total_count"] and not summary.get("waived_count"):
        for path in (md_path, yaml_path):
            if path.exists():
                if apply:
                    if existing_problem and path == yaml_path:
                        backup = yaml_path.parent / (DATA_REQUIREMENTS_YAML + ".broken")
                        _atomic_write(
                            backup, yaml_path.read_text(encoding="utf-8")
                        )
                        result["backup"] = backup.relative_to(root).as_posix()
                        print(f"  копия неразобранного листа: {result['backup']}")
                    path.unlink()
                result["removed"].append(path.relative_to(root).as_posix())
        return result
    if apply:
        stale_new = yaml_path.parent / (DATA_REQUIREMENTS_YAML + ".new")
        if stale_new.exists():
            stale_new.unlink()
        if existing_problem and yaml_path.exists():
            backup = yaml_path.parent / (DATA_REQUIREMENTS_YAML + ".broken")
            _atomic_write(backup, yaml_path.read_text(encoding="utf-8"))
            result["backup"] = backup.relative_to(root).as_posix()
            print(f"  копия неразобранного листа: {result['backup']}")
        _atomic_write(md_path, rendered["md"])
        _atomic_write(yaml_path, rendered["yaml"])
    return result


def _requirements_pending(root, code, entry, info, criteria):
    """Заполненные, но не принятые значения листа требований ИС."""
    _folder_rel, _folder, _md, yaml_path = _requirements_paths(root, code, entry)
    inputs, problem = _requirements_sheet_inputs(yaml_path)
    if problem:
        return []
    return _requirements_pending_ids(inputs, info, criteria)


def _requirements_line(result):
    if result["status"] == "no_folder":
        return f"лист требований не создан: нет папки {result['folder_rel']}"
    if result["status"] == "complete":
        return "недостающих входов нет — лист требований удалён"
    waived = result.get("waived") or 0
    waived_text = f", отказов (waive): {waived}" if waived else ""
    return (
        f"лист требований: {result['yaml_path']} — "
        f"чего не хватает: {result['blocking']} blocking, {result['advisory']} advisory"
        f"{waived_text}"
    )


def _load_info_file(folder: Path):
    path = folder / INFORMATION_FILE
    if not path.exists():
        return None
    try:
        info = load_yaml(path)
    except YamlError:
        return None
    return info if isinstance(info, dict) else None


def cmd_requirements(args) -> int:
    root = repo_root_from_args(args)
    apply = bool(args.apply)
    try:
        date = parse_date_arg(args.date, "--date") if args.date else None
    except ValueError as exc:
        print(f"ERROR: {exc}")
        return 1
    try:
        criteria = load_criteria()
        _, systems = load_catalog(root)
        codes, is_state = _is_codes_state(root)
    except YamlError as exc:
        print(f"ERROR: {exc}")
        return 1

    by_code = catalog_by_code(systems)
    exclusions = _exclusions(root, systems)
    if is_state == "empty":
        print(EMPTY_IS_ERROR)
        return 1
    if is_state == "missing":
        codes = [str(entry.get("code")) for entry in systems]
        source = "catalog.yaml (is.yaml не найден)"
    else:
        source = "is.yaml"
    if args.is_:
        if args.is_ not in codes and args.is_ not in by_code:
            print(
                f"ERROR: ИС {args.is_!r} нет ни в {source}, ни в catalog.yaml. "
                f"Доступные: {', '.join(sorted(set(codes) | set(by_code)))}"
            )
            return 1
        codes = [args.is_]

    mode = "APPLY" if apply else "DRY-RUN"
    print(f"Лист недостающих данных ({mode}). Список ИС: {source}.")
    print(f"Критерии: {criteria_path()}")
    print()

    totals = {"incomplete": 0, "complete": 0, "skipped": 0, "no_folder": 0, "integrity": 0}
    for code in codes:
        entry = by_code.get(code) or {}
        folder_rel, folder, _md, _yaml = _requirements_paths(root, code, entry)
        print(f"ИС: {code}")
        print(f"  папка: {folder_rel}")
        if code in exclusions:
            print(f"  статус: SKIPPED — {_exclusion_text(exclusions[code])}")
            totals["skipped"] += 1
            print()
            continue
        info = _load_info_file(folder)
        result = _write_requirements(
            root, criteria, code, entry, info, date, apply=apply
        )
        if result.get("integrity_error"):
            totals["integrity"] += 1
            print()
            continue
        if result["status"] == "no_folder":
            print(f"  статус: пропуск — нет папки ИС {folder_rel}")
            totals["no_folder"] += 1
            print()
            continue
        if result["status"] == "complete":
            print("  статус: OK — недостающих входов нет")
            if result["removed"]:
                for rel in result["removed"]:
                    print(f"  удалён: {rel}")
            totals["complete"] += 1
            print()
            continue
        totals["incomplete"] += 1
        # Advisory-входы расчёт не блокируют: гейт с 0 blocking — OK. Слово
        # BLOCKED здесь было ложным ярлыком (первый полный прогон: «BLOCKED —
        # 0 blocking, 3 advisory» при пройденном гейте).
        blocking = int(result.get("blocking") or 0)
        advisory = int(result.get("advisory") or 0)
        label = "BLOCKED" if blocking else ("PRELIMINARY" if advisory else "OK")
        print(
            f"  статус: {label} — чего не хватает: "
            f"{blocking} blocking, {advisory} advisory"
        )
        if apply:
            print(f"  записан: {result['md_path']}")
            print(f"  записан: {result['yaml_path']}")
        else:
            print(f"  будет записан: {result['md_path']}")
            print(f"  будет записан: {result['yaml_path']}")
            context = _requirements_context(criteria, code, entry, info, date)
            for item in context["requirements"]["items"]:
                print(
                    f"    - {item['id']} ({item['blocking_label']}, "
                    f"метод {item['method']}): {item['title']}"
                )
        print()

    print(
        f"Итого: ИС {len(codes)}, с требованиями {totals['incomplete']}, "
        f"полные {totals['complete']}, SKIPPED {totals['skipped']}, "
        f"без папки {totals['no_folder']}."
    )
    if not apply:
        print("DRY-RUN: файлы не записаны.")
    if totals["integrity"]:
        print(
            f"ОШИБКА: у {totals['integrity']} ИС лист требований не перезаписан "
            "(потеря заполненных значений, см. выше)."
        )
        return 1
    _emit_next_steps(root, criteria, args, codes=codes)
    return 0


# --- enrich: приём заполненного листа --------------------------------------


def _source_problem(source):
    if not isinstance(source, dict):
        return (
            "source не заполнен: нужен блок {type, ref} "
            "(type: " + " | ".join(PROVENANCE_TYPES) + ")"
        )
    kind = str(source.get("type") or "").strip()
    ref = source.get("ref")
    if not kind:
        return "source.type не заполнен"
    if kind not in PROVENANCE_TYPES:
        return (
            f"source.type={kind!r} вне допустимого перечня: "
            + " | ".join(PROVENANCE_TYPES)
        )
    if ref in (None, "") or (isinstance(ref, str) and not ref.strip()):
        return "source.ref не заполнен (путь, page_id, URL MR или логин)"
    return None


def _waive_problem(criteria, identifier, waive, value=None):
    """Проверка блока `waive` (R17): причина, режим допущения, значение.

    None — блок корректен; строка — причина отказа принять его. Один валидатор
    на три места: `ask --answers`, `enrich` (приём листа) и `validate`.
    `value` передаётся, когда у вызывающего есть запись целиком: у waived-входа
    значения быть не может (иначе вход одновременно «готов» и «отказ»: диапазон
    считается по домену, а балл — из значения).
    """
    if value is not None and _has_value(value):
        return "у waived-входа не может быть значения: value должен быть null"
    if not isinstance(waive, dict):
        return (
            "status: waived требует блок waive: {reason, decided_by, date, "
            "fallback: {mode}}"
        )
    reason = str(waive.get("reason") or "").strip()
    if len(reason) < WAIVE_REASON_MIN:
        return (
            "waive.reason пуст или короче "
            f"{WAIVE_REASON_MIN} символов — причина отказа обязательна и проверяема"
        )
    fallback = waive.get("fallback")
    if not isinstance(fallback, dict):
        return "waive.fallback не заполнен: нужен режим допущения {mode}"
    mode = str(fallback.get("mode") or "").strip()
    if mode not in WAIVE_MODES:
        return (
            f"waive.fallback.mode={mode!r} вне допустимого перечня: "
            + " | ".join(WAIVE_MODES)
        )
    if mode == "assume_value":
        value = fallback.get("value")
        if not _has_value(value):
            return "waive.fallback.mode: assume_value требует value"
        problem = _ask_value_problem(criteria, identifier, value)
        if problem:
            return f"waive.fallback.value: {problem}"
    return None


def _requirement_filled(identifier, value):
    if isinstance(value, dict):
        fields = _requirement_value_fields(identifier) or list(value)
        filled = [field for field in fields if value.get(field) not in (None, "")]
        if not filled:
            return False
        if len(filled) != len(fields):
            missing = [field for field in fields if field not in filled]
            raise ValueError(
                "заполнены не все поля значения: не хватает " + ", ".join(missing)
            )
        return True
    return _has_value(value)


# Единицы измерения входов: дефолт скилла (историческое значение) и то, что
# перечислено в критериях (`inputs.required[].acceptable`). `unit` из findings
# применяется только если он допустим по критериям — иначе это была бы
# выдуманная единица (R14: провенанс значения должен быть правдой).
REQUIREMENT_UNIT_DEFAULTS = {
    "peak_hour_load": "клиентов/час",
    "object_sla": "мин",
}

# Статус значения: `confirmed` — дословно в источнике (дефолт: найденное по
# ссылкам SSoT принимается автоматически), `derived` — вычислено по формуле,
# прямо разрешённой критериями (`confirm` у входа).
REQUIREMENT_STATUSES = ("confirmed", "derived")

_UNIT_TOKEN_RE = re.compile(
    r"[A-Za-zА-Яа-яЁё0-9_.\-]+/[A-Za-zА-Яа-яЁё0-9_.\-]+"
)


def _requirement_allowed_units(criteria, identifier):
    """(дефолт, допустимые единицы) входа; (None, ()) — вход без единицы."""
    default = REQUIREMENT_UNIT_DEFAULTS.get(identifier)
    if default is None:
        return None, ()
    guidance = _input_guidance(criteria, identifier)
    allowed = [default]
    for token in _UNIT_TOKEN_RE.findall(str(guidance.get("acceptable") or "")):
        if token not in allowed:
            allowed.append(token)
    return default, tuple(allowed)


def _requirement_unit_problem(criteria, identifier, unit):
    """Причина, по которой `unit` не принимается (None — принимается)."""
    default, allowed = _requirement_allowed_units(criteria, identifier)
    if unit in (None, "") or (isinstance(unit, str) and not unit.strip()):
        return None
    if default is None:
        return (
            f"unit не применяется к входу {identifier}: у входа нет единицы "
            "измерения в criteria.inputs.required"
        )
    text = str(unit).strip()
    if text not in allowed:
        return f"unit={text!r} вне допустимых значений: " + ", ".join(allowed)
    return None


def _requirement_status_problem(status):
    """Причина, по которой `status` не принимается (None — принимается)."""
    if status in (None, ""):
        return None
    text = str(status).strip().lower()
    if text not in REQUIREMENT_STATUSES:
        return (
            f"status={status!r} вне допустимых значений: "
            + " | ".join(REQUIREMENT_STATUSES)
        )
    return None


def _normalize_requirement(identifier, raw_value, source, unit=None, status=None):
    entry = {}
    if identifier == "axes_scores":
        values = raw_value if isinstance(raw_value, dict) else {}
        for axis in INFORMATION_AXES:
            entry[axis] = _coerce_int(values.get(axis))
    elif identifier == "cia":
        values = raw_value if isinstance(raw_value, dict) else {}
        for upper, lower in INFORMATION_CIA:
            raw = values.get(lower)
            if raw is None:
                raw = values.get(upper)
            entry[lower] = str(raw).strip().lower() if raw not in (None, "") else None
    elif identifier == "time_to_impact":
        raw = raw_value.get("bucket") if isinstance(raw_value, dict) else raw_value
        try:
            bucket = normalize_time_bucket(raw)
        except ValueError:
            bucket = raw
        entry["value"] = bucket
        entry["bucket"] = bucket
    elif identifier in REQUIREMENT_UNIT_DEFAULTS:
        entry["value"] = _coerce_int(raw_value)
        # Единица измерения: из findings, если задана и допустима по критериям
        # (проверяется `_requirement_unit_problem`), иначе — дефолт скилла.
        entry["unit"] = (
            str(unit).strip()
            if unit not in (None, "")
            else REQUIREMENT_UNIT_DEFAULTS[identifier]
        )
    else:
        entry["value"] = raw_value.strip() if isinstance(raw_value, str) else raw_value
    entry["source"] = source
    entry["status"] = status or "confirmed"
    return entry


def _requirement_value_problems(criteria, identifier, entry):
    """Проверка значения теми же валидаторами, что и гейт (_value_problems)."""
    probe = {"criteria_inputs": {identifier: entry}}
    specs = _input_specs(criteria)
    records = {spec["id"]: _input_record(probe, spec["id"]) for spec in specs}
    return _value_problems(probe, criteria, records)


def _sheet_input_problems(criteria, identifier, block):
    """Проблемы записи входа в лист — те же проверки, что делает `enrich`.

    Один валидатор на два места: `enrich` (приём листа) и пост-проверка записи
    в `ask --answers`. Возвращает `(problems, normalized)`: пустой список
    проблем значит, что значение записано и будет принято `enrich`;
    `normalized` — форма `INFORMATION.yaml.criteria_inputs` (None, если вход
    не заполнен или запись некорректна).
    """
    if not isinstance(block, dict):
        return ["ожидался словарь value/source/status"], None
    raw_value = block.get("value")
    status = str(block.get("status") or "").strip().lower()
    # Явный отказ от данных (R17): значения нет и не будет — вход закрыт
    # осознанным решением, а не пропуском. Блок `waive` обязателен, иначе
    # отказ нельзя ни проверить, ни воспроизвести.
    if status == WAIVED_STATUS:
        problem = _waive_problem(
            criteria, identifier, block.get("waive"), value=raw_value
        )
        if problem:
            return [problem], None
        waive = block.get("waive") or {}
        fallback = waive.get("fallback") if isinstance(waive.get("fallback"), dict) else {}
        normalized = {
            "value": None,
            "source": None,
            "status": WAIVED_STATUS,
            "waive": {
                "reason": str(waive.get("reason") or "").strip(),
                "decided_by": str(waive.get("decided_by") or "").strip() or None,
                "date": str(waive.get("date") or "").strip() or None,
                "fallback": {
                    "mode": str(fallback.get("mode") or "").strip(),
                    **(
                        {"value": fallback.get("value")}
                        if fallback.get("value") is not None
                        else {}
                    ),
                },
            },
        }
        return [], normalized
    try:
        filled = _requirement_filled(identifier, raw_value)
    except ValueError as exc:
        return [str(exc)], None
    if not filled:
        return [], None
    problems = []
    if status != "confirmed":
        problems.append(
            f"value заполнено, но status={block.get('status')!r} — "
            "требуется status: confirmed"
        )
    source_problem = _source_problem(block.get("source"))
    if source_problem:
        problems.append(source_problem)
    if problems:
        return problems, None
    # Единица измерения из листа проверяется тем же валидатором, что
    # `sources-apply`: иначе `unit: сек` при дефолте `мин` проходил молча и
    # значение 240 «секунд» уезжало в расчёт как 240 минут.
    unit_problem = _requirement_unit_problem(criteria, identifier, block.get("unit"))
    if unit_problem:
        return [unit_problem], None
    normalized = _normalize_requirement(
        identifier, raw_value, block.get("source"), unit=block.get("unit")
    )
    problems = list(_requirement_value_problems(criteria, identifier, normalized))
    if problems:
        return problems, None
    return [], normalized


def _splice_top_level_section(text, section, new_block):
    """Заменить секцию верхнего уровня, сохранив остальной файл дословно."""
    lines = text.splitlines(True)
    span = _top_level_span(lines, section)
    block = new_block if new_block.endswith("\n") else new_block + "\n"
    if span is None:
        if text and not text.endswith("\n"):
            text += "\n"
        return text + block
    lines[span[0]:span[1]] = [block]
    return "".join(lines)


# --- сохранение комментариев в ручных секциях (дефект A7) -------------------
#
# `criteria_inputs` — файл пользователя: в нём допустимы `#`-комментарии у поля,
# у `source`, у `value`. Перезапись секции целиком их теряла молча. Комментарии
# запоминаются по пути ключа и восстанавливаются при рендере; то, что привязать
# не удалось (структура изменилась), возвращается вызывающему для WARN.

_YAML_KEY_LINE_RE = re.compile(r"^([^:#][^:]*):(?:\s|$)")
_COMMENT_LINE_RE = re.compile(r"^(\s*)#(.*)$")


def _indent_width(line: str) -> int:
    width = 0
    for char in line:
        if char == " ":
            width += 1
        elif char == "\t":
            width += 2
        else:
            break
    return width


def _yaml_key_of(line: str):
    """Ключ строки вида `key:` / `key: value` либо None (список, скаляр)."""
    stripped = line.strip()
    if not stripped or stripped.startswith("#") or stripped.startswith("-"):
        return None
    match = _YAML_KEY_LINE_RE.match(stripped)
    if not match:
        return None
    key = match.group(1).strip()
    if len(key) >= 2 and key[0] == key[-1] and key[0] in ("'", '"'):
        key = key[1:-1]
    return key


def _trailing_comment(line: str):
    """Комментарий в конце строки значения (вне кавычек) либо None."""
    quote = None
    for index, char in enumerate(line):
        if quote:
            if char == quote:
                quote = None
            continue
        if char in ("'", '"'):
            quote = char
            continue
        if char == "#" and index > 0 and line[index - 1] in (" ", "\t"):
            return line[index:].rstrip("\n").rstrip()
    return None


def _block_comments(lines):
    """Комментарии блока по пути ключа.

    Возвращает список `(path, indent, text, kind)`, где `kind` — `before`
    (отдельная строка перед ключом) или `trailing` (в конце строки значения).
    `path` — кортеж ключей от начала секции.
    """
    result = []
    stack = []
    pending = []
    for line in lines:
        if not line.strip():
            continue
        match = _COMMENT_LINE_RE.match(line)
        if match:
            pending.append((_indent_width(line), "#" + match.group(2).rstrip("\n").rstrip()))
            continue
        key = _yaml_key_of(line)
        if key is None:
            # Продолжение значения (элемент списка, block scalar): комментарий
            # относится к текущему пути.
            if pending:
                path = tuple(item[1] for item in stack)
                for indent, text in pending:
                    result.append((path, indent, text, "before"))
                pending = []
            continue
        indent = _indent_width(line)
        while stack and stack[-1][0] >= indent:
            stack.pop()
        path = tuple(item[1] for item in stack) + (key,)
        for comment_indent, text in pending:
            result.append((path, comment_indent, text, "before"))
        pending = []
        trailing = _trailing_comment(line)
        if trailing:
            result.append((path, indent, trailing, "trailing"))
        stack.append((indent, key))
    for indent, text in pending:
        # Комментарий в конце блока: привязать не к чему — это потеря.
        result.append((None, indent, text, "before"))
    return result


def _restore_comments(block: str, comments):
    """Вставить комментарии в отрендеренный блок секции.

    Возвращает `(текст, потерянные)`. Комментарий вставляется перед ключом с тем
    же путём; `trailing` дописывается в конец строки значения. Если ключа в
    новой структуре нет — комментарий попадает в `потерянные`.
    """
    if not comments:
        return block, []
    lines = block.splitlines(True)
    by_path = {}
    for index, item in enumerate(comments):
        by_path.setdefault(item[0], []).append(index)
    used = set()
    output = []
    stack = []
    for line in lines:
        if not line.strip():
            output.append(line)
            continue
        key = _yaml_key_of(line)
        if key is None:
            output.append(line)
            continue
        indent = _indent_width(line)
        while stack and stack[-1][0] >= indent:
            stack.pop()
        path = tuple(item[1] for item in stack) + (key,)
        for index in by_path.get(path, []):
            comment_path, comment_indent, text, kind = comments[index]
            if index in used:
                continue
            if kind == "before":
                output.append(" " * comment_indent + text + "\n")
                used.add(index)
        for index in by_path.get(path, []):
            comment_path, comment_indent, text, kind = comments[index]
            if index in used or kind != "trailing":
                continue
            line = line.rstrip("\n") + "  " + text + "\n"
            used.add(index)
        output.append(line)
        stack.append((indent, key))
    lost = [item for index, item in enumerate(comments) if index not in used]
    return "".join(output), lost


def _section_block(text: str, section: str):
    """Текст секции верхнего уровня (включая заголовок) либо пустая строка."""
    lines = text.splitlines(True)
    span = _top_level_span(lines, section)
    if span is None:
        return ""
    return "".join(lines[span[0]:span[1]])


def _splice_section_keep_comments(text, section, new_block):
    """Заменить секцию, перенеся `#`-комментарии по путям ключей.

    Возвращает `(новый текст, потерянные комментарии)`; потерянные описываются
    вызывающим как WARN — терять их молча запрещено (A7).
    """
    old_block = _section_block(text, section)
    comments = []
    if old_block:
        comments = _block_comments(old_block.splitlines(True))
    restored, lost = _restore_comments(new_block, comments)
    return _splice_top_level_section(text, section, restored), lost


def _lost_comments_text(lost) -> str:
    """Человекочитаемое описание потерянных комментариев."""
    parts = []
    for path, _indent, text, _kind in lost:
        where = ".".join(path) if path else "конец секции"
        parts.append(f"{text} (путь: {where})")
    return "; ".join(parts)


def _fact_names():
    """Допустимые имена фактов: ключи секции `facts` шаблона INFORMATION.yaml.

    Пустой набор — шаблон недоступен: проверка имён пропускается (не отказ).
    """
    try:
        skeleton = _load_template_skeleton()
    except (YamlError, OSError):
        return set()
    facts = skeleton.get("facts") if isinstance(skeleton, dict) else None
    return set(facts) if isinstance(facts, dict) else set()


def _sheet_facts(sheet):
    """Секция `facts` листа требований: (значения, ошибки).

    Формат: `facts: {<имя>: <значение>}` либо
    `facts: {<имя>: {value: …, source: {type, ref}, status: confirmed}}`.
    Это тот же путь, что у `inputs`: ответ человека на факт-вопрос попадает в
    лист, а `INFORMATION.yaml` пишет только `enrich` (один писатель).
    """
    raw = sheet.get("facts") if isinstance(sheet, dict) else None
    if raw in (None, ""):
        return {}, []
    if not isinstance(raw, dict):
        return {}, ["facts: ожидался словарь «имя факта → значение»"]
    known = _fact_names()
    values, errors = {}, []
    for name, block in raw.items():
        name = str(name)
        if known and name not in known:
            errors.append(
                f"facts.{name}: неизвестный факт "
                f"(допустимые: {', '.join(sorted(known))})"
            )
            continue
        block_is_wrapper = (
            isinstance(block, dict)
            and set(block) <= {"value", "source", "status"}
            and bool(block)
        )
        if block_is_wrapper:
            source = block.get("source")
            if source is not None:
                problem = _source_problem(source)
                if problem:
                    errors.append(f"facts.{name}: {problem}")
                    continue
            values[name] = block.get("value")
        else:
            values[name] = block
    return values, errors


def cmd_enrich(args) -> int:
    root = repo_root_from_args(args)
    apply = bool(args.apply)
    if not getattr(args, "is_", None):
        # Без --is: принять листы всех ИС реестра (с текущим статусом).
        return _loop_all_is(args, cmd_enrich, root, "Приём листа")
    try:
        criteria = load_criteria()
        _, systems = load_catalog(root)
    except YamlError as exc:
        print(f"ERROR: {exc}")
        return 1
    by_code = catalog_by_code(systems)
    code = args.is_
    exclusions = _exclusions(root, systems)
    if code in exclusions:
        print(f"ИС: {code}\n  статус: SKIPPED — {_exclusion_text(exclusions[code])}")
        return 0

    entry = by_code.get(code) or {}
    folder_rel, folder, _md, sheet_path = _requirements_paths(root, code, entry)
    info_path = folder / INFORMATION_FILE
    print(f"Приём листа недостающих данных ({'APPLY' if apply else 'DRY-RUN'}): {code}")
    print(f"  лист: {folder_rel}/{DATA_REQUIREMENTS_YAML}")
    if not sheet_path.exists():
        print(
            f"ERROR: нет {folder_rel}/{DATA_REQUIREMENTS_YAML} — "
            f"сначала выполните make requirements IS={code}"
        )
        return 1
    if not info_path.exists():
        print(f"ERROR: нет {folder_rel}/{INFORMATION_FILE} — соберите make prepare-apply")
        return 1
    try:
        sheet = load_yaml(sheet_path)
        info = load_yaml(info_path)
    except YamlError as exc:
        print(f"ERROR: {exc}")
        return 1
    if not isinstance(sheet, dict) or not isinstance(sheet.get("inputs"), dict):
        print(f"ERROR: {DATA_REQUIREMENTS_YAML}: ожидалась секция inputs: словарь")
        return 1
    if not isinstance(info, dict):
        print(f"ERROR: {INFORMATION_FILE}: ожидался словарь верхнего уровня")
        return 1

    # R16: язык свободного текста в листе и ручных секциях — WARN, не отказ.
    scope = [entry] if entry else [{"code": code, "path": folder_rel}]
    for where, message in _language_findings(root, scope):
        print(f"WARN  {where}: {message}")

    accepted = {}
    errors = []
    known_ids = {spec["id"] for spec in _input_specs(criteria)}
    unknown_ids = [
        str(identifier)
        for identifier in (sheet.get("inputs") or {})
        if str(identifier) not in known_ids
    ]
    if unknown_ids:
        print()
        print("ERROR: лист не принят — исправьте и повторите:")
        for identifier in unknown_ids:
            print(
                f"  - неизвестный вход '{identifier}' в {DATA_REQUIREMENTS_YAML} "
                f"(допустимые: {', '.join(sorted(known_ids))})"
            )
        print()
        print(f"{INFORMATION_FILE} не изменён.")
        return 2
    for identifier, block in (sheet.get("inputs") or {}).items():
        identifier = str(identifier)
        problems, normalized = _sheet_input_problems(criteria, identifier, block)
        for problem in problems:
            errors.append(f"{identifier}: {problem}")
        if normalized is not None:
            accepted[identifier] = normalized

    # Факты паспорта (e2e, зависимости, поддержка…): тот же лист, тот же
    # писатель. Имена сверяются с шаблоном INFORMATION.yaml — опечатка в
    # имени факта иначе молча создавала бы новый ключ.
    accepted_facts, fact_errors = _sheet_facts(sheet)
    if fact_errors:
        print()
        print("ERROR: лист не принят — исправьте и повторите:")
        for problem in fact_errors:
            print(f"  - {problem}")
        print()
        print(f"{INFORMATION_FILE} не изменён.")
        return 2

    if errors:
        print()
        print("ERROR: лист не принят — исправьте и повторите:")
        for problem in errors:
            print(f"  - {problem}")
        print()
        print(f"{INFORMATION_FILE} не изменён.")
        return 1

    if not accepted and not accepted_facts:
        print()
        print(f"Заполненных входов нет: принято 0.")
        remaining = _write_requirements(
            root, criteria, code, entry, info, None, apply=apply
        )
        gate = evaluate_gate(info, criteria)
        print(
            f"Гейт без изменений: сценарий {gate['scenario_label']} "
            f"({gate['scenario']}), вердикт {gate['verdict']}"
            + (f" — {gate['reason']}" if gate.get("reason") else "")
        )
        print(
            f"Осталось: {remaining['total']} "
            f"({remaining['blocking']} blocking, {remaining['advisory']} advisory)."
        )
        if not apply:
            print("DRY-RUN: файлы не записаны.")
        if remaining.get("integrity_error"):
            return 1
        return 0

    criteria_inputs = info.get("criteria_inputs")
    criteria_inputs = dict(criteria_inputs) if isinstance(criteria_inputs, dict) else {}
    for identifier, entry_value in accepted.items():
        criteria_inputs[identifier] = entry_value
    old_text = info_path.read_text(encoding="utf-8")
    new_text = old_text
    if accepted:
        new_block = dump_yaml({"criteria_inputs": criteria_inputs})
        new_text, lost_comments = _splice_section_keep_comments(
            new_text, "criteria_inputs", new_block
        )
        if lost_comments:
            print(
                f"WARN: комментарии в criteria_inputs не сохранены (IS={code}): "
                f"{_lost_comments_text(lost_comments)}"
            )
    if accepted_facts:
        facts = info.get("facts")
        facts = dict(facts) if isinstance(facts, dict) else {}
        for name, value in accepted_facts.items():
            facts[name] = value
        new_text, lost_comments = _splice_section_keep_comments(
            new_text, "facts", dump_yaml({"facts": facts})
        )
        if lost_comments:
            print(
                f"WARN: комментарии в facts не сохранены (IS={code}): "
                f"{_lost_comments_text(lost_comments)}"
            )

    print()
    waived_ids = sorted(
        identifier
        for identifier, entry_value in accepted.items()
        if entry_value.get("status") == WAIVED_STATUS
    )
    accepted_ids = sorted(set(accepted) - set(waived_ids))
    if accepted_ids:
        print("Принято: " + ", ".join(accepted_ids) + f" ({len(accepted_ids)}).")
    if accepted_facts:
        print(
            "Факты приняты: " + ", ".join(sorted(accepted_facts))
            + f" ({len(accepted_facts)})."
        )
    if not accepted_ids and not accepted_facts:
        print("Принято: 0.")
    if waived_ids:
        print(
            "Отказ (waive): " + ", ".join(waived_ids) + f" ({len(waived_ids)}). "
            "Вход закрыт осознанным решением: оценка предварительная (R17)."
        )
    if not apply:
        print()
        print(_unified_diff(old_text, new_text, f"{folder_rel}/{INFORMATION_FILE}"))
        print("DRY-RUN: INFORMATION.yaml не изменён.")
        projected = dict(info)
        projected["criteria_inputs"] = criteria_inputs
        if accepted_facts:
            projected_facts = dict(info.get("facts") or {})
            projected_facts.update(accepted_facts)
            projected["facts"] = projected_facts
        gate = evaluate_gate(projected, criteria)
        print(
            f"Гейт после приёма (прогноз): сценарий {gate['scenario_label']} "
            f"({gate['scenario']}), вердикт {gate['verdict']}"
            + (f" — {gate['reason']}" if gate.get("reason") else "")
        )
        return 0

    _atomic_write(info_path, new_text)
    updated = load_yaml(info_path)
    remaining = _write_requirements(
        root,
        criteria,
        code,
        entry,
        updated if isinstance(updated, dict) else info,
        None,
        apply=True,
    )
    gate = evaluate_gate(updated if isinstance(updated, dict) else info, criteria)
    print(
        f"Гейт после приёма: сценарий {gate['scenario_label']} ({gate['scenario']}), "
        f"вердикт {gate['verdict']}"
        + (f" — {gate['reason']}" if gate.get("reason") else "")
    )
    print(
        f"Осталось: {remaining['total']} "
        f"({remaining['blocking']} blocking, {remaining['advisory']} advisory)."
    )
    if remaining["status"] == "complete":
        print(
            f"Недостающих входов нет: {folder_rel}/{DATA_REQUIREMENTS_MD} и "
            f"{DATA_REQUIREMENTS_YAML} удалены. Дальше: make check IS={code}."
        )
    else:
        print(
            f"Лист перегенерирован: {remaining['yaml_path']}. "
            f"Дальше: make check IS={code}."
        )
    if remaining.get("integrity_error"):
        return 1
    _emit_next_steps(root, criteria, args, codes=[code], single=True)
    return 0


