def _wrap_text(text, width):
    """Разбить текст на строки не длиннее width по словам.

    Слово длиннее width режется на куски: контракт «строка не шире width» важнее
    сохранения длинного идентификатора в одной строке.
    """
    text = str(text)
    if width <= 0:
        return [text]
    lines = []
    for raw in text.split("\n"):
        words = []
        for word in raw.split():
            if len(word) <= width:
                words.append(word)
            else:
                words.extend(
                    word[index : index + width] for index in range(0, len(word), width)
                )
        if not words:
            lines.append("")
            continue
        current = words[0]
        for word in words[1:]:
            if len(current) + 1 + len(word) <= width:
                current += " " + word
            else:
                lines.append(current)
                current = word
        lines.append(current)
    return lines


def _info_cell(value):
    """Ячейка таблицы: None -> null, bool -> true/false (как в YAML)."""
    if value is None:
        return "null"
    if value is True:
        return "true"
    if value is False:
        return "false"
    return str(value)


def _print_field(label, text, indent=2):
    """Поле «label: text» с переносом длинного текста по ширине HELP_WIDTH."""
    prefix = " " * indent + label + ": "
    for index, line in enumerate(_wrap_text(text, HELP_WIDTH - len(prefix))):
        print((prefix if index == 0 else " " * len(prefix)) + line)


def _print_wrapped_table(headers, rows, width=HELP_WIDTH):
    """Таблица в markdown-виде с переносом длинных ячеек: ширина <= width."""
    columns = len(headers)
    rows = [[_info_cell(cell) for cell in row] for row in rows]
    if not rows:
        print("  (нет строк)")
        return
    natural = [len(str(header)) for header in headers]
    for row in rows:
        for index, cell in enumerate(row):
            natural[index] = max(natural[index], len(cell))
    budget = width - (3 * columns + 1)
    widths = list(natural)
    while sum(widths) > budget:
        index = max(range(columns), key=lambda item: widths[item])
        # Слово длиннее колонки _wrap_text режет на куски, поэтому нижняя
        # граница — заголовок (и минимум 6), а не самое длинное слово.
        floor = max(len(str(headers[index])), 6)
        if widths[index] <= floor:
            break
        widths[index] -= 1

    def render_row(cells):
        wrapped = [_wrap_text(cell, widths[index]) for index, cell in enumerate(cells)]
        height = max(len(lines) for lines in wrapped)
        rendered = []
        for line_index in range(height):
            parts = []
            for index, lines in enumerate(wrapped):
                part = lines[line_index] if line_index < len(lines) else ""
                parts.append(part.ljust(widths[index]))
            rendered.append("| " + " | ".join(parts) + " |")
        return rendered

    header_lines = render_row(headers)
    print(header_lines[0])
    print("|" + "|".join("-" * (item + 2) for item in widths) + "|")
    for line in header_lines[1:]:
        print(line)
    for row in rows:
        for line in render_row(row):
            print(line)


def _subparser_action(parser):
    for action in parser._actions:
        if isinstance(action, argparse._SubParsersAction):
            return action
    return None


def _leaf_subcommands(parser, prefix=""):
    """Полные имена листовых подкоманд build_parser() (группы раскрываются)."""
    action = _subparser_action(parser)
    if action is None:
        return []
    names = []
    for name, sub in action.choices.items():
        full = f"{prefix}{name}"
        if _subparser_action(sub) is None:
            names.append(full)
        else:
            names.extend(_leaf_subcommands(sub, prefix=f"{full} "))
    return names


def _mtime(path):
    try:
        return path.stat().st_mtime
    except OSError:
        return None


def _index_stale(root, systems, by_code):
    """INDEX.md устарел: файла нет или он старше данных, реестра и паспортов."""
    index_mtime = _mtime(root / "INDEX.md")
    if index_mtime is None:
        return True
    newest = _mtime(root / "catalog.yaml") or 0
    for entry in systems or []:
        code = str(entry.get("code") or "")
        if not code:
            continue
        folder_rel, _legacy = is_folder(root, code, entry)
        for name in (INFORMATION_FILE, "criticality-passport.yaml", "CRITICALITY.md"):
            value = _mtime(root / folder_rel / name)
            if value is not None and value > newest:
                newest = value
    return newest > index_mtime


def _ssot_available(root: Path) -> bool:
    """Клон SSoT есть и не пуст (та же проверка, что в prepare)."""
    ssot_dir = root / SSOT_DIR
    try:
        return ssot_dir.is_dir() and any(ssot_dir.iterdir())
    except OSError:
        return False


def _dochub_clone_dir(root: Path):
    """Каталог клона dochub (None, если клона нет)."""
    clone = root / DOCHUB_DEFAULT_DIR
    try:
        return clone if (clone / "architecture").is_dir() else None
    except OSError:  # pragma: no cover - недоступный каталог
        return None


def _publish_artifact_path(root: Path, code: str):
    """Артефакт этапа publish в рабочем дереве (`.publish/<код>-MR.url|md`).

    Артефакт пишет только `publish --apply`, то есть его наличие — след
    созданной ветки и коммита. Проверяется первым: это чтение файла, без git.
    """
    for base in (Path(root) / DOCHUB_DEFAULT_DIR, Path(root)):
        for suffix in (".url", ".md"):
            path = base / DOCHUB_MR_DIR / f"{code}-MR{suffix}"
            try:
                if path.is_file():
                    return path
            except OSError:  # pragma: no cover - недоступный каталог
                continue
    return None


def _publish_branch_candidates(clone, rel):
    """Ветки клона, в которых паспорт уже закоммичен.

    Нужен, когда Jira-ключ не записан ни в реестре, ни в `INFORMATION.yaml`:
    имя ветки MR (`feature/<ключ>`) тогда не вычислить. `git log --all
    --format=%D -- <путь>` отдаёт декорации коммитов, менявших паспорт, —
    подкоманда `log` есть в allowlist, а `for-each-ref`/`branch` нет.
    """
    ok, output = _run_git(
        [
            "git", "-C", str(clone), "log", "--all", "--format=%D", "--",
            str(rel),
        ],
        clone,
    )
    if not ok:
        return []
    found, seen = [], set()
    for line in output.splitlines():
        for ref in str(line).split(","):
            ref = ref.strip()
            if not ref.startswith("origin/feature/"):
                continue
            branch = ref[len("origin/"):]
            if branch not in seen:
                seen.add(branch)
                found.append(branch)
    return found


def _publish_state(root: Path, code: str, entry=None, systems=None, offline=False):
    """Признак публикации паспорта по трём источникам (от дешёвого к дорогому).

    1. артефакт `.publish/<код>-MR.url|md` в рабочем дереве — публикация была;
    2. ветка MR в клоне dochub (`refs/remotes/origin/<ветка>`, затем
       `ls-remote --heads origin <ветка>`) — ветка создана, но артефакта нет:
       `publish-apply` без `--update` упадёт «ветка уже существует»;
    3. паспорт в `origin/master` (`git show origin/master:<путь>`) — опубликован
       и смержен, публикацию советовать нельзя.

    Имя ветки MR берётся из Jira-ключа реестра (`_publish_branch`); если ключ не
    записан — из клона: ветки, в которых паспорт уже закоммичен
    (`_publish_branch_candidates`).

    Возвращает dict: state (`merged` | `artifact` | `branch` | `no` | None),
    branch (имя ветки MR или None), artifact (путь артефакта или None) и reason
    (почему состояние неизвестно — для подсказки). None — проверить нечем
    (клона нет, сети нет): это не блокер, конвейер локально завершён.

    `offline` (`--no-clone` / `NO_CLONE=1`) отключает только сетевой
    `ls-remote`: локальные чтения клона (`show`, `rev-parse`) остаются, иначе
    «опубликовано» терялось бы в офлайн-прогоне.
    """
    name, contour = split_is_code(code)
    branch = None
    if name and contour and systems is not None:
        task = _publish_task(entry or {}, None, None)
        if task:
            branch = _publish_branch(code, task, systems, None)
    artifact = _publish_artifact_path(root, code)
    if artifact is not None:
        return {
            "state": "artifact",
            "branch": branch,
            "artifact": str(artifact),
            "reason": "описание MR этапа publish есть в рабочем дереве",
        }
    clone = _dochub_clone_dir(root)
    if clone is None:
        return {
            "state": None,
            "branch": branch,
            "artifact": None,
            "reason": "клон dochub не найден — make prepare-apply (клонирование)",
        }
    if not name or not contour:
        return {
            "state": None,
            "branch": None,
            "artifact": None,
            "reason": f"код ИС {code!r} не раскладывается на <имя>.<контур>",
        }
    rel = (_publish_rel_dir(contour, name) / DOCHUB_PASSPORT_FILE).as_posix()
    ok, output = _run_git(
        ["git", "-C", str(clone), "show", f"origin/{DOCHUB_TARGET_BRANCH}:{rel}"],
        clone,
    )
    if ok and output.strip():
        return {
            "state": "merged",
            "branch": branch,
            "artifact": None,
            "reason": (
                f"паспорт есть в origin/{DOCHUB_TARGET_BRANCH} — публикация "
                "смержена"
            ),
        }
    merged_checked = ok
    if not branch and name and contour:
        # Jira-ключ не записан в реестре — имя ветки MR берём из клона: это
        # ветки, в которых паспорт уже закоммичен (`git log --all` по пути
        # паспорта).
        candidates = _publish_branch_candidates(clone, rel)
        if candidates:
            branch = candidates[0]
    branch_exists = False
    branch_checked = False
    if branch:
        ok_ref, ref_out = _run_git(
            [
                "git", "-C", str(clone), "rev-parse", "--verify", "--quiet",
                f"refs/remotes/origin/{branch}",
            ],
            clone,
        )
        if ok_ref and ref_out.strip():
            branch_exists = branch_checked = True
        elif not offline:
            ok_remote, remote_out = _run_git(
                ["git", "-C", str(clone), "ls-remote", "--heads", "origin", branch],
                clone,
            )
            if ok_remote:
                branch_checked = True
                branch_exists = bool(remote_out.strip())
    if branch_exists:
        return {
            "state": "branch",
            "branch": branch,
            "artifact": None,
            "reason": f"ветка {branch} есть в origin, но описания MR нет",
        }
    if merged_checked and branch_checked:
        return {
            "state": "no",
            "branch": branch,
            "artifact": None,
            "reason": "ветки MR и паспорта в origin/master нет",
        }
    return {
        "state": None,
        "branch": branch,
        "artifact": None,
        "reason": (
            "не удалось проверить публикацию в клоне dochub (нет сети или "
            "origin) — проверьте вручную .publish/<код>-MR.md"
        ),
    }


def _passport_published(root: Path, code: str, entry=None, systems=None, offline=False):
    """Опубликован ли паспорт: True/False по трём источникам, None — неизвестно.

    Тонкая обёртка над `_publish_state` для совместимости: `True` — публикация
    была (артефакт, ветка MR или смерженный паспорт), `False` — следов нет,
    `None` — проверить нечем (клона dochub нет или git недоступен).
    """
    state = _publish_state(root, code, entry, systems, offline)["state"]
    if state is None:
        return None
    return state != "no"


def _passport_validated(root: Path, path: Path, code: str, entry, criteria, catalog) -> bool:
    """Паспорт проходит `validate`: те же проверки, что в cmd_validate."""
    return not _passport_validate_errors(
        root, path, code, entry, criteria, catalog
    )


def _sources_checked(findings_path: Path, requirements_path: Path) -> bool:
    """Принят ли SOURCES-FINDINGS.yaml: лист требований не старше findings.

    `make check` перегенерирует DATA-REQUIREMENTS.*, поэтому после приёма
    источников и повторного гейта подсказка перестаёт советовать `make check`
    (иначе она зациклилась бы: check не меняет состояние, кроме листа).
    """
    if not findings_path.exists():
        return True
    if not requirements_path.exists():
        return False
    findings_mtime = _mtime(findings_path)
    requirements_mtime = _mtime(requirements_path)
    if findings_mtime is None or requirements_mtime is None:
        return False
    return requirements_mtime >= findings_mtime


def collect_state(root, criteria, codes=None, offline=False):
    """Состояние конвейера: общие флаги + одна запись на ИС.

    Запись ИС — вход для next_step(): код, сценарий, вердикт гейта, уровень,
    наличие файлов этапов, свежесть паспорта и переоценки. Ничего не выдумывает:
    нет файла — флаг False, нет данных — вердикт «—».
    """
    has_is_config = (root / IS_CONFIG).exists()
    try:
        is_config_codes, is_config_state = _is_codes_state(root)
    except YamlError:
        # Битый is.yaml — это не «файла нет»: make init его не перезапишет.
        is_config_codes, is_config_state = None, "broken"
    has_ssot = _ssot_available(root)
    catalog, systems = {}, []
    try:
        catalog, systems = load_catalog(root)
    except YamlError:
        pass
    by_code = catalog_by_code(systems)
    if codes is None:
        codes = _is_codes(root)
        if codes is None:
            codes = [str(entry.get("code")) for entry in systems]
    exclusions = _exclusions(root, systems)
    index_stale = _index_stale(root, systems, by_code)
    rows = []
    for code in codes:
        entry = by_code.get(code) or {}
        folder_rel, _legacy = is_folder(root, code, entry)
        folder = root / folder_rel
        info_path = folder / INFORMATION_FILE
        info = None
        if info_path.exists():
            try:
                loaded = load_yaml(info_path)
                info = loaded if isinstance(loaded, dict) else None
            except YamlError:
                info = None
        has_information = info is not None
        gate = evaluate_gate(info or {}, criteria)
        body = passport_body(root, entry) if entry else None
        passport = (
            passport_path(root, entry) if entry else folder / "criticality-passport.yaml"
        )
        has_passport = passport.exists()
        passport_stale = False
        if has_passport and has_information:
            info_mtime = _mtime(info_path)
            passport_mtime = _mtime(passport)
            if info_mtime is not None and passport_mtime is not None:
                passport_stale = info_mtime > passport_mtime
        # validate-состояние: паспорт проходит те же проверки, что cmd_validate.
        # Считается только при наличии записи в реестре (иначе проверять нечего).
        passport_validated = False
        if has_passport and entry:
            passport_validated = _passport_validated(
                root, passport, code, entry, criteria, catalog
            )
        # fingerprint_ok: артефакты собраны на текущей версии критериев.
        # Внешние изменения (publish/ssot) гейтятся по этому же признаку, иначе
        # подсказка вела бы к MR с паспортом, посчитанным по старым правилам.
        fingerprint_ok = False
        if has_passport:
            stored = artifact_fingerprint(passport.parent / "CRITICALITY.md")
            fingerprint_ok = (
                stored is not None and stored == criteria_fingerprint(criteria)
            )
        # published: True/False по трём источникам (артефакт → ветка origin →
        # origin/master); None — проверить нечем (не блокер). publish_state
        # уточняет, что именно найдено: от него зависит подсказка (publish или
        # publish-apply --update).
        publish = (
            _publish_state(root, code, entry, systems, offline)
            if has_passport
            else None
        )
        passport_published = None
        if publish is not None:
            passport_published = (
                None if publish["state"] is None else publish["state"] != "no"
            )
        # ssot_enriched: совпадает ли severity в клоне SSoT с целевым;
        # None — клона SSoT нет (проверить нечем, не блокер).
        ssot_enriched = (
            _ssot_enriched(root, code, entry, criteria) if has_passport else None
        )
        # ssot_mr_ready: описание SSoT-MR подготовлено (`<ssot>/.ssot/<код>-MR.md`).
        # Само по себе отсутствие файла НЕ делает SSoT «необогащённым»: если блок
        # `severity` уже совпадает, `make ssot` печатает «изменений нет» и MR не
        # создаёт — подсказка зациклилась бы. Флаг только уточняет причину.
        ssot_mr_ready = (
            (root / SSOT_DEFAULT_DIR / SSOT_MR_DIR / f"{code}-MR.md").exists()
            if has_passport
            else False
        )
        # passport_mr_url: ссылка на dochub-MR из `.publish/<код>-MR.url|md`.
        # Без неё `make ssot` отказывается писать описание MR — подсказка должна
        # назвать эту причину, иначе повторный `make ssot` упирается в ту же
        # ошибку молча.
        passport_mr_url = (
            _mr_url_artifact_read(root, code, DOCHUB_MR_DIR)
            if has_passport
            else ""
        )
        # ssot_mr_url: ссылка на SSoT-MR (`.ssot/<код>-MR.url` в клоне SSoT).
        # Пустая — в тексте треда остаётся `⛔`: публикация заблокирована.
        ssot_mr_url = (
            _mr_url_artifact_read(root, code, SSOT_MR_DIR)
            if has_passport
            else ""
        )
        # Незаполненные поля готового сообщения — из ОДНОГО источника с шапкой
        # action-пакета: `_publication_missing_fields` по отрендеренному тексту.
        # Иначе подсказка next_step («2 поля» — только MR) и шапка пакета
        # («4 поля» — весь текст) называли разные числа.
        message_blocked_fields = []
        if has_passport and info is not None and gate.get("verdict") == "OK":
            message_blocked_fields = _publication_missing_for_message(
                root, code, entry, info, criteria, gate, body, catalog
            )
        # Этап handoff: статус и срок ожидания MCP. Истёкший deadline — признак
        # нерабочего MCP: подсказка обязана вести к фолбэку, а не ждать вечно.
        handoff_status = str(entry.get(HANDOFF_STATUS_FIELD) or "").strip() or None
        handoff_expired, handoff_deadline = _handoff_deadline_state(entry, folder)
        if handoff_status != HANDOFF_STATUS_MCP_REQUESTED:
            handoff_expired = False
        review_value = effective_review_date(entry, body) if entry else None
        review_overdue = False
        if review_value not in (None, ""):
            try:
                review_date = parse_date(review_value)
            except ValueError:
                review_date = None
            if review_date is not None:
                review_overdue = (
                    due_date(review_date, review_period(catalog, entry, criteria))
                    < today()
                )
        level = None
        if body:
            level = body.get("object_criticality_estimation")
        if level in (None, ""):
            level = entry.get("criticality")
        sheet_pending = False
        if has_information:
            try:
                sheet_pending = bool(
                    _requirements_pending(root, code, entry, info, criteria)
                )
            except (YamlError, OSError):
                sheet_pending = False
        rows.append(
            {
                "code": code,
                "scenario": gate["scenario_label"] if has_information else "—",
                "gate": gate["verdict"] if has_information else "—",
                "level": level or "—",
                "missing_blocking": list(gate["blocking"]["missing"]),
                "scenario_switched": bool(gate.get("scenario_switched")),
                "scenario_switch_inputs": list(
                    gate.get("scenario_switch_inputs") or []
                ),
                "has_is_config": has_is_config,
                "is_config_state": is_config_state,
                "is_in_config": bool(
                    is_config_codes is not None and code in is_config_codes
                ),
                "has_ssot": has_ssot,
                "has_folder": folder.is_dir(),
                "has_information": has_information,
                "has_research_plan": (folder / RESEARCH_PLAN).exists(),
                "has_link_map": (folder / LINK_MAP_YAML).exists(),
                "has_sources_findings": (folder / SOURCES_FINDINGS).exists(),
                "has_ssot_links": (
                    root / SSOT_IS_ROOT / code / "links.yaml"
                ).exists(),
                "sources_checked": _sources_checked(
                    folder / SOURCES_FINDINGS,
                    folder / DATA_REQUIREMENTS_YAML,
                ),
                "has_service_findings": (folder / SERVICE_FINDINGS).exists(),
                "has_ask": (folder / ASK_MD).exists(),
                "has_passport": has_passport,
                "passport_stale": passport_stale,
                "passport_validated": passport_validated,
                "fingerprint_ok": fingerprint_ok,
                "passport_published": passport_published,
                "publish": publish,
                "ssot_enriched": ssot_enriched,
                "ssot_mr_ready": ssot_mr_ready,
                "passport_mr_url": passport_mr_url,
                "ssot_mr_url": ssot_mr_url,
                "message_blocked_fields": message_blocked_fields,
                "sheet_pending": sheet_pending,
                "review_overdue": review_overdue,
                "index_stale": index_stale,
                "excluded": code in exclusions,
                # status: confirmed в реестре = подтверждение SRE (гейт handoff).
                "confirmed": str(entry.get("status") or "draft") == "confirmed",
                "handoff_status": handoff_status,
                "handoff_expired": handoff_expired,
                "handoff_deadline": handoff_deadline,
                "thread_link": str(entry.get(THREAD_LINK_FIELD) or "").strip() or None,
            }
        )
    return {
        "root": str(root),
        "has_is_config": has_is_config,
        "has_ssot": has_ssot,
        "index_stale": index_stale,
        "rows": rows,
    }


def next_step(state):
    """Следующий шаг конвейера по состоянию ИС: {command, reason, stage} или None.

    Единая логика для help и для подсказки после команд: правила проверяются по
    порядку, возвращается первое сработавшее.

    Порядок намеренный: сначала локальные проблемы уже рассчитанной ИС
    (паспорт, лист требований, переоценка, INDEX) и только потом глобальные
    (нет is.yaml / нет SSoT). Иначе одна глобальная проблема («нет ssot/»)
    скрывает весь конвейер и подсказка зацикливается.

    Финальные этапы идут строго `publish` → `ssot` → `handoff`: SSoT-MR
    ссылается на dochub-MR (`mr.passport_mr_url`), а тред в
    `#Criticality_assessment` — на оба MR.

    Подсказка не советует разрушительных команд и не зацикливается: признак
    публикации берётся из артефакта `.publish/`, ветки MR в origin и
    `origin/master` (см. `_publish_state`), поэтому «клон на master + открытый
    MR» не даёт повторный `make publish`. Без клона SSoT подсказка ведёт к
    клонированию (`prepare-apply`) или к внешнему клону (`--ssot`), а не к
    `handoff`: без обогащения SSoT этап не пройден.
    """
    if not isinstance(state, dict) or state.get("excluded"):
        return None
    code = str(state.get("code") or "")
    is_arg = f" IS={code}" if code else ""

    # --- папки ИС нет: её создаёт scaffold, а не prepare -------------------
    # Состояние is.yaml различается: файла нет — make init (иначе коды берутся
    # из catalog.yaml и подсказка «ИС есть в is.yaml» была бы ложью); файл есть,
    # но пуст — make scaffold; ИС есть в файле, папки нет — тоже make scaffold.
    if state.get("has_folder") is False:
        is_config_state = state.get("is_config_state")
        if is_config_state == "missing" or (
            is_config_state is None and state.get("has_is_config") is False
        ):
            return {
                "stage": "init",
                "command": "make init",
                "reason": (
                    f"нет конфигурации проекта ({IS_CONFIG}): коды ИС взяты из "
                    "catalog.yaml — создайте каркас проекта"
                ),
            }
        if is_config_state == "empty":
            return {
                "stage": "scaffold",
                "command": f"make scaffold{is_arg}",
                "reason": (
                    f"{IS_CONFIG} пуст — в конвейере нет ни одной ИС; создайте "
                    "каркас ИС"
                ),
            }
        if is_config_state == "ok" and state.get("is_in_config") is False:
            return {
                "stage": "scaffold",
                "command": f"make scaffold{is_arg}",
                "reason": (
                    f"ИС нет в {IS_CONFIG} (код взят из catalog.yaml) — добавьте "
                    "её в список is: или создайте каркас"
                ),
            }
        return {
            "stage": "scaffold",
            "command": f"make scaffold{is_arg}",
            "reason": (
                f"ИС есть в {IS_CONFIG}, но папки is/<код>/ нет — создайте каркас"
            ),
        }

    # --- локальные проверки: данные ИС уже есть ---------------------------
    if state.get("has_information"):
        if state.get("gate") == "BLOCKED":
            if not state.get("has_research_plan"):
                return {
                    "stage": "collect",
                    "command": f"make collect-apply{is_arg}",
                    "reason": "гейт BLOCKED, плана сбора нет (RESEARCH-PLAN.md)",
                }
            # links → обход через MCP → sources. Этапы включаются только когда
            # карточка ИС в SSoT содержит links.yaml: без него `make links`
            # упадёт, и подсказка зациклилась бы. Старые состояния без этих
            # ключей (тесты, чужие вызовы) ведут себя как раньше.
            if state.get("has_ssot_links") and not state.get("has_link_map"):
                return {
                    "stage": "links",
                    "command": f"make links-apply{is_arg}",
                    "reason": (
                        "гейт BLOCKED, карты обхода ссылок нет (LINK-MAP.yaml): "
                        "SSoT links.yaml + catalog + компоненты → маршрут обхода"
                    ),
                }
            if state.get("has_link_map") and not state.get("has_sources_findings"):
                return {
                    "stage": "sources",
                    "command": f"make sources-apply{is_arg}",
                    "reason": (
                        "обход по LINK-MAP.md через MCP (Confluence/Grafana): "
                        "впишите SOURCES-FINDINGS.yaml, затем make sources-apply"
                    ),
                }
            if (
                state.get("has_sources_findings")
                and not state.get("sources_checked")
            ):
                return {
                    "stage": "check",
                    "command": f"make check{is_arg}",
                    "reason": (
                        "источники приняты (SOURCES-FINDINGS.yaml) — пересчитайте "
                        "гейт: какие входы ещё не закрыты"
                    ),
                }
            if not state.get("has_service_findings"):
                return {
                    "stage": "services",
                    "command": f"make services-apply{is_arg}",
                    "reason": "гейт BLOCKED, SERVICE-FINDINGS.md нет",
                }
            # План вопросов: пока ASK.md нет, агент сам решает, что спросить.
            # `ask` раскрывает enum дословно и приносит кандидатов с провенансом,
            # поэтому подсказка ведёт туда раньше `enrich` (значения не выдумывают).
            if not state.get("has_ask"):
                return {
                    "stage": "ask",
                    "command": f"make ask{is_arg}",
                    "reason": (
                        "гейт BLOCKED, плана вопросов нет (ASK.md) — соберите "
                        "вопросы по незакрытым входам"
                    ),
                }
            missing = state.get("missing_blocking") or []
            switched = bool(state.get("scenario_switched"))
            switch_text = "/".join(
                state.get("scenario_switch_inputs") or ["axes_scores", "cia"]
            )
            if switched and set(missing) == {"time_to_impact"}:
                # Сценарий переключён заполнением advisory detailed-входов: без
                # time_to_impact расчёт невозможен, фолбэк на простой запрещён.
                reason = (
                    "не хватает time_to_impact "
                    f"(сценарий переключён заполнением {switch_text})"
                )
            elif missing:
                if len(missing) == 1:
                    reason = f"не хватает 1 обязательного входа: {missing[0]}"
                else:
                    reason = (
                        f"не хватает {len(missing)} обязательных входов: "
                        + ", ".join(missing)
                    )
                if switched:
                    reason += (
                        f" (сценарий переключён заполнением {switch_text})"
                    )
            else:
                reason = "гейт BLOCKED: значения вне допустимых множеств"
            return {
                "stage": "enrich",
                "command": f"make enrich-apply{is_arg}",
                "reason": reason,
            }
        if state.get("gate") == "OK":
            if not state.get("has_passport"):
                return {
                    "stage": "start",
                    "command": f"make start-apply{is_arg} FORCE=1",
                    "reason": "гейт OK, паспорта нет",
                }
            if state.get("passport_stale"):
                return {
                    "stage": "start",
                    "command": f"make start-apply{is_arg} FORCE=1",
                    "reason": "паспорт старше изменений INFORMATION.yaml",
                }
            if state.get("sheet_pending"):
                return {
                    "stage": "enrich",
                    "command": f"make enrich-apply{is_arg}",
                    "reason": (
                        "в листе требований есть заполненные значения, "
                        "не принятые через enrich"
                    ),
                }
            if state.get("review_overdue"):
                return {
                    "stage": "reassess",
                    "command": f"make reassess-apply{is_arg}",
                    "reason": "review_date просрочен",
                }
            if state.get("index_stale"):
                return {
                    "stage": "index",
                    "command": "make index",
                    "reason": (
                        "INDEX.md устарел; порядок финальных этапов — "
                        "validate → index → publish → ssot → handoff"
                    ),
                }
            # Фаза verify: паспорт есть и свежий, но не проходит validate.
            if not state.get("passport_validated"):
                return {
                    "stage": "validate",
                    "command": "make validate",
                    "reason": (
                        "паспорт есть, но validate не пройден: исправьте ERROR "
                        "и повторите make validate"
                    ),
                }
            # Предусловие внешних изменений (publish/ssot): артефакты собраны
            # на текущей версии критериев. Тот же признак проверяет гейт
            # `external_change_gate` — подсказка не ведёт к MR с устаревшим
            # расчётом (порядок: расчёт → валидация → внешние изменения).
            if state.get("fingerprint_ok") is False:
                return {
                    "stage": "start",
                    "command": f"make start-apply{is_arg} FORCE=1",
                    "reason": (
                        "criteria_fingerprint артефактов не совпадает с "
                        "критериями — перегенерируйте артефакты до публикации "
                        "(внешние изменения только после зелёной валидации)"
                    ),
                }
            # Фаза publish: validate пройден, но следов публикации нет.
            #
            # Признак публикации берётся из трёх источников (см. _publish_state):
            # артефакт `.publish/<код>-MR.*` → ветка MR в origin → паспорт в
            # origin/master. Ветка без артефакта — публикация была, но обычный
            # `publish-apply` упадёт «ветка уже существует»: нужен `--update`.
            # None (клона dochub нет / нет сети) не блокирует конвейер: проверить
            # публикацию нечем, в причине это сказано явно.
            #
            # publish идёт ПЕРВЫМ: SSoT-MR в «Основании» ссылается на dochub-MR
            # (`mr.passport_mr_url`), поэтому паспорт публикуется раньше, чем
            # обогащается SSoT.
            publish = state.get("publish") if isinstance(state.get("publish"), dict) else {}
            publish_state = publish.get("state")
            if publish_state is None:
                # Совместимость: состояние передано только три-состоянием.
                published = state.get("passport_published")
                publish_state = (
                    "no" if published is False
                    else "artifact" if published is True
                    else None
                )
            if publish_state == "no":
                return {
                    "stage": "publish",
                    "command": f"make publish{is_arg} TASK=<key>",
                    "reason": (
                        "паспорт провалидирован, но не опубликован в dochub "
                        "(make publish — план, make publish-apply — ветка и коммит)"
                    ),
                }
            if publish_state == "branch":
                branch = str(publish.get("branch") or "<ветка>")
                return {
                    "stage": "publish",
                    "command": (
                        f"make publish-apply{is_arg} TASK=<key> UPDATE=1"
                    ),
                    "reason": (
                        f"паспорт уже опубликован: ветка {branch} есть в origin, "
                        "а описания MR (.publish/<код>-MR.md) нет — обновите "
                        "существующую ветку через --update (обычный publish-apply "
                        "упадёт «ветка уже существует»)"
                    ),
                }
            # Фаза ssot: паспорт опубликован в dochub, но критичность в SSoT ещё
            # не приведена к паспорту. Идёт ПОСЛЕ publish: SSoT-MR без ссылки на
            # dochub-MR не создаётся.
            if state.get("ssot_enriched") is False:
                reason = (
                    "критичность в SSoT расходится с паспортом — обогатите SSoT "
                    "после публикации паспорта (make ssot — план, "
                    "make ssot-apply — ветка и коммит)"
                )
                if not state.get("ssot_mr_ready"):
                    reason += "; описание SSoT-MR (.ssot/<код>-MR.md) ещё не подготовлено"
                if state.get("passport_mr_url") == "":
                    reason += (
                        "; ссылка на dochub-MR не записана "
                        "(.publish/<код>-MR.url) — впишите её после пуша MR: "
                        "без неё описание SSoT-MR не создаётся"
                    )
                if publish_state is None:
                    reason += (
                        "; публикация в dochub не проверена — "
                        + str(
                            publish.get("reason")
                            or "клон dochub не найден — make prepare-apply"
                        )
                    )
                return {
                    "stage": "ssot",
                    "command": f"make ssot{is_arg} TASK=<key>",
                    "reason": reason,
                }
            # Фаза ssot не проверена: клона SSoT нет. Без обогащения SSoT этап
            # не пройден, поэтому handoff не советуется — подсказка ведёт к
            # клонированию или к внешнему клону через --ssot. Клон есть, но
            # severity не прочитан (ssot_enriched=None при has_ssot=True) —
            # handoff не блокируем, причину называем ниже.
            if state.get("ssot_enriched") is None and state.get("has_ssot") is not True:
                return {
                    "stage": "ssot",
                    "command": f"make prepare-apply{is_arg}",
                    "reason": (
                        "этап SSoT не выполнен: клон SSoT не найден — "
                        f"make prepare-apply{is_arg} (клонирует SSoT) или "
                        f"make ssot{is_arg} TASK=<key> SSOT=<путь> (--ssot) для "
                        "внешнего клона; тред в #Criticality_assessment — только "
                        "после обогащения SSoT (текст: "
                        "actions/rocketchat-message.md)"
                    ),
                }
            # Фаза handoff: паспорт опубликован и SSoT обогащён — остаётся тред
            # согласования в #Criticality_assessment со ссылкой на оба MR.
            # Признак завершения handoff — `status: confirmed` в реестре
            # (подтверждение SRE); иначе этап пройденным не считается.
            if (
                not state.get("confirmed")
                and state.get("passport_published") is not False
                and state.get("ssot_enriched") is not False
            ):
                # MCP-канал в ожидании: подсказка не советует новый запрос
                # (это дубль), а ведёт к handoff-result или к фолбэку. Истёк
                # deadline — MCP считается нерабочим: команда с RESUME=1 сама
                # уйдёт в REST (mcp_timeout).
                handoff_status = state.get("handoff_status")
                if handoff_status == HANDOFF_STATUS_PUBLISHED:
                    # Тред отправлен: approve_link уже записан handoff'ом, ждать
                    # ответа в треде не нужно — гейт это мерж MR. finalize
                    # проставит даты (от generated_at) и status: confirmed.
                    return {
                        "stage": "finalize",
                        "command": f"make finalize IS={code}",
                        "reason": (
                            "тред отправлен в #Criticality_assessment; "
                            "approve_link = ссылка на тред уже в реестре. "
                            "Подтверждение фиксируется мержем MR — finalize "
                            "проставит даты (от даты генерации) и "
                            "status: confirmed"
                        ),
                    }
                if handoff_status == HANDOFF_STATUS_MCP_REQUESTED:
                    deadline = state.get("handoff_deadline") or "неизвестен"
                    if state.get("handoff_expired"):
                        return {
                            "stage": "handoff",
                            "command": f"make handoff IS={code} SEND=auto RESUME=1",
                            "reason": (
                                f"MCP не ответил до {deadline} — срок истёк, "
                                "фолбэк на REST API (mcp_timeout) с поиском "
                                "своего сообщения в канале"
                            ),
                        }
                    return {
                        "stage": "handoff",
                        "command": f"make handoff IS={code} RESUME=1",
                        "reason": (
                            f"MCP-запрос отправлен, ждём handoff-result до "
                            f"{deadline}; если исполнитель не ответил — "
                            "RESUME=1 принудительно уводит в REST API"
                        ),
                    }
                # Предусловие `handoff`: в готовом тексте треда нет `⛔`. Список
                # полей приходит из `collect_state` — он же печатается в шапке
                # `actions/rocketchat-message.md` (`_publication_missing_fields`
                # по отрендеренному тексту), поэтому числа совпадают.
                blocked_fields = list(state.get("message_blocked_fields") or [])
                blocked_text = _publication_blocked_text(blocked_fields)
                if state.get("passport_published") is None:
                    reason = (
                        "SSoT обогащён; публикация паспорта в dochub не "
                        "проверена — "
                        + str(
                            publish.get("reason")
                            or "клон dochub не найден — make prepare-apply"
                        )
                        + ". Тред согласования в "
                        "#Criticality_assessment (текст: "
                        "actions/rocketchat-message.md): отправить автоматически? "
                        f"make handoff IS={code} SEND=auto | оставить вручную "
                        "(SEND=manual)"
                    )
                elif state.get("ssot_enriched") is None:
                    reason = (
                        "паспорт опубликован в dochub; SSoT-клон есть, но "
                        "severity в base.yaml прочитать не удалось — проверьте "
                        "блок severity вручную. Затем тред согласования в "
                        "#Criticality_assessment (текст: "
                        "actions/rocketchat-message.md): отправить автоматически? "
                        f"make handoff IS={code} SEND=auto | оставить вручную "
                        "(SEND=manual)"
                    )
                else:
                    reason = (
                        "паспорт опубликован в dochub, SSoT обогащён — "
                        "тред согласования в #Criticality_assessment "
                        "(текст: actions/rocketchat-message.md): отправить "
                        f"автоматически? make handoff IS={code} SEND=auto | "
                        "оставить вручную (SEND=manual)"
                    )
                return {
                    "stage": "handoff",
                    "command": f"make handoff IS={code} SEND=auto",
                    "reason": reason + blocked_text,
                }

    # --- глобальные проверки: проект в целом ------------------------------
    if not state.get("has_is_config"):
        return {
            "stage": "init",
            "command": "make init",
            "reason": "нет конфигурации проекта (is.yaml)",
        }
    if not state.get("has_ssot"):
        # prepare-apply склонирует SSoT (этап 1); без клона данные ИС не
        # обновляются. Внешний клон — через `make ssot SSOT=<путь>` (--ssot).
        # Этап SSoT не считается выполненным, пока клона нет.
        return {
            "stage": "prepare",
            "command": "make prepare-apply",
            "reason": (
                "клон SSoT не найден — make prepare-apply склонирует SSoT "
                "(или make ssot SSOT=<путь>, --ssot, для внешнего клона); "
                "этап SSoT без клона не выполнен"
            ),
        }
    if not state.get("has_information"):
        return {
            "stage": "prepare",
            "command": "make prepare-apply",
            "reason": "нет рабочего файла данных (INFORMATION.yaml)",
        }
    return None


def project_next_step(root: Path):
    """Следующий шаг проекта целиком — когда ни одной ИС в конвейере нет.

    Используется, когда список ИС пуст (свежий проект): подсказка должна вести
    к `make init` / `make scaffold`, а не молчать и не повторять `make prepare`.
    """
    if not (root / IS_CONFIG).exists():
        return {
            "stage": "init",
            "command": "make init",
            "reason": "нет конфигурации проекта (is.yaml)",
        }
    if not _is_codes(root):
        return {
            "stage": "scaffold",
            "command": "make scaffold IS=<код>",
            "reason": "is.yaml пуст — в конвейере нет ни одной ИС",
        }
    return None


def _next_step_text(state):
    """«команда — причина» или None, если шага нет."""
    step = next_step(state)
    if step is None:
        return None
    return f"{step['command']} — {step['reason']}"


def _next_step_line(state):
    text = _next_step_text(state)
    if text is None:
        return None
    return f"Следующий шаг: {text}"


def _state_next_cell(state):
    if state.get("excluded"):
        return "— (SKIPPED)"
    step = next_step(state)
    return step["command"] if step else "все этапы пройдены"


def _emit_next_steps(root, criteria, args, codes=None, single=False):
    """Напечатать подсказку следующего шага (не ломает команду при ошибке чтения).

    Отключается флагами --no-next и --quiet (для скриптов и make-целей).
    criteria=None — файл критериев читается здесь (командам он может быть не нужен).
    """
    if getattr(args, "no_next", False) or getattr(args, "quiet", False):
        return
    try:
        if criteria is None:
            criteria = load_criteria()
        offline = bool(getattr(args, "no_clone", False)) or bool(
            os.environ.get("NO_CLONE")
        )
        rows = collect_state(root, criteria, codes, offline=offline)["rows"]
    except (YamlError, OSError, KeyError, TypeError, ValueError) as exc:
        print(f"WARN: подсказка следующего шага недоступна: {exc}")
        return
    if not rows:
        step = project_next_step(root)
        if step:
            print()
            print(f"Следующий шаг: {step['command']} — {step['reason']}")
        return
    print()
    if single:
        row = rows[0]
        if row.get("excluded"):
            print(f"{row['code']}: SKIPPED — ИС исключена из расчёта")
            return
        line = _next_step_line(row)
        print(line if line else f"{row['code']}: все этапы пройдены")
        return
    pending = [
        (row["code"], _next_step_text(row))
        for row in rows
        if _next_step_text(row) is not None
    ]
    if not pending:
        print("Все этапы пройдены.")
        return
    print("Следующие шаги:")
    for code, text in pending:
        print(f"  {code}: {text}")


def _info_source(path, kind=None):
    suffix = f" (kind: {kind})" if kind else ""
    print(f"источник: {CRITERIA_REL}#{path}{suffix}")


def _info_absent(path):
    print("  секция отсутствует в критериях")
    print(f"  источник: {CRITERIA_REL}#{path} (kind: нет секции)")


def _render_info_levels(criteria):
    print("Уровни критичности (levels)")
    block = criteria.get("levels")
    if not isinstance(block, dict) or not block:
        _info_absent("levels")
        return
    order = block.get("order") or []
    rank = block.get("rank") or {}
    definitions = block.get("definitions") or {}
    _print_field(
        "Порядок возрастания", " < ".join(str(item) for item in order)
    )
    rows = [
        [level, rank.get(level, "—"), definitions.get(level, "—")] for level in order
    ]
    _print_wrapped_table(["уровень", "rank", "определение"], rows)
    extra = block.get("dochub_extra_level") or {}
    if extra:
        _print_field(
            "dochub_extra_level",
            f"{extra.get('value')} -> {extra.get('mapping_to_ssot')} "
            f"(kind: {extra.get('kind')}; {extra.get('note')})",
        )
    mapping = (block.get("dochub_to_ssot") or {}).get("map") or {}
    if mapping:
        print("  Как уровень калькулятора/dochub превращается в уровень паспорта:")
        _print_wrapped_table(
            ["dochub / калькулятор", "паспорт (SSoT)"],
            [[key, value] for key, value in mapping.items()],
        )
    _info_source("levels", block.get("kind"))


def _render_info_scenarios(criteria):
    print("Сценарии оценки (scenarios)")
    block = criteria.get("scenarios")
    if not isinstance(block, dict) or not block:
        _info_absent("scenarios")
        return
    rows = []
    for name in ("simple", "complex"):
        part = block.get(name) or {}
        if not part:
            continue
        inputs = part.get("inputs") or []
        rows.append(
            [
                part.get("title") or name,
                part.get("method") or "—",
                f"{len(inputs)}: " + ", ".join(str(item) for item in inputs),
            ]
        )
    _print_wrapped_table(["сценарий", "метод", "обязательные входы"], rows)
    selection = (block.get("selection") or {}).get("rule")
    if selection:
        _print_field("selection.rule", selection)
    for name in ("simple", "complex"):
        rule = (block.get(name) or {}).get("rule")
        if rule:
            _print_field(f"{name}.rule", rule)
    if block.get("rationale"):
        _print_field("rationale", block.get("rationale"))
    _info_source("scenarios", block.get("kind"))


def _render_info_inputs(criteria):
    print("Обязательные входы (inputs.required)")
    block = criteria.get("inputs")
    if not isinstance(block, dict) or not block:
        _info_absent("inputs")
        return
    required = block.get("required") or []
    if not required:
        _info_absent("inputs.required")
        return
    rows = []
    for item in required:
        if not isinstance(item, dict):
            continue
        rows.append(
            [
                item.get("id"),
                item.get("title"),
                item.get("method"),
                "да" if item.get("blocking") else "нет",
            ]
        )
    _print_wrapped_table(["id", "title", "method", "blocking"], rows)
    print()
    print("  Подробно по каждому входу (acceptable / definition / why / where / whom / confirm):")
    for item in required:
        if not isinstance(item, dict):
            continue
        print(f"  {item.get('id')} — {item.get('title')}")
        for key in ("acceptable", "definition", "why", "where", "whom", "confirm"):
            value = item.get(key)
            if value in (None, ""):
                continue
            indent = "    " + key + ": "
            for index, line in enumerate(_wrap_text(value, HELP_WIDTH - len(indent))):
                print((indent if index == 0 else " " * len(indent)) + line)
        print()
    gate = block.get("gate") or {}
    if gate.get("rule"):
        _print_field("inputs.gate", gate.get("rule"))
    if block.get("guidance_kind"):
        _print_field(
            "guidance",
            "пояснения полей — инженерное решение репозитория "
            f"(kind: {block.get('guidance_kind')}, "
            f"status: {block.get('guidance_status')})",
        )
    _info_source("inputs", block.get("kind"))


def _render_info_enums(criteria):
    print("Enum-значения (enum_selection)")
    block = criteria.get("enum_selection")
    if not isinstance(block, dict) or not block:
        _info_absent("enum_selection")
        return
    consumers = block.get("consumers_type") or {}
    values = consumers.get("values") or []
    print(f"  consumers_type — {len(values)} значений:")
    for index, value in enumerate(values, 1):
        print(f"    {index}. {value}")
    rule = (consumers.get("selection_rule") or {}).get("rule")
    if rule:
        _print_field("selection_rule (дословно)", rule)
    impact = block.get("outage_impact") or {}
    impact_values = impact.get("values") or []
    print(f"  outage_impact — {len(impact_values)} значений:")
    for index, value in enumerate(impact_values, 1):
        print(f"    {index}. {value}")
    severity = impact.get("severity_order") or {}
    if severity.get("order"):
        print(
            "  severity_order: "
            + ", ".join(str(item) for item in severity.get("order"))
        )
    _info_source(
        "enum_selection", consumers.get("kind") or impact.get("kind")
    )


def _render_info_express(criteria):
    print("Экспресс-метод (express_method)")
    block = criteria.get("express_method")
    if not isinstance(block, dict) or not block:
        _info_absent("express_method")
        return
    formula = block.get("formula") or {}
    if formula:
        print("  Формула (formula):")
        for key in ("load", "time", "score", "level"):
            if formula.get(key):
                _print_field(key, formula.get(key), indent=4)
    client = block.get("client_coefficients") or {}
    if client.get("map"):
        print("  Коэффициенты типа клиентов (client_coefficients.map):")
        _print_wrapped_table(
            ["тип клиентов", "коэф."],
            [[key, value] for key, value in client.get("map").items()],
        )
    impact = block.get("impact_coefficients") or {}
    categories = (block.get("impact_categories") or {}).get("map") or {}
    if impact.get("map"):
        print("  Коэффициенты влияния (impact_coefficients.map + impact_categories):")
        _print_wrapped_table(
            ["влияние при простое", "коэф.", "категория"],
            [
                [key, value, categories.get(key, "—")]
                for key, value in impact.get("map").items()
            ],
        )
    intervals = block.get("intervals") or {}
    if intervals.get("items"):
        print("  Интервалы (intervals.items):")
        _print_wrapped_table(
            ["#", "lo", "hi", "label"],
            [
                [item.get("index"), item.get("lo"), item.get("hi"), item.get("label")]
                for item in intervals.get("items")
                if isinstance(item, dict)
            ],
        )
    matrix = block.get("matrix") or {}
    if matrix.get("rows"):
        print("  Матрица (matrix.rows; первая подходящая severity задаёт балл):")
        rows = [row for row in matrix.get("rows") or [] if isinstance(row, dict)]
        count = max((len(row.get("scores") or []) for row in rows), default=0)
        headers = ["severity"] + [f"#{index}" for index in range(count)]
        _print_wrapped_table(
            headers,
            [[row.get("severity")] + list(row.get("scores") or []) for row in rows],
        )
    score_map = (block.get("score_to_level") or {}).get("map") or {}
    if score_map:
        print("  Балл → уровень калькулятора (score_to_level.map):")
        _print_wrapped_table(
            ["балл", "код уровня"], [[key, value] for key, value in score_map.items()]
        )
    deviations = block.get("deviations_from_artifact") or []
    if deviations:
        print("  Отклонения от артефакта (deviations_from_artifact):")
        for item in deviations:
            for index, line in enumerate(_wrap_text(item, HELP_WIDTH - 6)):
                print(("    - " if index == 0 else "      ") + line)
    numerics = block.get("numerics") or {}
    if numerics:
        print(
            "  numerics: round_digits="
            f"{numerics.get('round_digits')} (kind: {numerics.get('kind')}, "
            f"status: {numerics.get('status')})"
        )
    _info_source("express_method", block.get("kind"))


def _render_info_detailed(criteria):
    print("Детальный метод (axes / cia / impact_matrix / final_matrix)")
    levels = level_order(criteria)
    axes = criteria.get("axes")
    if not isinstance(axes, dict) or not axes:
        print("  axes: секция отсутствует в критериях")
    else:
        print("  Оси (axes.items), шкала 0..4:")
        for item in axes.get("items") or []:
            if not isinstance(item, dict):
                continue
            print(f"    {item.get('id')} — {item.get('title')}")
            scale = item.get("scale") or {}
            for score in range(5):
                text = scale.get(str(score))
                if text is not None:
                    print(f"        {score}: {text}")
        _print_field(
            "aggregation",
            f"{axes.get('aggregation')} — {axes.get('aggregation_note')}",
        )
        _info_source("axes", axes.get("kind"))
    cia = criteria.get("cia")
    if not isinstance(cia, dict) or not cia:
        print("  cia: секция отсутствует в критериях")
    else:
        parameters = cia.get("parameters") or []
        cia_levels = cia.get("levels") or []
        print(
            "  CIA: параметры "
            + ", ".join(str(item) for item in parameters)
            + "; уровни "
            + ", ".join(str(item) for item in cia_levels)
        )
        weights = cia.get("weights") or {}
        if weights:
            print(
                "  Веса (cia.weights): "
                + ", ".join(
                    f"{key}={weights.get(key)}"
                    for key in ("low", "medium", "high")
                    if key in weights
                )
            )
        if cia.get("formula"):
            print("  Формула: " + str(cia.get("formula")))
        ranges = (cia.get("protection_levels") or {}).get("ranges") or []
        if ranges:
            print("  Пороги уровня защищённости (protection_levels.ranges):")
            _print_wrapped_table(
                ["уровень", "min", "max", "max_inclusive"],
                [
                    [
                        item.get("level"),
                        item.get("min"),
                        item.get("max"),
                        item.get("max_inclusive"),
                    ]
                    for item in ranges
                    if isinstance(item, dict)
                ],
            )
        protection_map = (cia.get("protection_to_level") or {}).get("map") or {}
        if protection_map:
            print("  Защищённость → бизнес-уровень (protection_to_level.map):")
            _print_wrapped_table(
                ["защищённость", "бизнес-уровень"],
                [[key, value] for key, value in protection_map.items()],
            )
        _info_source("cia", cia.get("kind"))
    impact = criteria.get("impact_matrix")
    if not isinstance(impact, dict) or not impact.get("cells"):
        print("  impact_matrix: секция отсутствует в критериях")
    else:
        buckets = time_bucket_columns(criteria)
        print("  Матрица impact (строка — max по осям, колонка — время):")
        rows = []
        for score in range(5):
            row = (impact.get("cells") or {}).get(str(score)) or {}
            rows.append([score] + [row.get(bucket, "—") for bucket in buckets])
        _print_wrapped_table(["оценка"] + buckets, rows)
        _info_source("impact_matrix", impact.get("kind"))
    final = criteria.get("final_matrix")
    if not isinstance(final, dict) or not final.get("cells"):
        print("  final_matrix: секция отсутствует в критериях")
    else:
        protections = [
            str(item.get("level"))
            for item in ((criteria.get("cia") or {}).get("protection_levels") or {}).get(
                "ranges"
            )
            or []
            if isinstance(item, dict)
        ]
        print("  Финальная матрица (бизнес × защищённость):")
        rows = [
            [business]
            + [
                (final.get("cells") or {}).get(business, {}).get(protection, "—")
                for protection in protections
            ]
            for business in levels
        ]
        _print_wrapped_table(["бизнес"] + protections, rows)
        if final.get("note"):
            _print_field("aggregation", final.get("note"))
        _info_source("final_matrix", final.get("kind"))


