def _info_data(criteria, sections):
    """Те же данные для --json: секции критериев дословно, без пересборки."""
    data = {"source": CRITERIA_REL, "sections": {}}
    for name in sections:
        paths = INFO_SECTION_PATHS[name]
        if len(paths) == 1:
            value = criteria.get(paths[0])
            data["sections"][name] = value if value is not None else None
        else:
            data["sections"][name] = {path: criteria.get(path) for path in paths}
    return data


def cmd_info(args) -> int:
    try:
        criteria = load_criteria()
    except YamlError as exc:
        print(f"ERROR: {exc}")
        return 1
    section = getattr(args, "section", None)
    if section and section not in INFO_SECTIONS:
        print(
            f"ERROR: неизвестная секция {section!r}. Допустимые: "
            + ", ".join(INFO_SECTIONS)
        )
        return 2
    sections = [section] if section else list(INFO_SECTIONS)
    if getattr(args, "json", False):
        print(
            json.dumps(
                _info_data(criteria, sections),
                ensure_ascii=False,
                indent=2,
                default=str,
            )
        )
        return 0
    meta = criteria.get("meta") or {}
    print("Критерии оценки критичности ИС — пояснения")
    shown = _criteria_display_path()
    if len(f"Файл: {shown}") <= 100:
        print(f"Файл: {shown}")
    else:
        print("Файл:")
        print(f"  {shown}")
    print(
        f"schema_version: {criteria.get('schema_version')}, "
        f"статус: {meta.get('status', '—')}, обновлено: {meta.get('updated', '—')}"
    )
    print()
    for name in sections:
        INFO_RENDERERS[name](criteria)
        print()
    return 0


# ---------------------------------------------------------------------------
# GitLab API: описание MR и ссылка на MR
# ---------------------------------------------------------------------------
# Единственное сетевое место скилла. Git не пропускает переводы строк в
# push-опциях («must not contain a NUL or LF character»), поэтому полное
# описание из шаблона доезжает до MR только через API: после пуша описание
# сверяется (`GET /merge_requests`) и при расхождении переписывается
# (`PUT /projects/:id/merge_requests/:iid`). Токен — `GITLAB_TOKEN`; без него
# пуш выполняется, но описание не верифицируется (печатается WARN).
# Проект и адрес API не хардкодятся: берутся из `remote.origin.url` клона.

GITLAB_TOKEN_ENV = "GITLAB_TOKEN"
GITLAB_API_SUFFIX = "/api/v4"
GITLAB_TIMEOUT = 30
MR_WEB_MARK = "/-/merge_requests/"
MR_URL_RE = re.compile(r"https://\S+/-/merge_requests/\d+")
# Проверка дублей MR: сколько открытых MR просматривать за один запрос.
MR_DUPLICATE_SEARCH_LIMIT = 100
# Строки таблицы расхождений: «ничего не найдено» и «проверка не выполнялась».
# Секция шаблона рендерится всегда — пропавший заголовок ломает сверку описания.
MR_DUPLICATE_NO_ROWS = "| — | — | — | открытых MR по этому паспорту не найдено |"
MR_DUPLICATE_SKIPPED = (
    "| — | — | — | проверка не выполнялась: --update обновляет существующий MR |"
)


def _git_remote_url(clone):
    """`remote.origin.url` клона, прочитанный из `.git/config` без запуска git.

    `git config` вне allowlist git-подкоманд (клоны только читаются), поэтому
    конфиг разбирается как обычный текстовый файл.
    """
    config = Path(clone) / ".git" / "config"
    try:
        text = config.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return None
    section = None
    for raw in text.splitlines():
        line = raw.strip()
        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip()
            continue
        if section != 'remote "origin"':
            continue
        if line.startswith("url") and "=" in line:
            return line.split("=", 1)[1].strip()
    return None


def _gitlab_web_project(remote_url):
    """(web_base, project_path) из URL remote: `https://host/group/proj.git`."""
    text = str(remote_url or "").strip()
    if not text:
        return None, None
    if GIT_SSH_SCP_RE.match(text):
        host, path = text.split(":", 1)
        host = host.split("@", 1)[1]
    elif text.startswith(("https://", "ssh://")):
        parts = urlsplit(text)
        host, path = parts.hostname, parts.path
    else:
        return None, None
    path = (path or "").strip("/")
    if path.endswith(".git"):
        path = path[: -len(".git")]
    if not host or not path:
        return None, None
    return f"https://{host}", path


def _gitlab_api(clone):
    """(api_base, project_id, web_base) для клона; (None, None, None) — нет remote."""
    web, project = _gitlab_web_project(_git_remote_url(clone))
    if not web:
        return None, None, None
    return f"{web}{GITLAB_API_SUFFIX}", quote(project, safe=""), web


def _gitlab_conn(clone, criteria=None, repo_key="dochub"):
    """(api_base, project_path, web_base) для клона, с фолбэком на критерии.

    Основной источник — `remote.origin.url` клона. Если remote не разобран
    (клон не git-репозиторий, remote без хоста), берутся
    `criteria.external_refs.repos.<repo_key>.gitlab_base` (адрес инстанса) и
    `gitlab_project` (путь проекта). Так проверка дублей MR работает без
    правки кода: перенос инструмента в другой контур меняет только критерии.
    """
    web, project = _gitlab_web_project(_git_remote_url(clone))
    if web and project:
        return f"{web}{GITLAB_API_SUFFIX}", project, web
    block = (criteria or {}).get("external_refs") or {}
    repos = block.get("repos") if isinstance(block, dict) else None
    item = repos.get(repo_key) if isinstance(repos, dict) else None
    if not isinstance(item, dict):
        return None, None, None
    base = str(item.get("gitlab_base") or "").strip().rstrip("/")
    project = str(item.get("gitlab_project") or "").strip().strip("/")
    if not base or not project:
        return None, None, None
    return f"{base}{GITLAB_API_SUFFIX}", project, base


def _gitlab_request(method, url, token, payload=None, timeout=GITLAB_TIMEOUT):
    """Запрос к GitLab API. Возвращает (ok, разобранный JSON или текст ошибки)."""
    data = None
    headers = {"PRIVATE-TOKEN": token, "Accept": "application/json"}
    if payload is not None:
        data = json.dumps(payload).encode("utf-8")
        headers["Content-Type"] = "application/json"
    request = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            body = response.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as exc:
        try:
            detail = exc.read().decode("utf-8", "replace")
        except OSError:
            detail = ""
        return False, f"HTTP {exc.code}: {detail[:300]}"
    except (urllib.error.URLError, OSError, ValueError) as exc:
        return False, f"{type(exc).__name__}: {exc}"
    try:
        return True, json.loads(body) if body.strip() else {}
    except ValueError:
        return True, body


def _gitlab_mr_for_branch(clone, branch, token):
    """Открытый MR по source-ветке: (ok, mr|None, сообщение)."""
    api, project, _web = _gitlab_api(clone)
    if not api:
        return False, None, f"не разобран remote.origin.url клона {clone}"
    url = (
        f"{api}/projects/{project}/merge_requests"
        f"?state=opened&source_branch={quote(str(branch), safe='')}&per_page=1"
    )
    ok, data = _gitlab_request("GET", url, token)
    if not ok:
        return False, None, f"GET merge_requests: {data}"
    items = data if isinstance(data, list) else []
    if not items:
        return False, None, f"открытый MR для ветки {branch} не найден"
    return True, items[0], ""


def _gitlab_open_mrs(conn, token, code):
    """Открытые MR проекта, найденные по коду ИС: (ok, items, сообщение).

    `search` — полнотекстовый поиск GitLab по заголовку/описанию MR, поэтому
    дополнительно каждый MR фильтруется по факту правки файла паспорта
    (`_gitlab_mr_changes`). Лимит страницы — MR_DUPLICATE_SEARCH_LIMIT.
    """
    api, project, _web = conn
    if not api or not project:
        return False, [], "не определён GitLab-проект"
    url = (
        f"{api}/projects/{quote(str(project), safe='')}/merge_requests"
        f"?state=opened&search={quote(str(code), safe='')}"
        f"&per_page={MR_DUPLICATE_SEARCH_LIMIT}"
    )
    ok, data = _gitlab_request("GET", url, token)
    if not ok:
        return False, [], f"GET merge_requests: {data}"
    return True, data if isinstance(data, list) else [], ""


def _gitlab_mr_changes(conn, token, iid):
    """Список изменённых файлов MR: (ok, paths, сообщение)."""
    api, project, _web = conn
    url = (
        f"{api}/projects/{quote(str(project), safe='')}/merge_requests/"
        f"{iid}/changes"
    )
    ok, data = _gitlab_request("GET", url, token)
    if not ok:
        return False, [], f"GET merge_requests/{iid}/changes: {data}"
    changes = (data or {}).get("changes") if isinstance(data, dict) else None
    paths = []
    for item in changes or []:
        if not isinstance(item, dict):
            continue
        for key in ("new_path", "old_path"):
            value = item.get(key)
            if value and value not in paths:
                paths.append(value)
    return True, paths, ""


def _gitlab_file_text(conn, token, path, ref):
    """Содержимое файла на ветке MR: (ok, text, сообщение)."""
    api, project, _web = conn
    url = (
        f"{api}/projects/{quote(str(project), safe='')}/repository/files/"
        f"{quote(str(path), safe='')}/raw?ref={quote(str(ref), safe='')}"
    )
    ok, data = _gitlab_request("GET", url, token)
    if not ok:
        return False, None, f"GET repository/files: {data}"
    return True, data if isinstance(data, str) else "", ""


def _load_yaml_text(text, name):
    """YAML из строки (файл на ветке MR приходит текстом, не путём)."""
    if _pyyaml is not None:
        try:
            return _pyyaml.load(text, Loader=_SSOT_LOADER)
        except Exception as exc:  # noqa: BLE001 - сообщение PyYAML информативно
            raise YamlError(f"{name}: {exc}") from exc
    return parse_yaml(text, name)


def _passport_body(doc):
    """(ключ, тело) паспорта dochub из разобранного YAML; (None, {}) — не паспорт."""
    if not isinstance(doc, dict) or len(doc) != 1:
        return None, {}
    section = next(iter(doc.values()))
    if not isinstance(section, dict) or len(section) != 1:
        return None, {}
    body = next(iter(section.values()))
    return next(iter(section)), body if isinstance(body, dict) else {}


def _publish_cell(value):
    """Ячейка таблицы расхождений: пустое значение — «—», не маркер ⛔."""
    if value is None or value == "":
        return "—"
    return str(value).replace("|", "\\|")


def _publish_same_value(left, right):
    """Сравнение значений паспорта без ложных расхождений (int/str, регистр)."""
    if left is None or right is None:
        return left in (None, "") and right in (None, "")
    if isinstance(left, (int, float)) and isinstance(right, (int, float)):
        return float(left) == float(right)
    return str(left).strip() == str(right).strip()


def _publish_duplicate_rows(mr_body, our_body, sources):
    """Строки таблицы «поле | в MR | в расчёте | источник расчёта»."""
    fields = list(our_body) + [key for key in mr_body if key not in our_body]
    rows = []
    for field in fields:
        if _publish_same_value(mr_body.get(field), our_body.get(field)):
            continue
        rows.append(
            f"| `{field}` | {_publish_cell(mr_body.get(field))} "
            f"| {_publish_cell(our_body.get(field))} "
            f"| {sources.get(field) or '—'} |"
        )
    return rows


def _mr_push_option(text):
    """Однострочное описание для push-options: git не пропускает LF.

    Все заголовки шаблона сохраняются (проверяется самопроверкой); полный
    многострочный текст ставится через API сразу после пуша.
    """
    return " ".join(part.strip() for part in str(text).splitlines() if part.strip())


def _mr_same_description(current, rendered):
    """Совпадает ли описание MR с рендером (GitLab срезает хвостовые переводы)."""
    return str(current or "").rstrip("\n") == str(rendered or "").rstrip("\n")


def _mr_description_sync(clone, branch, mr_text, label="MR", artifact="", token=None):
    """Сверить описание MR после пуша и привести его к рендеру шаблона.

    Возвращает (статус, web_url, сообщение), статус: `synced` (совпало),
    `updated` (переписано через PUT), `skipped` (нет токена/GitLab-remote/MR),
    `failed` (API отказал).
    """
    if token is None:
        token = os.environ.get(GITLAB_TOKEN_ENV)
    token = str(token or "").strip()
    if not token:
        return (
            "skipped",
            None,
            f"{GITLAB_TOKEN_ENV} не задан — описание {label} не верифицировано"
            + (f"; полный текст: {artifact}" if artifact else ""),
        )
    api, project, _web = _gitlab_api(clone)
    if not api:
        return (
            "skipped",
            None,
            f"remote.origin.url клона не указывает на GitLab — описание {label} "
            "не верифицировано"
            + (f"; полный текст: {artifact}" if artifact else ""),
        )
    ok, mr, message = _gitlab_mr_for_branch(clone, branch, token)
    if not ok:
        return "failed", None, message
    iid = mr.get("iid")
    web_url = mr.get("web_url")
    current = mr.get("description") or ""
    if _mr_same_description(current, mr_text):
        return "synced", web_url, f"описание {label} уже совпадает с шаблоном"
    ok, data = _gitlab_request(
        "PUT",
        f"{api}/projects/{project}/merge_requests/{iid}",
        token,
        payload={"description": mr_text},
    )
    if not ok:
        return "failed", web_url, f"PUT merge_requests/{iid}: {data}"
    updated = data if isinstance(data, dict) else {}
    web_url = updated.get("web_url") or web_url
    if not _mr_same_description(updated.get("description"), mr_text):
        return (
            "failed",
            web_url,
            f"описание {label} не сохранилось: PUT вернул другой текст",
        )
    return "updated", web_url, f"описание {label} переписано через PUT (iid {iid})"


def _mr_description_report(status, url, message, label="MR"):
    """Напечатать результат сверки описания MR. Код возврата: None — не ошибка."""
    if status == "synced":
        print(f"Описание {label}: {message}.")
        return None
    if status == "updated":
        print(f"Описание {label}: {message}.")
        if url:
            print(f"  MR: {url}")
        return None
    if status == "skipped":
        print(f"WARN: {message}")
        return None
    print(f"ERROR: описание {label} не обновлено: {message}")
    if url:
        print(f"  MR: {url} — обновите описание вручную")
    return 1


def _mr_url_artifact_write(clone, code, url, folder):
    """Записать URL созданного MR рядом с описанием (`<folder>/<код>-MR.url`).

    Нужен этапу `ssot`: описание SSoT-MR обязано ссылаться на dochub-MR,
    а ссылка известна только после пуша публикации.
    """
    text = str(url or "").strip()
    if not text:
        return None
    path = Path(clone) / folder / f"{code}-MR.url"
    try:
        _atomic_write(path, text + "\n")
    except OSError as exc:
        print(f"WARN: не удалось записать {path}: {exc}")
        return None
    return path


def _publish_mr_url_record(root, dochub, code, url):
    """Записать ссылку dochub-MR в клон (`.publish/`) и в проект (`.dochub/`).

    Копия в проекте — по аналогии с `.ssot/<код>-MR.url`: её читает `start`,
    чтобы подставить ссылку на паспорт в тред `handoff` без ручного шага.
    """
    written = _mr_url_artifact_write(dochub, code, url, DOCHUB_MR_DIR)
    project = _mr_url_artifact_write(root, code, url, DOCHUB_MR_URL_DIR)
    return project or written


def _mr_url_artifact_read(root, code, folder):
    """URL MR из `<folder>/<код>-MR.url` или из `<код>-MR.md` (первая ссылка).

    Ищет в рабочем дереве и в обоих клонах: `.publish` живёт в dochub, `.ssot` —
    в клоне SSoT, `.dochub` — в проекте (симметрично `.ssot`: файл переживает
    пересоздание клона). Так ссылка на MR попадает в тред согласования без
    ручного копирования.
    """
    bases = [
        Path(root) / DOCHUB_MR_URL_DIR,
        Path(root) / DOCHUB_DEFAULT_DIR,
        Path(root) / SSOT_DEFAULT_DIR,
        Path(root),
    ]
    for base in bases:
        path = base / folder / f"{code}-MR.url"
        try:
            text = path.read_text(encoding="utf-8").strip()
        except OSError:
            text = ""
        if MR_URL_RE.fullmatch(text):
            return text
        md = base / folder / f"{code}-MR.md"
        try:
            body = md.read_text(encoding="utf-8")
        except OSError:
            continue
        found = MR_URL_RE.search(body)
        if found:
            return found.group(0)
    return ""


def _mr_url_problem(url):
    """Проверка ссылки на MR: пусто или не URL MR — текст проблемы."""
    text = str(url or "").strip()
    if not text:
        return "не заполнено поле 'mr.passport_mr_url'"
    if not MR_URL_RE.fullmatch(text):
        return (
            f"ссылка на MR не распознана: {text} "
            "(ожидается https://<host>/<проект>/-/merge_requests/<iid>)"
        )
    return None


