def _criteria_repo(criteria, key):
    """(url, branch, note) репозитория из criteria.external_refs.repos.<key>.

    URL — канон в критериях, в коде не хардкодится: перенос инструмента в
    другой контур меняет только файл критериев.
    """
    block = (criteria or {}).get("external_refs") or {}
    repos = block.get("repos") if isinstance(block, dict) else None
    item = repos.get(key) if isinstance(repos, dict) else None
    if not isinstance(item, dict):
        return None, None, None
    url = str(item.get("url") or "").strip() or None
    branch = str(item.get("branch") or "").strip() or None
    note = str(item.get("note") or "").strip() or None
    return url, branch, note


def _repo_clone_command(url, target) -> str:
    """Готовая команда клонирования — ровно та, что печатается человеку."""
    return f"git clone {url} {target} --depth 1"


def _repo_clone_missing(criteria, key, target, label, flag, root, do_clone=False):
    """Клона нет: печатает команду из критериев; с --clone — клонирует.

    True — клон доступен; False — ошибка (сообщение уже напечатано).
    """
    url, branch, _note = _criteria_repo(criteria, key)
    command = _repo_clone_command(url, target) if url else None
    if do_clone:
        if not command:
            print(
                f"ERROR: клон {label} не найден: {target} и не задан "
                f"criteria.external_refs.repos.{key}.url — клонировать нечем"
            )
            print(f"  укажите --{flag} <путь к существующему клону>")
            return False
        print(f"  $ {command}")
        ok, output = _run_git(
            ["git", "clone", url, str(target), "--depth", "1"], root
        )
        if not ok:
            print(f"ERROR: клон {label} не создан: {output}")
            return False
        print("    OK")
        return Path(target).is_dir()
    print(f"ERROR: клон {label} не найден: {target} (укажите --{flag} <путь>)")
    if command:
        print(f"  выполните: {command}")
        if branch:
            print(f"  ветка: {branch}; клон создаётся автоматически с --clone")
    else:
        print(
            f"  URL не задан: criteria.external_refs.repos.{key}.url — "
            f"укажите --{flag} <путь к существующему клону>"
        )
    return False


