def _publish_fail(text, code=1):
    print(f"ERROR: {text}")
    return code


def dochub_repo_url(criteria, catalog, override=None):
    """URL репозитория dochub: --dochub-url → catalog.yaml → criteria.

    Порядок: явный флаг `--dochub-url`, затем `catalog.yaml` (`dochub_url` или
    вложенный `dochub.url`), затем `criteria.dochub.url`. URL нужен только для
    подсказки «чем клонировать»: публикация работает с локальным клоном, и без
    URL человек искал репозиторий вручную (первый полный прогон).
    """
    if override not in (None, ""):
        return str(override).strip()
    if isinstance(catalog, dict):
        direct = catalog.get("dochub_url")
        if direct not in (None, ""):
            return str(direct).strip()
        nested = catalog.get("dochub")
        if isinstance(nested, dict) and nested.get("url") not in (None, ""):
            return str(nested["url"]).strip()
    nested = (criteria or {}).get("dochub")
    if isinstance(nested, dict) and nested.get("url") not in (None, ""):
        return str(nested["url"]).strip()
    return ""


