def _human_error(exc) -> str:
    """Человеческий текст для ошибок ввода-вывода/данных (без traceback)."""
    if isinstance(exc, FileNotFoundError):
        return f"файл не найден: {exc.filename or exc}"
    if isinstance(exc, IsADirectoryError):
        return f"ожидался файл, а найден каталог: {exc.filename or exc}"
    if isinstance(exc, NotADirectoryError):
        return f"ожидался каталог, а найден файл: {exc.filename or exc}"
    if isinstance(exc, PermissionError):
        return f"нет прав на доступ к файлу: {exc.filename or exc}"
    if isinstance(exc, OSError):
        reason = exc.strerror or str(exc)
        target = f": {exc.filename}" if exc.filename else ""
        return f"ошибка ввода-вывода: {reason}{target}"
    if isinstance(exc, UnicodeDecodeError):
        return (
            "файл не читается как UTF-8 "
            f"(позиция {exc.start}, байт {exc.object[exc.start:exc.start + 1]!r})"
        )
    if isinstance(exc, KeyError):
        key = exc.args[0] if exc.args else "?"
        return f"нет обязательного ключа/поля: {key!r}"
    return f"{type(exc).__name__}: {exc}"


def main(argv=None) -> int:
    parser = build_parser()
    argv = list(sys.argv[1:] if argv is None else argv)
    args, unknown = parser.parse_known_args(argv)
    if unknown:
        if getattr(args, "command", None) == "help":
            print(
                f"ERROR: у команды help нет аргумента {unknown[0]!r}. "
                "Справка по опциям подкоманд: `score --help`, `start --help`, "
                "`prepare --help`; общий список команд — `help`."
            )
            return 2
        parser.error("unrecognized arguments: " + " ".join(unknown))
    debug = bool(getattr(args, "debug", False))
    try:
        return args.func(args)
    except BrokenPipeError:  # pragma: no cover - при `| head`
        # stdout уже закрыт: перенаправляем в /dev/null, чтобы интерпретатор
        # не пытался сбросить буфер при завершении и не печатал traceback.
        try:
            devnull = os.open(os.devnull, os.O_WRONLY)
            os.dup2(devnull, sys.stdout.fileno())
        except OSError:
            pass
        return 0
    except (YamlError, OSError, UnicodeDecodeError, KeyError) as exc:
        if debug:
            raise
        print(f"ERROR: {exc if isinstance(exc, YamlError) else _human_error(exc)}")
        return 1


if __name__ == "__main__":
    sys.exit(main())



